def get_server_heartbeat_path(account_key: str = None) -> Path:
    """Get the server heartbeat file path in data directory for a specific account"""
    if account_key:
        return config.DATA_DIR / f"ez_manage_running_{account_key}"
    return config.DATA_DIR / "ez_manage_running"
SERVER_HOST = "s1-int"
HEARTBEAT_STALE_THRESHOLD = 30 # Consider heartbeat stale if older than 30 seconds
HEARTBEAT_UPDATE_INTERVAL = 30 # Update heartbeat every 30 seconds
_heartbeat_deleted_due_to_ban = False # Global flag to track if heartbeat was deleted due to ban

async def check_server_heartbeat(account_key: str = None) -> bool:
    """Check if server heartbeat file exists and is fresh (not stale) for specific account"""
    try:
        if account_key:
            heartbeat_path = get_server_heartbeat_path(account_key)
            server_path = f"/home/niels/binance/data/ez_manage_running_{account_key}"
        else:
            heartbeat_path = get_server_heartbeat_path()
            server_path = "/home/niels/binance/data/ez_manage_running"
        if current_env['env'] == 'server':
            if account_key:
                if not heartbeat_path.exists(): return False
                try:
                    mtime = heartbeat_path.stat().st_mtime
                    age = time.time() - mtime
                    is_fresh = age < HEARTBEAT_STALE_THRESHOLD
                    if not is_fresh and logger: logger.warning(f"[HEARTBEAT] Server heartbeat for {account_key} is stale (age: {age:.1f}s > {HEARTBEAT_STALE_THRESHOLD}s)")
                    return is_fresh
                except (PermissionError, OSError):
                    return False
            else:
                for acc in config.ACCOUNT_KEYS:
                    acc_path = get_server_heartbeat_path(acc)
                    if acc_path.exists():
                        try:
                            mtime = acc_path.stat().st_mtime
                            age = time.time() - mtime
                            if age < HEARTBEAT_STALE_THRESHOLD: return True
                        except Exception: pass
                return False
        else:
            if account_key:
                result = await asyncio.to_thread(subprocess.run, ["ssh", "-o", "ConnectTimeout=2", "-o", "StrictHostKeyChecking=no", SERVER_HOST, "stat", "-c", "%Y", server_path], capture_output=True, text=True, timeout=3)
                if result.returncode != 0: return False
                try:
                    mtime = float(result.stdout.strip())
                    age = time.time() - mtime
                    is_fresh = age < HEARTBEAT_STALE_THRESHOLD
                    if not is_fresh and logger: logger.warning(f"[HEARTBEAT] Server heartbeat for {account_key} is stale (age: {age:.1f}s > {HEARTBEAT_STALE_THRESHOLD}s), allowing orders from {current_env['env']}")
                    return is_fresh
                except (ValueError, AttributeError): return False
            else:
                for acc in config.ACCOUNT_KEYS:
                    acc_server_path = f"/home/niels/binance/data/ez_manage_running_{acc}"
                    result = await asyncio.to_thread(subprocess.run, ["ssh", "-o", "ConnectTimeout=2", "-o", "StrictHostKeyChecking=no", SERVER_HOST, "stat", "-c", "%Y", acc_server_path], capture_output=True, text=True, timeout=3)
                    if result.returncode == 0:
                        try:
                            mtime = float(result.stdout.strip())
                            age = time.time() - mtime
                            if age < HEARTBEAT_STALE_THRESHOLD: return True
                        except Exception: pass
                return False
    except Exception as e:
        logger.info(f"[HEARTBEAT] Check failed: {e}")
        return False

async def update_server_heartbeat(account_key: str = None):
    """Update heartbeat file(s) on server with current timestamp for specific account or all accounts"""
    if current_env['env'] == 'server':
        accounts_to_update = [account_key] if account_key else config.ACCOUNT_KEYS
        for acc in accounts_to_update:
            heartbeat_path = get_server_heartbeat_path(acc)
            try:
                heartbeat_path.parent.mkdir(parents=True, exist_ok=True)
                try: os.chmod(str(heartbeat_path.parent), 0o755)
                except Exception: pass
                if heartbeat_path.exists():
                    os.chmod(str(heartbeat_path), 0o644)
                    os.utime(str(heartbeat_path))
                else:
                    heartbeat_path.touch(mode=0o644)
                    os.chmod(str(heartbeat_path), 0o644)
            except (PermissionError, OSError) as e:
                logger.warning(f"[HEARTBEAT] Cannot update heartbeat file for {acc} (permission issue, continuing anyway): {e}")
            except Exception as e:
                logger.warning(f"[HEARTBEAT] Failed to update heartbeat for {acc}: {e}")
    else:
        if account_key:
            server_path = f"/home/niels/binance/data/ez_manage_running_{account_key}"
            try:
                await asyncio.to_thread(subprocess.run, ["ssh", "-o", "ConnectTimeout=2", "-o", "StrictHostKeyChecking=no", SERVER_HOST, "mkdir", "-p", "/home/niels/binance/data"], timeout=3, capture_output=True)
                await asyncio.to_thread(subprocess.run, ["ssh", "-o", "ConnectTimeout=2", "-o", "StrictHostKeyChecking=no", SERVER_HOST, "touch", server_path], timeout=3, capture_output=True)
                await asyncio.to_thread(subprocess.run, ["ssh", "-o", "ConnectTimeout=2", "-o", "StrictHostKeyChecking=no", SERVER_HOST, "chmod", "644", server_path], timeout=3, capture_output=True)
            except Exception: pass

async def delete_server_heartbeat():
    """Delete all heartbeat files on server"""
    if current_env['env'] == 'server':
        for account_key in config.ACCOUNT_KEYS:
            heartbeat_path = get_server_heartbeat_path(account_key)
            try:
                if heartbeat_path.exists(): heartbeat_path.unlink()
            except FileNotFoundError:
                pass
            except Exception as e:
                logger.info(f"[HEARTBEAT] Failed to delete heartbeat for {account_key}: {e}")
    else:
        for account_key in config.ACCOUNT_KEYS:
            server_path = f"/home/niels/binance/data/ez_manage_running_{account_key}"
            try: 
                await asyncio.to_thread(subprocess.run, ["ssh", "-o", "ConnectTimeout=2", "-o", "StrictHostKeyChecking=no", SERVER_HOST, "rm", "-f", server_path], timeout=3, capture_output=True)
            except Exception: pass

async def safe_check_server_heartbeat(account_key: str = None) -> bool: return await check_server_heartbeat(account_key)

async def create_server_heartbeat():
    """Create heartbeat file on server"""
    try:
        await update_server_heartbeat()
    except Exception as e:
        logger.warning(f"[HEARTBEAT] Failed to create heartbeat (non-critical, continuing): {e}")

async def delete_heartbeat_on_ban():
    """Delete heartbeat immediately when ban is detected (allows failover to other instances)"""
    global _heartbeat_deleted_due_to_ban
    if current_env['env'] == 'server':
        try:
            await delete_server_heartbeat()
            _heartbeat_deleted_due_to_ban = True
            logger.critical("[HEARTBEAT] Server banned - heartbeat deleted to allow failover")
        except Exception as e:
            logger.error(f"[HEARTBEAT] Failed to delete heartbeat on ban: {e}")

async def restore_heartbeat_on_ban_lifted():
    """Restore all account heartbeats when ban is lifted (server can resume order execution)"""
    global _heartbeat_deleted_due_to_ban
    if current_env['env'] == 'server' and _heartbeat_deleted_due_to_ban:
        try:
            for account_key in config.ACCOUNT_KEYS:
                await update_server_heartbeat(account_key)
            _heartbeat_deleted_due_to_ban = False
            logger.critical("[HEARTBEAT] Ban lifted - heartbeats restored for all accounts, server resuming order execution")
        except Exception as e:
            logger.error(f"[HEARTBEAT] Failed to restore heartbeat after ban lifted: {e}")

async def periodic_heartbeat_update():
    """Periodically update server heartbeat for each account to keep it fresh"""
    global _heartbeat_deleted_due_to_ban
    while True:
        try:
            await asyncio.sleep(HEARTBEAT_UPDATE_INTERVAL)
            if current_env['env'] == 'server':
                if _heartbeat_deleted_due_to_ban:
                    await restore_heartbeat_on_ban_lifted()
                else:
                    for account_key in config.ACCOUNT_KEYS:
                        await update_server_heartbeat(account_key)
        except asyncio.CancelledError: break
        except Exception as e:
            logger.warning(f"[HEARTBEAT] Failed to update heartbeat: {e}")
