async def handle_market_index_spike(trade_manager, market_index: float, previous_index: float):
    """Handle market index spike: queue longs, reduce shorts"""
    global logger
    SPIKE_THRESHOLD = 4.0
    if previous_index is None or (market_index - previous_index) < SPIKE_THRESHOLD:
        return
    previous_index_display = float(previous_index) if previous_index is not None else 0.0
    spike_amount = float(market_index - previous_index) if previous_index is not None else 0.0
    logger.warning(f"🚀 MARKET SPIKE DETECTED: {previous_index_display:.1f} -> {market_index:.1f} (+{spike_amount:.1f})")
    order_size_usd = 0.5 * config.START_POSITION_SIZE
    symbols_list = trade_manager._load_all_symbols_list()
    queued_longs = 0
    reduced_shorts = 0
    for symbol in symbols_list:
        try:
            current_price, _ = await get_current_price(symbol)
            if not current_price or current_price <= 0:
                continue
            i = await ii(trade_manager, symbol)
            if not i:
                continue
            k_3m = safe_fetch_float(i.get('stoch_k_3m', 50), 50.0)
            d_3m = safe_fetch_float(i.get('stoch_d_3m', 50), 50.0)
            k_15m = safe_fetch_float(i.get('stoch_k_15m', 50), 50.0)
            d_15m = safe_fetch_float(i.get('stoch_d_15m', 50), 50.0)
            t_up_3m = bool(i.get('t_up_3m', False))
            t_up_15m = bool(i.get('t_up_15m', True))
            higher_high_15m = bool(i.get('high_15m', 0) and i.get('high_15m_prev', 0) and i.get('high_15m', 0) >= i.get('high_15m_prev', 0))
            lower_low_15m = bool(i.get('low_15m', 0) and i.get('low_15m_prev', 0) and i.get('low_15m', 0) <= i.get('low_15m_prev', 0))
            t_up_15m_override = higher_high_15m or (k_15m > d_15m if k_15m and d_15m else False)
            t_up_15m_effective = t_up_15m if not t_up_15m_override else True
            if (k_3m == 50 and d_3m == 50) or (k_15m == 50 and d_15m == 50): continue
            long_conditions_met = k_3m < 70 and k_15m < 80 and k_3m > d_3m and t_up_3m and t_up_15m_effective
            order_qty = order_size_usd / current_price
            for account_key in getattr(trade_manager, '_allowed_accounts', trade_manager.accounts.keys()):
                if not trade_manager.allows_side(account_key, "LONG"): continue
                long_key = construct_position_key(account_key, symbol, "LONG")
                short_key = construct_position_key(account_key, symbol, "SHORT")
                if not _check_leaderboard_allowed(trade_manager, symbol, "LONG", account_key, long_key): continue
                position_long = await trade_manager.get_position(long_key)
                position_short = await trade_manager.get_position(short_key)
                if position_short and abs(safe_float(position_short.positionAmt)) > 0 and getattr(config, 'EXIT_MARKET_SPIKE_REDUCE_ENABLED', True):
                    if _check_leaderboard_allowed(trade_manager, symbol, "SHORT", account_key, short_key):
                        result = await queue_trade_action(trade_manager.order_queue, trade_manager, short_key, "REDUCE", f"MARKET_SPIKE_REDUCE{market_index:.1f}", 0.8)
                    if "NOT_ALLOWED" not in str(result):
                        reduced_shorts += 1
                if long_conditions_met and (not position_long or abs(safe_float(position_long.positionAmt)) < 0.0001):
                    result = await queue_trade_action(trade_manager.order_queue, trade_manager, long_key, "OPEN", f"MARKET_SPIKE_AUGMENT_qty_{order_qty}_{market_index:.1f}", 0.8)#, override_qty=order_qty)
                    if "NOT_ALLOWED" not in str(result):
                        queued_longs += 1
        except Exception as e:
            logger.error(f"Error handling spike for {symbol}: {e}")
    logger.info(f"📊 Spike response: Queued {queued_longs} longs, Reduced {reduced_shorts} shorts")

async def handle_market_index_drop(trade_manager, market_index: float, previous_index: float):
    """Handle market index drop: reduce longs, queue shorts"""
    global logger
    DROP_THRESHOLD = -11.0
    CRASH_LEVEL = 5.0 # If market_index is below this, it's a crash regardless of previous value
    drop_amount = market_index - previous_index if previous_index is not None else 0.0
    is_sudden_drop = previous_index is not None and drop_amount <= DROP_THRESHOLD
    is_crash_level = market_index <= CRASH_LEVEL and drop_amount <= 0.7 * DROP_THRESHOLD
    if not is_sudden_drop and not is_crash_level:
        return
    previous_index_display = float(previous_index) if previous_index is not None else 0.0
    drop_amount_display = float(drop_amount) if drop_amount is not None else 0.0
    if is_crash_level:
        logger.warning(f"📉📉📉 CRASH DETECTED: market_index={market_index:.1f} <= {CRASH_LEVEL} (previous={previous_index_display:.1f}, drop={drop_amount_display:.1f})")
    else:
        logger.warning(f"📉 MARKET DROP DETECTED: {previous_index_display:.1f} -> {market_index:.1f} ({drop_amount_display:.1f})")
    order_size_usd = 0.25 * config.START_POSITION_SIZE
    symbols_list = trade_manager._load_all_symbols_list()
    queued_shorts = 0
    reduced_longs = 0
    for symbol in symbols_list:
        try:
            current_price, _ = await get_current_price(symbol)
            if not current_price or current_price <= 0:
                continue
            i = await ii(trade_manager, symbol)
            if not i:
                continue
            k_3m = safe_fetch_float(i.get('stoch_k_3m', 50), 50.0)
            d_3m = safe_fetch_float(i.get('stoch_d_3m', 50), 50.0)
            k_15m = safe_fetch_float(i.get('stoch_k_15m', 50), 50.0)
            d_15m = safe_fetch_float(i.get('stoch_d_15m', 50), 50.0)
            t_up_3m = bool(i.get('t_up_3m', False))
            t_up_15m = bool(i.get('t_up_15m', True))
            higher_high_15m = bool(i.get('high_15m', 0) and i.get('high_15m_prev', 0) and i.get('high_15m', 0) >= i.get('high_15m_prev', 0))
            lower_low_15m = bool(i.get('low_15m', 0) and i.get('low_15m_prev', 0) and i.get('low_15m', 0) <= i.get('low_15m_prev', 0))
            t_up_15m_override = lower_low_15m or (k_15m < d_15m if k_15m and d_15m else False)
            t_up_15m_effective = t_up_15m if not t_up_15m_override else False
            if (k_3m == 50 and d_3m == 50) or (k_15m == 50 and d_15m == 50): continue
            short_conditions_met = k_3m > 30 and k_15m > 20 and k_3m < d_3m and (not t_up_3m or not t_up_15m_effective)  # crash handler: keep loose, structure check in entry_vetting
            order_qty = order_size_usd / current_price
            for account_key in getattr(trade_manager, '_allowed_accounts', trade_manager.accounts.keys()):
                if not trade_manager.allows_side(account_key, "SHORT"):
                    continue
                long_key = construct_position_key(account_key, symbol, "LONG")
                short_key = construct_position_key(account_key, symbol, "SHORT")
                if not _check_leaderboard_allowed(trade_manager, symbol, "SHORT", account_key, short_key):
                    continue
                position_long = await trade_manager.get_position(long_key)
                position_short = await trade_manager.get_position(short_key)
                if position_long and abs(safe_float(position_long.positionAmt)) > 2 * config.MIN_POSITION_SIZE / current_price and getattr(config, 'EXIT_MARKET_SPIKE_REDUCE_ENABLED', True):
                    if _check_leaderboard_allowed(trade_manager, symbol, "LONG", account_key, long_key):
                        result = await queue_trade_action(trade_manager.order_queue, trade_manager, long_key, "REDUCE", f"MARKET_DROP_{market_index:.1f}", 0.8)
                        if "NOT_ALLOWED" not in str(result):
                            reduced_longs += 1
                if short_conditions_met and (not position_short or abs(safe_float(position_short.positionAmt)) < 3 * config.MIN_POSITION_SIZE / current_price):
                    result = await queue_trade_action(trade_manager.order_queue, trade_manager, short_key, "OPEN", f"MARKET_DROP_{market_index:.1f}", 0.8)
                    if "NOT_ALLOWED" not in str(result):
                        queued_shorts += 1
        except Exception as e:
            logger.error(f"Error handling drop for {symbol}: {e}")
    logger.info(f"📊 Drop response: Reduced {reduced_longs} longs, Queued {queued_shorts} shorts")

async def monitor_system_state(trade_manager):
    """Monitor and log system state every minute to verify data updates"""
    global _previous_market_index, _previous_market_index_time
    while True:
        try:
            await asyncio.sleep(60)
            logger.info("="*80)
            logger.info("📊 SYSTEM STATE MONITOR")
            logger.info("="*80)
            now = datetime.now(timezone.utc)
            ticker = await get_market_index_ticker()
            market_index = safe_float(ticker.get("price") if ticker else None, 50.0) if ticker else 50.0
            mode = ticker.get("mode", "NORMAL_MODE") if ticker else "NORMAL_MODE"
            market_index = float(market_index) if market_index is not None else 50.0
            logger.info(f"📊 MARKET INDEX: {market_index:.1f} ({mode})")
            CRASH_LEVEL = 15.0
            is_crash = market_index <= CRASH_LEVEL
            recent_previous = _previous_market_index is not None and _previous_market_index_time and (now - _previous_market_index_time).total_seconds() < 300
            if recent_previous or is_crash:
                await handle_market_index_spike(trade_manager, market_index, _previous_market_index)
                await handle_market_index_drop(trade_manager, market_index, _previous_market_index)
            _previous_market_index = market_index
            _previous_market_index_time = now
            all_positions = []
            managed_accounts = set(trade_manager.accounts.keys())
            for account_key, positions_dict in trade_manager.positions_by_account.items():
                if account_key not in managed_accounts or account_key not in config.ACCOUNT_KEYS:
                    continue
                for position_key, position in positions_dict.items():
                    if position and abs(safe_float(position.positionAmt)) > 0:
                        all_positions.append((position_key, position))
            all_positions.sort(key=lambda x: abs(safe_float(x[1].positionAmt) * safe_float(x[1].mark_price)), reverse=True)
            market_index_display = float(market_index) if market_index is not None else 50.0
            logger.info(f"📈 TOP 5 POSITIONS (by value) [Market Index: {market_index_display:.1f}]:")
            top_positions = all_positions[:5]
            for i, (position_key, pos) in enumerate(top_positions, 1):
                amt = safe_float(pos.positionAmt) or 0.0
                mark = safe_float(pos.mark_price) or 0.0
                value = abs(amt * mark) or 0.0
                updated = getattr(pos, 'mark_price_last_updated', None)
                try:
                    age = f"{(now - updated).total_seconds():.1f}s" if isinstance(updated, datetime) else "never"
                except Exception:
                    age = "never"
                logger.info(f" {i}. {position_key}: amt={amt:.4f} mark=${mark:.2f} value=${value:.2f} updated={age} ago")
            sample_positions = all_positions[:3] if all_positions else []
            sample_symbols = [p.symbol for _, p in sample_positions] if sample_positions else ["BTCUSDC"]
            for symbol in sample_symbols[:2]:
                try:
                    ctx_snapshot = {'trade_manager': trade_manager, 'symbol': symbol, 'logger': logger, 'position_key': f"monitor::{symbol}"}
                    i = await ii(trade_manager, symbol)
                    indicators = i if i else {}
                    if i:
                        ts_3m = i.get("timestamp_3m", "")
                        if ts_3m:
                            ts_dt = _parse_indicator_timestamp(ts_3m)
                            if not isinstance(ts_dt, datetime):
                                source_ts = getattr(trade_manager, "indicators_timestamp", None)
                                if isinstance(source_ts, datetime):
                                    ts_dt = source_ts if source_ts.tzinfo else source_ts.replace(tzinfo=timezone.utc)
                                else:
                                    latest_mtime = getattr(trade_manager, "_latest_market_data_mtime", 0.0)
                                    if latest_mtime:
                                        ts_dt = datetime.fromtimestamp(latest_mtime, tz=timezone.utc)
                            if isinstance(ts_dt, datetime):
                                if ts_dt.tzinfo is None:
                                    ts_dt = ts_dt.replace(tzinfo=timezone.utc)
                                try:
                                    age = max(0.0, (now - ts_dt).total_seconds()) or 0.0
                                except Exception:
                                    age = 0.0
                                age = float(age) if age is not None and isinstance(age, (int, float)) else 0.0
                                logger.info(f"📊 {symbol} indicators: 3m_age={age:.1f}s, keys={len(indicators)}")
                            else:
                                logger.info(f"📊 {symbol} indicators: keys={len(indicators)} (no timestamp)")
                        else:
                            logger.info(f"📊 {symbol} indicators: keys={len(indicators)}")
                    else:
                        logger.warning(f"📊 {symbol} indicators: NONE")
                except Exception as e:
                    logger.error(f"📊 {symbol} indicator check failed: {e}")
            latest_reversed = sorted([(k, v) for k, v in trade_manager.reversed_positions.items()], key=lambda x: x[1], reverse=True)[:3]
            managed_accounts = set(trade_manager.accounts.keys())
            _sm_reentry = trade_manager.service.reentry_data if trade_manager.service else trade_manager.reentry_data
            filtered_reentry_data = {k: v for k, v in _sm_reentry.items() if ':' in k and k.split(':')[0] in managed_accounts and isinstance(v, dict) and safe_float(v.get('reentry_amount', 0), 0.0) > 0}
            reentry_count = len(filtered_reentry_data)
            if reentry_count > 0:
                logger.info(f"🎯 REENTRY LEVELS ({reentry_count} total):")
                shown = 0
                for position_key, entry in filtered_reentry_data.items():
                    if shown >= 5:
                        break
                    if isinstance(entry, dict):
                        reentry_level = safe_float(entry.get('reentry_level'), 0.0) or 0.0
                        reentry_amount = safe_float(entry.get('reentry_amount'), 0.0) or 0.0
                        reentry_level = float(reentry_level) if reentry_level is not None else 0.0
                        reentry_amount = float(reentry_amount) if reentry_amount is not None else 0.0
                        logger.info(f" {position_key}: reentry_level=${reentry_level:.2f} reentry_amount={reentry_amount:.4f}")
                        shown += 1
            else:
                logger.info(f"🎯 REENTRY LEVELS: none")
            reentry_data_dict = trade_manager.service.reentry_data if trade_manager.service else getattr(trade_manager, 'reentry_data', {})
            if reentry_data_dict and isinstance(reentry_data_dict, dict):
                filtered_keys = _filter_position_keys(trade_manager, list(reentry_data_dict.keys()))
                if filtered_keys:
                    filtered_reentry_data = {position_key: reentry_data_dict[position_key] for position_key in filtered_keys if position_key in reentry_data_dict}
                    original_reentry_data = trade_manager.reentry_data
                    try:
                        trade_manager.reentry_data = filtered_reentry_data
                        await evaluate_reentry_2(trade_manager)
                    finally:
                        trade_manager.reentry_data = original_reentry_data
            logger.info("="*80)
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"[MONITOR] State monitor error: {e}") 
