def _extract_ts_from_filename(path: Path) -> float:
    try:
        path=Path(config.DATA_DIR)
        match = re.search(r"market_data__?(\d{4})(\d{2})(\d{2})_(\d{2})(\d{2})(\d{2})", path.name)
        if match:
            y, m, d, H, M, S = map(int, match.groups())
            dt = datetime(y, m, d, H, M, S, tzinfo=timezone.utc)
            return dt.timestamp()
    except Exception: pass
    return 0.0

def _file_age_seconds(file_path: Path) -> float:
    try:
        resolved_path = file_path.resolve() if file_path.exists() else file_path
        file_mtime = os.path.getmtime(str(resolved_path))
        return max(0.0, time.time() - file_mtime)
    except (FileNotFoundError, OSError):
        return float("inf")
    except Exception:
        return float("inf")

def _is_file_fresh(file_path: Path, max_age: float) -> bool:
    return _file_age_seconds(file_path) <= max_age

async def load_json_safe(file_path: Union[str, Path], account_key: str = None) -> dict:
    file_path = Path(file_path)
    async with _global_file_write_semaphore:
        content = b""
        try:
            if not file_path.exists():
                return {}
            async with aiofiles.open(file_path, "rb") as f:
                content = await f.read()
            if not content.strip():
                return {}
            data = safe_json_loads(content)
        except Exception:
            data = {}
            recovery_success = False
            try:
                txt = content.decode('utf-8', errors='ignore').strip()
                end_idx = txt.rfind('}')
                if end_idx != -1:
                    fixed_txt = txt[:end_idx+1]
                    data = orjson.loads(fixed_txt)
                    recovery_success = True
                    async with aiofiles.open(file_path, "wb") as f:
                        await f.write(orjson.dumps(data, option=orjson.OPT_INDENT_2))
            except Exception:
                pass
            if not recovery_success:
                backup_path = file_path.with_suffix(file_path.suffix + ".bak")
                if backup_path.exists():
                    try:
                        async with aiofiles.open(backup_path, "rb") as f:
                            bk_content = await f.read()
                        data = safe_json_loads(bk_content)
                        recovery_success = True
                        async with aiofiles.open(file_path, "wb") as f:
                            await f.write(bk_content)
                    except Exception:
                        pass
            if not recovery_success:
                try:
                    if file_path.exists():
                        os.remove(file_path)
                except Exception:
                    pass
                return {}
        if not isinstance(data, dict):
            return {}
        data = _convert_timestamp_strings(data) 
        return data
_indicator_restart_lock = DummyLock()
_last_indicator_restart_ts = datetime.min.replace(tzinfo=timezone.utc)

async def _exec_shell_command(command: Optional[str], label: str, timeout: float = 10.0) -> Optional[int]:
    if not command:
        return None
    try:
        proc = await asyncio.create_subprocess_shell(command)
        try:
            await asyncio.wait_for(proc.wait(), timeout=timeout)
        except asyncio.TimeoutError:
            logger.warning(f"[{label}] command timed out after {timeout:.1f}s; terminating")
            with suppress(Exception):
                proc.kill()
            return None
        return proc.returncode
    except Exception as exc:
        logger.warning(f"[{label}] command failed: {exc}")
        return None

async def request_ez_indicators_restart(reason: str = "external") -> bool:
    cmd = getattr(config, "EZ_INDICATORS_START_CMD", None)
    if not cmd:
        return False
    cooldown = float(getattr(config, "EZ_INDICATORS_RESTART_COOLDOWN", 60.0))
    timeout = float(getattr(config, "EZ_INDICATORS_CMD_TIMEOUT", 10.0))
    now = datetime.now(timezone.utc)
    async with _indicator_restart_lock:
        global _last_indicator_restart_ts
        if (now - _last_indicator_restart_ts).total_seconds() < cooldown:
            return False
        logger.warning(f"[ez_indicators] Restart requested ({reason})")
        rc = await _exec_shell_command(cmd, f"ez_indicators restart ({reason})", timeout=timeout)
        _last_indicator_restart_ts = datetime.now(timezone.utc)
        return rc == 0 if rc is not None else False

async def _maybe_restart_indicators(trade_manager: Optional["MultiAccountTradeManager"], reason: str) -> None:
    restarted = await request_ez_indicators_restart(reason)
    if restarted:
        logger.info(f"[ez_indicators] Restart command executed ({reason})")
