async def monitor_memory():
    process = psutil.Process(os.getpid())
    while True:
        mem_bytes = process.memory_info().rss
        mem_gb = mem_bytes / (1024 ** 3)
        if mem_gb > config.MAX_MEMORY_GB:
            print(f"Memory usage exceeded: {mem_gb:.2f} GB. Restarting...")
            os.execv(sys.executable, ['python'] + sys.argv) # Restart script
        await asyncio.sleep(60) 

async def monitor_market_mode():
    """Monitor market_mode.json and update config when ez_rankings changes the mode"""
    mode_file = config.DATA_DIR / "market_mode.json"
    last_mode = config.MARKET_MODE # Initialize from config.py settings
    startup_time = time.time()
    try:
        last_seen_mtime = mode_file.stat().st_mtime if mode_file.exists() else 0.0
    except OSError:
        last_seen_mtime = 0.0
    logger.debug(f"📊 Market mode monitor initialized with mode from config.py: {last_mode} (manual override active until ez_rankings updates market_mode.json)")
    while True:
        try:
            if mode_file.exists():
                try:
                    file_mtime = mode_file.stat().st_mtime
                except OSError:
                    file_mtime = 0.0
                async with aiofiles.open(mode_file, 'r') as f:
                    content = await f.read()
                    mode_data = json.loads(content)
                    new_mode = mode_data.get("mode", "NORMAL_MODE")
                    market_index = mode_data.get("market_index", 0.0)
                    update_ready = file_mtime > max(last_seen_mtime, startup_time)
                    if update_ready:
                        if new_mode != last_mode:
                            Config.set_market_mode(new_mode)
                            logger.info(f"📊 Market mode updated by ez_rankings: {last_mode} -> {new_mode} (Index: {market_index:.1f})")
                            logger.info(f"📊 Config.EXTREME_MODE={config.EXTREME_MODE}, Config.LIGHT_MODE={config.LIGHT_MODE}, Config.MARKET_MODE={config.MARKET_MODE}")
                            last_mode = new_mode
                        last_seen_mtime = file_mtime
                    elif new_mode != last_mode:
                        logger.debug(f"📊 Market mode manual override active: ignoring ez_rankings recommendation {new_mode}, retaining config mode {last_mode}")
        except Exception as e:
            logger.debug(f"Error checking market mode: {e}")
        await asyncio.sleep(30)

class PositionCallbackManager:

    def __init__(self):
        self._callbacks: DefaultDict[str, list] = defaultdict(list)
        self._latest: Dict[str, Any] = {}
        self._lock = DummyLock()

    async def register_callback(self, position_key: str, callback: Callable[[Dict[str, Any]], Awaitable[Any] | Any]) -> None:
        if not position_key or not callable(callback): return
        async with self._lock:
            if callback not in self._callbacks[position_key]: self._callbacks[position_key].append(callback)

    async def unregister_callback(self, position_key: str, callback: Callable[[Dict[str, Any]], Awaitable[Any] | Any]) -> None:
        if not position_key or not callable(callback): return
        async with self._lock:
            callbacks = self._callbacks.get(position_key)
            if not callbacks: return
            if callback in callbacks: callbacks.remove(callback)
            if not callbacks: self._callbacks.pop(position_key, None)

    async def notify(self, position_key: str, payload: Dict[str, Any]) -> None:
        async with self._lock:
            callbacks = list(self._callbacks.get(position_key, ()))
        for callback in callbacks:
            try:
                result = callback(payload)
                if asyncio.iscoroutine(result): await result
            except Exception as exc:
                logger.debug(f"[position_callback] notify failed for {position_key}: {exc}")
        self._latest[position_key] = payload

    async def get_latest_position(self, position_key: str) -> Optional[Dict[str, Any]]:
        return self._latest.get(position_key)

    async def has_recent_update(self, position_key: str, max_age_seconds: float) -> bool:
        payload = self._latest.get(position_key)
        if not isinstance(payload, dict): return False
        ts = payload.get("timestamp")
        if isinstance(ts, (int, float)): return (time.time() - float(ts)) <= max_age_seconds
        if isinstance(ts, datetime): return (datetime.now(timezone.utc) - ts).total_seconds() <= max_age_seconds
        return False

class TradeVerifier:

    def __init__(self, position_callback_manager=None, positions_by_account=None, positions_service=None, active_maker_orders=None, managed_maker_order_registry=None, accounts=None):
        self.position_callback_manager = position_callback_manager
        self.positions_service = positions_service
        self.positions_by_account = self.positions_service.positions_by_account or {}
        self.active_maker_orders = {}
        self.active_maker_orders.update(active_maker_orders or {})
        self.managed_maker_order_registry = {}
        self.managed_maker_order_registry.update(managed_maker_order_registry or {})
        self.accounts = accounts or {}

    async def verify_trade(self, account_key: Optional[str] = None, position_key: Optional[str] = None, qty: float = 0.0, is_long: bool = True, timeout_seconds: int = 10, initial_positionAmt: float = 0.0, action: str = '') -> bool:
        if not self.positions_by_account:
            logger.warning(f"[TradeVerifier][{position_key}] positions_by_account is None, cannot verify trade")
            return False
        if not position_key:
            logger.warning("[TradeVerifier] position_key is None, cannot verify trade")
            return False
        symbol = position_key.split(':')[1].replace('_LONG', '').replace('_SHORT', '')
        start_time = time.time()
        if ('CLOSE' in action or 'REDUCE' in action or 'PROFIT_TAKE' in action) and initial_positionAmt <= 0: return False
        expected_qty_float = float(qty); expected_diff = expected_qty_float if is_long else -expected_qty_float
        if 'CLOSE' in action or 'REDUCE' in action or 'PROFIT_TAKE' in action: expected_diff = -expected_qty_float if is_long else expected_qty_float
        has_ws_manager = self.position_callback_manager is not None
        for attempt in range(int(timeout_seconds * 2)): # Check every 0.5s
            try:
                await asyncio.sleep(0.5)
                if time.time() - start_time >= timeout_seconds: break
                current_amt = None
                if has_ws_manager and self.position_callback_manager:
                    try:
                        ws_latest = await self.position_callback_manager.get_latest_position(position_key)
                        if ws_latest:
                            ts_val = ws_latest.get('timestamp')
                            if isinstance(ts_val, str): 
                                from dateutil.parser import isoparse
                                ts_val = isoparse(ts_val)
                            if isinstance(ts_val, datetime):
                                if ts_val.tzinfo is None: ts_val = ts_val.replace(tzinfo=timezone.utc)
                                if ts_val.timestamp() > start_time - 3.0: current_amt = abs(safe_fetch_float(ws_latest.get('positionAmt', 0.0), 0.0))
                    except Exception: pass
                if current_amt is None:
                    api_positions = self.positions_by_account.get(account_key, {})
                    current_pos = api_positions.get(position_key)
                    if current_pos:
                        last_upd = getattr(current_pos, 'last_updated', None)
                        if last_upd:
                            if last_upd.tzinfo is None: last_upd = last_upd.replace(tzinfo=timezone.utc)
                            if last_upd.timestamp() > start_time - 3.0: current_amt = abs(safe_fetch_float(getattr(current_pos, 'positionAmt', 0.0), 0.0))
                if current_amt is not None:
                    qty_diff = float(current_amt) - float(initial_positionAmt)
                    is_reduction = any(x in action for x in ['REDUCE', 'CLOSE', 'PROFIT_TAKE'])
                    valid_direction = (is_reduction and qty_diff < 0) or (not is_reduction and qty_diff > 0)
                    if abs(initial_positionAmt) < 1e-6 and any(x in action for x in ('OPEN', 'AUGMENT', 'REENTRY', 'QUICK_OPEN')) and current_amt > 1e-6:
                        logger.info(f"[TradeVerifier] Verified via WS/Mem (OPEN from zero): {current_amt:.6f}")
                        return True
                    if abs(qty_diff) >= abs(qty) * 0.1 and valid_direction:
                        logger.info(f"[TradeVerifier] Verified via WS/Mem: {current_amt:.6f} (diff={qty_diff:.6f})")
                        return True
                    if abs(qty_diff) >= abs(expected_diff) * 0.1 and valid_direction:
                        logger.info(f"[TradeVerifier] Verified via WS/Mem: {current_amt:.6f} (diff={qty_diff:.6f})")
                        return True
            except Exception: await asyncio.sleep(0.5)
        try:
            if self.positions_service:
                await self.positions_service.fetch_positions(account_key)
            api_positions = self.positions_by_account.get(account_key, {})
            current_pos = api_positions.get(position_key)
            final_amt = abs(safe_fetch_float(getattr(current_pos, 'positionAmt', 0.0), 0.0)) if current_pos else 0.0
            qty_diff = float(final_amt) - float(initial_positionAmt)
            _is_red_final = any(x in action for x in ['REDUCE', 'CLOSE', 'PROFIT_TAKE'])
            _valid_dir_final = (_is_red_final and qty_diff < 0) or (not _is_red_final and qty_diff > 0)
            if abs(qty_diff) >= abs(expected_diff) * 0.1 and _valid_dir_final:
                logger.info(f"[TradeVerifier] Executed: {final_amt:.6f} (diff={qty_diff:.6f})")
                return True
            if abs(initial_positionAmt) < 1e-6 and any(x in action for x in ('OPEN', 'AUGMENT', 'REENTRY', 'QUICK_OPEN')) and final_amt > 1e-6:
                logger.info(f"[TradeVerifier] Executed (OPEN from zero): {final_amt:.6f}")
                return True
            if ('CLOSE' in action or 'REDUCE' in action or 'PROFIT_TAKE' in action) and final_amt < 1e-6 and abs(initial_positionAmt) >= abs(expected_qty_float) * 0.9:
                logger.info(f"[TradeVerifier] Executed (CLOSED): position gone")
                return True
        except Exception as e: logger.error(f"[TradeVerifier] API fetch failed: {e}")
        order_ids_to_cancel = []
        if position_key in self.active_maker_orders:
            order_info = self.active_maker_orders[position_key]
            order_id = order_info.get('order_id')
            if order_id and str(order_id).isdigit():
                order_ids_to_cancel.append(int(order_id))
        for order_id_str, order_info in list(self.managed_maker_order_registry.items()):
            if order_info.get('position_key') == position_key:
                try:
                    oid = int(order_id_str)
                    if oid not in order_ids_to_cancel: order_ids_to_cancel.append(oid)
                except Exception: pass
        if order_ids_to_cancel and account_key in self.accounts:
            account = self.accounts[account_key]
            if account and hasattr(account, 'client') and account.client:
                client = account.client
                for order_id in order_ids_to_cancel:
                    try:
                        asyncio.create_task(asyncio.to_thread(client.futures_cancel_order, symbol=symbol, orderId=order_id))
                    except Exception: pass
        return False

async def verify_trade_via_websocket(trade_manager, account_key: Optional[str] = None, position_key: Optional[str] = None, qty: float = 0.0, is_long: bool = True, timeout_seconds: float = 10.0, initial_positionAmt: float = 0.0, action: str = '') -> bool:
    position_callback_mgr = None
    if hasattr(trade_manager, 'position_callback_manager') and trade_manager.position_callback_manager:
        position_callback_mgr = trade_manager.position_callback_manager
    elif hasattr(trade_manager, 'data_manager') and trade_manager.data_manager:
        if hasattr(trade_manager.data_manager, 'position_callback_manager') and trade_manager.data_manager.position_callback_manager:
            position_callback_mgr = trade_manager.data_manager.position_callback_manager
    positions_by_account = getattr(trade_manager, 'positions_by_account', {})
    positions_service = getattr(trade_manager, 'positions_service', None)
    active_maker_orders = getattr(trade_manager, 'active_maker_orders', {})
    managed_maker_order_registry = getattr(trade_manager, 'managed_maker_order_registry', {})
    accounts = getattr(trade_manager, 'accounts', {})
    verifier = TradeVerifier(position_callback_manager=position_callback_mgr, positions_by_account=positions_by_account, positions_service=positions_service, active_maker_orders=active_maker_orders, managed_maker_order_registry=managed_maker_order_registry, accounts=accounts)
    return await verifier.verify_trade(account_key, position_key, qty, is_long, timeout_seconds, initial_positionAmt, action)

def _validate_and_apply_snapshot(self, data, source_label, override_ts=None):
        """Helper to validate timestamp and apply data. Trusts override_ts if provided."""
        if isinstance(data, dict) and data:
            if override_ts and override_ts > 0:
                payload_ts = override_ts
            else:
                payload_ts = _snapshot_timestamp(data)
            max_age = 1200 
            if payload_ts:
                data_age = time.time() - payload_ts
                if data_age <= max_age:
                    self.indicators_snapshot.clear()
                    for sym, indicators in data.items():
                        if isinstance(indicators, dict):
                            self.indicators_snapshot[sym] = indicators
                    self.indicators_cache_timestamps.clear()
                    self.indicators_cache_timestamps.update({sym: time.time() for sym in data.keys()})
                    self.indicators_timestamp = datetime.now(timezone.utc)
                    self.indicators_source_label = source_label
                    self.indicators_snapshot_refresh_time = time.time()
                    logger.info(f" [REFRESH] Success from {source_label} (Calculated Age: {data_age:.1f}s)")
                    return True
                else:
                    logger.error(f"🚫 [REFRESH] REJECTED STALE DATA: {source_label} timestamp is {data_age:.0f}s old (> {max_age}s)")
            else:
                logger.error(f"🚫 [REFRESH] REJECTED: No timestamp found in {source_label}") 
        return False
_latest_market_data_file_cache = {"file": None, "timestamp": 0.0, "mtime": 0.0}
_latest_market_data_file_cache_lock = threading.Lock()
_latest_market_data_file_cache_ttl = 2.0 # Cache for 2 seconds to prevent file handle accumulation

def _get_latest_market_data_file():
    global _latest_market_data_file_cache
    try:
        now = time.time()
        with _latest_market_data_file_cache_lock:
            if _latest_market_data_file_cache["file"] and (now - _latest_market_data_file_cache["timestamp"]) < 2.0:
                return _latest_market_data_file_cache["file"]
        data_dir = Path(config.DATA_DIR)
        if not data_dir.exists():
            return None
        files = [f for f in data_dir.glob("market_data_*.json") if "worker" not in f.name]
        if not files:
            static_file = data_dir / "latest_market_data.json"
            return str(static_file) if static_file.exists() else None
        files.sort(key=lambda f: f.stat().st_mtime, reverse=True)
        result = str(files[0])
        with _latest_market_data_file_cache_lock:
            _latest_market_data_file_cache = {"file": result, "timestamp": now, "mtime": files[0].stat().st_mtime}
        return result
    except Exception as e:
        logger.error(f"Error finding latest market data file: {e}")
        return None

def _check_loss_protection(position, position_key): 
    try:
        if position.gain < config.NEW_POSITION_MAX_LOSS_THRESHOLD:
            return False
        if config.ENABLE_LOSS_PROTECTION:
            return position.gain <= 0.12
        opened_at = getattr(position, 'last_augmentation_time', None)
        if not opened_at:
            return False
        try:
            if isinstance(opened_at, str):
                opened_at = isoparse(opened_at)
            if isinstance(opened_at, datetime):
                if opened_at.tzinfo is None:
                    opened_at = opened_at.replace(tzinfo=timezone.utc)
                now = datetime.now(timezone.utc)
                age_seconds = (now - opened_at).total_seconds()
                if age_seconds is None or age_seconds < 0:
                    logger.warning(f"{position_key}: Invalid age_seconds: {age_seconds}")
                    return False
                is_new_position = age_seconds < config.NEW_POSITION_MIN_AGE_SECONDS
                return is_new_position and position.gain >= config.NEW_POSITION_MAX_LOSS_THRESHOLD
        except (TypeError, ValueError, AttributeError) as e:
            logger.debug(f"{position_key}: Error processing position time: {e}")
            return False
    except Exception as e:
        logger.error(f"{position_key}: Unexpected error in : {e}")
        return False
    return False

def _refresh_last_events_cache():
    """Refresh the in-memory cache of last_events.json data."""
    global _last_events_cache, _last_events_cache_time
    try:
        last_events_path = os.path.join('data', 'last_events.json')
        if not os.path.exists(last_events_path):
            logger.warning(f"WARNING: last_events.json not found at {last_events_path}")
            _last_events_cache = {}
            _last_events_cache_time = time.time()
            return
        with open(last_events_path, "rb") as f:
            _last_events_cache = safe_json_loads(f.read())
        _last_events_cache_time = time.time()
        logger.debug(f"Refreshed last_events.json cache with {len(_last_events_cache)} symbols")
    except Exception as e:
        logger.warning(f"WARNING: Error refreshing last_events.json cache: {e}")
        _last_events_cache = {}
        _last_events_cache_time = time.time()

def force_refresh_last_events_cache():
    """Force refresh the last_events.json cache (call this on listener signals)."""
    global _last_events_cache_time
    _last_events_cache_time = 0 # Force refresh on next access
    _refresh_last_events_cache()

def _normalize_timestamp_to_z(timestamp_str: str) -> str:
    """Normalize timestamp string to end with 'Z' for UTC - only processes actual ISO timestamp strings"""
    if not isinstance(timestamp_str, str) or not timestamp_str: return timestamp_str
    ts = timestamp_str.strip()
    if ts.endswith(('Z', 'z')):
        core = ts[:-1]
        if core:
            try:
                float(core)
                return f"{core}Z"
            except ValueError:
                pass
        return f"{core}Z" if core else "Z"
    if '+' in ts or '-' in ts[10:]: return ts
    if not ('-' in ts or 'T' in ts): return ts
    if ts.count('-') < 2: return ts
    if len(ts) < 10: return ts
    if 'T' in ts: return ts + 'Z'
    return ts

def _check_timestamp_3m_freshness(indicators: dict, max_age_minutes: float = 5.0) -> bool:
    ts = indicators.get('timestamp_3m') or indicators.get('timestamp')
    if not ts: return False
    try:
        if isinstance(ts, str):
            dt = datetime.fromisoformat(ts.replace('Z', '+00:00'))
        elif isinstance(ts, (int, float)):
            dt = datetime.fromtimestamp(ts, tz=timezone.utc)
        else:
            return False
        if dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)
        age = (datetime.now(timezone.utc) - dt).total_seconds()
        return age < (max_age_minutes * 60)
    except Exception:
        return False

def _parse_indicator_timestamp(value: Any) -> Optional[datetime]:
    if value is None:
        return None
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=timezone.utc)
    if isinstance(value, (int, float)):
        try:
            seconds = float(value)
            if seconds > 1e12:
                seconds /= 1000.0
            return datetime.fromtimestamp(seconds, tz=timezone.utc)
        except Exception:
            return None
    if isinstance(value, str):
        ts = _normalize_timestamp_to_z(value)
        if not ts:
            return None
        stripped = ts.strip()
        if not stripped:
            return None
        try:
            numeric = float(stripped)
            return _parse_indicator_timestamp(numeric)
        except ValueError:
            pass
        try:
            parsed = isoparse(stripped)
        except Exception:
            try:
                parsed = datetime.fromisoformat(stripped.replace('Z', '+00:00'))
            except Exception:
                return None
        if parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed.astimezone(timezone.utc)
    return None

def _indicator_payload_timestamp(payload: dict) -> Optional[datetime]:
    if not isinstance(payload, dict) or not payload:
        return None
    primary_keys = ('timestamp', 'last_updated', 'generated_at', 'created_at')
    timeframe_keys = ('timestamp_3m', 'timestamp_3m_mid', 'timestamp_1m', 'timestamp_5m', 'timestamp_15m', 'timestamp_30m', 'timestamp_1h', 'timestamp_2h', 'timestamp_4h', 'timestamp_6h', 'timestamp_12h', 'timestamp_D', 'timestamp_W')
    for key in (*primary_keys, *timeframe_keys):
        ts = _parse_indicator_timestamp(payload.get(key))
        if ts:
            return ts
    for nested in ('3m', '5m', '15m', '1h', '4h', 'D'):
        nested_payload = payload.get(nested)
        if isinstance(nested_payload, dict):
            ts = _indicator_payload_timestamp(nested_payload)
            if ts:
                return ts
    return None

def _indicator_payload_is_fresh(payload: dict, max_age: float = MAX_MARKET_DATA_AGE_SECONDS, fallback_ts: Optional[datetime] = None) -> bool:
    if not isinstance(payload, dict):
        return False
    ts = _indicator_payload_timestamp(payload) or fallback_ts
    if not ts:
        return False
    age = (datetime.now(timezone.utc) - ts).total_seconds()
    return age <= max_age

def _snapshot_timestamp(data: dict) -> float:
    """Extracts timestamp from payload, supporting multiple key formats."""
    try:
        if "timestamp" in data: return _parse_ts(data["timestamp"])
        if "_tick_ts" in data: return float(data["_tick_ts"])
        max_ts = 0
        check_count = 0
        for k, v in data.items():
            if isinstance(v, dict):
                ts = v.get("_tick_ts") or v.get("timestamp") or v.get("time")
                if ts:
                    parsed = _parse_ts(ts)
                    if parsed > max_ts: max_ts = parsed
                check_count += 1
                if check_count > 5: break # Don't scan 500 symbols
        return max_ts
    except Exception: return 0.0

def _parse_ts(val):
    if isinstance(val, (int, float)): return float(val)
    if isinstance(val, str):
        try:
            from dateutil.parser import isoparse
            dt = isoparse(val)
            return dt.timestamp()
        except Exception: pass
    return 0.0

def _snapshot_is_fresh(snapshot: dict, max_age: float = MAX_MARKET_DATA_AGE_SECONDS, fallback_ts: Optional[Any] = None) -> bool:
    if not isinstance(snapshot, dict) or not snapshot:
        return False

    def _normalize(candidate: Any) -> Optional[datetime]:
        if candidate is None:
            return None
        if isinstance(candidate, datetime):
            return candidate if candidate.tzinfo else candidate.replace(tzinfo=timezone.utc)
        if isinstance(candidate, (int, float)):
            try:
                return datetime.fromtimestamp(float(candidate), tz=timezone.utc)
            except (TypeError, ValueError, OverflowError):
                return None
        return None
    candidates: list[datetime] = []
    primary_ts = _snapshot_timestamp(snapshot)
    normalized_primary = _normalize(primary_ts)
    if normalized_primary:
        candidates.append(normalized_primary)
    if isinstance(fallback_ts, (list, tuple, set)):
        fallback_iterable = fallback_ts
    else:
        fallback_iterable = (fallback_ts,)
    for fb in fallback_iterable:
        normalized_fb = _normalize(fb)
        if normalized_fb:
            candidates.append(normalized_fb)
    if not candidates:
        return False
    now_utc = datetime.now(timezone.utc)
    for candidate in candidates:
        age = (now_utc - candidate).total_seconds()
        if age <= max_age or age < 0:
            return True
    return False

async def _ensure_indicator_snapshot(ctx: dict) -> bool:
    symbol = ctx.get('symbol')
    trade_manager = ctx['trade_manager']
    normalized_symbol = symbol.strip().upper() if isinstance(symbol, str) else symbol
    return await ensure_indicator_snapshot_ready(ctx)

async def _ensure_reentry_snapshot(ctx: dict) -> bool:
    return await ensure_indicator_snapshot_ready(ctx)

def _compare_and_merge_market_data_freshness(symbol: Optional[str] = None, primary_data: dict = None, secondary_data: dict = None, source_name: str = "secondary") -> dict:
    """Compare freshness of market data from two sources and merge the fresher values."""
    if not secondary_data or not isinstance(secondary_data, dict):
        return primary_data
    if not primary_data:
        primary_data = {}
    try:
        merged = primary_data.copy()
        timeframes = ['3m', '15m', '1h', '4h', 'D']
        for tf in timeframes:
            primary_ts_key = f'timestamp_{tf}'
            secondary_ts_key = f'timestamp_{tf}'
            primary_ts = None
            secondary_ts = None
            if primary_ts_key in primary_data and primary_data[primary_ts_key]:
                try:
                    normalized_primary = _normalize_timestamp_to_z(primary_data[primary_ts_key]) if isinstance(primary_data[primary_ts_key], str) else primary_data[primary_ts_key]
                    primary_ts = isoparse(normalized_primary) if isinstance(normalized_primary, str) else normalized_primary
                    if primary_ts.tzinfo is None:
                        primary_ts = primary_ts.replace(tzinfo=timezone.utc)
                except Exception:
                    pass
            if secondary_ts_key in secondary_data and secondary_data[secondary_ts_key]:
                try:
                    normalized_secondary = _normalize_timestamp_to_z(secondary_data[secondary_ts_key]) if isinstance(secondary_data[secondary_ts_key], str) else secondary_data[secondary_ts_key]
                    secondary_ts = isoparse(normalized_secondary) if isinstance(normalized_secondary, str) else normalized_secondary
                    if secondary_ts.tzinfo is None:
                        secondary_ts = secondary_ts.replace(tzinfo=timezone.utc)
                except Exception:
                    pass
            use_secondary = False
            if secondary_ts and primary_ts:
                use_secondary = secondary_ts >= primary_ts
            elif secondary_ts and not primary_ts:
                use_secondary = True
            if use_secondary:
                tf_prefixes = [f'stoch_k_{tf}', f'stoch_d_{tf}', f'dc_high_{tf}', f'dc_low_{tf}', f'wt1_{tf}', f'wt2_{tf}', f'rsi_{tf}', f'mfi_{tf}', f'atr_{tf}', f'ha_{tf}', f'sma_200_{tf}', f'ema_20_{tf}', f'ema_50_{tf}', f'close_{tf}', f'high_{tf}', f'low_{tf}']
                for key_prefix in tf_prefixes:
                    if key_prefix in secondary_data:
                        merged[key_prefix] = secondary_data[key_prefix]
                    key_prev = f'{key_prefix}_prev'
                    if key_prev in secondary_data:
                        merged[key_prev] = secondary_data[key_prev]
                if secondary_ts_key in secondary_data:
                    merged[primary_ts_key] = secondary_data[secondary_ts_key]
        return merged
    except Exception as e:
        logger.debug(f"Error comparing market data freshness for {symbol}: {e}")
        return primary_data

def _get_with_staleness_check(ind_dict: dict, key: str, default):
    """Get indicator with timeframe staleness check"""
    thresholds = {'3m': 300, '15m': 1200, '1h': 5400, '4h': 16800, 'D': 86400}
    for tf, secs in thresholds.items():
        if f'_{tf}' in key and f'timestamp_{tf}' in ind_dict:
            try:
                ts_str = ind_dict[f'timestamp_{tf}']
                normalized_ts = _normalize_timestamp_to_z(ts_str) if isinstance(ts_str, str) else ts_str
                ts_dt = isoparse(normalized_ts) if isinstance(normalized_ts, str) else normalized_ts
                if ts_dt.tzinfo is None:
                    ts_dt = ts_dt.replace(tzinfo=timezone.utc)
                if (datetime.now(timezone.utc) - ts_dt).total_seconds() > secs: 
                    return _get_smart_default(key, default)
            except Exception: return _get_smart_default(key, default)
    return ind_dict.get(key, default)

def _coerce_indicator_epoch(value: Any) -> Optional[float]:
    """ Safely convert a timestamp value (string, datetime, int, float) to a unix epoch float. Returns None if conversion fails. """
    if value is None: 
        return None
    if isinstance(value, (int, float)):
        try: 
            val = float(value)
            if val > 32503680000: 
                val /= 1000.0
            return val
        except Exception: return None
    if isinstance(value, datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        return value.timestamp()
    if isinstance(value, str):
        val = value.strip()
        if not val: return None
        try:
            numeric = float(val)
            if numeric > 32503680000: numeric /= 1000.0
            return numeric
        except ValueError:
            pass
        try:
            if val.endswith('Z'): val = val.replace('Z', '+00:00')
            dt = datetime.fromisoformat(val)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=timezone.utc)
            return dt.timestamp()
        except ValueError:
            try:
                from dateutil.parser import isoparse
                dt = isoparse(val)
                if dt.tzinfo is None: dt = dt.replace(tzinfo=timezone.utc)
                return dt.timestamp()
            except Exception: pass
    return None

def _get_smart_default(key: str, default_value=None):
    """ Smart defaults without file reading or complex fallbacks """
    if 'stoch_k' in key or 'stoch_d' in key:
        return 50.0
    elif 'ha_' in key:
        return 'neutral'
    elif key.startswith('wt') or 'wt1' in key or 'wt2' in key:
        return 0.0
    elif 'crossover' in key or 'crossunder' in key:
        return False
    elif any(x in key for x in ['dc_', 'sma_', 'ema_', 'atr_']):
        return 0.0
    elif 'rsi' in key or 'mfi' in key:
        return 50.0
    elif any(x in key for x in ['0market_sentiment']):
        return 0.0
    elif key == '0sentiment_rank':
        return -1
    elif key in ['0is_top_sentiment', '0is_bottom_sentiment']:
        return False
    elif key == '0sentiment_classification':
        return 'NEUTRAL'
    elif 'volume' in key:
        return 1.0
    return default_value

def _clean_symbol_for_lookup(complex_symbol: str) -> str:
    s = str(complex_symbol)
    if ':' in s: s = s.split(':')[-1]
    s = s.replace('_LONG', '').replace('_SHORT', '')
    return s.strip().upper()

def _parse_iso_or_float(val):
    """Helper to get a float timestamp from mixed data types."""
    if not val: return 0.0
    try:
        if isinstance(val, (int, float)): 
            return float(val)
        if isinstance(val, str):
            dt = datetime.fromisoformat(val.replace('Z', '+00:00'))
            return dt.timestamp()
    except Exception: pass
    return 0.0

async def _refresh_cold_data_cache(trade_manager):
    """Scans for the freshest JSON file."""
    global _COLD_DATA_CACHE, _LAST_COLD_CHECK, _LAST_LOADED_FILE
    now = time.time()
    if (now - _LAST_COLD_CHECK) < 5.0: return
    _LAST_COLD_CHECK = now
    try:
        data_dir = config.DATA_DIR
        if not isinstance(data_dir, Path): data_dir = Path(data_dir)
        search_pat = os.path.join(str(config.DATA_DIR), "market_data_*.json")
        candidates = [Path(p) for p in glob.glob(search_pat)]
        target = sorted(candidates, key=lambda p: p.name, reverse=True)[0] if candidates else data_dir/"latest_market_data.json"
        if target.exists() and target != _LAST_LOADED_FILE:
            async with aiofiles.open(target, "rb") as f:
                content = await f.read()
                if content:
                    _COLD_DATA_CACHE = orjson.loads(content)
                    _LAST_LOADED_FILE = target
    except Exception: pass

async def ii(trade_manager: Optional["MultiAccountTradeManager"] = None, raw_symbol: Optional[str] = None) -> dict:
    """THE LIFELINE: Fetches indicators with priority: Bridge (SharedMem) -> Redis -> JSON File."""
    if not raw_symbol: return {}
    sym = raw_symbol.strip().upper()
    if ':' in sym: sym = sym.split(':')[-1]
    sym = sym.replace('_LONG', '').replace('_SHORT', '')
    now = time.time()
    result = {}
    hot_cache = getattr(trade_manager, 'hot_data_cache', {})
    hot_data = hot_cache.get(sym)
    if isinstance(hot_data, dict):
        rcv_ts = hot_data.get('_rcv_ts', 0)
        if (now - rcv_ts) < 6.0:
            result = hot_data.copy()
            trade_manager.indicators_source_label = "bridge"
    if not result and trade_manager:
        rm = getattr(trade_manager, 'redis_manager', None)
        if rm and hasattr(rm, 'connections') and rm.connections:
            try:
                client = rm.connections.get("local")
                if client:
                    hot_raw = await asyncio.wait_for(client.get(f"hot_metrics:{sym}"), timeout=2.0)
                    if hot_raw:
                        if isinstance(hot_raw, bytes): hot_raw = hot_raw.decode('utf-8')
                        parsed = orjson.loads(hot_raw)
                        if isinstance(parsed, dict):
                            result = parsed.copy()
                            trade_manager.indicators_source_label = "redis_hot"
            except Exception: pass
    if not result:
        snapshot = getattr(trade_manager, 'indicators_snapshot', {})
        bulk_data = snapshot.get(sym)
        if isinstance(bulk_data, dict):
            result = bulk_data.copy()
            trade_manager.indicators_source_label = trade_manager.indicators_source_label or "snapshot"
    if not result:
        try:
            latest_file = _get_latest_market_data_file()
            if latest_file:
                with open(latest_file, "rb") as f:
                    file_content = f.read()
                    if file_content:
                        full_data = orjson.loads(file_content)
                        if isinstance(full_data, dict) and sym in full_data:
                            result = full_data[sym].copy()
                            trade_manager.indicators_source_label = "json_file"
        except Exception: pass
    if result:
        mapping = { 'k_1m': 'stoch_k_1m', 'd_1m': 'stoch_d_1m', 'k_3m': 'stoch_k_3m', 'd_3m': 'stoch_d_3m', 'k_1m_prev': 'stoch_k_1m_prev', 'd_1m_prev': 'stoch_d_1m_prev', 'k_3m_prev': 'stoch_k_3m_prev', 'd_3m_prev': 'stoch_d_3m_prev', 'price': 'current_price', 'close': 'current_price' }
        for s_key, val in list(result.items()):
            if s_key in mapping: result[mapping[s_key]] = val
        hot_ts_val = result.get('_tick_ts') or result.get('ts') or result.get('time')
        if hot_ts_val:
            try:
                dt_obj = safe_datetime(hot_ts_val)
                if dt_obj: result['timestamp_1m'] = dt_obj.isoformat().replace('+00:00', 'Z')
            except Exception: pass
    return result if isinstance(result, dict) else {}

async def ensure_indicator_snapshot_ready(ctx: dict, max_latency: float = 0.5, stale_seconds: float = 300) -> dict:
    """ Fetches the latest indicators using the Unified Injector (ii). """
    trade_manager = ctx.get('trade_manager')
    symbol = ctx.get('symbol')
    if not trade_manager or not symbol: return {}
    indicators = await ii(trade_manager, symbol)
    ctx['indicators'] = indicators
    return indicators

def _check_leaderboard_allowed(trade_manager: "MultiAccountTradeManager", symbol: Optional[str] = None, position_side: Optional[str] = None, account_key: Optional[str] = None, position_key: Optional[str] = None) -> bool:
    if not position_key:
        if not symbol or not position_side or not account_key: return False
        position_key = f"{account_key}:{symbol.strip().upper()}_{position_side.strip().upper()}"
    try:
        service = getattr(trade_manager, 'positions_service', None)
        if service:
            acct_pos = service.positions_by_account.get(account_key, {})
            pos = acct_pos.get(position_key)
            if pos and abs(safe_fetch_float(getattr(pos, 'positionAmt', 0.0), 0.0)) > 0:
                return True
        local_pos = trade_manager.positions.get(position_key)
        if local_pos and abs(safe_fetch_float(getattr(local_pos, 'positionAmt', 0.0), 0.0)) > 0:
            return True
    except Exception: pass
    if hasattr(trade_manager, 'tradeable_keys') and trade_manager.tradeable_keys:
        return position_key in trade_manager.tradeable_keys
    return False

async def _handle_stale_indicator_snapshot(ctx: dict, *, elapsed: Optional[float], age: Optional[float], ts_key: Optional[str], ts_value: Optional[Any], threshold: float, warn_threshold: float) -> None:
    trade_manager = ctx.get('trade_manager'); logger = ctx.get('logger'); position_key = ctx.get('position_key'); symbol = ctx.get('symbol'); account_key = ctx.get('account_key')
    if logger:
        parts = []
        if elapsed is not None: parts.append(f"elapsed={elapsed:.3f}s")
        if age is not None: parts.append(f"age={age:.1f}s>{threshold:.1f}s")
        source_label = getattr(trade_manager, 'indicators_source_label', None)
        if source_label:
            parts.append(f"source={source_label}")
        if ts_key:
            if isinstance(ts_value, (int, float, str)):
                parts.append(f"ts={ts_key}({ts_value})")
            else:
                parts.append(f"ts={ts_key}")
        payload_ts = ctx.get('payload_timestamp')
        if isinstance(payload_ts, datetime):
            parts.append(f"payload_ts={payload_ts.isoformat().replace('+00:00','Z')}")
        should_warn = age is None or age >= warn_threshold
        message = f"[{position_key or symbol}] INDICATOR_SNAPSHOT_STALE {' '.join(parts) if parts else ''}"
        if should_warn:
            logger.warning(message)
        else:
            logger.debug(message)
    throttle = getattr(trade_manager, '_indicator_refresh_timestamps', None)
    now_ts = time.time(); throttle_key = position_key or symbol
    if throttle is not None:
        last = throttle.get(throttle_key, 0.0)
        if now_ts - last < 1.0: return
        throttle[throttle_key] = now_ts

    async def _refresh_and_requeue():
        try:
            await trade_manager.force_refresh_all_indicators()
        except Exception as exc:
            logger.error(f"[{position_key or symbol}] indicator refresh task failed: {exc}")
        order_queue = getattr(trade_manager, 'order_queue', None)
        if order_queue and position_key and account_key:
            try:
                allowed = filter_monitor_keys(trade_manager, account_key, position_key)
                if not allowed: return
                await monitor_entries(order_queue, trade_manager, account_key, position_keys=allowed, event_type="indicator_refresh", is_priority_add=False, force=True)
            except Exception as queue_err:
                logger.error(f"[{position_key}] indicator requeue failed: {queue_err}")
    try:
        asyncio.create_task(_refresh_and_requeue())
    except RuntimeError:
        await _refresh_and_requeue()

def tf(indicators: dict, timeframe: str, keys_with_defaults: list[tuple[str, object]], symbol: Optional[str] = None):
    """Lightweight timeframe helper used by confirmation logic."""
    i=indicators
    return tuple(i.get(f"{name}_{timeframe}", default) if isinstance(indicators, dict) else default for name, default in keys_with_defaults)

