    async def _attempt_json_repair(self, content: str) -> Optional[str]:
        if not content or not isinstance(content, str):
            return types.NoneType
        if isinstance(content, bytes):
            try:
                content = content.decode('utf-8', errors='ignore')
            except Exception:
                return None
        if not content or not isinstance(content, str):
            return None
        content = content.strip()
        if not content:
            return None
        try:
            json.loads(content)
            return content 
        except json.JSONDecodeError:
            lines = content.splitlines()
            fixed_lines = []
            for i, line in enumerate(lines):
                line = line.rstrip()
                if line.endswith(','):
                    line = line[:-1].rstrip()
                fixed_lines.append(line)
            fixed_content = '\n'.join(fixed_lines)
            try:
                json.loads(fixed_content)
                return fixed_content
            except json.JSONDecodeError:
                pass 
        try:
            start_brace = min( content.find('{'), content.find('['), key=lambda x: float('inf') if x == -1 else x )
            end_brace = max( content.rfind('}'), content.rfind(']') )
            if start_brace != -1 and end_brace != -1 and end_brace > start_brace:
                extracted = content[start_brace:end_brace+1]
                json.loads(extracted) # Test if valid
                return extracted
        except (json.JSONDecodeError, ValueError):
            pass
        return None 

    def _check_account_allowed(self, account_key: Optional[str] = None) -> bool:
        if not account_key or not hasattr(self, '_allowed_accounts'):
            return False
        if not self._allowed_accounts:
            return True
        return account_key in self._allowed_accounts

    async def _mark_positions_dirty(self):
        asyncio.create_task(self._check_and_reload_stale_positions())

    async def _check_and_reload_stale_positions(self):
        if self.positions_service:
            return
        try:
            now = datetime.now(timezone.utc)
            stale_positions = []
            stale_threshold = timedelta(seconds=12.0)
            ttl = stale_threshold.total_seconds()
            for position_key, position in self.positions.items():
                if not position:
                    continue
                if abs(safe_float(getattr(position, "positionAmt", 0.0), 0.0)) < 1e-9:
                    continue
                position_ts = self._position_update_timestamps.get(position_key) or getattr(position, "last_updated", None)
                if isinstance(position_ts, str):
                    try:
                        position_ts = isoparse(position_ts)
                    except Exception:
                        position_ts = None
                if isinstance(position_ts, datetime):
                    if position_ts.tzinfo is None:
                        position_ts = position_ts.replace(tzinfo=timezone.utc)
                    age = (now - position_ts).total_seconds()
                    if age <= ttl:
                        continue
                else:
                    age = float("inf")
                stale_positions.append((position_key, position, age))
            if stale_positions:
                now_ts = now.timestamp()
                if now_ts - self._last_stale_reload_ts < 15.0:
                    logger.debug(f"[stale_mark_price] {len(stale_positions)} positions detected but reload suppressed (cooldown active)")
                    return
                self._last_stale_reload_ts = now_ts
                logger.debug(f"⚠️ Found {len(stale_positions)} positions stale (>12s), reloading from disk/Redis (ez_manage only reads positions, never modifies them). Processing continues normally.")
                stale_keys = [position_key for position_key, _, _ in stale_positions]

                def _collect_stale(keys_to_check: List[str]) -> List[Tuple[str, Position, float]]:
                    refreshed: List[Tuple[str, Position, float]] = []
                    ref_now = datetime.now(timezone.utc)
                    for position_key in keys_to_check:
                        pos = self.positions.get(position_key)
                        if not pos or not getattr(pos, "symbol", None):
                            continue
                        position_ts = self._position_update_timestamps.get(position_key) or getattr(pos, "last_updated", None)
                        if isinstance(position_ts, str):
                            try:
                                position_ts = isoparse(position_ts)
                            except Exception:
                                position_ts = None
                        if isinstance(position_ts, datetime):
                            if position_ts.tzinfo is None:
                                position_ts = position_ts.replace(tzinfo=timezone.utc)
                            age_val = (ref_now - position_ts).total_seconds()
                        else:
                            age_val = float("inf")
                        if age_val > ttl:
                            refreshed.append((position_key, pos, age_val))
                    return refreshed
                try:
                    asyncio.create_task(self.refresh_from_files_once())
                    await asyncio.sleep(0.1)
                    still_stale_entries = _collect_stale(stale_keys)
                    if still_stale_entries:
                        try:
                            asyncio.create_task(self.load_all_positions())
                            await asyncio.sleep(0.1)
                        except Exception as full_reload_err:
                            logger.error(f"[stale_mark_price] Full position reload failed: {full_reload_err}")
                        still_stale_entries = _collect_stale(stale_keys)
                    if still_stale_entries:
                        logger.debug(f"[CRITICAL_STALE_POSITIONS] {len(still_stale_entries)} positions STILL stale after reloading from disk/Redis: {[(position_key, f'{age:.1f}s') for position_key, _, age in still_stale_entries[:5]]}. Positions will be reloaded again on next cycle (ez_manage only reads from disk/Redis, never modifies positions). Processing continues normally - stale positions do NOT block monitor/process/high_gain/evaluate_reentry/augmentations.")
                except Exception as reload_err:
                    logger.error(f"[_che ck_and_reload_stale_positions] Reload failed: {reload_err}")
        except Exception as e:
            logger.debug(f"[_che ck_and_reload_stale_positions] Error: {e}")

    def _ensure_account_positions_cache(self, account_key: Optional[str]) -> Dict[str, Position]:
        if not account_key or not isinstance(account_key, str):
            return {}
        if account_key not in self._allowed_accounts:
            return {}
        prefix = f"{account_key.upper()}:"
        fresh = {key: position for key, position in self.positions.items() if isinstance(key, str) and key.upper().startswith(prefix) and isinstance(position, Position)}
        acct = self.positions_by_account.setdefault(account_key, {})
        for position_key, pos_obj in fresh.items(): acct[position_key] = pos_obj; self.positions[position_key] = pos_obj
        return acct

    def _get_position_obj(self, position_key: str, account_key: Optional[str] = None) -> Optional[Position]:
        if not isinstance(position_key, str):
            return None
        cached = self.positions.get(position_key)
        if cached:
            return cached
        derived_account = account_key
        if not derived_account:
            try:
                derived_account, _, _ = parse_position_key(position_key)
            except Exception:
                derived_account = None
        if derived_account:
            if derived_account in self._allowed_accounts:
                account_positions = self._ensure_account_positions_cache(derived_account)
                candidate = account_positions.get(position_key)
                if candidate:
                    return candidate
        for account_key in self._allowed_accounts.intersection(set(getattr(config, 'ACCOUNT_KEYS', []))):
            account_positions = self.positions_by_account.get(account_key, {})
            candidate = account_positions.get(position_key)
            if candidate:
                return candidate
        return None

    def get_positions_by_account(self, account_key: Optional[str], side: Optional[str] = None) -> Dict[str, Position]:
        positions = self._ensure_account_positions_cache(account_key)
        if side is None:
            return positions
        side_upper = str(side).upper()
        return {key: value for key, value in positions.items() if isinstance(value, Position) and getattr(value, "position_side", "").upper() == side_upper}

    def get_account_positions(self, account_key: Optional[str], side: Optional[str] = None):
        return self.get_positions_by_account(account_key, side)

    async def get_position(self, position_key: str, max_age_s: Optional[float] = None) -> Optional[Position]:
        """Read the authoritative Position object.
        2026-04-16: positions_service.positions is the WS-fresh source of truth; self.positions
        is a local mirror that drifts 1-3s during fill propagation. When max_age_s is provided,
        always re-read from positions_service (ignoring stale local cache) so race-sensitive
        callers (execute_now preflight, hedge existence checks) see the freshest state.
        Dead code paths (disk fallback, Redis read) removed — were unreachable + "KILLED" noted in comments.
        """
        # Freshness-sensitive path: always go to the service dict first.
        if max_age_s is not None and self.positions_service:
            svc_pos = self.positions_service.positions.get(position_key)
            if svc_pos is not None:
                self.positions[position_key] = svc_pos
                return svc_pos
            # If service has no record, fall through to local cache (legacy behavior).
        pos = self.positions.get(position_key)
        if pos:
            return pos
        if self.positions_service:
            pos = self.positions_service.positions.get(position_key)
            if pos:
                self.positions[position_key] = pos
                return pos
        return None

    async def _recover_position_safe(self, position_key: str, account_key: str = None, symbol: str = None, position_side: str = None) -> Optional[Position]:
        position = await self.get_position(position_key)
        if position: return position
        if not account_key or not symbol or not position_side:
            try: account_key, symbol, position_side = parse_position_key(position_key)
            except Exception: pass
        if not account_key: return None
        if account_key not in self._allowed_accounts: return None
        try:
            bucket = await self._load_positions_from_redis(account_key)
            if bucket and position_key in bucket:
                pos = bucket[position_key]
                self.positions[position_key] = pos
                if account_key not in self.positions_by_account: self.positions_by_account[account_key] = {}
                self.positions_by_account[account_key][position_key] = pos
                return pos
        except Exception: pass
        try:
            bucket = await self._load_positions_quick_from_files(account_key)
            if bucket and position_key in bucket:
                pos = bucket[position_key]
                self.positions[position_key] = pos
                if account_key not in self.positions_by_account: self.positions_by_account[account_key] = {}
                self.positions_by_account[account_key][position_key] = pos
                return pos
        except Exception: pass
        if symbol and position_side:
            if position_key not in self.positions_by_account.get(account_key, {}):
                restored = await self.ensure_position_present(account_key, symbol, position_side, position_key)
                if restored: return restored
            for other_account in self._allowed_accounts:
                if other_account == account_key: continue
                other_position_key = f"{other_account}:{symbol}_{position_side}"
                candidate = await self.get_position(other_position_key) or self.positions_by_account.get(other_account, {}).get(other_position_key)
                if candidate: return candidate
        return None

    def clean_symbols(self, symbol_list):
        """Clean and normalize symbol list by stripping whitespace and converting to uppercase."""
        return [symbol.strip().upper() for symbol in symbol_list if isinstance(symbol, str) and symbol.strip()]

    def ensure_position_floats(self, position: Position) -> Position:
        """Ensure all numeric values in a Position object are floats, not strings"""
        if position is None:
            return position
        position_dict = position.to_dict()
        numeric_fields = ['entry_price', 'mark_price', 'positionAmt', 'initial_quantity', 'gain', 'max_gain', 'prev_gain', 'max_quantity', 'last_augmentation_amount', 'last_augmentation_price', 'last_reduction_amount', 'last_reduction_price', 'max_positionSize', 'realized_pnl', 'unrealized_pnl_USD']
        for key, value in position_dict.items():
            if key in ['symbol', 'position_side', 'last_signal', 'augment_reason', 'reduction_reason', 'last_augmentation_time', 'last_reduction_time', 'opened_at', 'last_updated', 'prev_gain_last_updated', 'mark_price_last_updated']:
                continue # Skip non-numeric fields
            if key in numeric_fields:
                if value is None:
                    position_dict[key] = 0.0
                elif isinstance(value, str) and value.replace('.', '').replace('-', '').isdigit():
                    try:
                        position_dict[key] = safe_fetch_float(value, 0.0)
                    except Exception:
                        position_dict[key] = 0.0
        return Position.from_dict(position_dict)

    def validate_positions_floats(self):
        """Validate and fix all positions in positions_by_account to ensure numeric values are floats"""
        fixed_count = 0
        monitored_account_keys = set(self.accounts.keys())
        for account_key in monitored_account_keys:
            positions_dict = self.positions_by_account.get(account_key, {})
            for position_key, position in positions_dict.items():
                if position is None:
                    continue
                position_dict = position.to_dict()
                needs_fix = False
                for key, value in position_dict.items():
                    if key in ['symbol', 'position_side', 'last_signal', 'augment_reason', 'reduction_reason']:
                        continue
                    if isinstance(value, str) and value.replace('.', '').replace('-', '').replace(',', '').isdigit():
                        needs_fix = True
                        break
                if needs_fix:
                    fixed_position = self.ensure_position_floats(position)
                    if fixed_position:
                        positions_dict[position_key] = fixed_position
                        self.positions[position_key] = fixed_position
                        fixed_count += 1
        if fixed_count > 0:
            logger.debug(f"[validate_positions_floats] Fixed {fixed_count} positions with string numeric values")
        return fixed_count

    async def load_reentry_data_for_position(self, position_key: str):
        try:
            account_key, _, _ = parse_position_key(position_key)
        except ValueError:
            logger.error(f"[load_reentry_data_for_position] Invalid position_key: {position_key}")
            return
        now = datetime.now(timezone.utc)
        last_loaded = self.reentry_data_last_loaded.get(account_key)
        if position_key in self.reentry_data and last_loaded and (now - last_loaded).total_seconds() < self.reentry_cache_refresh_seconds:
            return
        lock = await self._get_reentry_lock(account_key)
        async with lock:
            refresh_needed = position_key not in self.reentry_data
            last_loaded = self.reentry_data_last_loaded.get(account_key)
            if not refresh_needed and last_loaded and (datetime.now(timezone.utc) - last_loaded).total_seconds() < self.reentry_cache_refresh_seconds:
                return
            await self.load_reentry_data(account_key)

    def _ensure_account_file(self, account_key: Optional[str] = None, filename: str = '') -> Path:
        base = Path(self.config.BASE_PATH) / account_key
        try:
            base.mkdir(parents=True, exist_ok=True)
            try:
                os.chmod(base, 0o775)
            except PermissionError:
                pass
        except Exception as e:
            logger.error(f"[fallback_io] Failed to prepare directory for {account_key}: {e}")
        path = base / filename
        if not path.exists():
            try:
                path.touch()
            except PermissionError:
                pass
            except Exception as e:
                logger.error(f"[fallback_io] Failed to create file {path}: {e}")
        try:
            os.chmod(path, 0o664)
        except PermissionError:
            pass
        return path

    def _normalize_position_key(self, account_key: Optional[str] = None, raw_key: str = '', position_side: str = 'LONG') -> Optional[str]:
        if not isinstance(raw_key, str):
            return None
        key = raw_key if raw_key.startswith(f"{account_key}:") else (f"{account_key}:{raw_key}" if ":" not in raw_key and "_" in raw_key else raw_key)
        if not key.startswith(f"{account_key}:"):
            return None
        if key.count(":") != 1 or key.count("_") < 1:
            return None
        side = key.rsplit("_", 1)[-1].upper()
        if side != position_side.upper():
            return None
        return key

    async def _load_positions_from_files(self, account_key: Optional[str] = None) -> Dict[str, Position]:
        # positions_service bailout removed — refresh from Redis/files is backup
        if account_key not in self._allowed_accounts:
            logger.warning(f"[_load_positions_from_files] BLOCKED: Account '{account_key}' not in allowed accounts {self._allowed_accounts}")
            return {}
        if account_key not in config.ACCOUNT_KEYS: return {}
        tracked_mtime = self._positions_file_mtimes.get(account_key, 0.0)
        file_stats: List[Tuple[Path, float, str]] = []
        for side in ("LONG", "SHORT"):
            file_path = self._ensure_account_file(account_key, f"{side.lower()}_positions.json")
            try:
                mtime = file_path.stat().st_mtime
            except OSError:
                mtime = 0.0
            file_stats.append((file_path, mtime, side))
        latest_mtime = max((stat[1] for stat in file_stats), default=0.0)
        if latest_mtime <= tracked_mtime and self.get_positions_by_account(account_key):
            return {}
        bucket: Dict[str, Position] = {}
        sanitized_count = 0
        for file_path, mtime, side in file_stats:
            age_seconds = _file_age_seconds(file_path)
            if age_seconds > LOCAL_DATA_MAX_AGE:
                logger.warning(f"[load_positions:file] {file_path.name} age={age_seconds:.3f}s exceeds {LOCAL_DATA_MAX_AGE:.3f}s; loading anyway")
            disk_data = await load_json_safe(file_path, account_key)
            if not isinstance(disk_data, dict):
                continue
            for position_key, payload in disk_data.items():
                if not isinstance(payload, dict):
                    continue
                try:
                    pos_obj = Position.from_dict(payload)
                except Exception as exc:
                    logger.debug(f"[load_positions:file] Parse failed for {position_key}: {exc!r}")
                    continue
                if isinstance(mtime, (int, float)) and mtime > 0:
                    file_ts = datetime.fromtimestamp(mtime, tz=timezone.utc)
                    if not isinstance(pos_obj.last_updated, datetime):
                        pos_obj.last_updated = file_ts
                    if not isinstance(pos_obj.mark_price_last_updated, datetime):
                        pos_obj.mark_price_last_updated = file_ts
                    self._position_update_timestamps[position_key] = file_ts
                bucket[position_key] = self.ensure_position_floats(pos_obj)
        if bucket:
            self._positions_file_mtimes[account_key] = latest_mtime
        return bucket

    async def _load_position_files_payload(self, account_key: str, long_path: Path, short_path: Path) -> Tuple[Dict[str, Any], Optional[datetime]]:
        # positions_service bailout removed — refresh from Redis/files is backup
        combined: Dict[str, Any] = {}
        ts_candidates: List[datetime] = []
        for path, default_side in ((long_path, "LONG"), (short_path, "SHORT")):
            best_path = path
            best_mtime = None
            try:
                if path.exists():
                    file_mtime = path.stat().st_mtime
                    file_age = time.time() - file_mtime
                    best_path = path
                    best_mtime = file_mtime
                    updated_file = path.parent / f"{default_side.lower()}_positions_updated.json"
                    if updated_file.exists():
                        try:
                            updated_mtime = updated_file.stat().st_mtime
                            updated_age = time.time() - updated_mtime
                            if updated_age <= 12.0: # Updated file is fresh (within 12s)
                                logger.debug(f"[CRITICAL_STALE_DICT][{account_key}:{default_side}] Using fresh {updated_file.name} (age: {updated_age:.1f}s) instead of {path.name} (age: {file_age:.1f}s)")
                                best_path = updated_file
                                best_mtime = updated_mtime
                            elif file_age > 10.0:
                                alt_files = [path.parent / f"{default_side.lower()}_positions_changed.json", path.parent / f"{default_side.lower()}_positions_active.json"]
                                for alt_path in alt_files:
                                    if alt_path.exists():
                                        try:
                                            alt_mtime = alt_path.stat().st_mtime
                                            alt_age = time.time() - alt_mtime
                                            if alt_age <= 10.0:
                                                logger.warning(f"[CRITICAL_STALE_DICT][{account_key}:{default_side}] {path.name} is {file_age:.1f}s old (>10s) but {alt_path.name} is {alt_age:.1f}s old - loading from {alt_path.name} instead!")
                                                best_path = alt_path
                                                best_mtime = alt_mtime
                                                break
                                        except Exception:
                                            pass
                        except Exception:
                            pass
                    elif file_age > 20.0:
                        alt_files = [path.parent / f"{default_side.lower()}_positions_changed.json", path.parent / f"{default_side.lower()}_positions_active.json"]
                        for alt_path in alt_files:
                            if alt_path.exists():
                                try:
                                    alt_mtime = alt_path.stat().st_mtime
                                    alt_age = time.time() - alt_mtime
                                    if alt_age <= 20.0:
                                        logger.warning(f"[CRITICAL_STALE_DICT][{account_key}:{default_side}] {path.name} is {file_age:.1f}s old (>20s) but {alt_path.name} is {alt_age:.1f}s old - loading from {alt_path.name} instead!")
                                        best_path = alt_path
                                        best_mtime = alt_mtime
                                        break
                                except Exception:
                                    pass
                else:
                    alt_files = [path.parent / f"{default_side.lower()}_positions_updated.json", path.parent / f"{default_side.lower()}_positions_changed.json", path.parent / f"{default_side.lower()}_positions_active.json"]
                    for alt_path in alt_files:
                        if alt_path.exists():
                            try:
                                alt_mtime = alt_path.stat().st_mtime
                                alt_age = time.time() - alt_mtime
                                logger.warning(f"[CRITICAL_STALE_DICT][{account_key}:{default_side}] {path.name} missing, using {alt_path.name} (age: {alt_age:.1f}s)")
                                best_path = alt_path
                                best_mtime = alt_mtime
                                break
                            except Exception:
                                pass
                            except Exception:
                                pass
                if best_mtime:
                    ts_candidates.append(datetime.fromtimestamp(best_mtime, tz=timezone.utc))
            except OSError:
                pass
            data = await load_json_safe(best_path, account_key)
            if not isinstance(data, dict):
                continue
            for position_key, payload in data.items():
                if not isinstance(payload, dict):
                    continue
                combined[position_key] = payload
        snapshot_ts = _snapshot_timestamp(combined)
        if snapshot_ts:
            ts_candidates.append(snapshot_ts)
        file_ts = max(ts_candidates) if ts_candidates else None
        return combined, file_ts

    def _split_positions_payload(self, account_key: str, payload: Dict[str, Any]) -> Tuple[Dict[str, Any], Dict[str, Any]]:
        longs: Dict[str, Any] = {}
        shorts: Dict[str, Any] = {}
        if not isinstance(payload, dict):
            return longs, shorts
        prefix = f"{account_key}:"
        for raw_key, entry in payload.items():
            if not isinstance(entry, dict):
                continue
            key = str(raw_key)
            if not key.startswith(prefix):
                continue
            suffix = key.rsplit("_", 1)[-1].upper() if "_" in key else ""
            if suffix == "LONG":
                longs[key] = entry
            elif suffix == "SHORT":
                shorts[key] = entry
        return longs, shorts

    def _positions_payload_to_bucket(self, account_key: str, payload: Dict[str, Any]) -> Dict[str, Position]:
        bucket: Dict[str, Position] = {}
        if not isinstance(payload, dict):
            return bucket
        prefix = f"{account_key}:"
        for position_key, entry in payload.items():
            if not isinstance(position_key, str) or not position_key.startswith(prefix):
                continue
            if not isinstance(entry, dict):
                continue
            try:
                pos_obj = Position.from_dict(entry)
            except Exception:
                continue
            bucket[position_key] = self.ensure_position_floats(pos_obj)
        return bucket

    async def _write_positions_payload_to_files(self, account_key: str, payload: Dict[str, Any]) -> None:
        logger.warning(f"[NOT_ALLOWED] ez_manage.py is NOT_ALLOWED to write positions to disk. Attempted write for {account_key} was not_allowed.")
        return

    async def _apply_positions_payload(self, account_key: str, payload: Dict[str, Any], snapshot_ts: Optional[datetime]) -> bool:
        if not isinstance(payload, dict):
            return False
        account_positions = self.positions_by_account.setdefault(account_key, {})
        updated = False
        now_dt = datetime.now(timezone.utc)
        for position_key, entry in payload.items():
            if not isinstance(entry, dict):
                continue
            ws_update_ts = self._ws_update_timestamps.get(position_key)
            if ws_update_ts:
                age_seconds = (now_dt - ws_update_ts).total_seconds()
                if age_seconds < 60.0:
                    if self.logger:
                        self.logger.debug(f"[positions_sync][skip_stale] 🔒 Protected {position_key} from stale payload (WS updated {age_seconds:.1f}s ago)")
                    continue
            entry_ts_raw = entry.get('last_updated') or entry.get('updated_at') or entry.get('timestamp') or entry.get('opened_at')
            entry_ts = safe_datetime(entry_ts_raw, snapshot_ts) if entry_ts_raw or snapshot_ts else None
            if entry_ts:
                entry_ts = ensure_tz(entry_ts)
            existing_position = account_positions.get(position_key) or self.positions.get(position_key)
            existing_ts = self._position_update_timestamps.get(position_key)
            if existing_ts:
                try:
                    existing_ts = ensure_tz(existing_ts)
                except Exception:
                    existing_ts = None
            if not existing_ts and existing_position and getattr(existing_position, 'last_updated', None):
                try:
                    existing_ts = ensure_tz(existing_position.last_updated)
                except Exception:
                    existing_ts = None
            if existing_ts and entry_ts and (existing_ts - entry_ts).total_seconds() > 0.25:
                if self.logger:
                    self.logger.debug(f"[positions_sync][skip_stale] {position_key} existing_ts={existing_ts.isoformat()} entry_ts={entry_ts.isoformat()}")
                continue
            try:
                position_obj = Position.from_dict(entry)
            except Exception:
                continue
            existing_before = self.positions.get(position_key)
            final_position = self._assign_position_if_newer(account_key, position_key, position_obj, entry_ts or snapshot_ts)
            if final_position is position_obj and final_position is not existing_before:
                updated = True
        if updated:
            self.positions_live = True
            self.positions_source = 'redis'
            self.positions_last_sync = snapshot_ts or datetime.now(timezone.utc)
        return updated

    def _normalize_timestamp(self, ts):
        if not ts: return None
        if isinstance(ts, (int, float)):
            try: ts = datetime.fromtimestamp(float(ts), tz=timezone.utc)
            except Exception: return None
        elif isinstance(ts, str):
            try: ts = isoparse(ts)
            except Exception: return None
        if isinstance(ts, datetime) and ts.tzinfo is None: ts = ts.replace(tzinfo=timezone.utc)
        return ts if isinstance(ts, datetime) else None

    def _extract_position_timestamp(self, position):
        if not position: return None
        for attr in ("last_updated", "prev_gain_last_updated", "opened_at","mark_price_last_updated"):
            ts = getattr(position, attr, None)
            normalized = self._normalize_timestamp(ts)
            if normalized: return normalized
        return None

    def _assign_position_if_newer(self, account_key: str, position_key: str, candidate, candidate_ts=None):
        existing = self.positions.get(position_key)
        existing_ts = self._extract_position_timestamp(existing)
        new_ts = self._normalize_timestamp(candidate_ts) if candidate_ts is not None else self._extract_position_timestamp(candidate)
        if existing:
            if existing_ts and new_ts and existing_ts > new_ts:
                self.positions_by_account.setdefault(account_key, {})[position_key] = existing
                return existing
            if existing_ts and new_ts is None:
                self.positions_by_account.setdefault(account_key, {})[position_key] = existing
                return existing
        if new_ts: self._position_update_timestamps[position_key] = new_ts
        else: self._position_update_timestamps[position_key] = datetime.now(timezone.utc)
        self.positions_by_account.setdefault(account_key, {})[position_key] = candidate
        self.positions[position_key] = candidate
        return candidate

    async def _load_positions_quick_from_files(self, account_key: Optional[str] = None) -> Dict[str, Position]:
        """KILLED — never read positions from disk after startup. Dict is sole source."""
        return {}

    def _normalize_redis_payload(self, payload: Any) -> Any:
        if isinstance(payload, (bytes, bytearray, memoryview, str)):
            return safe_json_loads(payload)
        return payload

    async def _redis_get_dict(self, key: str) -> Dict[str, Any]:
        if not key:
            return {}
        if not await self.initialize_redis_manager():
            return {}
        manager = getattr(self, "redis_manager", None)
        if not manager or not hasattr(manager, "get"):
            return {}
        try:
            raw = await manager.get(key)
        except Exception as exc:
            logger.debug(f"[redis_fetch] get failed for {key}: {exc}")
            return {}
        payload = self._normalize_redis_payload(raw)
        return payload if isinstance(payload, dict) else {}

    async def _reload_single_position_fast(self, position_key: Optional[str] = None, account_key: Optional[str] = None) -> Optional[Position]:
        if not self.redis_manager or not hasattr(self.redis_manager, "get"):
            return None
        try:
            raw_payload = await self.redis_manager.get(f"positions:{account_key}")
            raw_payload = self._normalize_redis_payload(raw_payload)
        except Exception:
            return None
        if not raw_payload or not isinstance(raw_payload, dict):
            return None
        raw_positions = raw_payload
        if "positions_by_account" in raw_payload:
            per_account = raw_payload.get("positions_by_account") or {}
            raw_positions = per_account.get(account_key, {}) if isinstance(per_account, dict) else {}
        elif "positions" in raw_payload:
            raw_positions = raw_payload.get("positions") or {}
        elif "data" in raw_payload and isinstance(raw_payload.get("data"), dict):
            raw_positions = raw_payload["data"]
        if not isinstance(raw_positions, dict):
            return None
        payload = raw_positions.get(position_key)
        if not isinstance(payload, dict):
            return None
        try:
            pos_obj = Position.from_dict(payload)
            pos_obj = self.ensure_position_floats(pos_obj)
            self.positions[position_key] = pos_obj
            if account_key not in self.positions_by_account:
                self.positions_by_account[account_key] = {}
            self.positions_by_account[account_key][position_key] = pos_obj
            self._position_update_timestamps[position_key] = datetime.now(timezone.utc)
            return pos_obj
        except Exception:
            return None

    async def _load_positions_from_redis(self, account_key: Optional[str] = None) -> Dict[str, Position]:
        """KILLED — never read positions from Redis after startup. Dict is sole source."""
        return {}

    def _positions_from_snapshot_payload(self, account_key: str, snapshot_payload: Dict[str, Any]) -> Dict[str, Position]:
        if not isinstance(snapshot_payload, dict):
            return {}
        positions_payload = (snapshot_payload.get("positions_by_account") or {}).get(account_key) or {}
        bucket = {}
        if isinstance(positions_payload, dict):
            for position_key, payload in positions_payload.items():
                if not isinstance(position_key, str) or not isinstance(payload, dict):
                    continue
                try:
                    pos_obj = Position.from_dict(payload)
                except Exception as exc:
                    logger.debug(f"[load_positions:snapshot] Parse failed for {position_key}: {exc!r}")
                    continue
                bucket[position_key] = self.ensure_position_floats(pos_obj)
        return bucket

    def get_stop_file(self, account_key: str, side: str) -> Path:
        return self._ensure_account_file(account_key, f"{side.lower()}_stop_levels.json")

    def get_reentry_file(self, account_key: str, side: str) -> Path:
        return self._ensure_account_file(account_key, f"{side.lower()}_reentry.json")

    def get_ladder_file(self, account_key: str, position_side: str) -> Path:
        return self._ensure_account_file(account_key, f"{position_side.lower()}_ladder.json")

    def _get_augment_file_path(self, account_key: str) -> Path:
        return self._ensure_account_file(account_key, "augmented_positions.json")

    def _get_reduced_file_path(self, account_key: str) -> Path:
        return self._ensure_account_file(account_key, "reduced_positions.json")

    def _get_reversal_file_path(self, account_key: str) -> Path:
        return self._ensure_account_file(account_key, "reversed_positions.json")

    async def _get_reentry_lock(self, account_key: str) -> DummyLock:
        async with self._load_reentry_locks_lock:
            lock = self._load_reentry_locks.get(account_key)
            if not lock:
                lock = DummyLock()
                self._load_reentry_locks[account_key] = lock
        return lock

    def _load_all_symbols_list(self) -> list:
        try:
            symbols_path = Path(getattr(self.config, "SYMBOLS_FILE", Path(self.config.BASE_PATH) / "symbols.json"))
            if symbols_path.exists():
                try:
                    with open(symbols_path, "rb") as f:
                        data = self.safe_json_loads(f.read())
                    if isinstance(data, list):
                        return [str(s).strip().upper() for s in data if s]
                    if isinstance(data, dict) and isinstance(data.get("symbols"), list):
                        return [str(s).strip().upper() for s in data.get("symbols") if s]
                except Exception:
                    return []
        except Exception:
            return []
        return []

    def _placeholder_position(self, symbol: str, side: str) -> Position:
        payload = { "symbol": symbol, "position_side": side, "entry_price": 0.0, "mark_price": 0.0, "positionAmt": 0.0, "initial_quantity": 0.0, "gain": 0.0, "max_gain": 0.0, "prev_gain": 0.0, "max_quantity": 0.0, "last_augmentation_amount": 0.0, "last_augmentation_price": 0.0, "last_reduction_amount": 0.0, "last_reduction_price": 0.0, "max_positionSize": 0.0, "opened_at": None, "last_updated": None, "last_signal": "", "realized_pnl": 0.0, "unrealized_pnl_USD": 0.0, "was_reentered": False, "was_reduced": False, "prev_gain_last_updated": None, "augment_reason": "", "reduction_reason": "", "mark_price_last_updated": None }
        try:
            return Position.from_dict(payload)
        except Exception:
            return Position.from_dict({"symbol": symbol, "position_side": side, "positionAmt": 0.0})

    async def ensure_full_symbol_set(self) -> None:
        symbols = self._load_all_symbols_list()
        if not symbols:
            return
        for account_key in self.accounts.keys():
            self.positions_by_account.setdefault(account_key, {})
            for side in ("LONG", "SHORT"):
                for sym in symbols:
                    position_key = construct_position_key(account_key, sym, side)
                    if position_key not in self.positions_by_account[account_key]:
                        await asyncio.sleep(3)
                        if position_key not in self.positions_by_account[account_key]:
                            await asyncio.sleep(3) 
                            if position_key not in self.positions_by_account[account_key]:
                                await asyncio.sleep(30) 
                                if position_key not in self.positions_by_account[account_key]:
                                    logger.warning(f'CRITICAL {position_key} was ERASED PUTTING IN BULLSHIT ZERO BULLSHIT VALUES')
                                    logger.warning(f'CRITICAL {position_key} was ERASED PUTTING IN BULLSHIT ZERO BULLSHIT VALUES')
                                    logger.warning(f'CRITICAL {position_key} was ERASED PUTTING IN BULLSHIT ZERO BULLSHIT VALUES')
                                    pos_obj = self._placeholder_position(sym, side)
                                    self.positions_by_account[account_key][position_key] = pos_obj
                                    self.positions[position_key] = pos_obj

    async def load_stop_levels(self, account_key: Optional[str] = None, snapshot: Optional[Dict[str, Any]] = None):
        if not account_key or not isinstance(account_key, str):
            logger.error(f"[load_stop_levels] Invalid account_key: {account_key}")
            return
        if await self._load_stop_levels_from_service(account_key, snapshot):
            return
        await self._load_stop_levels_from_file(account_key)

    async def _load_stop_levels_from_service(self, account_key: str, snapshot: Optional[Dict[str, Any]] = None) -> bool:
        if not account_key or not isinstance(account_key, str):
            return False
        seen_keys: Set[str] = set()
        loaded = False
        for side in ("LONG", "SHORT"):
            redis_payload = await self._redis_get_dict(f"stop_levels:{account_key}:{side.lower()}")
            if not isinstance(redis_payload, dict) or not redis_payload:
                continue
            loaded = True
            for position_key, value_dict in redis_payload.items():
                if not isinstance(position_key, str) or not position_key.startswith(f"{account_key}:"):
                    continue
                entries = value_dict.get("stop_levels") if isinstance(value_dict, dict) else value_dict
                parsed: List[StopLevel] = []
                if isinstance(entries, list):
                    fallback_side = position_key.rsplit("_", 1)[-1] if "_" in position_key else side
                    for entry in entries:
                        if isinstance(entry, StopLevel):
                            parsed.append(entry)
                        elif isinstance(entry, dict):
                            try:
                                payload = dict(entry)
                                if "position_side" not in payload:
                                    payload["position_side"] = fallback_side
                                parsed.append(StopLevel.from_dict(payload))
                            except Exception as exc:
                                logger.debug(f"[load_stop_levels:redis] parse failed for {position_key}: {exc}")
                if parsed:
                    self.stop_levels[position_key] = parsed
                    seen_keys.add(position_key)
                else:
                    self.stop_levels.pop(position_key, None)
                    if isinstance(getattr(self, "stop_snapshot", {}), dict):
                        self.stop_snapshot.pop(position_key, None)
        if not loaded:
            return False
        for key in list(self.stop_levels.keys()):
            if key.startswith(f"{account_key}:") and key not in seen_keys:
                self.stop_levels.pop(key, None)
                if isinstance(getattr(self, "stop_snapshot", {}), dict):
                    self.stop_snapshot.pop(key, None)
        self.stop_snapshot_refresh_time = time.time()
        logger.info(f"[load_stop_levels] Redis synced {len(seen_keys)} stops for {account_key}")
        return True

    async def _load_stop_levels_from_file(self, account_key: str):
        seen_keys = set()
        loaded = 0
        for position_side in ("LONG", "SHORT"):
            file_path = self.get_stop_file(account_key, position_side)
            age_seconds = _file_age_seconds(file_path)
            if age_seconds > LOCAL_DATA_MAX_AGE:
                logger.debug(f"[load_stop_levels:file] {file_path.name} age={age_seconds:.3f}s exceeds {LOCAL_DATA_MAX_AGE:.3f}s; loading anyway")
            stop_data = await load_json_safe(file_path, account_key)
            if not isinstance(stop_data, dict):
                continue
            for raw_key, value_dict in stop_data.items():
                normalized = self._normalize_position_key(account_key, raw_key, position_side)
                if not normalized or not isinstance(value_dict, dict):
                    continue
                stop_entries = value_dict.get("stop_levels")
                if not isinstance(stop_entries, list):
                    continue
                parsed_levels = []
                for entry in stop_entries:
                    if not isinstance(entry, dict):
                        continue
                    try:
                        parsed_levels.append(StopLevel.from_dict(entry))
                    except Exception as exc:
                        logger.debug(f"[load_stop_levels] File parse failed for {normalized}: {exc}")
                if parsed_levels:
                    self.stop_levels[normalized] = parsed_levels
                    if isinstance(getattr(self, "stop_snapshot", {}), dict):
                        self.stop_snapshot[normalized] = parsed_levels
                    seen_keys.add(normalized)
                    loaded += 1
        for key in list(self.stop_levels.keys()):
            if key.startswith(f"{account_key}:") and key not in seen_keys:
                self.stop_levels.pop(key, None)
                if isinstance(getattr(self, "stop_snapshot", {}), dict):
                    self.stop_snapshot.pop(key, None)
        logger.debug(f"[load_stop_levels] File fallback loaded {loaded} stops for {account_key}")

    async def load_reentry_data(self, account_key: Optional[str] = None, snapshot: Optional[Dict[str, Any]] = None):
        if not account_key or not isinstance(account_key, str):
            logger.error(f"[load_reentry_data] Invalid account_key: {account_key}")
            return
        if await self._load_reentry_data_from_service(account_key, snapshot):
            return
        await self._load_reentry_data_from_file(account_key)

    async def load_all_extra_account_data(self, account_key: str, snapshot: Optional[Dict[str, Any]] = None):
        """Consolidated loader for all persistent account metadata."""
        await asyncio.gather(
            self.load_reentry_data(account_key, snapshot),
            self.load_stop_levels(account_key, snapshot),
            self.load_ladder_levels(account_key, snapshot),
            self.load_augmented_positions(account_key, snapshot),
            self.load_reduced_positions(account_key, snapshot),
            self.load_reversed_positions(account_key, snapshot),
            self.load_direct_high_gain(account_key, snapshot),
            return_exceptions=True
        )

    async def _load_reentry_data_from_file(self, account_key: str):
        seen_keys = set()
        loaded = 0
        iso_now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        for side in ("LONG", "SHORT"):
            file_path = self.get_reentry_file(account_key, side)
            age_seconds = _file_age_seconds(file_path)
            if age_seconds > LOCAL_DATA_MAX_AGE:
                logger.debug(f"[load_reentry_data:file] {file_path.name} age={age_seconds:.3f}s exceeds {LOCAL_DATA_MAX_AGE:.3f}s; loading anyway")
            reentry_data = await load_json_safe(file_path, account_key)
            if not isinstance(reentry_data, dict):
                continue
            for raw_key, payload in reentry_data.items():
                if not isinstance(payload, dict):
                    continue
                cleaned_key = clean_position_key(str(raw_key))
                try:
                    key_account, _, key_side = parse_position_key(cleaned_key)
                except Exception:
                    continue
                if key_account != account_key or key_side != side:
                    continue
                level = safe_float(payload.get("reentry_level") or payload.get("reentry_data", 0.0))
                amount = safe_float(payload.get("reentry_amount"))
                timestamp = payload.get("timestamp") or iso_now
                reason = str(payload.get("reason", ""))
                if level <= 0 and amount <= 0:
                    continue
                self.reentry_data[cleaned_key] = { "reentry_level": level, "reentry_amount": amount, "timestamp": timestamp, "reason": reason }
                seen_keys.add(cleaned_key)
                loaded += 1
        for key in list(self.reentry_data.keys()):
            if key.startswith(f"{account_key}:") and key not in seen_keys:
                self.reentry_data.pop(key, None)
        self.reentry_data_last_loaded[account_key] = datetime.now(timezone.utc)
        logger.debug(f"[load_reentry_data] Loaded {loaded} reentry entries for {account_key}")

    async def _load_reentry_data_from_service(self, account_key: str, snapshot: Optional[Dict[str, Any]] = None) -> bool:
        if not account_key or not isinstance(account_key, str):
            return False
        seen_keys: Set[str] = set()
        loaded = False
        for side in ("LONG", "SHORT"):
            redis_payload = await self._redis_get_dict(f"reentry_levels:{account_key}:{side.lower()}")
            if not isinstance(redis_payload, dict) or not redis_payload:
                continue
            loaded = True
            for position_key, entry in redis_payload.items():
                if not isinstance(position_key, str) or not position_key.startswith(f"{account_key}:"):
                    continue
                if not isinstance(entry, dict):
                    continue
                level = safe_float(entry.get("reentry_level", entry.get("level")))
                amount = safe_float(entry.get("reentry_amount", entry.get("amount")))
                if level <= 0 and amount <= 0:
                    continue
                ts_value = entry.get("timestamp") or entry.get("updated_at") or entry.get("created_at")
                dt = safe_datetime(ts_value)
                iso_ts = dt.strftime("%Y-%m-%dT%H:%M:%S.%fZ") if isinstance(dt, datetime) else datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
                self.reentry_data[position_key] = { "reentry_level": level, "reentry_amount": amount, "timestamp": iso_ts, "reason": str(entry.get("reason", "")) }
                seen_keys.add(position_key)
        if not loaded:
            return False
        for key in list(self.reentry_data.keys()):
            if key.startswith(f"{account_key}:") and key not in seen_keys:
                self.reentry_data.pop(key, None)
        self.reentry_data_last_loaded[account_key] = datetime.now(timezone.utc)
        logger.debug(f"[load_reentry_data] Redis synced {len(seen_keys)} entries for {account_key}")
        return True

    async def load_ladder_levels(self, account_key: Optional[str] = None, snapshot: Optional[Dict[str, Any]] = None):
        if not account_key or not isinstance(account_key, str):
            logger.error(f"[load_ladder_levels] Invalid account_key: {account_key}")
            return
        if await self._load_ladder_levels_from_service(account_key, snapshot):
            return
        await self._load_ladder_levels_from_file(account_key)

    async def _load_ladder_levels_from_file(self, account_key: str):
        seen_keys = set()
        loaded = 0
        for side in ("LONG", "SHORT"):
            file_path = self.get_ladder_file(account_key, side)
            age_seconds = _file_age_seconds(file_path)
            ladder_data = await load_json_safe(file_path, account_key)
            if not isinstance(ladder_data, dict):
                continue
            for raw_key, entry in ladder_data.items():
                normalized = self._normalize_position_key(account_key, raw_key, side)
                if not normalized:
                    continue
                if not isinstance(entry, dict):
                    continue
                levels = entry.get("levels")
                if not isinstance(levels, list) or not levels:
                    continue
                sanitized_levels = []
                for item in levels:
                    if not isinstance(item, dict):
                        continue
                    sanitized_levels.append({ "level": safe_float(item.get("level")), "quantity": safe_float(item.get("quantity")), "created_at": item.get("created_at"), "crossed": bool(item.get("crossed", False)), "stoch_reversed": bool(item.get("stoch_reversed", False)) })
                if not sanitized_levels:
                    continue
                record = { "levels": sanitized_levels, "created_at": entry.get("created_at"), "is_long": bool(entry.get("is_long", side.upper() == "LONG")), "symbol": entry.get("symbol"), "account_key": entry.get("account_key", account_key) }
                self.ladder_levels[normalized] = record
                seen_keys.add(normalized)
                loaded += 1
        for key in list(self.ladder_levels.keys()):
            if key.startswith(f"{account_key}:") and key not in seen_keys:
                self.ladder_levels.pop(key, None)
        logger.debug(f"[load_ladder_levels] Loaded {loaded} ladder entries for {account_key}")

    async def _load_ladder_levels_from_service(self, account_key: str, snapshot: Optional[Dict[str, Any]] = None) -> bool:
        if not account_key or not isinstance(account_key, str):
            return False
        seen_keys: Set[str] = set()
        loaded = False
        for side in ("LONG", "SHORT"):
            redis_payload = await self._redis_get_dict(f"ladder_levels:{account_key}:{side.lower()}")
            if not isinstance(redis_payload, dict) or not redis_payload:
                continue
            loaded = True
            for position_key, entry in redis_payload.items():
                if not isinstance(position_key, str) or not position_key.startswith(f"{account_key}:"):
                    continue
                if not isinstance(entry, dict):
                    continue
                levels_payload = entry.get("levels") or []
                if not isinstance(levels_payload, list) or not levels_payload:
                    self.ladder_levels.pop(position_key, None)
                    continue
                sanitized_levels = []
                for item in levels_payload:
                    if not isinstance(item, dict):
                        continue
                    sanitized_levels.append({ "level": safe_float(item.get("level")), "quantity": safe_float(item.get("quantity")), "created_at": item.get("created_at"), "crossed": bool(item.get("crossed", False)), "stoch_reversed": bool(item.get("stoch_reversed", False)) })
                if not sanitized_levels:
                    self.ladder_levels.pop(position_key, None)
                    continue
                record = dict(entry)
                record["levels"] = sanitized_levels
                record["account_key"] = record.get("account_key", account_key)
                if "is_long" not in record:
                    record["is_long"] = position_key.endswith("_LONG")
                self.ladder_levels[position_key] = record
                seen_keys.add(position_key)
        if not loaded:
            return False
        for key in list(self.ladder_levels.keys()):
            if key.startswith(f"{account_key}:") and key not in seen_keys:
                self.ladder_levels.pop(key, None)
        logger.info(f"[load_ladder_levels] Redis synced {len(seen_keys)} entries for {account_key}")
        return True

