    async def _load_direct_high_gain_from_service(self, account_key: str, snapshot: Optional[Dict[str, Any]] = None) -> bool:
        if not account_key or not isinstance(account_key, str):
            return False
        allowed_symbols = await self.get_symbols_for_account(account_key)
        payload = await self._redis_get_dict(f"direct_high_gain_augmented:{account_key}")
        if not payload:
            return False
        seen_keys = set()
        keys_to_delete_from_redis = []
        for position_key, entry in payload.items():
            if not isinstance(position_key, str) or not position_key.startswith(f"{account_key}:") or not isinstance(entry, dict):
                continue
            try:
                _, symbol, _ = parse_position_key(position_key)
                symbol = symbol.strip().upper()
            except Exception:
                continue
            position = await self.get_position(position_key)
            has_position = position and abs(safe_fetch_float(getattr(position, 'positionAmt', 0.0), 0.0)) > 0
            if not has_position and symbol not in allowed_symbols and position_key not in self.positions_to_gracefully_exit:
                keys_to_delete_from_redis.append(position_key)
                continue
            self.direct_high_gain[position_key] = entry
            seen_keys.add(position_key)
        for key in list(self.direct_high_gain.keys()):
            if key.startswith(f"{account_key}:") and key not in seen_keys:
                self.direct_high_gain.pop(key, None)
        if keys_to_delete_from_redis and self.redis_manager:
            try:
                client = self.redis_manager.connections.get('local') or self.redis_manager.connections.get('server')
                if client:
                    await client.hdel(f"direct_high_gain_augmented:{account_key}", *keys_to_delete_from_redis)
                    logger.warning(f"[DIRECT_GAIN_LOAD] 🧹 Sanitized {len(keys_to_delete_from_redis)} disallowed/closed symbols from Redis for {account_key}")
            except Exception: pass
        logger.info(f"[load_direct_high_gain] Redis synced {len(seen_keys)} valid entries for {account_key}")
        return True

    async def _fetch_account_snapshot(self, account_key: Optional[str] = None) -> Optional[Dict[str, Any]]:
        if account_key and not isinstance(account_key, str):
            return None
        accounts = [account_key] if account_key else list(self.accounts.keys())
        timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        positions_by_account: Dict[str, Dict[str, Any]] = {}
        stop_levels_payload: Dict[str, List[Dict[str, Any]]] = {}
        reentry_payload: Dict[str, Dict[str, Any]] = {}
        ladder_payload: Dict[str, Dict[str, Any]] = {}
        augmented_payload: Dict[str, str] = {}
        reduced_payload: Dict[str, str] = {}
        reversed_payload: Dict[str, str] = {}
        direct_payload: Dict[str, Dict[str, Any]] = {}
        for acct in accounts:
            if not acct:
                continue
            positions_payload = await self._redis_get_dict(f"positions:{acct}")
            if isinstance(positions_payload, dict) and positions_payload:
                actual_positions = positions_payload.get("positions", {})
                if isinstance(actual_positions, dict) and actual_positions:
                    positions_by_account[acct] = actual_positions
                elif not actual_positions:
                    filtered_positions = {k: v for k, v in positions_payload.items() if k not in ("positions", "meta") and isinstance(k, str) and ":" in k}
                    if filtered_positions:
                        positions_by_account[acct] = filtered_positions
            for side in ("long", "short"):
                redis_stop = await self._redis_get_dict(f"stop_levels:{acct}:{side}")
                if isinstance(redis_stop, dict):
                    for position_key, value in redis_stop.items():
                        if not isinstance(position_key, str) or not position_key.startswith(f"{acct}:"):
                            continue
                        entries = value.get("stop_levels") if isinstance(value, dict) else value
                        if isinstance(entries, list) and entries:
                            stop_levels_payload[position_key] = entries
                redis_reentry = await self._redis_get_dict(f"reentry_levels:{acct}:{side}")
                if isinstance(redis_reentry, dict):
                    for position_key, value in redis_reentry.items():
                        if isinstance(position_key, str) and position_key.startswith(f"{acct}:") and isinstance(value, dict):
                            reentry_payload[position_key] = value
                redis_ladder = await self._redis_get_dict(f"ladder_levels:{acct}:{side}")
                if isinstance(redis_ladder, dict):
                    for position_key, value in redis_ladder.items():
                        if isinstance(position_key, str) and position_key.startswith(f"{acct}:") and isinstance(value, dict):
                            ladder_payload[position_key] = value
            redis_augmented = await self._redis_get_dict(f"augmented_positions:{acct}")
            if isinstance(redis_augmented, dict):
                for position_key, value in redis_augmented.items():
                    if isinstance(position_key, str) and position_key.startswith(f"{acct}:"):
                        augmented_payload[position_key] = str(value)
            redis_reduced = await self._redis_get_dict(f"reduced_positions:{acct}")
            if isinstance(redis_reduced, dict):
                for position_key, value in redis_reduced.items():
                    if isinstance(position_key, str) and position_key.startswith(f"{acct}:"):
                        reduced_payload[position_key] = str(value)
            redis_reversed = await self._redis_get_dict(f"reversed_positions:{acct}")
            if isinstance(redis_reversed, dict):
                for position_key, value in redis_reversed.items():
                    if isinstance(position_key, str) and position_key.startswith(f"{acct}:"):
                        reversed_payload[position_key] = str(value)
            redis_direct = await self._redis_get_dict(f"direct_high_gain_augmented:{acct}")
            if isinstance(redis_direct, dict):
                for position_key, value in redis_direct.items():
                    if isinstance(position_key, str) and position_key.startswith(f"{acct}:") and isinstance(value, dict):
                        direct_payload[position_key] = value
        if not positions_by_account and not stop_levels_payload and not reentry_payload and not ladder_payload:
            return None
        snapshot: Dict[str, Any] = {"timestamp": timestamp, "positions_by_account": positions_by_account}
        if stop_levels_payload:
            snapshot["stop_levels"] = stop_levels_payload
        if reentry_payload:
            snapshot["reentry_data"] = reentry_payload
        if ladder_payload:
            snapshot["ladder_levels"] = ladder_payload
        if augmented_payload:
            snapshot["augmented_positions"] = augmented_payload
        if reduced_payload:
            snapshot["reduced_positions"] = reduced_payload
        if reversed_payload:
            snapshot["reversed_positions"] = reversed_payload
        return snapshot

    async def cleanup_all_stale_locks_on_startup(self):
        """Clean up stale locks on startup - clears locks older than 60s to prevent gridlock after restart - ONLY for allowed accounts"""
        if not self.redis_manager:
            return
        if not hasattr(self, '_allowed_accounts') or not self._allowed_accounts:
            logger.warning("[STARTUP_CLEANUP] No allowed accounts configured - skipping lock cleanup")
            return
        logger.info(f"[STARTUP_CLEANUP] Cleaning up stale Redis locks (>= 60s old) for allowed accounts: {list(self._allowed_accounts)}...")
        cleaned_count = 0
        try:
            for account_key in self._allowed_accounts:
                if account_key not in self.positions_by_account:
                    continue
                account_positions = self.positions_by_account.get(account_key, {})
                for position_key in list(account_positions.keys()):
                    if not position_key.startswith(f"{account_key}:"):
                        continue
                    for side in ['BUY', 'SELL']:
                        exec_lock_key = f"execute_now:{position_key}:{side}"
                        try:
                            lock_value = await self.redis_manager.get(exec_lock_key)
                            if lock_value:
                                lock_age = await self.get_lock_age(exec_lock_key)
                                if lock_age >= 60.0:
                                    await self.redis_manager.delete(exec_lock_key)
                                    if hasattr(self, 'clear_active_lock'):
                                        await self.clear_active_lock(position_key)
                                    cleaned_count += 1
                                    logger.info(f"[STARTUP_CLEANUP] Cleaned stale lock: {exec_lock_key} (age={lock_age:.1f}s)")
                        except Exception:
                            pass
            logger.info(f"[STARTUP_CLEANUP] Cleaned {cleaned_count} stale locks on startup")
        except Exception as cleanup_err:
            logger.warning(f"[STARTUP_CLEANUP] Error during startup cleanup: {cleanup_err}")

    async def periodic_zombie_nuke(self):
            """ Emergency task to clear stuck orders. CRITICAL: Ensures active limit orders are cancelled on Binance before clearing memory. """
            while True:
                await asyncio.sleep(30)
                try:
                    now = time.time()
                    keys_to_process = []
                    async with self.dedupe_lock:
                        for position_key, data in self.active_maker_orders.items():
                            age = now - data.get('start_time', 0)
                            status = data.get('status')
                            order_id = data.get('order_id')
                            if (status == 'placing' and age > 20) or (age > 60):
                                keys_to_process.append((position_key, status, order_id))
                    for position_key, status, order_id in keys_to_process:
                        if order_id and str(order_id).isdigit():
                            logger.warning(f"[NUKE] ☢️ Detected STALE ACTIVE order {position_key} (Age > 60s). ID: {order_id}. Cancelling on Binance...")
                            await self.cancel_and_clear_active_maker_order(position_key)
                            await self.force_clear_execution_lock(position_key)
                        else:
                            logger.warning(f"[NUKE] 🧹 Cleaning stuck '{status}' state for {position_key}. No valid Order ID (ID: {order_id}). Wiping memory.")
                            async with self.dedupe_lock:
                                if position_key in self.active_maker_orders:
                                    self.active_maker_orders.pop(position_key, None)
                                if position_key in self.order_deduplication:
                                    self.order_deduplication.pop(position_key, None)
                            await self.force_clear_execution_lock(position_key)
                except Exception as e:
                    logger.error(f"[NUKE_ERROR] Critical error in zombie nuke task: {e}", exc_info=True)

    async def cleanup_stale_execution_locks(self):
        """Clean up stale execution locks to prevent deadlocks"""
        now_ts = time.time()
        STALE_PENDING_SECONDS = 15 # Was 70 - If placing takes >15s, it's broken
        STALE_COMPLETE_SECONDS = 30 # Was 45
        STALE_MAKER_ORDER_SECONDS = 15 # Was 30
        STALE_REDIS_LOCK_SECONDS = 20 
        stale_keys_to_release = []
        for key, lock_data in list(self.active_order_locks.items()):
            status = lock_data.get("status", "unknown")
            timestamp = lock_data.get("timestamp", 0)
            if status == "pending" and (now_ts - timestamp) > STALE_PENDING_SECONDS:
                stale_keys_to_release.append(key)
            elif status in ["complete", "error"] and (now_ts - timestamp) > STALE_COMPLETE_SECONDS:
                stale_keys_to_release.append(key)
        if stale_keys_to_release:
            for key in stale_keys_to_release:
                self.active_order_locks.pop(key, None)
                logger.info(f"[LOCK_CLEANUP] Released stale execution lock: {key}")
        if hasattr(self, 'active_maker_orders'):
            stale_maker_orders = []
            for position_key, order_data in list(self.active_maker_orders.items()):
                start_time = order_data.get('start_time', 0)
                order_age = now_ts - start_time
                if order_age > STALE_MAKER_ORDER_SECONDS:
                    stale_maker_orders.append((position_key, order_age))
            if stale_maker_orders:
                for position_key, order_age in stale_maker_orders:
                    logger.warning(f"[LOCK_CLEANUP] Cancelling stale active_maker_order: {position_key} (age={order_age:.1f}s)")
                    await self.cancel_and_clear_active_maker_order(position_key)
        if hasattr(self, 'augmentation_cooldown_map'):
            now_utc = datetime.now(timezone.utc)
            stale_keys = []
            for position_key, cooldown_entry in list(self.augmentation_cooldown_map.items()):
                if isinstance(cooldown_entry, dict):
                    cooldown_time = cooldown_entry.get('time')
                    if isinstance(cooldown_time, datetime):
                        cooldown_age = (now_utc - cooldown_time).total_seconds()
                        if cooldown_age >= _AUGMENT_LOCK_MIN_SECONDS:
                            stale_keys.append(position_key)
            for key in stale_keys:
                self.augmentation_cooldown_map.pop(key, None)
                logger.debug(f"[LOCK_CLEANUP] Cleaned stale augmentation_cooldown_map entry: {key} (age >= 60s)")
        if self.redis_manager:
            try:
                all_account_keys = list(self.positions_by_account.keys()) if hasattr(self, 'positions_by_account') else []
                common_accounts = ['fin', 'men', 'inf', 'ang', 'flz']
                all_account_keys = list(set(all_account_keys + common_accounts))
                STALE_LOCK_THRESHOLD = 60.0 # Only clean locks older than 60s
                for account_key in all_account_keys:
                    for side in ['BUY', 'SELL']:
                        account_positions = self.positions_by_account.get(account_key, {})
                        for position_key in list(account_positions.keys()):
                            exec_lock_key = f"execute_now:{position_key}:{side}"
                            try:
                                lock_value = await self.redis_manager.get(exec_lock_key)
                                if lock_value:
                                    lock_age = await self.get_lock_age(exec_lock_key)
                                    if lock_age > 20.0:
                                        logger.warning(f"[GRIDLOCK_BREAKER] {position_key}: Force clearing zombie lock at queue entry (age={lock_age:.1f}s)")
                                        await self.force_clear_execution_lock(position_key)
                                        await asyncio.sleep(0.1) 
                            except Exception as redis_err:
                                logger.debug(f"[LOCK_CLEANUP] Error checking Redis lock {exec_lock_key}: {redis_err}")
                        for position_key in list(account_positions.keys()):
                            maker_lock_key = f"maker_order:{position_key}"
                            maker_active_lock_key = f"maker_order:maker:{position_key}"
                            for lock_key in [maker_lock_key, maker_active_lock_key]:
                                try:
                                    lock_value = await self.redis_manager.get(lock_key)
                                    if lock_value:
                                        await self.redis_manager.delete(lock_key)
                                        logger.debug(f"[LOCK_CLEANUP] Cleaned Redis maker lock: {lock_key}")
                                except Exception as redis_err:
                                    logger.debug(f"[LOCK_CLEANUP] Error checking Redis maker lock {lock_key}: {redis_err}")
            except Exception as cleanup_err:
                logger.debug(f"[LOCK_CLEANUP] Error cleaning Redis locks: {cleanup_err}")
    @property

    def redis_client(self):
        """Get a working Redis client for write operations with robust fallback."""
        if not self.redis_manager:
            return None
        if not self.redis_manager._initialized:
            return None
        if not self.redis_manager.connections:
            logger.error(f"❌ redis_manager is not a manager object: {type(self.redis_manager)}")
            return None
        clients_to_try = [ ("gateway", self.redis_manager.connections.get("gateway")), ("server", self.redis_manager.connections.get("server")), ("local", self.redis_manager.connections.get("local")) ]
        for name, client in clients_to_try:
            if client is not None:
                try:
                    import asyncio

                    async def test_connection():
                        try:
                            await asyncio.wait_for(client.ping(), timeout=1.0)
                            return True
                        except Exception:
                            return False
                    return client
                except Exception as e:
                    logger.debug(f"Redis client {name} test failed: {e}")
                    continue
        import time
        current_time = time.time()
        if not hasattr(self, '_last_redis_warning') or current_time - self._last_redis_warning > 60:
            logger.warning("⚠️ No Redis clients available for write operations - using file fallbacks")
            self._last_redis_warning = current_time
        return None
    @property

    def redis_client_read(self):
        """Provides the best available read Redis client"""
        if not self.redis_manager:
            return None
        if not self.redis_manager._initialized:
            return None
        if not self.redis_manager.connections:
            logger.error(f"❌ redis_manager is not a manager object: {type(self.redis_manager)}")
            return None
        clients_to_try = [ ("gateway", self.redis_manager.connections.get("gateway")), ("server", self.redis_manager.connections.get("server")), ("local", self.redis_manager.connections.get("local")) ]
        for name, client in clients_to_try:
            if client is not None:
                return client
        import time
        current_time = time.time()
        if not hasattr(self, '_last_read_warning') or current_time - self._last_read_warning > 60:
            logger.warning("⚠️ No Redis read clients available - using file fallbacks")
            self._last_read_warning = current_time
        return None

    async def initialize_redis_manager(self):
        """Initialize Redis manager with proper error handling"""
        try:
            if not self.redis_manager:
                self.redis_manager = await get_simple_redis_manager()
                if not self.redis_manager.connections:
                    logger.error(f"❌ get_simple_redis_manager() returned wrong type: {type(self.redis_manager)}")
                    self.redis_manager = None
                    return False
            return True
        except Exception as e:
            logger.error(f"❌ Failed to initialize Redis manager: {e}")
            return False

    async def monitor_redis_connectivity(self):
        """Monitor Redis connectivity and restart listeners if needed"""
        while True:
            try:
                await asyncio.sleep(60) # Check every minute
                if not self.redis_manager or not self.redis_manager._initialized:
                    logger.warning("🔄 Redis manager not initialized - attempting reconnection")
                    await self.initialize_redis_manager()
                active_connections = [target for target, client in self.redis_manager.connections.items() if client]
                if not active_connections:
                    logger.error("❌ No active Redis connections - restarting listeners")
                    await self.initialize_redis_manager()
            except Exception as e:
                logger.error(f"❌ Redis connectivity monitor error: {e}")
                await asyncio.sleep(30) # Wait longer on error

    def _safe_merge_indicators(self, symbol: str, incoming_data: dict, source_type: str = "cold"):
        """ The Gatekeeper. Merges data based on source authority. source_type: 'hot' (Bridge/SharedMem/EmergencyRedis) or 'cold' (File/StandardRedis) """
        if not incoming_data: return
        symbol = symbol.strip().upper()
        if symbol.endswith("USDT"):
            alt = symbol.replace("USDT", "USDC")
            if alt in self.indicators_snapshot: symbol = alt
        if symbol not in self.indicators_snapshot:
            self.indicators_snapshot[symbol] = {}
        existing = self.indicators_snapshot[symbol]
        now = time.time()
        ONE_MINUTE_KEYS = { 'stoch_k_1m', 'stoch_d_1m', 'k_1m_prev', 'k_1m', 'd_1m', 'k_1m_prev', 'timestamp_1m' }
        LIVE_KEYS = { 'stoch_k_3m', 'stoch_d_3m', 'k_3m_prev', 'k_3m', 'd_3m', 'k_3m_prev', 'current_price', 'price', '_tick_ts' }
        if source_type == 'hot':
            existing.update(incoming_data)
            existing['_hot_ts'] = now # Mark as fresh
        elif source_type == 'cold':
            hot_ts = float(existing.get('_hot_ts') or 0)
            is_hot_active = (now - hot_ts) < 15.0
            for k, v in incoming_data.items():
                if k in ONE_MINUTE_KEYS: 
                    continue
                if is_hot_active and k in LIVE_KEYS:
                    continue
                existing[k] = v
        self.indicators_snapshot_refresh_time = now

    async def log_btcusdc_refresh(self):
        symbol = "BTCUSDC"
        while True:
            try:
                now_utc = datetime.now(timezone.utc)
                indicator_payload = {}
                indicator_source = "none"
                i = await ii(self, symbol)
                fresh_payload = i if i else {}
                if fresh_payload:
                    indicator_payload = fresh_payload
                    indicator_source = fresh_payload.get('data_source', 'service')
                if not indicator_payload and self.raw_indicators_json_content:
                    try:
                        snapshot_dict = orjson.loads(self.raw_indicators_json_content)
                        payload = snapshot_dict.get(symbol) if isinstance(snapshot_dict, dict) else None
                        if isinstance(payload, dict) and payload:
                                indicator_payload = payload
                                indicator_source = "redis_snapshot"
                    except Exception as exc:
                        logger.debug(f"[BTCUSDC_REFRESH] snapshot decode failed: {exc}")
                if not indicator_payload:
                    latest_file = self._get_latest_timestamped_file() or self.indicators_filepath
                    if latest_file and Path(latest_file).exists():
                        try:
                            file_data = await read_json_file(str(latest_file))
                            payload = file_data.get(symbol) if isinstance(file_data, dict) else None
                            if isinstance(payload, dict) and payload:
                                    indicator_payload = payload
                                    indicator_source = Path(latest_file).name
                        except Exception as exc:
                            logger.debug(f"[BTCUSDC_REFRESH] file load failed: {exc}")
                indicator_ts = None
                if isinstance(indicator_payload, dict):
                    ts_raw = indicator_payload.get("timestamp") or indicator_payload.get("time") or indicator_payload.get("timestamp_1m")
                    if isinstance(ts_raw, (int, float)):
                        divisor = 1000.0 if ts_raw > 1e12 else 1.0
                        indicator_ts = datetime.fromtimestamp(ts_raw / divisor, tz=timezone.utc)
                    elif isinstance(ts_raw, str):
                        try:
                            indicator_ts = isoparse(_normalize_timestamp_to_z(ts_raw))
                        except Exception:
                            indicator_ts = None
                if not isinstance(indicator_ts, datetime):
                    fallback_ts = getattr(self, "indicators_timestamp", None)
                    if isinstance(fallback_ts, datetime):
                        indicator_ts = fallback_ts if fallback_ts.tzinfo else fallback_ts.replace(tzinfo=timezone.utc)
                    else:
                        latest_mtime = getattr(self, "_latest_market_data_mtime", 0.0)
                        if latest_mtime:
                            indicator_ts = datetime.fromtimestamp(latest_mtime, tz=timezone.utc)
                if isinstance(indicator_ts, datetime) and indicator_ts.tzinfo is None:
                    indicator_ts = indicator_ts.replace(tzinfo=timezone.utc)
                indicator_ts_str = indicator_ts.strftime('%Y-%m-%dT%H:%M:%S.%fZ') if isinstance(indicator_ts, datetime) else "unknown"
                indicator_age = max(0.0, (now_utc - indicator_ts).total_seconds()) if isinstance(indicator_ts, datetime) else None
                pos_updated_at = None
                position_account_key = None
                position_key_found = None
                positionAmt_found = 0.0
                managed_accounts = set(self.accounts.keys())
                for account_key, positions_dict in self.positions_by_account.items():
                    if account_key not in managed_accounts or account_key not in config.ACCOUNT_KEYS:
                        continue
                    for position_key, position in positions_dict.items():
                        if position and position.symbol == symbol:
                            positionAmt = abs(safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0))
                            if positionAmt > 0.0:
                                pos_updated_at = getattr(position, "last_updated", None) or getattr(position, "mark_price_last_updated", None)
                                position_account_key = account_key
                                position_key_found = position_key
                                positionAmt_found = positionAmt
                                break
                    if pos_updated_at:
                        break
                if not isinstance(pos_updated_at, datetime):
                    if isinstance(pos_updated_at, str):
                        try:
                            pos_updated_at = isoparse(pos_updated_at)
                        except Exception:
                            pos_updated_at = None
                    if not isinstance(pos_updated_at, datetime):
                        price_ts_override = None
                        if hasattr(self, "price_update_time") and isinstance(self.price_update_time, dict):
                            price_ts_override = self.price_update_time.get(symbol)
                    if position_key_found and hasattr(self, "_position_update_timestamps"):
                        file_ts_override = self._position_update_timestamps.get(position_key_found)
                        if isinstance(file_ts_override, datetime):
                            if not isinstance(price_ts_override, datetime) or file_ts_override > price_ts_override:
                                price_ts_override = file_ts_override
                    if isinstance(price_ts_override, datetime):
                        pos_updated_at = price_ts_override
                if position_key_found and hasattr(self, "_position_update_timestamps"):
                    file_ts_override = self._position_update_timestamps.get(position_key_found)
                    if isinstance(file_ts_override, datetime):
                        if not isinstance(pos_updated_at, datetime) or file_ts_override > pos_updated_at:
                            pos_updated_at = file_ts_override
                if isinstance(pos_updated_at, str):
                    try:
                        pos_updated_at = isoparse(pos_updated_at)
                    except Exception:
                        pos_updated_at = None
                if isinstance(pos_updated_at, datetime) and pos_updated_at.tzinfo is None:
                    pos_updated_at = pos_updated_at.replace(tzinfo=timezone.utc)
                pos_updated_str = pos_updated_at.strftime('%Y-%m-%dT%H:%M:%S.%fZ') if isinstance(pos_updated_at, datetime) else "unknown"
                position_age = max(0.0, (now_utc - pos_updated_at).total_seconds()) if isinstance(pos_updated_at, datetime) else None
                if position_key_found and positionAmt_found > 0.0 and position_account_key:
                    file_mtime = self._positions_file_mtimes.get(position_account_key, 0.0)
                    if file_mtime > 0.0:
                        file_age = time.time() - file_mtime
                        if file_age > POSITION_STALE_SECONDS:
                            position_age = file_age
                indicator_age_str = f"{indicator_age:.3f}s" if indicator_age is not None else "unknown"
                position_age_str = f"{position_age:.3f}s" if position_age is not None else "unknown"
                cache_age = time.time() - self.indicators_snapshot_refresh_time if self.indicators_snapshot_refresh_time > 0 else 999
                cache_age_str = f"{cache_age:.3f}s"
                if not hasattr(self, "_btc_refresh_warning_state"):
                    self._btc_refresh_warning_state = {"indicator": 0.0, "price": 0.0, "position": 0.0, "cache": 0.0}
                if not hasattr(self, "_btc_stale_count"):
                    self._btc_stale_count = {"indicator": 0, "cache": 0, "position": 0}
                warning_ts = time.time()

                def _should_warn(key):
                    last = self._btc_refresh_warning_state.get(key, 0.0)
                    if warning_ts - last >= STALE_WARNING_INTERVAL_SECONDS:
                        self._btc_refresh_warning_state[key] = warning_ts
                        return True
                    return False
                if cache_age > CACHE_STALE_SECONDS:
                    asyncio.create_task(self.refresh_from_files_once())
                    asyncio.create_task(self._force_refresh_indicators_aggressive())
                    if _should_warn("cache"):
                        self._btc_stale_count["cache"] += 1
                        logger.info( f"[CRITICAL_DATA_STALE] indicators_snapshot CACHE NOT REFRESHED FOR {cache_age_str} (>{CACHE_STALE_SECONDS:.0f}s) | " f"indicator_age={indicator_age_str} position_age={position_age_str} | " f"CONSECUTIVE_FAILURES={self._btc_stale_count['cache']} | " f"FORCING IMMEDIATE REFRESH NOW!" )

                        async def _aggressive_refresh():
                            try:
                                await self._force_refresh_indicators_aggressive()
                            except Exception as refresh_err:
                                logger.critical(f"[CRITICAL_REFRESH_FAILED] Failed to force refresh: {refresh_err}")
                        asyncio.create_task(_aggressive_refresh())
                else:
                    self._btc_stale_count["cache"] = 0
                if indicator_age is None or indicator_age > MAX_MARKET_DATA_AGE_SECONDS:
                    if _should_warn("indicator"):
                        self._btc_stale_count["indicator"] += 1
                        old_indicator_age = indicator_age
                        if indicator_age > 900:
                            logger.critical( f"[CRITICAL_DATA_STALE] INDICATORS NOT REFRESHED FOR {indicator_age_str} (source={indicator_source}) | " f"cache_age={cache_age_str} position_age={position_age_str} | " f"CONSECUTIVE_FAILURES={self._btc_stale_count['indicator']} | " f"FORCING IMMEDIATE REFRESH NOW!" )
                        try:
                            await self._force_refresh_indicators_aggressive()
                            await asyncio.sleep(0.25) # Give refresh time to complete
                            btc_check = self.indicators_snapshot.get("ETHUSDC", {})
                            if isinstance(btc_check, dict):
                                payload_check = btc_check.get('complete', btc_check) if 'complete' in btc_check else btc_check
                                if isinstance(payload_check, dict):
                                    ts_check_raw = payload_check.get("timestamp") or payload_check.get("time") or payload_check.get("timestamp_1m")
                                    if ts_check_raw:
                                        try:
                                            indicator_ts_check = None
                                            if isinstance(ts_check_raw,(int,float)):
                                                divisor_check = 1000.0 if ts_check_raw > 1e12 else 1.0
                                                indicator_ts_check = datetime.fromtimestamp(float(ts_check_raw)/divisor_check, tz=timezone.utc)
                                            elif isinstance(ts_check_raw,str):
                                                indicator_ts_check = safe_datetime(ts_check_raw, None)
                                            if not isinstance(indicator_ts_check, datetime):
                                                raise ValueError(f"Unsupported timestamp payload: {ts_check_raw}")
                                            new_indicator_age = (now_utc - indicator_ts_check).total_seconds()
                                            if new_indicator_age + 1.0 < old_indicator_age:
                                                logger.debug(f" [WATCHDOG_SUCCESS] Refresh improved indicator age from {old_indicator_age:.1f}s to {new_indicator_age:.1f}s")
                                                self._btc_stale_count["indicator"] = 0 # Reset on success
                                            else:
                                                logger.critical(f"[WATCHDOG_FAILED] Refresh did NOT improve indicator age! Old={old_indicator_age:.1f}s, New={new_indicator_age:.1f}s - Triggering indicator service restart!")
                                                await request_ez_indicators_restart("watchdog_failed_refresh")
                                                await asyncio.sleep(5) # Wait for restart
                                                await self._force_refresh_indicators_aggressive() # Try again after restart
                                        except Exception as verify_err:
                                            logger.warning(f"⚠️ [WATCHDOG] Failed to verify refresh: {verify_err}")
                        except Exception as refresh_err:
                            logger.critical(f"[CRITICAL_REFRESH_FAILED] Failed to force refresh: {refresh_err}")
                            if self._btc_stale_count["indicator"] >= 3:
                                logger.critical(f"[WATCHDOG] {self._btc_stale_count['indicator']} consecutive failures - triggering indicator service restart!")
                                await request_ez_indicators_restart("consecutive_refresh_failures")
                else:
                    self._btc_stale_count["indicator"] = 0
                if position_key_found and positionAmt_found > 0.0 and (position_age is None or position_age > POSITION_STALE_SECONDS):
                    if _should_warn("position"):
                        self._btc_stale_count["position"] = self._btc_stale_count.get("position", 0) + 1
                        logger.critical( f"[CRITICAL_DATA_STALE] POSITION NOT UPDATED FOR {position_age_str} (>{POSITION_STALE_SECONDS:.0f}s) | " f"position_key={position_key_found} positionAmt={positionAmt_found:.6f} | " f"indicator_age={indicator_age_str} cache_age={cache_age_str} | " f"CONSECUTIVE_FAILURES={self._btc_stale_count['position']} | " f"FORCING IMMEDIATE REFRESH NOW!" )
                        try:
                            if position_account_key:
                                try:
                                    await self.refresh_from_files_once()
                                    await asyncio.sleep(0.5)
                                    await self.load_all_positions()
                                    logger.debug(f" [CRITICAL_REFRESH] Reloaded positions for {position_account_key} into ez_manage cache")
                                except Exception as pos_err:
                                    logger.warning(f"⚠️ [CRITICAL_REFRESH] Local position reload failed for {position_account_key}: {pos_err}")
                                    await self.load_all_positions()
                            else:
                                try:
                                    await self.refresh_from_files_once()
                                    await asyncio.sleep(0.3)
                                    await self.load_all_positions()
                                    logger.debug(" [CRITICAL_REFRESH] Reloaded positions for all accounts into ez_manage cache")
                                except Exception as acc_err: 
                                    logger.warning(f"⚠️ [CRITICAL_REFRESH] Failed to reload all accounts: {acc_err}")
                        except Exception as refresh_err:
                            logger.critical(f"[CRITICAL_REFRESH_FAILED] Failed to force position refresh: {refresh_err}")
                else:
                    self._btc_stale_count["position"] = 0
            except Exception as exc:
                logger.debug(f"[BTCUSDC_REFRESH] log failed: {exc}")
            await asyncio.sleep(1)

    async def mark_recent_signal(self, position_key: str, cooldown: float = 15.0): #TEMP OUT SUSPICIOUS
        try:
            if self.redis_manager:
                await self.redis_manager.set(f"recent_signal:{position_key}", "1", ex=max(1, int(cooldown)))
                return
        except Exception as e:
            logger.warning(f"Error setting redis recent signal for {position_key}: {e}")
        ts = time.time()
        self.recently_queued_signals[position_key] = ts

    def _init_circuit_breaker(self, account_key: str):
        if account_key not in self.circuit_breakers:
            self.circuit_breakers[account_key] = { 'state': 'CLOSED', 'failure_count': 0,'success_count': 0, 'last_failure_time': None,'last_success_time': None }

    def _is_circuit_open(self, account_key: str) -> bool:
        self._init_circuit_breaker(account_key)
        cb = self.circuit_breakers[account_key]
        if cb['state'] == 'OPEN':
            if cb['last_failure_time'] and (datetime.now(timezone.utc) - cb['last_failure_time']).total_seconds() > self.circuit_breaker_config['recovery_timeout']:
                cb['state'] = 'HALF_OPEN'
                cb['success_count'] = 0
                logger.info(f"Circuit breaker for {account_key} moved to HALF_OPEN state")
                return False
            return True
        return False

    def _record_success(self, account_key: str):
        self._init_circuit_breaker(account_key)
        cb = self.circuit_breakers[account_key]
        cb['success_count'] += 1
        cb['last_success_time'] = datetime.now(timezone.utc)
        if cb['state'] == 'HALF_OPEN' and cb['success_count'] >= self.circuit_breaker_config['success_threshold']:
            cb['state'] = 'CLOSED'
            cb['failure_count'] = 0
            logger.info(f"Circuit breaker for {account_key} moved to CLOSED state")

    def _record_failure(self, account_key: str):
        self._init_circuit_breaker(account_key)
        cb = self.circuit_breakers[account_key]
        cb['failure_count'] += 1
        cb['last_failure_time'] = datetime.now(timezone.utc)
        if cb['failure_count'] >= self.circuit_breaker_config['failure_threshold']:
            cb['state'] = 'OPEN'
            logger.warning(f"Circuit breaker for {account_key} moved to OPEN state due to {cb['failure_count']} failurres")

    def _track_api_failure(self, account_key: str):
        """Track API failures for enhanced rate limiting"""
        current_failures = self._recent_api_failures.get(account_key, 0)
        self._recent_api_failures[account_key] = current_failures + 1
        now = time.time()
        last_decay = self._last_failure_decay.get(account_key, now)
        if now - last_decay > 300: # 5 minutes
            if current_failures > 0:
                self._recent_api_failures[account_key] = max(0, current_failures - 1)
            self._last_failure_decay[account_key] = now

    def set_order_queue(self, queue):
        self.order_queue = queue

    async def _handle_position_update(self, payload: Any) -> None:
        try:
            if isinstance(payload, str):
                payload = json.loads(payload)
            if not isinstance(payload, dict):
                return
            account_key = payload.get("account_key")
            if not account_key or account_key not in self.accounts:
                return
            update_type = payload.get("type")
            if update_type == "augmented_positions":
                redis_key = f"augmented_positions:{account_key}"
                try:
                    if self.redis_manager:
                        raw_data = await self.redis_manager.get(redis_key)
                        raw_data = self._normalize_redis_payload(raw_data)
                        if isinstance(raw_data, dict):
                            for key, value in raw_data.items():
                                if key.startswith(f"{account_key}:") and isinstance(value, str):
                                    try:
                                        redis_dt = isoparse(value)
                                        if not isinstance(redis_dt, datetime):
                                            continue
                                        if redis_dt.tzinfo is None:
                                            redis_dt = redis_dt.replace(tzinfo=timezone.utc)
                                        existing_dt = self._get_augmented_timestamp(key)
                                        if not existing_dt or redis_dt > existing_dt:
                                            self.augmented_positions[key] = redis_dt
                                    except Exception:
                                        pass
                except Exception: pass
            elif update_type == "reversed_positions":
                if account_key != "fin" or not self.config.REV_MODE:
                    for key in list(self.reversed_positions.keys()):
                        if key.startswith(f"{account_key}:"): self.reversed_positions.pop(key, None)
                    return
                redis_key = f"reversed_positions:{account_key}"
                try:
                    if self.redis_manager:
                        raw_data = await self.redis_manager.get(redis_key)
                        raw_data = self._normalize_redis_payload(raw_data)
                        if isinstance(raw_data, dict):
                            for key, value in raw_data.items():
                                if key.startswith(f"{account_key}:") and isinstance(value, str):
                                    try:
                                        redis_dt = isoparse(value)
                                        existing_dt = self.reversed_positions.get(key)
                                        if not existing_dt or redis_dt > existing_dt:
                                            self.reversed_positions[key] = redis_dt
                                    except Exception:
                                        pass
                except Exception: pass
            elif update_type == "stop_levels":
                side = payload.get("side", "").upper()
                redis_key = f"stop_levels:{account_key}:{side.lower()}"
                try:
                    if self.redis_manager:
                        raw_data = await self.redis_manager.get(redis_key)
                        raw_data = self._normalize_redis_payload(raw_data)
                        if isinstance(raw_data, dict):
                            for position_key, value_dict in raw_data.items():
                                if position_key.startswith(f"{account_key}:") and position_key.endswith(f"_{side}"):
                                    if isinstance(value_dict, dict) and "stop_levels" in value_dict:
                                        redis_last_updated = value_dict.get("last_updated")
                                        if isinstance(redis_last_updated, str):
                                            try:
                                                redis_last_updated = isoparse(redis_last_updated)
                                            except Exception:
                                                redis_last_updated = None
                                        existing_levels = self.stop_levels.get(position_key, [])
                                        should_update = False
                                        if not existing_levels:
                                            should_update = True
                                        elif redis_last_updated:
                                            existing_has_timestamp = any(hasattr(level, 'created_at') and level.created_at for level in existing_levels if hasattr(level, 'created_at'))
                                            if not existing_has_timestamp:
                                                should_update = True
                                            else:
                                                existing_max_ts = max((level.created_at for level in existing_levels if hasattr(level, 'created_at') and level.created_at), default=None)
                                                if existing_max_ts and redis_last_updated > existing_max_ts:
                                                    should_update = True
                                        if should_update:
                                            stop_levels = value_dict.get("stop_levels", [])
                                            if isinstance(stop_levels, list):
                                                parsed_levels = []
                                                for entry in stop_levels:
                                                    if isinstance(entry, dict):
                                                        try:
                                                            parsed_levels.append(StopLevel.from_dict(entry))
                                                        except Exception:
                                                            pass
                                                if parsed_levels:
                                                    self.stop_levels[position_key] = parsed_levels
                except Exception: pass
            elif update_type == "direct_high_gain_augmented":
                redis_key = f"direct_high_gain_augmented:{account_key}"
                try:
                    if self.redis_manager:
                        raw_data = await self.redis_manager.get(redis_key)
                        raw_data = self._normalize_redis_payload(raw_data)
                        if isinstance(raw_data, dict):
                            for key, value in raw_data.items():
                                if key.startswith(f"{account_key}:") and isinstance(value, dict):
                                    redis_ts = value.get("timestamp")
                                    if isinstance(redis_ts, str):
                                        try:
                                            redis_ts = isoparse(redis_ts)
                                        except Exception:
                                            redis_ts = None
                                    existing_entry = self.direct_high_gain.get(key)
                                    existing_ts = existing_entry.get("timestamp") if isinstance(existing_entry, dict) else None
                                    if isinstance(existing_ts, str):
                                        try:
                                            existing_ts = isoparse(existing_ts)
                                        except Exception:
                                            existing_ts = None
                                    if not existing_ts or (redis_ts and redis_ts > existing_ts):
                                        self.direct_high_gain[key] = value
                except Exception: pass
            elif update_type == "reentry_levels":
                side = payload.get("side", "").upper()
                redis_key = f"reentry_levels:{account_key}:{side.lower()}"
                try:
                    if self.redis_manager:
                        raw_data = await self.redis_manager.get(redis_key)
                        raw_data = self._normalize_redis_payload(raw_data)
                        if isinstance(raw_data, dict):
                            for position_key, entry_data in raw_data.items():
                                if position_key.startswith(f"{account_key}:") and position_key.endswith(f"_{side}"):
                                    if isinstance(entry_data, dict):
                                        redis_ts = entry_data.get("timestamp")
                                        if isinstance(redis_ts, str):
                                            try:
                                                redis_ts = isoparse(redis_ts)
                                            except Exception:
                                                redis_ts = None
                                        existing_entry = self.reentry_data.get(position_key)
                                        existing_ts = existing_entry.get("timestamp") if isinstance(existing_entry, dict) else None
                                        if isinstance(existing_ts, str):
                                            try:
                                                existing_ts = isoparse(existing_ts)
                                            except Exception:
                                                existing_ts = None
                                        if not existing_ts or (redis_ts and redis_ts > existing_ts):
                                            self.reentry_data[position_key] = entry_data
                except Exception: pass
            elif update_type == "ladder_levels":
                side = payload.get("side", "").upper()
                redis_key = f"ladder_levels:{account_key}:{side.lower()}"
                try:
                    if self.redis_manager:
                        raw_data = await self.redis_manager.get(redis_key)
                        raw_data = self._normalize_redis_payload(raw_data)
                        if isinstance(raw_data, dict):
                            for position_key, entry_data in raw_data.items():
                                if position_key.startswith(f"{account_key}:") and position_key.endswith(f"_{side}"):
                                    if isinstance(entry_data, dict):
                                        redis_ts = entry_data.get("created_at") or entry_data.get("timestamp")
                                        if isinstance(redis_ts, str):
                                            try:
                                                redis_ts = isoparse(redis_ts)
                                            except Exception:
                                                redis_ts = None
                                        existing_entry = self.ladder_levels.get(position_key)
                                        existing_ts = existing_entry.get("created_at") or (existing_entry.get("timestamp") if isinstance(existing_entry, dict) else None)
                                        if isinstance(existing_ts, str):
                                            try:
                                                existing_ts = isoparse(existing_ts)
                                            except Exception:
                                                existing_ts = None
                                        if not existing_ts or (redis_ts and redis_ts > existing_ts):
                                            self.ladder_levels[position_key] = entry_data
                except Exception: pass
            elif update_type == "delta" or payload.get("meta", {}).get("type") == "delta":
                positions_in_payload = payload.get("positions")
                if positions_in_payload and isinstance(positions_in_payload, dict):
                    account_positions = self.positions_by_account.setdefault(account_key, {})
                    updated_count = 0
                    metadata_keys = {"positions", "meta", "timestamp", "data", "positions_by_account"}
                    for position_key, pos_dict in positions_in_payload.items():
                        if not isinstance(pos_dict, dict) or not isinstance(position_key, str) or position_key in metadata_keys or not position_key.startswith(f"{account_key}:") or ":" not in position_key:
                            continue
                        try:
                            pos_obj = Position.from_dict(pos_dict)
                            account_positions[position_key] = pos_obj
                            self.positions[position_key] = pos_obj
                            updated_count += 1
                        except Exception as e:
                            logger.debug(f"[position_update_delta] Failed to parse position {position_key}: {e}")
                    if updated_count > 0:
                        logger.info(f"[position_update_delta] Replaced {updated_count} positions for {account_key} (direct replacement only)")
                        for position_key in positions_in_payload.keys():
                            if position_key in account_positions:
                                asyncio.create_task(override_check_uptrend_positions(self, account_key))
                                break # Only trigger once per account
            else:
                side = payload.get("side")
                is_full_broadcast = side is not None # Full broadcast includes "side" field
                positions_in_payload = payload.get("positions")
                if positions_in_payload and isinstance(positions_in_payload, dict):
                    account_positions = self.positions_by_account.setdefault(account_key, {})
                    updated_count = 0
                    metadata_keys = {"positions", "meta", "timestamp", "data", "positions_by_account"}
                    for position_key, pos_dict in positions_in_payload.items():
                        if not isinstance(pos_dict, dict) or not isinstance(position_key, str) or position_key in metadata_keys or not position_key.startswith(f"{account_key}:") or ":" not in position_key:
                            continue
                        try:
                            pos_obj = Position.from_dict(pos_dict)
                            existing_pos = account_positions.get(position_key)
                            existing_ts = self._extract_position_timestamp(existing_pos) if existing_pos else None
                            new_ts = self._extract_position_timestamp(pos_obj)
                            if existing_ts and new_ts and existing_ts > new_ts:
                                continue
                            account_positions[position_key] = pos_obj
                            self.positions[position_key] = pos_obj
                            if new_ts:
                                self._position_update_timestamps[position_key] = new_ts
                            else:
                                self._position_update_timestamps[position_key] = datetime.now(timezone.utc)
                            updated_count += 1
                            logger.debug(f"[position_update] Applied position update: {position_key} (positionAmt={pos_obj.positionAmt:.6f}, gain={pos_obj.gain:.4f}%)")
                        except Exception as e:
                            logger.error(f"[position_update] ❌ Failed to parse/apply position {position_key}: {e}", exc_info=True)
                    if updated_count > 0:
                        logger.info(f"[position_update] Applied {updated_count} position updates for {account_key} from Redis")
                        asyncio.create_task(override_check_uptrend_positions(self, account_key))
                    if is_full_broadcast:
                        asyncio.create_task(self.sync_positions_from_redis_once([account_key]))
                        logger.debug(f"[position_update] Full broadcast detected for {account_key}:{side} - triggered immediate reload")
                else:
                    redis_key = f"positions:{account_key}"
                    try:
                        if self.redis_manager:
                            raw_data = await self.redis_manager.get(redis_key)
                            if raw_data:
                                payload_data = json.loads(raw_data) if isinstance(raw_data, str) else raw_data
                                if isinstance(payload_data, dict):
                                    all_positions = payload_data.get("positions", {})
                                    if not isinstance(all_positions, dict):
                                        all_positions = payload_data # Fallback: assume payload is positions dict directly
                                    metadata_keys = {"positions", "meta", "timestamp", "data", "positions_by_account"}
                                    account_positions = self.positions_by_account.setdefault(account_key, {})
                                    for position_key, pos_dict in all_positions.items():
                                        if not isinstance(position_key, str) or position_key in metadata_keys or ":" not in position_key:
                                            continue
                                        if not isinstance(pos_dict, dict) or not position_key.startswith(f"{account_key}:"):
                                            continue
                                        try:
                                            pos_obj = Position.from_dict(pos_dict)
                                            account_positions[position_key] = pos_obj
                                            self.positions[position_key] = pos_obj
                                            if pos_obj.mark_price and pos_obj.mark_price > 0:
                                                mark_price_ts = pos_obj.mark_price_last_updated or datetime.now(timezone.utc)
                                        except Exception: pass
                    except Exception: pass
        except Exception as e:
            logger.debug(f"[position_update] Failed to handle update: {e}")

    async def start_position_updates_listener(self):
        try:
            if not self.redis_manager:
                logger.warning("⚠️ Redis manager not available - skipping position updates listener")
                return
            logger.debug(f" Subscribing to Redis '{REDIS_CHANNELS['position_updates']}' for real-time position updates...")
            await self.redis_manager.subscribe(channel=REDIS_CHANNELS["position_updates"], callback=self._handle_position_update, data_type="positions")
            delta_channel = REDIS_CHANNELS.get("position_updates_delta", "position_updates_delta")
            logger.debug(f" Subscribing to Redis '{delta_channel}' for incremental position updates...")
            await self.redis_manager.subscribe(channel=delta_channel, callback=self._handle_position_update, data_type="positions")
        except Exception as e:
            logger.warning(f"⚠️ Redis position updates listener setup failed: {e} - continuing without Redis position updates")

    async def init_async(self):
        self.min_qty = await self.load_min_qty()
        self.symbol_configs= await self.load_symbol_configs()
        self.logger.info(f"Loaded symbol configs from self.config.SYMBOL_CONFIGS_FILE " )
        try:
            with open(config.LIVE_USDC_PAIRS_FILE, 'rb') as f:
                self.available_usdc_pairs = set(orjson.loads(f.read()))
        except (FileNotFoundError, json.JSONDecodeError) as e:
            logger.error(f"CRITICAL: Could not load live USDC pairs file: {e}. USDC conversion will not work.")
        await self._load_initial_indicators_snapshot()

    async def initialize_clients(self):
        """Initializes all Redis and Binance clients using the new centralized manager."""
        try:
            self.redis_manager = await get_simple_redis_manager()
            if not self.redis_manager.connections:
                logger.error(f"❌ get_simple_redis_manager() returned wrong type: {type(self.redis_manager)}")
                self.redis_manager = None
                logger.warning("⚠️ Redis manager initialization failed - proceeding with JSON fallback mode")
            else:
                working_connections = [target for target, client in self.redis_manager.connections.items() if client]
                if working_connections:
                    logger.debug(f" Simple Redis Manager initialized with connections: {working_connections}")
                    responsive_connections = []
                    for target, client in self.redis_manager.connections.items():
                        if client:
                            try:
                                await asyncio.wait_for(client.ping(), timeout=1.0)
                                responsive_connections.append(target)
                            except Exception:
                                pass
                    if responsive_connections:
                        logger.debug(f" Redis connections verified: {responsive_connections}")
                        logger.debug(" Redis manager ready for read/write operations")
                    else:
                        logger.warning("⚠️ No responsive Redis connections - proceeding with fallback mode")
                        self.redis_manager = None
                else:
                    logger.warning("⚠️ No Redis connections available - proceeding with JSON fallback mode")
                    self.redis_manager = None
        except Exception as e:
            logger.warning(f"⚠️ Redis initialization failed: {e} - proceeding with JSON fallback mode")
            self.redis_manager = None
        account_keys_to_init = list(self.accounts.keys())
        if self.config and self.config.ACCOUNT_KEYS:
            account_keys_to_init = [ak for ak in account_keys_to_init if ak in self.config.ACCOUNT_KEYS]
        logger.info(f"🔧 Initializing {len(account_keys_to_init)} Binance client(s) for account(s): {account_keys_to_init}")
        accounts_to_init = {k: v for k, v in self.accounts.items() if k in account_keys_to_init}
        await asyncio.gather(*(account.initialize() for account in accounts_to_init.values()))
        logger.info(f" All {len(account_keys_to_init)} Binance client(s) initialized for account(s): {account_keys_to_init}")

    async def start_indicators_cache_listener(self):
        """DEPRECATED: No longer listening to indicators channel - using file-based approach"""
        logger.debug("Indicators channel listener disabled - using file-based indicators approach")
        pass

    async def initialize_indicators_bridge(self, poll_interval: float = None, cache_ttl: float = None) -> None:
        if self.indicators_bridge:
            return
        poll_iv = float(poll_interval if poll_interval is not None else getattr(self.config, "MARKET_DATA_REFRESH_INTERVAL_SECONDS", 20.0))
        cache_ttl_val = float(cache_ttl if cache_ttl is not None else getattr(self.config, "INDICATOR_CACHE_TTL", 1.0))
        redis_manager = self.redis_manager
        if not redis_manager:
            try:
                redis_manager = await get_simple_redis_manager()
            except Exception as exc:
                logger.warning(f"[indicators_bridge] Redis manager acquisition failed: {exc}")
                redis_manager = None
        try:
            bridge = IndicatorsBridge(self, logger=self.logger, poll_interval=poll_iv, cache_ttl=cache_ttl_val, redis_manager=redis_manager)
            await bridge.initialize()
            self.indicators_bridge = bridge
            logger.debug("[indicators_bridge] Bridge initialized for ez_manage")
        except Exception as exc:
            self.indicators_bridge = None
            logger.warning(f"[indicators_bridge] Initialization failed: {exc}")

    async def hydrate_from_service_snapshot(self, snapshot: Dict[str, Any]) -> None:
        if not isinstance(snapshot, dict):
            raise ValueError("snapshot must be a dictionary")

        def _fmt_ts(raw_value):
            dt = safe_datetime(raw_value)
            return dt.strftime("%Y-%m-%dT%H:%M:%S.%fZ") if dt else None
        positions_payload = snapshot.get("positions_by_account", {}) or {}
        if not positions_payload:
            logger.warning("[hydrate_snapshot] Snapshot contained no positions; preserving existing cache")
            positions_payload = {}
        for account_key in self._allowed_accounts:
            self.positions_by_account.setdefault(account_key, {})
        total_positions_loaded = 0
        for account_key, account_positions in positions_payload.items():
            if account_key not in self._allowed_accounts: continue
            if not isinstance(account_positions, dict):
                continue
            normalized_account_key = account_key
            account_bucket: Dict[str, Position] = {}
            for position_key, payload in account_positions.items():
                if not isinstance(payload, dict):
                    continue
                try:
                    pos_obj = Position.from_dict(payload)
                except Exception as exc:
                    logger.error(f"[hydrate_snapshot] Failed to parse position {position_key}: {exc}")
                    continue
                account_bucket[position_key] = pos_obj
                self.positions[position_key] = pos_obj
                total_positions_loaded += 1
            if account_bucket:
                existing_for_account = {k: v for k, v in self.positions.items() if k.startswith(f"{normalized_account_key}:")}
                for key in list(existing_for_account.keys()):
                    if key not in account_bucket:
                        logger.warning(f"[hydrate_snapshot] Preserving position {key} - not in snapshot but exists in memory")
                        account_bucket[key] = existing_for_account[key]
            if normalized_account_key not in self.positions_by_account:
                self.positions_by_account[normalized_account_key] = {}
            if account_bucket:
                self.positions_by_account[normalized_account_key].update(account_bucket)
        stop_payload = snapshot.get("stop_levels", {}) or {}
        self.stop_levels.clear()
        if isinstance(stop_payload, dict):
            for position_key, levels in stop_payload.items():
                if not isinstance(levels, list):
                    continue
                cleaned_levels = []
                for entry in levels:
                    if isinstance(entry, dict):
                        cleaned_levels.append({ "level": float(entry.get("level", 0.0)), "reduction_amount": float(entry.get("reduction_amount", 0.0)), "augmentation_price": float(entry.get("augmentation_price", 0.0)), "created_at": str(entry.get("created_at", "")), "position_side": str(entry.get("position_side", "")), })
                if cleaned_levels:
                    self.stop_levels[position_key] = cleaned_levels
        reentry_payload = snapshot.get("reentry_data", {}) or {}
        if isinstance(reentry_payload, dict):
            for position_key, entry in reentry_payload.items():
                if isinstance(entry, dict):
                    self.reentry_data[position_key] = { "reentry_level": float(entry.get("reentry_level", entry.get("level", 0.0))), "reentry_amount": float(entry.get("reentry_amount", entry.get("amount", 0.0))), "timestamp": _fmt_ts(entry.get("timestamp")), "reason": str(entry.get("reason", "")), }
        ladder_payload = snapshot.get("ladder_levels", {}) or {}
        self.ladder_levels.clear()
        if isinstance(ladder_payload, dict):
            for position_key, entry in ladder_payload.items():
                if isinstance(entry, dict):
                    self.ladder_levels[position_key] = {k: (entry[k] if k != "timestamp" else _fmt_ts(entry[k])) for k in entry.keys()}
        invalidation_payload = snapshot.get("invalidation_levels", {}) or {}
        if isinstance(invalidation_payload, dict):
            for position_key, entry in invalidation_payload.items():
                if isinstance(entry, dict):
                    self.invalidation_levels[position_key] = {k: (entry[k] if k != "timestamp" else _fmt_ts(entry[k])) for k in entry.keys()}
        managed_payload = snapshot.get("managed_stop_registry", {}) or {}
        if isinstance(managed_payload, dict):
            self.managed_stop_registry.clear()
            self.managed_stop_registry.update({key: {k: (value[k] if k != "timestamp" else _fmt_ts(value[k])) for k in value.keys()} for key, value in managed_payload.items() if isinstance(value, dict)})
            self.managed_stop_registry_dirty = False
        augmented_payload = snapshot.get("augmented_positions", {}) or {}
        if isinstance(augmented_payload, dict):
            for position_key, ts in augmented_payload.items():
                dt = safe_datetime(ts)
                if isinstance(dt, datetime) and position_key not in self.augmented_positions:
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    self.augmented_positions[position_key] = dt
        reduced_payload = snapshot.get("reduced_positions", {}) or {}
        if isinstance(reduced_payload, dict):
            for position_key, ts in reduced_payload.items():
                dt = safe_datetime(ts)
                if dt and position_key not in self.reduced_positions:
                    self.reduced_positions[position_key] = dt
        reversed_payload = snapshot.get("reversed_positions", {}) or {}
        self.reversed_positions.clear()
        if self.config.REV_MODE and isinstance(reversed_payload, dict):
            for position_key, ts in reversed_payload.items():
                if position_key.startswith("fin:"):
                    dt = safe_datetime(ts)
                    if dt:
                        self.reversed_positions[position_key] = dt
        direct_high_gain_payload = snapshot.get("direct_high_gain", {}) or {}
        self.direct_high_gain = {}
        if isinstance(direct_high_gain_payload, dict):
            for position_key, entry in direct_high_gain_payload.items():
                if isinstance(entry, dict):
                    self.direct_high_gain[position_key] = {k: (entry[k] if k != "timestamp" else _fmt_ts(entry[k])) for k in entry.keys()}
        price_cache_payload = snapshot.get("price_cache", {}) or {}
        if isinstance(price_cache_payload, dict):
            self.price_cache.clear()
            self.price_cache.update(price_cache_payload)
            self.price_update_time.clear()
            for symbol, payload in price_cache_payload.items():
                if isinstance(payload, dict):
                    dt = safe_datetime(payload.get("timestamp"))
                    if dt:
                        self.price_update_time[symbol] = dt
        available_pairs = snapshot.get("available_usdc_pairs", []) or []
        if isinstance(available_pairs, list):
            self.available_usdc_pairs = set(str(symbol).upper() for symbol in available_pairs)
        indicators_payload = snapshot.get("latest_market_data") or {}
        if isinstance(indicators_payload, dict) and indicators_payload:
            indicators_ts = safe_datetime(snapshot.get("latest_market_data_timestamp") or snapshot.get("indicators_timestamp"))
            self._apply_indicator_payload(indicators_payload, "rpc_snapshot", indicators_ts)
        indicators_ts = snapshot.get("indicators_timestamp")
        dt = safe_datetime(indicators_ts)
        if dt:
            self.indicators_timestamp = ensure_tz(dt)
        logger.debug(f"[hydrate_snapshot] Loaded {total_positions_loaded} positions from snapshot payloads")

    async def start_hybrid_cache_system(self):
        self._cache_tasks.append( asyncio.create_task(self._last_events_refresh_loop()) )
        self._cache_tasks.append( asyncio.create_task(self._aggressive_indicator_health_check()) )

    async def _batch_refresh_loop(self):
        """Refresh entire cache periodically"""
        await asyncio.sleep(10)
        while True:
            try:
                if self.redis_manager:
                    raw = await self.redis_manager.get("latest_market_data")
                else: 
                     raw = None
                if raw:
                    data = safe_json_loads(raw)
                    for symbol, indicators in data.items():
                        self.indicators_snapshot[symbol] = indicators
                    self.indicators_cache_timestamps.clear()
                    self.indicators_cache_timestamps.update({symbol: time.time() for symbol in data.keys()})
                    self.indicators_timestamp = _snapshot_timestamp(data)#datetime.now(timezone.utc)
                    self.indicators_source_label = "redis_batch_refresh"
                    self.latest_indicator_payload_timestamp = _snapshot_timestamp(data)
                    self.currently_loaded_indicator_source_path = None
                    logger.debug(f"🔄 Refreshed cache with {len(data)} symbols")
            except Exception as e:
                logger.error(f"❌ Batch refresh failed: {e}")
            await asyncio.sleep(30) # Refresh every 30 seconds

    async def _indicators_snapshot_refresh_loop(self):
        """Refresh indicators_snapshot dict every 20 seconds from Redis (optional) or files"""
        await asyncio.sleep(5)
        while True:
            try:
                refreshed = False
                if self.redis_manager:
                    try:
                        raw_data = await self.redis_manager.get(config.REDIS_KEY_MARKET_DATA)
                        if raw_data:
                            data = json.loads(raw_data)
                            if isinstance(data, dict) and data:
                                should_refresh = True
                                btc_data = data.get("ETHUSDC", {})
                                if isinstance(btc_data, dict):
                                    payload = btc_data
                                    if isinstance(payload, dict):
                                        ts_raw = payload.get("timestamp") or payload.get("time") or payload.get("timestamp_1m") or payload.get("timestamp_3m") or payload.get("timestamp_15m")
                                        if ts_raw:
                                            try:
                                                divisor = 1000.0 if isinstance(ts_raw, (int, float)) and ts_raw > 1e12 else 1.0
                                                indicator_ts = datetime.fromtimestamp(float(ts_raw) / divisor, tz=timezone.utc)
                                                data_age = (datetime.now(timezone.utc) - indicator_ts).total_seconds()
                                                if data_age > 200: # Data is > 5 minutes old, skip refresh
                                                    logger.warning(f"⚠️ Skipping Redis refresh: data is {data_age:.0f}s old (>300s)")
                                                    should_refresh = False # Force file refresh instead
                                            except Exception:
                                                pass
                                if should_refresh:
                                    self.indicators_snapshot.clear()
                                    for symbol, indicators in data.items():
                                        if isinstance(indicators, dict):
                                            self.indicators_snapshot[symbol] = indicators
                                    self.indicators_cache_timestamps.clear()
                                    self.indicators_cache_timestamps.update({symbol: time.time() for symbol in data.keys()})
                                    self.indicators_timestamp = _snapshot_timestamp(data)#datetime.now(timezone.utc)
                                    self.indicators_source_label = "redis_refresh_loop"
                                    self.latest_indicator_payload_timestamp = _snapshot_timestamp(data)
                                    self.currently_loaded_indicator_source_path = None
                                    self.indicators_snapshot_refresh_time = time.time()
                                    logger.debug(f" Refreshed indicators_snapshot from Redis with {len(data)} symbols")
                                    refreshed = True
                    except Exception as redis_err:
                        err_name = type(redis_err).__name__
                        if 'Connection' not in err_name and 'Reset' not in err_name and err_name not in ('OSError', 'TimeoutError'):
                            logger.error(f"❌ Redis error in refresh loop: {redis_err}")
                if not refreshed:
                    await self._refresh_indicators_from_file()
            except Exception as e:
                logger.error(f"❌ Indicators snapshot refresh failed: {e}")
            await asyncio.sleep(20)

    async def _refresh_indicators_from_sources(self, force: bool = False) -> bool:
        if not self._last_file_refresh_time:
            self._last_file_refresh_time = 0.0
        if not force and (time.time() - self._last_file_refresh_time) < 2.0:
            if self.indicators_snapshot and isinstance(self.indicators_snapshot, dict):
                return True
        # DEDUP_STEP5: fast path — read from positions_service.indicators_snapshot (same process, shared dict)
        _svc = getattr(self, 'positions_service', None)
        _svc_snap = getattr(_svc, 'indicators_snapshot', None) if _svc else None
        if _svc_snap and isinstance(_svc_snap, dict) and len(_svc_snap) > 10:
            current_snapshot = self.indicators_snapshot
            PROTECTED_KEYS = { 'stoch_k_1m', 'stoch_d_1m', 'stoch_k_3m', 'stoch_d_3m', 'k1', 'd1', 'k3', 'd3', 'k1p', 'k3p', 'timestamp_1m', 'timestamp_3m', 'timestamp_3m_mid', 'current_price', 'price' }
            for symbol_key, new_data in _svc_snap.items():
                if not isinstance(new_data, dict): continue
                if symbol_key not in current_snapshot:
                    current_snapshot[symbol_key] = new_data.copy()
                    continue
                existing = current_snapshot[symbol_key]
                mem_ts_1m = _parse_indicator_timestamp(existing.get('timestamp_1m'))
                bulk_ts = _parse_indicator_timestamp(new_data.get('timestamp'))
                preserve_hot = bool(mem_ts_1m and bulk_ts and mem_ts_1m > bulk_ts) or bool(existing.get('_hot_source'))
                if preserve_hot:
                    for k, v in new_data.items():
                        if k not in PROTECTED_KEYS:
                            existing[k] = v
                else:
                    existing.update(new_data)
            self.indicators_timestamp = datetime.now(timezone.utc)
            self.indicators_source_label = "positions_service"
            self._last_file_refresh_time = time.time()
            self.indicators_snapshot_refresh_time = time.time()
            return True
        # DEDUP_STEP5: fallback — original Redis/file path (used if positions_service not yet initialized)
        redis_data = None
        redis_age = 999999
        redis_ts = None
        if self.redis_manager:
            try:
                raw_data = await self.redis_manager.get(config.REDIS_KEY_MARKET_DATA)
                if raw_data:
                    redis_data = json.loads(raw_data) if isinstance(raw_data, (str, bytes)) else raw_data
                    if isinstance(redis_data, dict) and redis_data:
                        redis_ts = _snapshot_timestamp(redis_data)
                        if redis_ts:
                            redis_ts = safe_datetime(redis_ts)
                            if redis_ts:
                                redis_age = (datetime.now(timezone.utc) - redis_ts).total_seconds()
            except Exception as redis_err:
                logger.debug(f"[indicators] Redis check failed: {redis_err}")
        file_data = None
        file_age = 999999
        file_ts = None
        file_path_str = None
        latest_file = _get_latest_market_data_file()
        if latest_file:
            try:
                latest_path = Path(latest_file)
                file_path_str = str(latest_file)
                file_mtime = latest_path.stat().st_mtime
                if not force and self.currently_loaded_indicator_source_path and str(self.currently_loaded_indicator_source_path) == file_path_str:
                    last_load_time = getattr(self, '_last_file_load_mtime', 0.0)
                    if abs(file_mtime - last_load_time) < 0.1:
                        if self.indicators_snapshot:
                            return True
                json_content = await self._load_json_file_content(latest_path)
                if isinstance(json_content, dict) and json_content:
                    payload_ts = _snapshot_timestamp(json_content)
                    if payload_ts:
                        payload_ts = safe_datetime(payload_ts)
                        if payload_ts:
                            file_data = json_content
                            file_age = (datetime.now(timezone.utc) - payload_ts).total_seconds()
                            file_ts = payload_ts
                            self._last_file_load_mtime = file_mtime
            except Exception as exc:
                logger.debug(f"[indicators] File check failed: {exc}")
        final_payload = None
        final_ts = None
        final_source_label = "none"
        use_redis = False
        if redis_data and redis_age < 100:
            use_redis = True
        elif redis_data and file_data:
            if file_age < redis_age:
                use_redis = False
            else:
                use_redis = True # Redis is stale, but file is even staler
        elif redis_data:
            use_redis = True
        elif file_data:
            use_redis = False
        if use_redis and redis_data:
            final_payload = redis_data
            final_ts = redis_ts
            final_source_label = "redis"
        elif file_data:
            final_payload = file_data
            final_ts = file_ts
            final_source_label = f"file:{Path(file_path_str).name}"
        if not final_payload:
            logger.warning(f"⚠️ No valid market data found (Redis age: {redis_age:.1f}s, File age: {file_age:.1f}s)")
            return False
        current_snapshot = self.indicators_snapshot
        all_symbols = set()
        for sym_set in [ getattr(self, 'symbols_ang_long', set()), getattr(self, 'symbols_inf_long', set()), getattr(self, 'symbols_inf_short', set()), getattr(self, 'symbols_flz', set()), getattr(self, 'symbols_men', set()), getattr(self, 'symbols_fin', set()) ]:
            all_symbols.update(sym_set)
        PROTECTED_KEYS = { 'stoch_k_1m', 'stoch_d_1m', 'stoch_k_3m', 'stoch_d_3m', 'k1', 'd1', 'k3', 'd3', 'k1p', 'k3p', 'timestamp_1m', 'timestamp_3m', 'timestamp_3m_mid', 'current_price', 'price' }
        for raw_symbol, new_data in final_payload.items():
            if not isinstance(new_data, dict): continue
            symbol = str(raw_symbol).upper().strip()
            if symbol.endswith("USDT"):
                usdc_candidate = symbol.replace("USDT", "USDC")
                symbol_key = usdc_candidate if usdc_candidate in all_symbols else symbol
            else:
                symbol_key = symbol
            if symbol_key not in current_snapshot:
                current_snapshot[symbol_key] = new_data
                continue
            existing = current_snapshot[symbol_key]
            mem_ts_1m = _parse_indicator_timestamp(existing.get('timestamp_1m'))
            mem_ts_3m = _parse_indicator_timestamp(existing.get('timestamp_3m'))
            bulk_ts = _parse_indicator_timestamp(new_data.get('timestamp'))
            preserve_hot = False
            if mem_ts_1m and bulk_ts and mem_ts_1m > bulk_ts:
                preserve_hot = True
            elif mem_ts_3m and bulk_ts and mem_ts_3m > bulk_ts:
                preserve_hot = True
            elif existing.get('_hot_source'): 
                preserve_hot = True
            if preserve_hot:
                for k, v in new_data.items():
                    if k not in PROTECTED_KEYS:
                        existing[k] = v
            else:
                existing.update(new_data)
        self.indicators_timestamp = final_ts or datetime.now(timezone.utc)
        self.indicators_source_label = final_source_label
        self.latest_indicator_payload_timestamp = final_ts
        self._last_file_refresh_time = time.time()
        self.indicators_snapshot_refresh_time = time.time()
        if self.currently_loaded_indicator_source_path and "file" in final_source_label:
             try:
                self.raw_indicators_json_content = orjson.dumps(self.indicators_snapshot)
                self.last_redis_data_hash = hash(self.raw_indicators_json_content)
             except Exception: pass
        return True

    async def _refresh_indicators_from_file(self):
        """Refresh indicators_snapshot from Redis FIRST, fallback to file if Redis fails"""
        try:
            if self.redis_manager and getattr(self.redis_manager, "_initialized", False):
                try:
                    raw_data = await self.redis_manager.get(config.REDIS_KEY_MARKET_DATA)
                    if not raw_data:
                        raw_data = await self.redis_manager.get("latest_market_data")
                    if raw_data:
                        data = json.loads(raw_data) if isinstance(raw_data, (str, bytes)) else raw_data
                        if isinstance(data, dict) and data:
                            payload_ts = _snapshot_timestamp(data)
                            data_is_fresh = True
                            if payload_ts:
                                payload_ts = safe_datetime(payload_ts)
                                if payload_ts:
                                    data_age = (datetime.now(timezone.utc) - payload_ts).total_seconds()
                                    if data_age <= MAX_FILE_AGE_SECONDS:
                                        self.indicators_snapshot.clear()
                                        for sym, indicators in data.items():
                                            if isinstance(indicators, dict):
                                                self.indicators_snapshot[sym] = indicators
                                        self.indicators_cache_timestamps.clear()
                                        self.indicators_cache_timestamps.update({sym: time.time() for sym in data.keys()})
                                        self.indicators_timestamp = datetime.now(timezone.utc)
                                        self.indicators_source_label = "redis"
                                        self.indicators_snapshot_refresh_time = time.time()
                                        logger.debug(f" Refreshed indicators_snapshot from Redis with {len(data)} symbols (age={data_age:.1f}s)")
                                        return
                                    else:
                                        logger.debug(f"[_refresh_indicators_from_file] Redis data stale (age={data_age:.1f}s > {MAX_FILE_AGE_SECONDS:.0f}s), falling back to file")
                            else:
                                self.indicators_snapshot.clear()
                                for sym, indicators in data.items():
                                    if isinstance(indicators, dict):
                                        self.indicators_snapshot[sym] = indicators
                                self.indicators_cache_timestamps.clear()
                                self.indicators_cache_timestamps.update({sym: time.time() for sym in data.keys()})
                                self.indicators_timestamp = datetime.now(timezone.utc)
                                self.indicators_source_label = "redis"
                                self.indicators_snapshot_refresh_time = time.time()
                                logger.debug(f" Refreshed indicators_snapshot from Redis with {len(data)} symbols (no timestamp)")
                                return
                except Exception as redis_err:
                    logger.debug(f"[_refresh_indicators_from_file] Redis failed, using file: {redis_err}")
            import aiofiles
            latest_file = _get_latest_market_data_file()
            if not latest_file:
                self.indicators_snapshot_refresh_time = time.time()
                logger.error(f"❌ No valid market data file found in _refresh_indicators_from_file")
                return
            latest_path = Path(latest_file)
            if latest_path.exists():
                file_mtime = latest_path.stat().st_mtime
                file_age = time.time() - file_mtime
                if file_age > MAX_FILE_AGE_SECONDS:
                    logger.error(f"🚫 REJECTED STALE FILE in _refresh_indicators_from_file: {latest_path.name} (age={file_age:.0f}s > {MAX_FILE_AGE_SECONDS:.0f}s)")
                    self.indicators_snapshot_refresh_time = time.time()
                    return
                async with aiofiles.open(latest_path, 'r', encoding='utf-8') as f:
                    content = await f.read()
                    data = json.loads(content)
                    if isinstance(data, dict) and data:
                        payload_ts = _snapshot_timestamp(data)
                        data_is_fresh = True
                        if payload_ts:
                            payload_ts = safe_datetime(payload_ts)
                            if payload_ts:
                                data_age = (datetime.now(timezone.utc) - payload_ts).total_seconds()
                                if data_age > MAX_FILE_AGE_SECONDS:
                                    logger.error(f"🚫 REJECTED STALE DATA in {latest_path.name}: payload timestamp is {data_age:.0f}s old (> {MAX_FILE_AGE_SECONDS:.0f}s)")
                                    data_is_fresh = False
                        if data_is_fresh:
                            self.indicators_snapshot.clear()
                            for symbol, indicators in data.items():
                                if isinstance(indicators, dict):
                                    self.indicators_snapshot[symbol] = indicators
                            self.indicators_cache_timestamps.clear()
                            self.indicators_cache_timestamps.update({symbol: time.time() for symbol in data.keys()})
                            self.indicators_timestamp = datetime.fromtimestamp(file_mtime, tz=timezone.utc)
                            self.indicators_source_label = latest_path.name
                            self.latest_indicator_payload_timestamp = payload_ts
                            self.currently_loaded_indicator_source_path = latest_path
                            self.indicators_snapshot_refresh_time = time.time()
                            logger.debug(f" Refreshed indicators_snapshot from {latest_path.name} (file_age={file_age:.0f}s) with {len(data)} symbols")
                        else:
                            self.indicators_snapshot_refresh_time = time.time()
                            logger.error(f"🚫 Data in {latest_path.name} is stale, not refreshing snapshot")
            else:
                self.indicators_snapshot_refresh_time = time.time()
                logger.error(f"❌ Market data file {latest_path.name} does not exist")
        except Exception as e:
            logger.error(f"❌ Failed to refresh indicators from file: {e}")
            self.indicators_snapshot_refresh_time = time.time()

    async def _force_refresh_indicators_aggressive(self):
        """Aggressively refresh indicators from all available sources - used when stale data is detected"""
        refreshed = False
        if self.redis_manager:
            try:
                raw_data = await self.redis_manager.get(config.REDIS_KEY_MARKET_DATA)
                if raw_data:
                    data = json.loads(raw_data)
                    if isinstance(data, dict) and data:
                        should_refresh = True
                        btc_data = data.get("BTCUSDC", data.get("ETHUSDC", {}))
                        if isinstance(btc_data, dict):
                            payload = btc_data
                            if isinstance(payload, dict):
                                ts_raw = ( payload.get("_tick_ts") or payload.get("timestamp") or payload.get("time") or payload.get("timestamp_1m"))
                                if ts_raw:
                                    try:
                                        divisor = 1000.0 if isinstance(ts_raw, (int, float)) and ts_raw > 1e12 else 1.0
                                        indicator_ts = datetime.fromtimestamp(float(ts_raw) / divisor, tz=timezone.utc)
                                        data_age = (datetime.now(timezone.utc) - indicator_ts).total_seconds()
                                        if data_age < FORCE_REFRESH_MAX_AGE_SECONDS:
                                            logger.warning(f"⚠️ Redis data is {data_age:.0f}s old, trying file instead")
                                            should_refresh = False
                                    except Exception:
                                        pass
                        if should_refresh:
                            self.indicators_snapshot.clear()
                            for symbol, indicators in data.items():
                                if isinstance(indicators, dict):
                                    self.indicators_snapshot[symbol] = indicators
                            self.indicators_cache_timestamps.clear()
                            self.indicators_cache_timestamps.update({symbol: time.time() for symbol in data.keys()})
                            self.indicators_timestamp =datetime.now(timezone.utc)
                            self.indicators_source_label = "redis_aggressive_refresh"
                            self.latest_indicator_payload_timestamp = _snapshot_timestamp(data)
                            self.currently_loaded_indicator_source_path = None
                            self.indicators_snapshot_refresh_time = time.time()
                            logger.debug(f" [REFRESH] Refreshed from Redis with {len(data)} symbols")
                            refreshed = True
            except Exception as redis_err:
                logger.debug(f"[REFRESH] Redis failed: {redis_err}")
        if not refreshed:
            try:
                import aiofiles
                latest_file = _get_latest_market_data_file()
                if not latest_file:
                    logger.error(f"❌ [REFRESH] No valid market data file found")
                    return
                latest_path = Path(latest_file)
                if latest_path.exists():
                    file_mtime = latest_path.stat().st_mtime
                    file_age = time.time() - file_mtime
                    if file_age > MAX_FILE_AGE_SECONDS:
                        logger.error(f"🚫 [REFRESH] REJECTED STALE FILE: {latest_path.name} (age={file_age:.0f}s > {MAX_FILE_AGE_SECONDS:.0f}s)")
                        return
                    async with aiofiles.open(latest_path, 'r', encoding='utf-8') as f:
                        content = await f.read()
                        data = json.loads(content)
                        if isinstance(data, dict) and data:
                            payload_ts = _snapshot_timestamp(data)
                            if payload_ts:
                                payload_ts = safe_datetime(payload_ts)
                                if payload_ts:
                                    data_age = (datetime.now(timezone.utc) - payload_ts).total_seconds()
                                    if data_age > MAX_FILE_AGE_SECONDS:
                                        logger.error(f"🚫 [REFRESH] REJECTED STALE DATA: {latest_path.name} payload timestamp is {data_age:.0f}s old (> {MAX_FILE_AGE_SECONDS:.0f}s)")
                                        return
                            self.indicators_snapshot.clear()
                            for symbol, indicators in data.items():
                                if isinstance(indicators, dict):
                                    self.indicators_snapshot[symbol] = indicators
                            self.indicators_cache_timestamps.clear()
                            self.indicators_cache_timestamps.update({symbol: time.time() for symbol in data.keys()})
                            self.indicators_timestamp = datetime.fromtimestamp(file_mtime, tz=timezone.utc)
                            self.indicators_source_label = latest_path.name
                            self.latest_indicator_payload_timestamp = payload_ts
                            self.currently_loaded_indicator_source_path = latest_path
                            self.indicators_snapshot_refresh_time = time.time()
                            logger.debug(f" [REFRESH] Refreshed from file {latest_path.name} with {len(data)} symbols")
                            refreshed = True
            except Exception as file_err:
                logger.warning(f"⚠️ [REFRESH] File refresh failed: {file_err}")
        if not refreshed:
            logger.critical(f"[REFRESH] All sources failed, requesting indicator service restart")
            try:
                await request_ez_indicators_restart("stale_data_detected")
                await asyncio.sleep(3)
                await self._refresh_indicators_from_file()
            except Exception as restart_err:
                logger.critical(f"[REFRESH] Restart request failed: {restart_err}")
        return refreshed

    async def _last_events_refresh_loop(self):
        """Refresh last_events dict every 5 seconds from data/last_events.json"""
        await asyncio.sleep(10)
        while True:
            try:
                last_events_path = os.path.join('data', 'last_events.json')
                if os.path.exists(last_events_path):
                    with open(last_events_path, "rb") as f:
                        self.last_events = orjson.loads(f.read())
                    self.last_events_refresh_time = time.time()
                    logger.debug(f" Refreshed last_events dict with {len(self.last_events)} symbols")
                else:
                    self.last_events = {}
            except Exception as e:
                logger.error(f"❌ Last events refresh failed: {e}")
            await asyncio.sleep(45)

    async def _dict_refresh_watchdog(self):
        """Watchdog: Force refresh both dicts if they are > 22 seconds old (indicators) or > 27 seconds old (last_events)"""
        await asyncio.sleep(15)
        consecutive_failures = 0
        while True:
            try:
                now = time.time()
                indicators_age = now - self.indicators_snapshot_refresh_time if self.indicators_snapshot_refresh_time > 0 else 999
                last_events_age = now - self.last_events_refresh_time if self.last_events_refresh_time > 0 else 999
                actual_data_stale = False
                stale_data_age = 0.0
                if self.indicators_snapshot:
                    btc_data = self.indicators_snapshot.get("BTCUSDC", {})
                    if isinstance(btc_data, dict):
                        payload = btc_data
                        if isinstance(payload, dict):
                            ts_raw = ( payload.get("_tick_ts") or payload.get("timestamp") or payload.get("time") or payload.get("timestamp_1m") ) 
                            if ts_raw:
                                try:
                                    divisor = 1000.0 if isinstance(ts_raw, (int, float)) and ts_raw > 1e12 else 1.0
                                    indicator_ts = datetime.fromtimestamp(float(ts_raw) / divisor, tz=timezone.utc)
                                    data_age = (datetime.now(timezone.utc) - indicator_ts).total_seconds()
                                    stale_data_age = data_age
                                    if data_age > 120: # Data itself is > 2 minutes old
                                        actual_data_stale = True
                                        consecutive_failures += 1
                                        logger.critical(f"WATCHDOG CRITICAL: Indicator data itself is {data_age:.0f}s old (>120s), forcing refresh (consecutive failures: {consecutive_failures})")
                                except Exception:
                                    pass
                if indicators_age > 22 or actual_data_stale:
                    consecutive_failures += 1 if indicators_age > 22 else 0
                    logger.critical(f"WATCHDOG CRITICAL: indicators_snapshot cache is {indicators_age:.0f}s old (>22s) or data stale (age={stale_data_age:.0f}s), forcing refresh (consecutive failures: {consecutive_failures})")
                    try:
                        await self._refresh_indicators_from_file()
                        new_age = time.time() - self.indicators_snapshot_refresh_time if self.indicators_snapshot_refresh_time > 0 else 999
                        if new_age < 5: # Refresh happened (timestamp is fresh)
                            consecutive_failures = 0 # Reset on success
                        else:
                            logger.critical(f"WATCHDOG: Refresh called but timestamp still stale (age={new_age:.0f}s)")
                    except Exception as refresh_err:
                        logger.critical(f"WATCHDOG REFRESH FAILED: {refresh_err} (consecutive failures: {consecutive_failures})")
                else:
                    consecutive_failures = 0 # Reset if all good
                if last_events_age > 47:
                    logger.warning(f"🚨 WATCHDOG: last_events is {last_events_age:.0f}s old (>7s), forcing refresh")
                    try:
                        last_events_path = os.path.join('data', 'last_events.json')
                        if os.path.exists(last_events_path):
                            with open(last_events_path, "r", encoding="utf-8") as f:
                                self.last_events = json.load(f)
                            self.last_events_refresh_time = time.time()
                            logger.debug(f" WATCHDOG: Refreshed last_events dict with {len(self.last_events)} symbols")
                    except Exception as e:
                        logger.error(f"❌ WATCHDOG: Last events refresh failed: {e}")
                reentry_age = now - self.reentry_snapshot_refresh_time if self.reentry_snapshot_refresh_time > 0 else 999
                if reentry_age > 60:
                    await self._refresh_reentry_snapshot()
                ladder_age = now - self.ladder_snapshot_refresh_time if self.ladder_snapshot_refresh_time > 0 else 999
                if ladder_age > 60:
                    await self._refresh_ladder_snapshot()
                stop_age = now - self.stop_snapshot_refresh_time if self.stop_snapshot_refresh_time > 0 else 999
                if stop_age > 60:
                    await self._refresh_stop_snapshot()
            except Exception as e:
                logger.error(f"❌ Watchdog error: {e}")
            await asyncio.sleep(5) # Check every 5 seconds instead of 10

    async def _aggressive_indicator_health_check(self):
        """ Main Loop. 1. Checks Bridge Health (Hot Data). 2. If Bridge is dead > 20s, calls _refresh_indicators_from_sources(). """
        await asyncio.sleep(10)
        while True:
            try:
                now = time.time()
                hot_cache = getattr(self, 'hot_data_cache', {})
                bridge_alive = False
                btc = hot_cache.get("BTCUSDC")
                if btc:
                    last_rcv = btc.get('_rcv_ts', 0)
                    if (now - last_rcv) < 10.0:
                        bridge_alive = True
                        self.indicators_snapshot_refresh_time = now
                if bridge_alive:
                    await asyncio.sleep(2)
                    continue
                age = now - self.indicators_snapshot_refresh_time
                if age > 20.0:
                    logger.warning(f"⚠️ [HEALTH] Bridge silent for {age:.1f}s. Triggering Cold Refresh.")
                    await self._refresh_indicators_from_sources()
            except Exception as e:
                logger.error(f"Health Check Error: {e}")
            await asyncio.sleep(2)

    async def ensure_reentry_snapshot_fresh(self, force: bool = False):
        now = time.time()
        age = now - self.reentry_snapshot_refresh_time if self.reentry_snapshot_refresh_time > 0 else 999
        if force or not self.reentry_snapshot or age > 60:
            await self._refresh_reentry_snapshot(force=force)

    async def _refresh_reentry_snapshot(self, force: bool = False):
        async with self._reentry_snapshot_lock:
            now = time.time()
            if not force and self.reentry_snapshot and self.reentry_snapshot_refresh_time > 0 and now - self.reentry_snapshot_refresh_time <= 60:
                return
            snapshot = {}
            account_keys = list(getattr(self, "accounts", {}).keys()) if hasattr(self, "accounts") else []
            for account_key in account_keys:
                if isinstance(self.reentry_data, dict):
                    snapshot.update(self.reentry_data)
            self.reentry_snapshot = snapshot
            self.reentry_snapshot_refresh_time = now

    async def ensure_ladder_snapshot_fresh(self, force: bool = False):
        now = time.time()
        age = now - self.ladder_snapshot_refresh_time if self.ladder_snapshot_refresh_time > 0 else 999
        if force or not self.ladder_snapshot or age > 60:
            await self._refresh_ladder_snapshot(force=force)

    async def _refresh_ladder_snapshot(self, force: bool = False):
        async with self._ladder_snapshot_lock:
            now = time.time()
            if not force and self.ladder_snapshot and self.ladder_snapshot_refresh_time > 0 and now - self.ladder_snapshot_refresh_time <= 60:
                return
            account_keys = list(getattr(self, "accounts", {}).keys()) if hasattr(self, "accounts") else []
            for account_key in account_keys:
                try:
                    await self.load_ladder_levels(account_key)
                except Exception as err:
                    logger.error(f"❌ Ladder snapshot refresh failed for {account_key}: {err}")
            self.ladder_snapshot = self.ladder_levels if isinstance(self.ladder_levels, dict) else {}
            self.ladder_snapshot_refresh_time = now

    async def ensure_stop_snapshot_fresh(self, force: bool = False):
        now = time.time()
        age = now - self.stop_snapshot_refresh_time if self.stop_snapshot_refresh_time > 0 else 999
        if force or not self.stop_snapshot or age > 60:
            await self._refresh_stop_snapshot(force=force)

    async def _refresh_stop_snapshot(self, force: bool = False):
        async with self._stop_snapshot_lock:
            now = time.time()
            refresh_interval = 2.0
            if not force and self.stop_snapshot and self.stop_snapshot_refresh_time > 0 and now - self.stop_snapshot_refresh_time <= refresh_interval:
                return
            account_keys = list(getattr(self, "accounts", {}).keys()) if hasattr(self, "accounts") else []
            for account_key in account_keys:
                try:
                    await self.load_stop_levels(account_key)
                except Exception as err:
                    logger.error(f"❌ Stop snapshot refresh failed for {account_key}: {err}")
            self.stop_snapshot = self.stop_levels if isinstance(self.stop_levels, dict) else {}
            self.stop_snapshot_refresh_time = now

    async def get_cached_positions(self, account_key: str, max_age: float = None) -> Optional[Dict]:
        """Get positions from cache if fresh, returns None if cache doesn't exist or is too old"""
        async with self._autonomous_cache_lock:
            if account_key not in self._autonomous_position_cache:
                return None
            cached = self._autonomous_position_cache[account_key]
            max_age = max_age or self._cache_staleness_threshold
            cache_age = time.time() - cached.get('timestamp', 0)
            if cache_age < max_age:
                return cached['positions_dict']
            return None

    async def cleanup_old_cache_entries(self):
        """Remove old cache entries to prevent memory bloat"""
        while True:
            await asyncio.sleep(300) # Every 5 minutes
            try:
                current_time = time.time()
                expired_symbols = [ symbol for symbol, timestamp in self.indicators_cache_timestamps.items()if current_time - timestamp > 3600 ]
                for symbol in expired_symbols:
                    self.indicators_snapshot.pop(symbol, None)
                    self.indicators_cache_timestamps.pop(symbol, None)
                if expired_symbols:
                    logger.info(f"🧹 Cleaned up {len(expired_symbols)} old cache entries")
            except Exception as e:
                logger.error(f"❌ Cache cleanup failed: {e}")

    def get_client(self, account_key: str):
        if account_key not in self.accounts:
            logger.error(f"Account '{account_key}' not found in loaded accounts.")
            return None # Or raise a custom exception
        return self.accounts[account_key].client

    async def _get_file_lock(self, file_path: Path) -> asyncio.Lock:
        async with self._lock_for_file_write_locks: # Protects the self._file_write_locks dictionary
            if file_path not in self._file_write_locks:
                self._file_write_locks[file_path] = asyncio.Lock()
            return self._file_write_locks[file_path]

    def log_queue_states(self, account_key=None):
        if account_key:
            queue = self.account_position_queues.get(account_key, deque())
        else:
            for ak, q in self.account_position_queues.items():
                logger.debug(f"[Queue] {ak} queue size: {len(q)} - Next: {q[0] if q else 'None'}")

    def log_once_per_cooldown(self, position_key, message_type, message, cooldown_minutes=5):
        """Log a message only once per cooldown period per position"""
        now = datetime.now(timezone.utc)
        key = f"{position_key}:{message_type}"
        if key not in self.log_cooldowns or minutes_since(self.log_cooldowns[key], now) >= cooldown_minutes:
            self.log_cooldowns[key] = now

    async def _reinitialize_binance_client(self, account_key: str):
        account_config = self.accounts.get(account_key)
        if not account_config:
            logger.error(f"Account '{account_key}' does not exist, cannot reinitialize.")
            return
        await account_config.close()
        account_config.client = None
        await account_config.initialize()

    async def try_add_order_redis(self, position_key, expiry_seconds=45):
        """Enhanced with detailed logging and robust Redis client handling"""
        try:
            if position_key.startswith("execute_now:") or position_key.startswith("maker_order:"):
                lock_key = position_key
            else:
                lock_key = f"execute_now:{position_key}"
            redis_client = None
            if self.redis_manager and self.redis_manager._initialized:
                redis_client = self.redis_manager.connections.get("local")
            if redis_client:
                result = await redis_client.set(lock_key, "1", ex=expiry_seconds, nx=True)
                if result:
                    ttl = await redis_client.ttl(lock_key)
                    logger.debug(f"[LOCK_ACQUIRED] {lock_key}: Redis lock acquired (TTL={ttl}s)")
                return bool(result)
            logger.error(f"[LOCK_ERROR] {lock_key}: Redis client unavailable. Falling back to local lock.")
            return await self._try_local_lock(lock_key, expiry_seconds)
        except Exception as e:
            lock_key = position_key if position_key.startswith("execute_now:") else f"execute_now:{position_key}"
            lock_acquired = await self._try_local_lock(lock_key, expiry_seconds)
            if lock_acquired:
                logger.debug(f"[LOCK_ERROR] {lock_key}: Redis failed ({str(e)[:60]}), using local fallback")
            return lock_acquired

    async def _try_local_lock(self, position_key, expiry_seconds):
            """Try to acquire a local in-memory lock as fallback"""
            try:
                lock_key = position_key if position_key.startswith("execute_now:") else f"execute_now:{position_key}"
                now = time.time()
                expired = [k for k, v in self.local_locks.items() if v['expires'] < now]
                for k in expired:
                    del self.local_locks[k]
                if lock_key in self.local_locks and self.local_locks[lock_key]['expires'] > now:
                    return False
                self.local_locks[lock_key] = {'value': '1', 'expires': now + expiry_seconds}
                logger.debug(f"[LOCAL_LOCK_FALLBACK] {position_key}: Lock acquired in local fallback after Redis error")
                if not self.local_locks_cleanup_task:
                    self.local_locks_cleanup_task = None
                if self.local_locks_cleanup_task is None or self.local_locks_cleanup_task.done():
                    self.local_locks_cleanup_task = asyncio.create_task(self._cleanuplocal_locks())
                return True
            except Exception as e:
                logger.error(f"[LOCAL_LOCK_ERROR] {position_key}: Failed to set local lock: {e}")
                return False

    async def _cleanuplocal_locks(self):
        """Periodic cleanup of expired local locks"""
        while True:
            try:
                await asyncio.sleep(60)
                now = time.time()
                expired = [k for k, v in self.local_locks.items() if v['expires'] < now]
                for k in expired:
                    del self.local_locks[k]
                if expired:
                    logger.info(f"[LOCAL_LOCK_CLEANUP] Cleaned {len(expired)} expired locks")
            except Exception as e:
                logger.error(f"[LOCAL_LOCK_CLEANUP_ERROR] {e}")
                await asyncio.sleep(60)

    def _get_augmented_timestamp(self, position_key: str) -> Optional[datetime]:
        if not position_key or position_key not in self.augmented_positions:
            return None
        raw = self.augmented_positions[position_key]
        if isinstance(raw, datetime):
            if raw.tzinfo is None:
                raw = raw.replace(tzinfo=timezone.utc)
                self.augmented_positions[position_key] = raw
            return raw
        parsed = safe_datetime(raw)
        if isinstance(parsed, datetime):
            self.augmented_positions[position_key] = parsed
            return parsed
        logger.warning(f"[augmented_timestamp] Invalid entry for {position_key}: {type(raw)} -> {raw}")
        self.augmented_positions.pop(position_key, None)
        return None

    async def _expire_limbo_order(self, position_key: str, side: str, delay_seconds: float):
        """Remove order from limbo dict after delay if not confirmed"""
        await asyncio.sleep(delay_seconds)
        if position_key in self.orders_in_limbo and side in self.orders_in_limbo[position_key]:
            limbo_time = self.orders_in_limbo[position_key][side]
            if time.time() - limbo_time >= delay_seconds:
                del self.orders_in_limbo[position_key][side]
                if not self.orders_in_limbo[position_key]:
                    del self.orders_in_limbo[position_key]
                logger.debug(f"[{position_key}] Limbo order expired (not confirmed): {side}")
                async with self.dedupe_lock:
                    if position_key in self.order_deduplication:
                        self.order_deduplication.pop(position_key, None)
                        logger.debug(f"[CLEAR_DEDUPE_NOT_EXECUTED] {position_key}: Cleared deduplication entry (order not executed)")

    async def _delayed_lock_cleanup(self, lock_key: str, delay_seconds: int):
        try:
            logger.info(f"[DELAYED_CLEANUP] Waiting {delay_seconds}s before clearing {lock_key}")
            await asyncio.sleep(delay_seconds)
            if lock_key:
                current_value = await self.redis_manager.get(lock_key)
                if current_value and isinstance(current_value, str) and current_value.startswith("post_fill"): # Check for post_fill prefix to match post_fill_{action}
                    await self.redis_manager.delete(lock_key)
        except Exception as e:pass

    async def update_active_lock(self, position_key, status="active"):
        """Update the active lock status for a position key - works with ANY key"""
        try:
            if self.redis_manager:
                await self.redis_manager.set(position_key, status, ex=45)
        except Exception as e:
            logger.error(f"Error updating active lock for {position_key}: {e}")

    async def clear_active_lock(self, position_key):
        """Clear the active lock for ANY key - matches try _add_order_redis key transformation - clears both BUY and SELL locks"""
        try:
            if self.redis_manager:
                for side in ['BUY', 'SELL']:
                    lock_key = f"execute_now:{position_key}:{side}" if not position_key.startswith("execute_now:") else f"{position_key}:{side}"
                    await self.redis_manager.delete(lock_key)
                lock_key = position_key if position_key.startswith("execute_now:") else f"execute_now:{position_key}"
                await self.redis_manager.delete(lock_key)
            if hasattr(self, 'local_locks'):
                for side in ['BUY', 'SELL']:
                    lock_key = f"execute_now:{position_key}:{side}" if not position_key.startswith("execute_now:") else f"{position_key}:{side}"
                    self.local_locks.pop(lock_key, None)
                lock_key = position_key if position_key.startswith("execute_now:") else f"execute_now:{position_key}"
                self.local_locks.pop(lock_key, None)
        except Exception as e:
            logger.error(f"Error clearing active lock for {position_key}: {e}")

    async def audit_active_locks(self):
        try:
            logger.debug("[LOCK_AUDIT] Starting comprehensive lock audit...")
            if self.redis_manager:
                keys = []
                for target in self.redis_manager.connections:
                    if self.redis_manager.connections[target]:
                        try:
                            async for key in self.redis_manager.connections[target].scan_iter(match="execute_now:*"):
                                keys.append(key)
                        except Exception:
                            continue
                for key in keys:
                    position_key = key.replace("execute_now:", "")
                    try:
                        ttl = await self.redis_manager.connections['local'].ttl(key) if self.redis_manager.connections.get('local') else 0
                        is_processing = position_key in self.processing_keys
                        if ttl > 30 and not is_processing:
                            logger.error(f"[LOCK_LEAK] {position_key}: Stale lock with {ttl}s TTL but not in processing _keys!")
                            await self.redis_manager.delete(key)
                    except Exception:
                        continue
        except Exception as e:
            logger.error(f"[LOCK_AUDIT_ERROR] {e}")

    async def is_order_locked(self, position_key):
        """Check if ANY key is locked - checks both Redis and local locks"""
        try:
            keys = [position_key]
            if position_key and not position_key.startswith("execute_now:"):
                keys.append(f"execute_now:{position_key}")
            normalized_keys = [k if k.startswith("execute_now:") else f"execute_now:{k}" for k in keys]
            all_keys = list(set(keys + normalized_keys))
            if self.redis_manager:
                for key in all_keys:
                    try:
                        value = await self.redis_manager.get(key)
                        if value is not None:
                            return True
                    except Exception:
                        continue
            if hasattr(self, 'local_locks'):
                now = time.time()
                for key in all_keys:
                    if key in self.local_locks and self.local_locks[key].get('expires', 0.0) > now:
                        return True
            return False
        except Exception:
            return False

    async def get_lock_age(self, position_key: str) -> float:
        """Get the age of a Redis lock in seconds - properly calculates based on actual TTL"""
        try:
            if not self.redis_manager:
                return 0.0
            client = self.redis_manager.connections.get('local')
            if not client:
                return 0.0
            ttl = await client.ttl(position_key)
            if ttl:
                if ttl == -2:
                    return 0.0 # Key doesn't exist
                elif ttl == -1:
                    return 999.0 # Key exists but no expiration - treat as very old
                else:
                    if ttl >= 110: # Likely 120s expiry
                        return max(0.0, 120.0 - ttl)
                    elif ttl >= 40: # Likely 45s or 60s expiry
                        return max(0.0, 60.0 - ttl)
                    else: # Very short TTL - likely just set
                        return max(0.0, 45.0 - ttl)
            return 0.0
        except Exception as e:
            logger.error(f"Error getting lock age for {position_key}: {e}")
            return 0.0

    async def list_active_locks(self, account_key):
        client = None
        if self.redis_manager and self.redis_manager._initialized:
            client = self.redis_manager.connections.get("local")
        if not client:
            logger.warning(f"No Redis client available for listing locks for {account_key}")
            return
        active_locks = []
        async for key in client.scan_iter(match=f"{account_key}*_*"):
            ttl = await client.ttl(key)
            active_locks.append((key, ttl))
        for key, ttl in sorted(active_locks):
            logger.debug(f"{key:<50} TTL: {ttl:>4}s")

    async def force_clear_execution_lock(self, position_key: str):
        """Force clear execution lock for emergency recovery - clears both BUY and SELL locks"""
        exec_lock_key_buy = f"execute_now:{position_key}:BUY"
        exec_lock_key_sell = f"execute_now:{position_key}:SELL"
        try:
            await self.clear_active_lock(exec_lock_key_buy)
            await self.clear_active_lock(exec_lock_key_sell)
            return True
        except Exception as e:
            logger.error(f"[LOCK_RECOVERY] Failed to clear locks for {position_key}: {e}")
            return False

    async def clear_recent_signal(self, position_key):
        try:
            if self.redis_manager:
                await self.redis_manager.delete(f"recent_signal:{position_key}")
        except Exception as e:
            logger.warning(f"Error clearing redis recent signal for {position_key}: {e}")

    async def clear_all_cooldowns_for_position(self, position_key: str, side: str = None):
        """Clear signal cooldowns for a position when execution fails. NEVER clear augment guards."""
        try:
            self.recently_queued_signals.pop(position_key, None)
            # NEVER clear augmentation_cooldown_map — it's an augment guard, not a signal cooldown
            self.reduction_cooldown_map.pop(position_key, None)
            await self.clear_recent_signal(position_key)
            if hasattr(self, 'orders_in_limbo') and position_key in self.orders_in_limbo:
                if side:
                    self.orders_in_limbo[position_key].pop(side, None)
                    if not self.orders_in_limbo[position_key]:
                        del self.orders_in_limbo[position_key]
                else:
                    del self.orders_in_limbo[position_key]
            if hasattr(self, 'reduction_cooldown_map'):
                self.reduction_cooldown_map.pop(position_key, None)
            logger.debug(f"[CLEAR_ALL_COOLDOWNS] {position_key}: Cleared all cooldown data (side={side})")
        except Exception as e:
            logger.warning(f"[CLEAR_ALL_COOLDOWNS] {position_key}: Error clearing cooldowns: {e}")

    async def clear_all_trade_blocks(self, position_key: str, side: str = None):
        """Clear ALL trade blocking mechanisms including cooldowns, locks, and signals"""
        try:
            await self.clear_all_cooldowns_for_position(position_key, side)
            await self.clear_active_lock(position_key)
            logger.info(f"[CLEAR_ALL_TRADE_BLOCKS] {position_key}: Cleared all trade blocks (side={side})")
        except Exception as e:
            logger.warning(f"[CLEAR_ALL_TRADE_BLOCKS] {position_key}: Error clearing trade blocks: {e}")

    async def close_clients(self):
        account_keys_to_close = list(self.accounts.keys())
        if self.config and self.config.ACCOUNT_KEYS:
            account_keys_to_close = [ak for ak in account_keys_to_close if ak in self.config.ACCOUNT_KEYS]
        logger.info(f"🔌 Closing {len(account_keys_to_close)} client(s) for account(s): {account_keys_to_close}")
        for acct_key, acct in self.accounts.items():
            if acct_key not in account_keys_to_close:
                continue
            try:
                await acct.close()
                logger.info(f"Closed client for account '{acct_key}'")
            except Exception as e:
                logging.error(f"Error closing client for '{acct_key}': {e}")

    def _clean_old_position_cache(self):
        """Remove position cache entries older than 60 seconds to prevent memory leaks"""
        now = time.time()
        expired_keys = [ key for key, data in self._position_cache.items() if now - data['timestamp'] > 60]
        for key in expired_keys:
            del self._position_cache[key]

    async def get_cached_open_orders(self, account_key: Any, symbol: str | None = None) -> List[Dict[str, Any]]:
            cache_key = "all_open_orders"
            now = time.time()
            client = self.accounts.get(account_key).client
            if getattr(self, "_last_rate_limit_time", 0) and now - self._last_rate_limit_time < config.CIRCUIT_BREAKER_COOLDOWN:
                self.logger.warning("[get_cached_open_orders] circuit breaker active, using cached data")
                cached = self._order_cache.get(cache_key)
                if cached and "orders" in cached:
                    orders = cached["orders"]
                    return [o for o in orders if o.get("symbol") == symbol] if symbol else orders
                return []
            cached = self._order_cache.get(cache_key)
            if cached and "orders" in cached and now - cached["timestamp"] < config.ORDER_CACHE_TTL:
                orders = cached["orders"]
                return [o for o in orders if o.get("symbol") == symbol] if symbol else orders
            try:
                async with self.maker_semaphore:
                    orders = await asyncio.to_thread(client.futures_get_open_orders)
                self._order_cache[cache_key] = {"orders": orders, "timestamp": now}
                return [o for o in orders if o.get("symbol") == symbol] if symbol else orders
            except Exception as exc:
                error_str = str(exc)
                if "-1021" in error_str or "Timestamp" in error_str or "ahead" in error_str.lower():
                    self.logger.warning(f"[get_cached_open_orders] Timestamp error detected for {account_key}, syncing Binance time...")
                    account = self.accounts.get(account_key)
                    if account and hasattr(account, "sync_binance_time"):
                        account.sync_binance_time()
                if "banned" in error_str.lower() or "too many requests" in error_str.lower():
                    self._last_rate_limit_time = now
                    self.logger.error(f"[get_cached_open_orders] Rate limit detected: {exc}")
                    await delete_heartbeat_on_ban()
                    account = self.accounts.get(account_key)
                    if account and hasattr(account, "handle_api_ban"):
                        account.handle_api_ban()
                else:
                    self.logger.error(f"[get_cached_open_orders] Failed to fetch: {exc}")
                if cached and "orders" in cached:
                    self.logger.warning("[get_cached_open_orders] serving stale cache")
                    orders = cached["orders"]
                    return [o for o in orders if o.get("symbol") == symbol] if symbol else orders
                return []

    async def _load_initial_indicators_snapshot(self):
        """Ensure the fresh market-data snapshot is loaded before trading starts."""
        try:
            logger.info("📥 Loading Initial Indicators Snapshot...")
            success = await self._refresh_indicators_from_sources(force=True)
            if not success:
                 await self._ensure_latest_market_data_loaded(force=True)
            count = len(self.indicators_snapshot)
            if count > 0:
                logger.info(f" Initial snapshot loaded: {count} symbols")
            else:
                logger.warning("⚠️ Initial snapshot empty - waiting for background loops")
        except Exception as exc:
            logger.error(f"❌ Error loading initial indicators snapshot: {exc}", exc_info=True)

    def _get_latest_timestamped_file(self) -> Optional[Path]:
        """🚀 Get the latest timestamped market data file"""
        try:
            latest_file_path = _get_latest_market_data_file()
            if latest_file_path and Path(latest_file_path).exists():
                return Path(latest_file_path)
        except Exception as e:
            logger.debug(f"Error getting latest timestamped file: {e}")
        logger.warning("⚠️ No timestamped market data files found")
        return None

    async def _refresh_indicators_from_redis(self, symbol_key: str, bypass_snapshot: bool = False, force_refresh: bool = False) -> Dict[str, Any]:
        snapshot = await self._get_fresh_snapshot(force_refresh)
        if not snapshot:
            return {}
        payload = snapshot.get(symbol_key, {})
        if not isinstance(payload, dict) or not _indicator_payload_is_fresh(payload, MAX_MARKET_DATA_AGE_SECONDS, getattr(self, "indicators_timestamp", None)):
            if bypass_snapshot:
                return {}
            snapshot = await self._get_fresh_snapshot(True)
            payload = snapshot.get(symbol_key, {})
            if not isinstance(payload, dict) or not _indicator_payload_is_fresh(payload, MAX_MARKET_DATA_AGE_SECONDS, getattr(self, "indicators_timestamp", None)):
                return {}
        async with self.redis_fetch_lock:
            if not hasattr(self, 'indicators_snapshot') or self.indicators_snapshot is None:
                self.indicators_snapshot = {}
            self.indicators_snapshot[symbol_key] = payload
            self.indicators_cache_timestamps[symbol_key] = time.time()
        return payload.copy()

    async def _load_from_timestamped_file(self, symbol_key: str) -> Dict[str, Any]:
        try:
            latest_file = self._get_latest_timestamped_file()
            if not latest_file:
                logger.warning(f"[{symbol_key}] No timestamped market data file available")
                return {}
            latest_path = Path(latest_file)
            if not await aio_os.path.exists(latest_path):
                logger.warning(f"[{symbol_key}] Timestamped file missing: {latest_path}")
                return {}
            file_stat = await aio_os.stat(latest_path)
            file_age_seconds = (datetime.now(timezone.utc).timestamp() - file_stat.st_mtime)
            if file_age_seconds > 900: # 5 minutes
                logger.warning(f"[{symbol_key}] File too old: {latest_path.name} (age: {file_age_seconds:.0f}s) - rejecting stale data")
                return {}
            json_content = await self._load_json_file_content(latest_path)
            if not json_content or not isinstance(json_content, dict):
                logger.warning(f"[{symbol_key}] Invalid or empty content in timestamped file: {latest_path}")
                return {}
            snapshot_ts = None; ts_str = ''
            for symbol_data in json_content.values():
                if not isinstance(symbol_data, dict): continue
                for key in ('timestamp','timestamp_3m','last_updated','timestamp_1m','timestamp_5m','timestamp_15m'):
                    candidate = _parse_indicator_timestamp(symbol_data.get(key))
                    if candidate and (snapshot_ts is None or candidate > snapshot_ts):
                        snapshot_ts = candidate if candidate.tzinfo else candidate.replace(tzinfo=timezone.utc)
                        ts_value = symbol_data.get(key)
                        ts_str = ts_value if isinstance(ts_value, str) else snapshot_ts.isoformat().replace('+00:00','Z')
            if snapshot_ts is None:
                snapshot_ts = datetime.now(timezone.utc)
                ts_str = snapshot_ts.isoformat().replace('+00:00','Z')
            elif snapshot_ts.tzinfo is None:
                snapshot_ts = snapshot_ts.replace(tzinfo=timezone.utc)
                ts_str = ts_str or snapshot_ts.isoformat().replace('+00:00','Z')
            else:
                ts_str = ts_str or snapshot_ts.isoformat().replace('+00:00','Z')
            self.indicators_timestamp = snapshot_ts
            self.raw_indicators_json_content = orjson.dumps(json_content)
            return json_content.get(symbol_key, {})
        except Exception as e:
            logger.error(f"[{symbol_key}] Error loading from timestamped file: {e}")
            return {}

    async def _ensure_latest_market_data_loaded(self, force: bool = False) -> None:
        latest_file = _get_latest_market_data_file()
        if not latest_file:
            logger.error(f"❌ No valid market data file found in _ensure_latest_market_data_loaded")
            return
        latest_path = Path(latest_file)
        try:
            latest_mtime = latest_path.stat().st_mtime
        except OSError:
            return
        now_ts = time.time()
        file_age = now_ts - latest_mtime
        if file_age > MAX_FILE_AGE_SECONDS:
            logger.error(f"🚫 REJECTED STALE FILE in _ensure_latest_market_data_loaded: {latest_path.name} (age={file_age:.0f}s > {MAX_FILE_AGE_SECONDS:.0f}s)")
            return
        json_content = await self._load_json_file_content(latest_path)
        if not isinstance(json_content, dict) or not json_content:
            return
        payload_ts = _snapshot_timestamp(json_content)
        if payload_ts:
            payload_ts = safe_datetime(payload_ts)
            if payload_ts:
                payload_age = (datetime.now(timezone.utc) - payload_ts).total_seconds()
                if payload_age > MAX_FILE_AGE_SECONDS:
                    logger.error(f"🚫 REJECTED STALE DATA in _ensure_latest_market_data_loaded: {latest_path.name} payload timestamp is {payload_age:.0f}s old (> {MAX_FILE_AGE_SECONDS:.0f}s)")
                    return
        self._latest_market_data_path = latest_path
        self._latest_market_data_mtime = latest_mtime
        self._snapshot_last_refresh = now_ts
        snapshot_ts = datetime.fromtimestamp(latest_mtime, tz=timezone.utc)
        self.latest_indicator_payload_timestamp = payload_ts
        self.currently_loaded_indicator_source_path = latest_path
        self._apply_indicator_payload(json_content, str(latest_path), snapshot_ts)
        fallback_candidates = [self.indicators_timestamp]
        if getattr(self, "_snapshot_last_refresh", 0.0):
            fallback_candidates.append(datetime.fromtimestamp(self._snapshot_last_refresh, tz=timezone.utc))
        if not _snapshot_is_fresh(self.indicators_snapshot, MAX_MARKET_DATA_AGE_SECONDS, fallback_candidates):
            logger.warning(f"⚠️ Loaded indicators snapshot is older than {MAX_MARKET_DATA_AGE_SECONDS:.0f}s based on embedded timestamps")

    def _apply_indicator_payload(self, payload: Dict[str, Any], source: str = "", timestamp: Optional[datetime] = None) -> None:
        if not isinstance(payload, dict) or not payload:
            return
        ts_candidates: List[datetime] = []
        if isinstance(timestamp, datetime):
            ts_candidates.append(timestamp if timestamp.tzinfo else timestamp.replace(tzinfo=timezone.utc))
        payload_ts = _snapshot_timestamp(payload)
        if isinstance(payload_ts, datetime):
            ts_candidates.append(payload_ts if payload_ts.tzinfo else payload_ts.replace(tzinfo=timezone.utc))
        if isinstance(source, str):
            try:
                source_path = Path(source)
                if source_path.exists():
                    ts_candidates.append(datetime.fromtimestamp(source_path.stat().st_mtime, tz=timezone.utc))
            except Exception:
                pass
        ts_candidates.append(datetime.now(timezone.utc))
        ts = max(ts_candidates)
        self.indicators_source_label = source or "unknown"
        if source == "redis":
            self.currently_loaded_indicator_source_path = None
        elif isinstance(source, str) and source and source != "unknown":
            try:
                source_path = Path(source)
                if source_path.exists():
                    self.currently_loaded_indicator_source_path = source_path
                    self._last_file_load_mtime = source_path.stat().st_mtime
            except Exception:
                pass
        normalized: Dict[str, Dict[str, Any]] = {}
        ts_iso = ts.strftime('%Y-%m-%dT%H:%M:%S.%fZ')
        now_ts = time.time()
        all_symbols = set()
        for sym_set in [getattr(self, 'symbols_ang_long', set()), getattr(self, 'symbols_inf_long', set()), getattr(self, 'symbols_inf_short', set()), getattr(self, 'symbols_flz', set()), getattr(self, 'symbols_men', set()), getattr(self, 'symbols_ang_short', set()), getattr(self, 'symbols_fin', set())]:
            all_symbols.update(sym_set)
        for symbol, data in payload.items():
            if not isinstance(symbol, str) or not isinstance(data, dict):
                continue
            symbol = symbol.strip().upper()
            if symbol.endswith("USDT"):
                usdc_candidate = symbol.replace("USDT", "USDC")
                symbol_key = usdc_candidate if usdc_candidate in all_symbols else symbol
            else:
                symbol_key = symbol
            payload_dict = dict(data)
            symbol_ts = _indicator_payload_timestamp(payload_dict)
            needs_override = True
            if isinstance(symbol_ts, datetime):
                symbol_ts = symbol_ts if symbol_ts.tzinfo else symbol_ts.replace(tzinfo=timezone.utc)
                needs_override = (ts - symbol_ts).total_seconds() > 30.0
            if needs_override:
                payload_dict["timestamp"] = ts_iso
                payload_dict["generated_at"] = ts_iso
                payload_dict["last_updated"] = ts_iso
                complete_section = payload_dict.get("complete")
                if isinstance(complete_section, dict):
                    complete_copy = dict(complete_section)
                    complete_copy["timestamp"] = ts_iso
                    complete_copy["generated_at"] = ts_iso
                    complete_copy["last_updated"] = ts_iso
                    payload_dict["complete"] = complete_copy
            normalized[symbol_key] = payload_dict
        if not normalized:
            return
        self.indicators_snapshot.clear()
        self.indicators_cache_timestamps.clear()
        for symbol_key, data in normalized.items():
            self.indicators_snapshot[symbol_key] = data
            self.indicators_cache_timestamps[symbol_key] = now_ts
        try:
            self.raw_indicators_json_content = orjson.dumps(normalized)
        except Exception:
            try:
                self.raw_indicators_json_content = json.dumps(normalized).encode("utf-8")
            except Exception:
                self.raw_indicators_json_content = None
        self.indicators_timestamp = ts
        self._snapshot_last_refresh = now_ts
        if source == "redis" and self.raw_indicators_json_content:
            try:
                self.last_redis_data_hash = hash(self.raw_indicators_json_content)
            except Exception:
                pass

    async def _get_fresh_snapshot(self, force: bool = False) -> Dict[str, Any]:
        async with self._snapshot_lock:
            snapshot = self.indicators_snapshot if isinstance(self.indicators_snapshot, dict) else None
            snapshot_ts = self.indicators_timestamp if isinstance(getattr(self, "indicators_timestamp", None), datetime) else None
        if force and snapshot and snapshot_ts:
            logger.debug("[indicators] Force refresh requested; bypassing existing snapshot freshness check")
        elif snapshot and _snapshot_is_fresh(snapshot, MAX_MARKET_DATA_AGE_SECONDS, snapshot_ts):
            return snapshot
        refreshed = await self._refresh_indicators_from_sources(force=True)
        snapshot = self.indicators_snapshot if isinstance(self.indicators_snapshot, dict) else None
        snapshot_ts = self.indicators_timestamp if isinstance(getattr(self, "indicators_timestamp", None), datetime) else None
        fallback_candidates = [snapshot_ts] if snapshot_ts else []
        if getattr(self, "_snapshot_last_refresh", 0.0):
            fallback_candidates.append(datetime.fromtimestamp(self._snapshot_last_refresh, tz=timezone.utc))
        if snapshot and _snapshot_is_fresh(snapshot, MAX_MARKET_DATA_AGE_SECONDS, fallback_candidates):
            return snapshot
        if not refreshed:
            await self._ensure_latest_market_data_loaded(force=True)
            snapshot = self.indicators_snapshot if isinstance(self.indicators_snapshot, dict) else None
            snapshot_ts = self.indicators_timestamp if isinstance(getattr(self, "indicators_timestamp", None), datetime) else None
            fallback_candidates = [snapshot_ts] if snapshot_ts else []
            if getattr(self, "_snapshot_last_refresh", 0.0):
                fallback_candidates.append(datetime.fromtimestamp(self._snapshot_last_refresh, tz=timezone.utc))
            if snapshot and _snapshot_is_fresh(snapshot, MAX_MARKET_DATA_AGE_SECONDS, fallback_candidates):
                return snapshot
        if snapshot:
            return snapshot
        logger.warning("⚠️ Indicators snapshot unavailable after refresh")
        await _maybe_restart_indicators(self, "missing_snapshot")
        return {}

    async def market_snapshot_refresh_loop(self, interval: float = None):
        refresh_interval = float(interval or self._snapshot_refresh_interval)
        await asyncio.sleep(0.1)
        while True:
            try:
                await self._refresh_indicators_from_sources()
            except Exception as exc:
                logger.error(f"[snapshot_refresh_loop] Failed to refresh market data snapshot: {exc}")
            await asyncio.sleep(refresh_interval)

    def get_indicators_cache_stats(self) -> Dict[str, Any]:
        """🚀 Get cache statistics for monitoring and debugging."""
        now = datetime.now(timezone.utc)
        age_seconds = (now - self.indicators_timestamp).total_seconds() if self.indicators_timestamp > datetime.min.replace(tzinfo=timezone.utc) else -1
        current_file = self._get_latest_timestamped_file()
        file_exists = current_file.exists() if current_file else False
        cache_size = 0
        if self.raw_indicators_json_content:
            try:
                snapshot_dict = orjson.loads(self.raw_indicators_json_content)
                cache_size = len(snapshot_dict)
            except Exception:
                cache_size = 0
        return { "cache_size": cache_size, "last_update": self.indicators_timestamp.strftime('%Y-%m-%dT%H:%M:%S.%fZ') if self.indicators_timestamp > datetime.min.replace(tzinfo=timezone.utc) else "never", "age_seconds": age_seconds, "is_fresh": age_seconds < self.indicators_cache_ttl if age_seconds >= 0 else False, "ttl_seconds": self.indicators_cache_ttl, "redis_hash": self.last_redis_data_hash, "legacy_cache_size": len(self.indicators_snapshot), "current_file": str(current_file) if current_file else "none", "file_exists": file_exists, "file_name": current_file.name if current_file else "none" }

    def force_clear_indicators_cache(self):
        """🚀 Force clear the indicators cache to force fresh data on next request."""
        self.raw_indicators_json_content = None
        self.indicators_timestamp = datetime.min.replace(tzinfo=timezone.utc)
        self.last_redis_data_hash = None
        logger.info("🚀 FORCED indicators cache clear - next request will fetch fresh data")

    def enable_hash_debugging(self):
        """🚀 Enable detailed hash debugging for troubleshooting."""
        self._debug_hash_logging = True
        logger.info("🚀 HASH DEBUGGING ENABLED - will log Redis hash comparisons")

    async def check_redis_data_freshness(self):
        """🚀 Check if Redis data is fresh and log detailed status."""
        if not self.redis_manager:
            logger.warning("🚨 Cannot check Redis freshness - no Redis manager")
            return False
        try:
            json_data_bytes = await self.redis_manager.get("latest_market_data")
            if not json_data_bytes:
                logger.warning("🚨 Redis 'latest_market_data' key is empty")
                return False
            try:
                test_parse = safe_json_loads(json_data_bytes)
            except JSONDecodeError as e:
                logger.debug(f"Redis data parse failed during integrity check: {e} - attempting recovery")
                json_data_str = None
                if isinstance(json_data_bytes, bytes):
                    try: json_data_str = json_data_bytes.decode('utf-8')
                    except Exception: pass
                elif isinstance(json_data_bytes, str):
                    json_data_str = json_data_bytes
                repaired = False
                if json_data_str:
                    repaired_content = await self._attempt_json_repair(json_data_str)
                    if repaired_content:
                        try:
                            test_parse = json.loads(repaired_content)
                            repaired = True
                            logger.debug(" Repaired Redis data during integrity check")
                        except Exception: pass
                if not repaired:
                    logger.error("Corrupted Redis data detected during integrity check, clearing")
                    try:
                        await self.redis_manager.delete("latest_market_data")
                        logger.info("Successfully cleared corrupted Redis data during integrity check")
                    except Exception as redis_error:
                        logger.error(f"Failed to clear corrupted Redis data during integrity check: {redis_error}")
                    return False
            current_hash = hash(json_data_bytes)
            age_seconds = (datetime.now(timezone.utc) - self.indicators_timestamp).total_seconds() if self.indicators_timestamp > datetime.min.replace(tzinfo=timezone.utc) else -1
            logger.info(f"🚀 REDIS DATA STATUS: hash={current_hash}, cached_hash={self.last_redis_data_hash}, age={age_seconds:.1f}s, size={len(json_data_bytes)} bytes")
            if age_seconds > 60: # More than 1 minute old
                logger.warning(f"🚨 REDIS DATA IS OLD: {age_seconds:.1f} seconds old - may be stale!")
            return True
        except Exception as e:
            logger.error(f"🚨 Error checking Redis data freshness: {e}")
            return False

    async def repair_latest_market_data_json(self, corrupted_file_path: str) -> dict:
        """Repair latest_market_data.json by trying to fix corrupted JSON (used as last resort fallback)"""
        try:
            if await aio_os.path.exists(corrupted_file_path):
                try:
                    async with aiofiles.open(corrupted_file_path, 'r', encoding='utf-8') as f:
                        content = await f.read()
                        if content.strip():
                            repaired_content = await self._attempt_json_repair(content)
                            if repaired_content:
                                try:
                                    data = json.loads(repaired_content)
                                    if isinstance(data, dict):
                                        logger.info(f"[REPAIR] Successfully repaired latest_market_data.json")
                                        return data
                                except json.JSONDecodeError:
                                    pass
                except Exception as e:
                    logger.debug(f"[REPAIR] Could not read latest_market_data.json: {e}")
            logger.debug("[REPAIR] latest_market_data.json is not available or corrupted")
            return {}
        except Exception as e:
            logger.error(f"[REPAIR] Failed to repair latest_market_data.json: {e}")
            return {}

    async def force_refresh_all_indicators(self):
        logger.info("🚨 FORCE REFRESHING ALL INDICATORS - bypassing all caching")
        async with self._snapshot_lock:
            backup_snapshot = dict(self.indicators_snapshot) if isinstance(self.indicators_snapshot, dict) else {}
            backup_cache = dict(self.indicators_cache_timestamps) if isinstance(self.indicators_cache_timestamps, dict) else {}
            backup_raw = self.raw_indicators_json_content
            backup_timestamp = self.indicators_timestamp
            backup_last_refresh = self._snapshot_last_refresh
            backup_source = getattr(self, "indicators_source_label", "unknown")
        self.last_redis_data_hash = None
        loaded = 0
        source = "none"
        redis_payload = None
        if self.redis_manager and hasattr(self.redis_manager, "get"):
            try:
                raw = await self.redis_manager.get("latest_market_data")
                if raw:
                    if isinstance(raw, dict):
                        parsed = raw
                    else:
                        parsed = None
                        try:
                            parsed = orjson.loads(raw)
                        except TypeError:
                            if isinstance(raw, str):
                                parsed = orjson.loads(raw.encode("utf-8"))
                        except Exception:
                            try:
                                text = raw.decode("utf-8") if isinstance(raw, (bytes, bytearray)) else str(raw)
                                parsed = json.loads(text)
                            except Exception as decode_err:
                                logger.warning(f"[force_refresh_all_indicators] Redis data decode failed: {decode_err}")
                    if isinstance(parsed, dict) and parsed:
                        redis_payload = parsed
            except Exception as redis_err:
                logger.warning(f"[force_refresh_all_indicators] Redis fetch failed: {redis_err}")
        if isinstance(redis_payload, dict) and redis_payload:
            ts = _snapshot_timestamp(redis_payload) or datetime.now(timezone.utc)
            async with self._snapshot_lock:
                self.latest_indicator_payload_timestamp = _snapshot_timestamp(redis_payload)
                self._apply_indicator_payload(redis_payload, "redis", ts)
            loaded = len(self.indicators_snapshot) if isinstance(self.indicators_snapshot, dict) else 0
            source = "redis" if loaded else source
        if loaded == 0:
            await self._get_fresh_snapshot(force=True)
            loaded = len(self.indicators_snapshot) if isinstance(self.indicators_snapshot, dict) else 0
            source = "file" if loaded and source == "none" else source
        if loaded == 0:
            await self._ensure_latest_market_data_loaded(force=True)
            loaded = len(self.indicators_snapshot) if isinstance(self.indicators_snapshot, dict) else 0
            source = "file" if loaded and source == "none" else source
        if loaded == 0:
            async with self._snapshot_lock:
                if backup_snapshot:
                    self.indicators_snapshot = backup_snapshot
                    self.indicators_cache_timestamps.clear()
                    if isinstance(backup_cache, dict):
                        self.indicators_cache_timestamps.update(backup_cache)
                    self.raw_indicators_json_content = backup_raw
                    self.indicators_timestamp = backup_timestamp
                    self._snapshot_last_refresh = backup_last_refresh
                    self.indicators_source_label = backup_source
            logger.warning("⚠️ FORCE REFRESH COMPLETE - snapshot still empty after redis+file attempts, restored previous snapshot")
        else:
            logger.debug(f"🚨 FORCE REFRESH COMPLETE - loaded {loaded} symbols via {source}")
        return loaded

    async def _load_json_file_content(self, file_path: Path) -> Dict[str, Any]:
        raw_content = ""
        try:
            if not file_path or not await aio_os.path.exists(file_path):
                return {} 
            async with aiofiles.open(file_path, "r", encoding='utf-8') as f:
                raw_content = await f.read()
            if not raw_content.strip():
                return {}
            try:
                data = safe_json_loads(raw_content)
                if not isinstance(data, dict):
                    logger.warning(f"Content of '{file_path.name}' is not a dictionary. Treating as empty.")
                    return {}
                return data
            except JSONDecodeError as e:
                logger.warning(f"JSON decode error in '{file_path.name}': {e} - attempting recovery")
                raw_content = raw_content.strip()
                if raw_content.endswith(','):
                    raw_content = raw_content[:-1]
                if not raw_content.endswith('}'):
                    raw_content += '}'
                try:
                    data = json.loads(raw_content)
                    if isinstance(data, dict):
                        logger.debug(f" Recovered JSON from '{file_path.name}' after fixing trailing issues")
                        return data
                except Exception:
                    pass
                try:
                    decoder = json.JSONDecoder()
                    first_obj, index = decoder.raw_decode(raw_content)
                    if isinstance(first_obj, dict):
                        logger.warning(f"Partial recovery of '{file_path.name}' - using first valid dictionary")
                        return first_obj
                except Exception:
                    pass
                logger.error(f"Failed to load '{file_path.name}")
                return {}
        except Exception as e:
            logger.error(f"Error loading '{file_path}': {e}")
            return {}

    def _schedule_save(self):
        """Schedule a save task if one isn't already running/pending"""
        if not self._save_accounts_lock:
            self._save_accounts_lock = DummyLock()
            self._last_save_time = 0.0
            self._save_cooldown = 1.0 # Reduced to 1 second for real-time websocket updates
        if self._save_task is None or self._save_task.done():
            self._save_task = asyncio.create_task(self._save_all_accounts())

    async def _save_all_accounts(self, force: bool = False):
        logger.warning("[NOT_ALLOWED] ez_manage.py is NOT_ALLOWED to save positions to disk. Save operation was not_allowed.")
        return

    async def _save_all_accounts_impl(self):
        logger.warning("[NOT_ALLOWED] ez_manage.py is NOT_ALLOWED to save positions to disk. _save_all_accounts_impl was not_allowed.")
        return True

    async def restore_position_from_backups(self, account_key: Optional[str] = None, symbol: Optional[str] = None, position_side: Optional[str] = None) -> Optional[Position]:
        """Delegate to positions_service which searches: own backups → own main file → ALL other accounts."""
        if not account_key or not symbol or not position_side:
            return None
        if self.positions_service and hasattr(self.positions_service, 'restore_position_from_backups'):
            return await self.positions_service.restore_position_from_backups(account_key, symbol, position_side)
        return None

    async def get_symbols_for_account(self, account_key: Optional[str] = None) -> set:
        if not account_key: return set()
        symbols_map = { "ang": self.symbols_ang_long.union(self.symbols_ang_short), "inf": self.symbols_inf_long.union(self.symbols_inf_short), "men": self.symbols_men, "flz": self.symbols_flz, }
        symbols = symbols_map.get(account_key, [])
        return set(s.strip().upper() for s in symbols if s)

    async def ensure_position_present(self, account_key: Optional[str] = None, symbol: Optional[str] = None, position_side: Optional[str] = None, position_key: Optional[str] = None) -> Optional[Position]:
        try:
            if not position_key:
                position_key = construct_position_key(account_key, symbol, position_side)
            await self.load_all_positions()
            position = await self.get_position(position_key)
            if position:
                return position
            restored = await self.restore_position_from_backups(account_key, symbol, position_side)
            if restored:
                self.positions_by_account.setdefault(account_key, {})[position_key] = restored
                await self._save_all_accounts()
                return restored
            return None
        except Exception as e:
            logger.error(f"[ensure_position_present] Failure ensuring position {position_key}: {e}")
            return None

    async def load_all_positions(self):
        """KILLED — positions loaded once at bootstrap from disk. After that, API/WS only."""
        return

    async def _load_positions_with_lock(self, master_allowed_symbols):
        # positions_service bailout removed — refresh from Redis/files is backup
        total_loaded_count = 0
        total_ignored_count = 0
        for account_config in self.accounts.values():
            account_key = account_config.prefix
            current_account_positions_in_memory = self.positions_by_account.setdefault(account_key, {})
            for position_side_str in ["LONG", "SHORT"]:
                file_path = await self.get_position_file(account_key, position_side_str)
                symbols_data_from_disk = await self._load_and_merge_backups(file_path, position_side_str)
                for raw_key, position_data_on_disk in symbols_data_from_disk.items():
                    if not isinstance(position_data_on_disk, dict):
                        continue
                    symbol = position_data_on_disk.get('symbol') or ''
                    if not symbol:
                        symbol = str(raw_key).split(':', 1)[-1] if ':' in str(raw_key) else str(raw_key)
                        symbol = symbol.replace(f"_{position_side_str}", "").replace("_LONG", "").replace("_SHORT", "")
                    symbol = str(symbol).strip().upper()
                    if not symbol:
                        total_ignored_count += 1
                        continue
                    if symbol not in master_allowed_symbols:
                        logger.debug(f"[load_all_positions] Loading position for '{symbol}' (not in active symbols.json but preserving data)")
                    try:
                        normalized_position_key = construct_position_key(account_key, symbol, position_side_str)
                        if not normalized_position_key: 
                            logger.error(f"[load_pos] ⚠️ SKIPPING - construct_position_key returned None: account={account_key}, symbol={symbol}, entry_side={position_side_str}")
                            continue
                    except ValueError as e:
                        logger.warning(f"[load_all_positions] Failed to construct position key for symbol '{symbol}': {e}")
                        continue
                    try:
                        position_data_on_disk['symbol'] = symbol
                        position_data_on_disk['position_side'] = position_side_str
                        disk_pos_obj_candidate = Position.from_dict(position_data_on_disk)
                    except Exception as e:
                        logger.error(f"[load_all_positions] Error creating Position object for '{raw_key}': {e}.") 
                        continue
                    if normalized_position_key not in current_account_positions_in_memory:
                        current_account_positions_in_memory[normalized_position_key] = disk_pos_obj_candidate
                        logger.debug(f"[l oad_all_positions] Added new position from disk: {normalized_position_key}")
                    else:
                        logger.debug(f"[l oad_all_positions] Preserving existing memory position: {normalized_position_key}")
                    total_loaded_count += 1
        logger.info(f"[l oad_all_positions] Finished. Loaded {total_loaded_count} positions (including positions for symbols not in symbols.json to preserve data).")
        monitored_account_keys = set(self.accounts.keys())
        for account_key in monitored_account_keys:
            account_positions = self.positions_by_account.get(account_key, {})
            for position_key, position in account_positions.items():
                self.positions[position_key] = position
        logger.info(f"[l oad_all_positions] Synced {len(self.positions)} positions to positions dict (for {len(monitored_account_keys)} monitored account(s): {sorted(monitored_account_keys)})")
        fixed_count = self.validate_positions_floats()
        if fixed_count > 0:
            logger.info(f"[l oad_all_positions] Fixed {fixed_count} positions with string numeric values during load")

    async def cleanup_temp_files(self, account_key: Optional[str] = None) -> int:
        if not account_key or not isinstance(account_key, str):
            return 0
        temp_files_cleaned = 0
        try:
            import glob
            import os
            base_path_str = str(self.config.BASE_PATH)
            account_dir_str = os.path.join(base_path_str, account_key.lower())
            if not await aio_os.path.exists(account_dir_str):
                return 0
            temp_patterns = [ "*.tmp", "*.temp", "*.pid.*.tmp", "*_positions.json.tmp", "*_positions.*.tmp", "*_stop_levels.json.tmp", "*_reentry.json.tmp", "*_augmented_positions.json.tmp", "*_reversed_positions.json.tmp", "*.json.tmp" ]
            for pattern in temp_patterns:
                search_path = os.path.join(account_dir_str, "**", pattern)
                for temp_path in glob.glob(search_path, recursive=True):
                    try:
                        await aio_os.remove(temp_path)
                        temp_files_cleaned += 1
                    except Exception:
                        pass
            cutoff_time = time.time() - (7 * 24 * 3600) # 7 days in seconds
            backup_patterns = ["*backup*.json", "*_backup_*.json"]
            for pattern in backup_patterns:
                search_path = os.path.join(account_dir_str, "**", pattern)
                for backup_path in glob.glob(search_path, recursive=True):
                    if "BACKUP_BEFORE_SAVE" in backup_path: 
                        continue
                    try:
                        if os.path.getmtime(backup_path) < cutoff_time:
                            await aio_os.remove(backup_path)
                            temp_files_cleaned += 1
                    except Exception:
                        pass
            for side in ["long", "short"]:
                pattern = f"{side}_positions_BACKUP_BEFORE_SAVE_*.json"
                search_path = os.path.join(account_dir_str, pattern)
                all_backups = []
                for backup_file in glob.glob(search_path):
                    try:
                        mtime = os.path.getmtime(backup_file)
                        all_backups.append((mtime, backup_file))
                    except Exception: continue
                if len(all_backups) > 1:
                    all_backups.sort(key=lambda x: x[0], reverse=True) # Newest first
                    keep_paths = set()
                    now = time.time()
                    hourly_kept = {}
                    four_hourly_kept = {}
                    daily_kept = {}
                    for mtime, path in all_backups:
                        dt = datetime.fromtimestamp(mtime, tz=timezone.utc)
                        age_seconds = now - mtime
                        if age_seconds <= 3600:
                            key = (dt.day, dt.hour)
                            if key not in hourly_kept: hourly_kept[key] = []
                            if len(hourly_kept[key]) < 2:
                                hourly_kept[key].append(path)
                                keep_paths.add(path)
                        elif age_seconds <= 14400:
                            key = (dt.day, dt.hour // 4)
                            if key not in four_hourly_kept:
                                four_hourly_kept[key] = path
                                keep_paths.add(path)
                        else:
                            key = (dt.month, dt.day)
                            if key not in daily_kept:
                                daily_kept[key] = path
                                keep_paths.add(path)
                    for _, path in all_backups:
                        if path not in keep_paths:
                            try:
                                await aio_os.remove(path)
                                temp_files_cleaned += 1
                            except Exception: pass
        except Exception as error:
            logger.error(f"[cleanup_temp_files] Error cleaning for {account_key}: {error}")
        return temp_files_cleaned

    async def _load_and_merge_backups(self, main_file_path: Path, position_side_str: str) -> Dict[str, dict]:
        main_content = await self._load_json_file_content(main_file_path)
        if not main_content:
            main_content = {}
        backup_dir = main_file_path.parent / "backups"
        patterns = [ f"{position_side_str.lower()}_positions.json_backup_*.json", f"{position_side_str.lower()}_positions_backup_*.json", ]
        if await aio_os.path.isdir(backup_dir):
            backup_files_with_mtime: List[Tuple[float, Path]] = []
            try:
                for file_path in backup_dir.iterdir():
                    if not file_path.is_file():
                        continue
                    for pat in patterns:
                        if fnmatch.fnmatch(file_path.name, pat):
                            try:
                                mtime = file_path.stat().st_mtime
                                backup_files_with_mtime.append((mtime, file_path))
                            except OSError:
                                continue
                            break
            except Exception as e:
                logger.warning(f"[ez_manage] Error scanning backup directory {backup_dir}: {e}")
            if backup_files_with_mtime:
                backup_files_with_mtime.sort(key=lambda x: x[0], reverse=True)
                logger.debug(f"[ez_manage] Backup files exist for {main_file_path.name} but NOT loading from backups (ez_positions_service is source of truth). Found {len(backup_files_with_mtime)} backup files.")
        return main_content

    def get_symbol_config(self, symbol):
        config = self.symbol_configs.get(symbol)
        if not config and symbol.endswith("USDC"):
            usdt_symbol = symbol.replace("USDC", "USDT")
            config = self.symbol_configs.get(usdt_symbol)
            if config and self.logger:
                self.logger.debug(f"[CONFIG_FALLBACK] Used {usdt_symbol} config for {symbol}")
        return config

    async def round_quantity_to_lot(self, symbol: str, quantity: float) -> float:
        if quantity <= 0:
            return 0.0
        try:
            symbol_config = self.get_symbol_config(symbol)
            step_size = 0.00001 
            if symbol_config:
                step_val = symbol_config.get('step_size') or symbol_config.get('stepSize')
                if step_val:
                    step_size = float(step_val)
            if step_size <= 0:
                step_size = 0.00000001
            d_qty = Decimal(str(float(quantity)))
            d_step = Decimal(str(step_size))
            rounded_qty = (d_qty // d_step) * d_step
            return float(rounded_qty)
        except Exception as e:
            self.logger.error(f"[round_quantity_to_lot] Error for {symbol} qty={quantity}: {e}")
            return quantity

    def adjust_price(self, price: float, tick_size: float) -> float:
        if not tick_size or tick_size <= 0: return round(price, 8)
        precision = int(-math.log10(tick_size))
        return round(math.floor(price / tick_size) * tick_size, precision) 

    def _extract_symbol_list(self, data: Any) -> list:
            """Helper to extract list from json result whether it's a list or dict"""
            if isinstance(data, list):
                return data
            if isinstance(data, dict):
                return data.get('symbols') or data.get('data') or []
            return []

