    async def _get_position_with_websocket_check(self, position_key: str, account_key: str, max_age_seconds: float = 5.0, fetch_if_stale: bool = True, wait_for_ws: bool = False) -> Optional[Any]:
        """Get position from cache if websocket is fresh, otherwise fetches positions if fetch_if_stale=True. wait_for_ws=True adds 0.5s delay to allow websocket messages to arrive after trades."""
        if wait_for_ws:
            await asyncio.sleep(0.5)
        has_recent = await self.position_callback_manager.has_recent_update(position_key, max_age_seconds)
        if has_recent:
            position = await self.get_position(position_key)
            if position:
                logger.debug(f"[{position_key}] Using position from cache (websocket fresh <{max_age_seconds}s)")
                return position
        return None

    async def cancel_empty_stop(self, account_key, symbol, position_key, current_price=None, positionAmt=None, require_tiny=True):
        if require_tiny:
            now = datetime.now(timezone.utc) 
            position = await self.get_position(position_key)
            min_qty = self.min_qty.get(symbol, 0.0001) * 1.2
            tiny_threshold = max(config.MIN_POSITION_SIZE * 3, min_qty * current_price)
            if positionAmt is not None and positionAmt * current_price > tiny_threshold:
                return
            else:
                if positionAmt is not None and positionAmt > min_qty:
                    return
        if not self.stop_manager:
            return
        registry = getattr(self.stop_manager.trade_manager, "managed_stop_registry", {}) if getattr(self.stop_manager, "trade_manager", None) else {}
        entry = registry.get(position_key)
        order_id = str(entry.get("orderId") or "") if entry else ""
        account = self.accounts.get(account_key)
        client = account.client if account else None
        if not client or not order_id:
            return
        try:
            await asyncio.to_thread(client.futures_cancel_order, symbol=symbol, orderId=order_id)
        except BinanceAPIException as exc:
            if exc.code not in (-2011, -2013):
                logger.warning(f"[{position_key}] Failed to cancel managed stop {order_id}: {exc}")
        except Exception as exc:
            logger.warning(f"[{position_key}] Unexpected error cancelling managed stop {order_id}: {exc}")
        self.stop_manager._managed_stop_ids.discard(order_id)
        self.stop_manager._clear_stop(position_key, order_id or None)
        await self.stop_manager._schedule_registry_flush()

    async def determine_reduction_type(self, position_key: str, account_key: str, symbol: str, position_side: str, current_price: float, now: datetime) -> str:
        try:
            if await self._was_stop_market_triggered(position_key, account_key, symbol, position_side, current_price):
                return "STOP_MARKET_ORDER_TRIGGERED"
            if await self._was_stop_level_hit(position_key, account_key, symbol, position_side, current_price):
                return "STOP_LEVEL_HIT"
            return "detected_reduction"
        except Exception as e:
            logger.error(f"[determine_reduction _type] Error determining reduction type for {position_key}: {e}")
            return "detected_reduction"

    async def _was_stop_market_triggered(self, position_key: str, account_key: str, symbol: str, position_side: str, current_price: float) -> bool:
        try:
            client = self.get_client(account_key)
            if not client:
                return False
            orders = await self.get_cached_open_orders(account_key, symbol)#await asyncio.wait_for( client.futures_get_open_orders(symbol), timeout=10.0 )
            if not orders:
                async with self.maker_semaphore:
                    all_orders = await asyncio.wait_for( asyncio.to_thread(client.futures_get_all_orders, symbol=symbol, limit=10), timeout=10.0 )
                for order in all_orders:
                    if (order.get('type') == 'STOP_MARKET' and order.get('status') == 'FILLED' and order.get('positionSide') == position_side):
                        order_time = datetime.fromtimestamp(order.get('time', 0) / 1000, tz=timezone.utc)
                        current_time = datetime.now(timezone.utc)
                        if (current_time - order_time).total_seconds() < 300: # 5 minutes
                            logger.info(f"[{position_key}] STOP_MARKET order detected: {order.get('orderId')} filled at {order.get('avgPrice')}")
                            return True
            return False
        except Exception as e:
            logger.error(f"[_was_stop_market_triggered] Error checking STOP_MARKET for {position_key}: {e}")
            return False

    async def _was_stop_level_hit(self, position_key: str, account_key: str, symbol: str, position_side: str, current_price: float) -> bool:
        try:
            if position_key in self.stop_levels:
                stop_levels = self.stop_levels[position_key]
                if isinstance(stop_levels, list):
                    for stop_obj in stop_levels:
                        if isinstance(stop_obj, dict) and 'level' in stop_obj:
                            stop_level = stop_obj.get('level', 0)
                            if stop_level > 0:
                                if position_side == "LONG" and current_price <= stop_level:
                                    logger.debug(f"[{position_key}] Stop level hit: {stop_level} (LONG position at {current_price})")
                                    return True
                                elif position_side == "SHORT" and current_price >= stop_level:
                                    logger.debug(f"[{position_key}] Stop level hit: {stop_level} (SHORT position at {current_price})")
                                    return True
            return False
        except Exception as e:
            logger.error(f"[_was_stop_level_hit] Error checking stop levels for {position_key}: {e}")
            return False

    def _is_priority_position(self, position_key: str, position: Optional[Position]) -> bool:
        if not position:
            return False
        try:
            mark_price_val = safe_fetch_float(position.mark_price, 0.0)
            notional = abs(position.positionAmt) * max(mark_price_val or 0.0, 0.0)
            return notional >= self.priority_position_threshold
        except Exception:
            return False

    async def _confirm_significant_price_change(self, position_key: str, current_price: float, window_minutes: int = 5, min_change_pct: float = 0.12) -> bool:
        try:
            now = datetime.now(timezone.utc)
            try:
                ak, sym, side = parse_position_key(position_key)
            except Exception:
                sym = None
            position_obj = None
            try:
                if ak:
                    position_obj = await self.get_position(position_key)
            except Exception:
                position_obj = None
            is_priority = self._is_priority_position(position_key, position_obj)
            if is_priority:
                window_minutes = self.price_filter_window_priority
                min_change_pct = self.price_filter_min_pct_priority
            else:
                window_minutes = self.price_filter_window_default
                min_change_pct = self.price_filter_min_pct_default
            lst = self.price_change_tracker.setdefault(position_key, [])
            window_seconds = max(int(window_minutes * 60), 60)
            max_history_window = max(window_seconds * 3, window_seconds + 120)
            lst = [r for r in lst if (now - r[0]).total_seconds() <= max_history_window]
            baseline_entry = None
            for entry in lst:
                age = (now - entry[0]).total_seconds()
                if age >= window_seconds:
                    baseline_entry = entry
                    break
            if not lst or baseline_entry is None:
                if not lst:
                    logger.debug(f"[_confirm_significant_price_change] First time processing {position_key}, allowing")
                else:
                    logger.debug(f"[_confirm_significant_price_change] Insufficient history (< {window_minutes}m) for {position_key}, allowing")
                lst.append((now, current_price, 0.0))
                self.price_change_tracker[position_key] = lst
                return True
            base_price = baseline_entry[1]
            if not base_price or base_price <= 0:
                lst.append((now, current_price, 0.0))
                self.price_change_tracker[position_key] = lst
                return True
            price_change_pct = abs(current_price - base_price) / base_price * 100
            lst.append((now, current_price, price_change_pct))
            self.price_change_tracker[position_key] = lst
            if price_change_pct < min_change_pct and not is_priority:
                return False
            return True
        except Exception as e:
            logger.debug(f"[_confirm_significant_price_change] Fallback True due to error: {e}")
            return True

    def get_position_file(self, account_key: str, position_side_str: str) -> Path:
        if not isinstance(account_key, str) or not account_key:
            logger.error("get_position_file: Invalid account_key provided.")
            raise ValueError("account_key cannot be empty or None")
        if position_side_str not in ['LONG', 'SHORT']:
            logger.error(f"get_position_file: Invalid position_side_str: {position_side_str}")
            raise ValueError(f"Invalid position_side_str: {position_side_str}")
        if not self.config.BASE_PATH:
            logger.error("get_position_file: self.config.BASE_PATH is not configured.")
            raise AttributeError("self.config.BASE_PATH is not configured in TradeManager's config.")
        try:
            base_path = Path(self.config.BASE_PATH) # Ensure BASE_PATH is Path
            account_dir = base_path / account_key.lower() 
            account_dir.mkdir(parents=True, exist_ok=True)
            filename = f"{position_side_str.lower()}_positions.json"
            machine_names = ['macbook', 'gateway', 'server']
            most_recent_file = None
            most_recent_mtime = 0
            for machine in machine_names:
                machine_dir = account_dir / machine
                if machine_dir.exists():
                    candidate_file = machine_dir / filename
                    if candidate_file.exists():
                        try:
                            mtime = candidate_file.stat().st_mtime
                            if mtime > most_recent_mtime:
                                most_recent_file = candidate_file
                                most_recent_mtime = mtime
                        except OSError:
                            continue
            root_file = account_dir / filename
            if root_file.exists():
                try:
                    mtime = root_file.stat().st_mtime
                    if mtime > most_recent_mtime:
                        most_recent_file = root_file
                        most_recent_mtime = mtime
                except OSError:
                    pass
            if most_recent_file and most_recent_file.parent.name != account_dir.name:
                logger.debug(f"get_position_file: Using file from {most_recent_file.parent.name} subfolder")
                return most_recent_file
            file_path_obj = root_file
            if not file_path_obj.exists():
                logger.warning(f"[NOT_ALLOWED][get_position_file] Position file '{file_path_obj}' does not exist - NOT creating it (ez_manage is NOT_ALLOWED to create/write position files)")
                return file_path_obj
            return file_path_obj # RETURNS A PATH OBJECT
        except Exception as e:
            logger.error(f"get_position_file: Critical error constructing path for {account_key}/{position_side_str}: {e}", exc_info=True)
            raise RuntimeError(f"Failed to get/create position file for {account_key}/{position_side_str}") from e

    async def load_min_qty(self) -> Dict[str, float]:
        file_path = self.config.MIN_QTY_FILE
        if not os.path.exists(file_path):
            logger.error(f"Minimum quantity file {file_path} not found.")
            return {}
        try:
            async with aiofiles.open(file_path, 'r') as f:
                content = await f.read()
            min_qty_data = json.loads(content)
            min_qty_flat = { symbol: float(details['minQty']) for symbol, details in min_qty_data.items() }
            logger.debug("Loaded minimum quantities from JSON.")
            return min_qty_flat
        except FileNotFoundError:
            logger.error(f"Minimum quantity file {file_path} not found.")
        except json.JSONDecodeError as e:
            logger.error(f"Error decoding JSON from {file_path}: {e}")
        except Exception as e:
            logger.error(f"Unexpected error loading minimum quantities: {e}")
        return {}

    def get_relevant_accounts_for_symbol(self, symbol: str) -> Set[str]:
        relevant = set()
        if symbol in self.symbols_inf_long:
            relevant.add("inf")
        if symbol in self.symbols_inf_short:
            relevant.add("inf")
        if symbol in self.symbols_flz:
            relevant.add("flz")
        if symbol in self.symbols_men:
            relevant.add("men")
        if symbol in self.symbols_fin:
            relevant.add("fin")
        if symbol in self.symbols_ang_short:
            relevant.add("ang")
        if symbol in self.symbols_ang_long:
            relevant.add("ang")
        for acct_key in config.ACCOUNT_KEYS:
            sub_dict = self.positions_by_account.get(acct_key, {})
            for position_key, position_obj in sub_dict.items():
                ak, pos_symbol, side = parse_position_key(position_key)
                if pos_symbol == symbol:
                    relevant.add(ak)
        return relevant

    def get_position_keys_for_symbol(self, account_key: str, symbol: str) -> List[str]:
        result = []
        subdict = self.get_positions_by_account(account_key)
        for position_key, pos_obj in subdict.copy().items():
            try:
                account_key, sym, side = parse_position_key(position_key)
                if sym == symbol:
                    result.append(position_key)
            except ValueError:
                pass
        logger.debug(f"[get_position_keys_for_symbol]act {account_key=}sym {symbol=} => res {result=}")
        return result

    async def _handle_signal_message(self, signal_data: dict):
        try:
            actual_data = signal_data.get('data', signal_data) 
            event_type = actual_data.get("event_type")
            symbol = actual_data.get("symbol")
            source = signal_data.get("source", "unknown")
            if not event_type or not symbol:
                logger.debug(f"[SIGNAL] Received incomplete signal: event_type={event_type}, symbol={symbol}")
                return
            signal_timestamp = signal_data.get("timestamp") or actual_data.get("timestamp")
            if hasattr(self.redis_manager, 'data_coordinator') and self.redis_manager.data_coordinator:
                if not self.redis_manager.data_coordinator.should_process_data( "signals", symbol, source, signal_timestamp, event_type ):
                    logger.debug(f"[SIGNAL] Signal filtered by data_coordinator: {symbol} | {event_type}")
                    return
            BULLISH_EVENT_KEYWORDS = { "stoch_crossover", "sma_crossover", "wt_crossover", "dc_basis_crossover", "dc_high_crossover", "dc_low_crossover","ha_15m_green" }
            BEARISH_EVENT_KEYWORDS = {"stoch_crossunder", "sma_crossunder", "wt_crossunder","dc_basis_crossunder", "dc_low_crossunder", "dc_high_crossunder","ha_15m_red" }
            RANKING_SIGNALS = { "long_term_winners_up_rank", "long_term_winners_down_rank", "long_term_losers_jump_rank", "long_term_losers_drop_rank", "short_term_winners_up_rank", "short_term_winners_down_rank", "short_term_losers_jump_rank", "short_term_losers_drop_rank", "winners_all_green_rank", "losers_all_red_rank", "WT Strong Alert", "BREAKOUT_LONG", "BREAKOUT_SHORT"}
            ALL_ACTIONS = BULLISH_EVENT_KEYWORDS | BEARISH_EVENT_KEYWORDS | RANKING_SIGNALS
            try:
                action = signal_data.get("action", "N/A")
                signal_price = signal_data.get("price", 0)
                logger.debug(f"📡 [SIGNAL_RECV] {symbol} | {event_type} | {action} | ${signal_price:.6f} | source={source}")
                if ('CLOSE' in action or 'REDUCE' in action or 'PROFIT_TAKE' in action) :
                    try:
                        position_key_str = actual_data.get("position_key") or signal_data.get("position_key")
                        if position_key_str:
                            try:
                                account_key_signal, symbol_signal, position_side_signal = parse_position_key(position_key_str)
                                if account_key_signal in self.accounts:
                                    asyncio.create_task(override_check_uptrend_positions(self, account_key_signal))
                                    logger.debug(f"[OVERRIDE_CHECK] Triggered immediately by {action} signal for {account_key_signal} {symbol_signal} {position_side_signal}")
                            except Exception:
                                pass
                        else:
                            for account_key_check in self.accounts.keys():
                                if self.is_symbol_allowed(account_key_check, symbol):
                                    asyncio.create_task(override_check_uptrend_positions(self, account_key_check))
                                    logger.debug(f"[OVERRIDE_CHECK] Triggered immediately by {action} signal for {account_key_check} {symbol}")
                    except Exception as override_err:
                        logger.error(f"[OVERRIDE_CHECK] Error triggering override from signal: {override_err}")
                parts = event_type.split('_')
                timeframe = "N/A"
                base_event_type = event_type
                if len(parts) > 1 and parts[-1] in ["1m", "3m", "15m", "1h", "4h", "D"]:
                    timeframe = parts[-1]
                    base_event_type = '_'.join(parts[:-1])
                current_account_key = list(self.accounts.keys())[0] if self.accounts else None
                loaded_accounts = set(self.accounts.keys())
                is_all_green = 'all_green' in event_type or 'winners_all_green' in event_type
                is_all_red = 'all_red' in event_type or 'losers_all_red' in event_type
                if (is_all_green or is_all_red) and action in ['BUY', 'SELL']:
                    signal_type = 'all_green' if is_all_green else 'all_red'
                    target_accounts = []
                    target_side = None
                    is_entry = False
                    if is_all_green and action == "BUY":
                        target_accounts = [ak for ak in ['ang', 'inf', 'men', 'fin', 'flz'] if ak in loaded_accounts]
                        target_side = "LONG"
                        is_entry = True
                    elif is_all_green and action == "SELL":
                        target_accounts = [ak for ak in ['ang', 'inf', 'men', 'fin', 'flz'] if ak in loaded_accounts]
                        target_side = "LONG"
                        is_entry = False
                    elif is_all_red and action == "BUY":
                        target_accounts = [ak for ak in ['ang', 'inf', 'men', 'fin', 'flz'] if ak in loaded_accounts]
                        target_side = "SHORT"
                        is_entry = False
                    elif is_all_red and action == "SELL":
                        target_accounts = [ak for ak in ['ang', 'inf', 'men', 'fin', 'flz'] if ak in loaded_accounts]
                        target_side = "SHORT"
                        is_entry = True
                    for account_key in target_accounts:
                        if not self.allows_side(account_key, target_side) or not self.is_symbol_allowed(account_key, symbol):
                            continue
                        if not _check_leaderboard_allowed(self, symbol, target_side, account_key):
                            logger.debug(f"[_handle_signal_message] FILTERED: {target_side} symbol {symbol} not in tradeable keys for {account_key}")
                            continue
                        if not self.allows_side(account_key, target_side) or not self.is_symbol_allowed(account_key, symbol):
                            continue
                        position_key = construct_position_key(account_key, symbol, target_side)
                        if not position_key: 
                            logger.error(f"[_handle_signal_message00] ⚠️ SKIPPING - construct_position_key returned None: account={account_key}, symbol={symbol}, entry_side={target_side}")
                            continue
                        position = await self.get_position(position_key)
                        current_price = signal_price if signal_price and signal_price > 0 else None
                        if not current_price:
                            try: current_price = await quick_price(symbol)
                            except Exception: pass
                        if not current_price or current_price <= 0:
                            current_price,_ = await self.get_current_price(symbol)
                        if not current_price or current_price <= 0:
                            if position and hasattr(position, 'mark_price') and position.mark_price and position.mark_price > 0: current_price = position.mark_price
                            elif position and hasattr(position, 'entry_price') and position.entry_price and position.entry_price > 0: current_price = position.entry_price
                        if not current_price or current_price <= 0: logger.error(f"[_handle_signal_message][{position_key}] CRITICAL: No valid price found!"); current_price = position.mark_price if position and hasattr(position, 'mark_price') and position.mark_price else (position.entry_price if position and hasattr(position, 'entry_price') and position.entry_price else 1.0)
                        indicators = await ii(self, symbol)
                        is_long = target_side == "LONG"
                        conviction = float(indicators.get('zconviction_long' if is_long else 'zconviction_short', signal_data.get("conviction", actual_data.get("conviction", 65.0))))
                        base_amt = abs(float(getattr(position, 'positionAmt', 0.0) or 0.0)) if position else 0.0
                        auto_action = "CLOSE" if not is_entry else ("OPEN" if base_amt <= config.START_POSITION_SIZE / current_price else "AUGMENT")
                        reason_code = f"ALL_{signal_type.upper()}_DIRECT_{auto_action}_{event_type}"
                        # === CHANNEL POSITION GATE ===
                        # ALL_RED fires SHORT opens — block if price already near channel BOTTOM (move is done)
                        # ALL_GREEN fires LONG opens — block if price already near channel TOP (too late to buy)
                        if auto_action in ("OPEN", "AUGMENT"):
                            bb_pb_1h = float(indicators.get("bb_pct_b_1h", 0.5) or 0.5)
                            lr_pb_1h = float(indicators.get("lr_pct_b_1h", 0.5) or 0.5)
                            bb_pb_4h = float(indicators.get("bb_pct_b_4h", 0.5) or 0.5)
                            lr_pb_4h = float(indicators.get("lr_pct_b_4h", 0.5) or 0.5)
                            ch_pb = bb_pb_1h * 0.3 + lr_pb_1h * 0.3 + bb_pb_4h * 0.2 + lr_pb_4h * 0.2
                            if not is_long and ch_pb < 0.40:
                                logger.warning(f"[DIRECT_QUEUE_BLOCKED] {position_key}: ALL_RED SHORT blocked — price at channel BOTTOM (pct_b={ch_pb:.2f}<0.40, move already done)")
                                continue
                            if is_long and ch_pb > 0.60:
                                logger.warning(f"[DIRECT_QUEUE_BLOCKED] {position_key}: ALL_GREEN LONG blocked — price at channel TOP (pct_b={ch_pb:.2f}>0.60, too late)")
                                continue
                        # === AUGMENT-IN-LOSS GATE ===
                        # Never add to a losing position from ALL_RED/ALL_GREEN signals
                        if auto_action == "AUGMENT" and position:
                            pos_gain = float(getattr(position, "gain", 0.0) or 0.0)
                            if pos_gain < -0.5:
                                logger.warning(f"[DIRECT_QUEUE_BLOCKED] {position_key}: AUGMENT blocked — position in loss ({pos_gain:.2f}%) via ALL signal")
                                continue
                        # === RATIO GATE for new SHORT opens ===
                        # If shorts already heavily outnumber longs, do not add more shorts
                        if auto_action == "OPEN" and not is_long:
                            try:
                                _rd = self.positions_service.get_long_short_ratio(account_key)
                                _short_pct = _rd.get("short_pct", 50.0)
                                if _short_pct > 65.0:
                                    logger.warning(f"[DIRECT_QUEUE_BLOCKED] {position_key}: SHORT OPEN blocked — ratio too short-heavy ({_short_pct:.0f}% short)")
                                    continue
                            except Exception:
                                pass
                        logger.warning(f"[🚀 DIRECT_QUEUE] {position_key}: {signal_type.upper()} signal -> {auto_action} (conviction={conviction:.1f})")
                        result = await queue_trade_action(self.order_queue, self, position_key, auto_action, reason_code, conviction)
                        if result and not result.startswith("QUEUED") and not result.startswith("SUCCESS") and not result.startswith("SKIPPED_OPEN_BLOCKED"):
                            account_key, symbol, position_side = parse_position_key(position_key)
                            side = ("BUY" if position_side == "LONG" else "SELL") if auto_action in ["OPEN", "AUGMENT"] else ("SELL" if position_side == "LONG" else "BUY")
                            await self.clear_all_cooldowns_for_position(position_key, side)
                            logger.info(f"[DIRECT_QUEUE] {position_key}: Cleared cooldowns after queue failure (result={result})")
                    return
                entry_accounts, entry_side = [], None
                exit_accounts, exit_side = [], None
                signal_category = "UNKNOWN"
                if base_event_type in BULLISH_EVENT_KEYWORDS:
                    signal_category = "BULLISH"
                    if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                        entry_accounts, entry_side = [current_account_key], "LONG"
                    if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] : # 'ang' only does LONG
                        exit_accounts, exit_side = [current_account_key], "SHORT"
                elif base_event_type in BEARISH_EVENT_KEYWORDS:
                    signal_category = "BEARISH"
                    if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                        entry_accounts, entry_side = [current_account_key], "SHORT"
                    if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                        exit_accounts, exit_side = [current_account_key], "LONG"
                elif base_event_type == 'wt_signal' or 'wt_signal' in event_type:
                    if action == "SELL":
                        signal_category = "BEARISH"
                        if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                            entry_accounts, entry_side = [current_account_key], "SHORT"
                        if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                            exit_accounts, exit_side = [current_account_key], "LONG"
                    elif action == "BUY":
                        signal_category = "BULLISH"
                        if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                            entry_accounts, entry_side = [current_account_key], "LONG"
                        if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                            exit_accounts, exit_side = [current_account_key], "SHORT"
                elif any(signal in event_type for signal in ALL_ACTIONS):
                    if any(ranking_signal in event_type for ranking_signal in RANKING_SIGNALS):
                        signal_category = "RANKING"
                        if 'short_term' in event_type:
                            if 'winners' in event_type:
                                if 'up_rank' in event_type:
                                    if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                        entry_accounts, entry_side = [current_account_key], "LONG"
                                elif 'down_rank' in event_type:
                                    if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                        exit_accounts, exit_side = [current_account_key], "LONG"
                            elif 'losers' in event_type:
                                if 'jump_rank' in event_type:
                                    if current_account_key in['ang', 'inf', 'men', 'fin', 'flz'] :
                                        exit_accounts, exit_side = [current_account_key], "SHORT"
                                elif 'drop_rank' in event_type:
                                    if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                        entry_accounts, entry_side = [current_account_key], "SHORT"
                        elif 'long_term_winners' in event_type or 'winners_all_green' in event_type:
                            if 'up_rank' in event_type or ('all_green' in event_type and action == "BUY"):
                                if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                    entry_accounts, entry_side = [current_account_key], "LONG"
                                if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                    exit_accounts, exit_side = [current_account_key], "SHORT"
                            elif 'down_rank' in event_type or ('all_green' in event_type and action == "SELL"):
                                if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                    exit_accounts, exit_side = [current_account_key], "LONG"
                        elif 'long_term_losers' in event_type or 'losers_all_red' in event_type:
                            if 'jump_rank' in event_type or ('all_red' in event_type and action == "BUY"):
                                if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                    exit_accounts, exit_side = [current_account_key], "SHORT"
                            elif 'drop_rank' in event_type or ('all_red' in event_type and action == "SELL"):
                                if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                    entry_accounts, entry_side = [current_account_key], "SHORT"
                        elif event_type == "BREAKOUT_LONG":
                            _bo_acct = actual_data.get("account", "fin")
                            if current_account_key == _bo_acct:
                                entry_accounts, entry_side = [current_account_key], "LONG"
                                logger.info(f"[BREAKOUT_SIGNAL] {symbol} LONG on {current_account_key} dist={actual_data.get('sma200_dist','?')}% chg={actual_data.get('change_24h','?')}%")
                        elif event_type == "BREAKOUT_SHORT":
                            _bo_acct = actual_data.get("account", "fin")
                            if current_account_key == _bo_acct:
                                entry_accounts, entry_side = [current_account_key], "SHORT"
                                logger.info(f"[BREAKOUT_SIGNAL] {symbol} SHORT on {current_account_key} dist={actual_data.get('sma200_dist','?')}% chg={actual_data.get('change_24h','?')}%")
                        else:
                            if base_event_type not in BEARISH_EVENT_KEYWORDS and base_event_type not in BULLISH_EVENT_KEYWORDS:
                                if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                    entry_accounts, entry_side = [current_account_key], "LONG"
                                    exit_accounts, exit_side = [current_account_key], "SHORT"
                    else:
                        if base_event_type not in BEARISH_EVENT_KEYWORDS and base_event_type not in BULLISH_EVENT_KEYWORDS:
                            if current_account_key in ['ang', 'inf', 'men', 'fin', 'flz'] :
                                entry_accounts, entry_side = [current_account_key], "LONG"
                                exit_accounts, exit_side = [current_account_key], "SHORT"
                else:
                    logger.debug(f" SIGNAL IGNORED: Unknown signal type {event_type}")
                    return
                if getattr(self.config, 'EXIT_ON_ALL', False) and getattr(self.config, 'EXIT_ON_ALL_ENABLED', False) and signal_category in ["BEARISH", "BULLISH"]:
                    target_side = "LONG" if signal_category == "BEARISH" else "SHORT"
                    now_utc = datetime.now(timezone.utc)
                    LEADERBOARD_FILTER = getattr(self.config, 'LEADERBOARD_FILTER', True)
                    winners_20 = getattr(self, 'winners_20', {})
                    winners_15m = getattr(self, 'winners_15m', {})
                    losers_20 = getattr(self, 'losers_20', {})
                    losers_15m = getattr(self, 'losers_15m', {})
                    allowed_winners = set(winners_20.keys()) | set(winners_15m.keys()) if isinstance(winners_20, dict) and isinstance(winners_15m, dict) else set()
                    allowed_losers = set(losers_20.keys()) | set(losers_15m.keys()) if isinstance(losers_20, dict) and isinstance(losers_15m, dict) else set()
                    for account_key in loaded_accounts:
                        if not self.allows_side(account_key, target_side): continue
                        account_symbols = set()
                        if account_key == "ang": account_symbols = getattr(self, 'symbols_ang_long', set()) if target_side == "LONG" else getattr(self, 'symbols_ang_short', set())
                        elif account_key == "flz": account_symbols = getattr(self, 'symbols_flz', set())
                        elif account_key == "inf": account_symbols = getattr(self, 'symbols_inf_long', set()) if target_side == "LONG" else getattr(self, 'symbols_inf_short', set())
                        elif account_key == "men": account_symbols = getattr(self, 'symbols_men', set())
                        elif account_key == "fin": account_symbols = getattr(self, 'symbols_fin', set())
                        for sym in account_symbols:
                            symbol = sym.strip().upper() if isinstance(sym, str) else str(sym).strip().upper()
                            if LEADERBOARD_FILTER:
                                if target_side == "LONG" and symbol not in allowed_winners: continue
                                if target_side == "SHORT" and symbol not in allowed_losers: continue
                            if not self.is_symbol_allowed(account_key, symbol): continue
                            try:
                                position_key = construct_position_key(account_key, symbol, target_side)
                                if not position_key: 
                                    logger.error(f"[_handle_signal_message0] ⚠️ SKIPPING - construct_position_key returned None: account={account_key}, symbol={symbol}, entry_side={target_side}")
                                    continue
                                position = await self.get_position(position_key)
                                if position and abs(float(getattr(position, 'positionAmt', 0.0) or 0.0)) > 1e-8:
                                    red_seconds = (now_utc - position.last_reduction_time).total_seconds() if position.last_reduction_time else float('inf')
                                    if red_seconds < config.REDUCTION_COOLDOWN_SECONDS: continue
                                    opened_at_dt = safe_datetime(getattr(position, 'opened_at', None)) if hasattr(position, 'opened_at') and position.opened_at else None
                                    position_age_seconds = (now_utc - opened_at_dt).total_seconds() if opened_at_dt else float('inf')
                                    is_new_position = position_age_seconds < 300.0
                                    position.gain = safe_fetch_float(getattr(position, 'gain', 0.0), 0.0)
                                    indicators = await ii(self, symbol)
                                    if is_new_position:
                                        k_3m = safe_fetch_float(indicators.get('stoch_k_3m', 50), 50.0) if indicators else 50.0
                                        d_3m = safe_fetch_float(indicators.get('stoch_d_3m', 50), 50.0) if indicators else 50.0
                                        if k_3m == 50 and d_3m == 50: continue
                                        k_3m_prev = safe_fetch_float(indicators.get('k_3m_prev', 50), 50.0) if indicators else 50.0
                                        entry_price = safe_fetch_float(getattr(position, 'entry_price', 0.0), 0.0)
                                        current_price = safe_fetch_float(indicators.get('current_price', 0.0), 0.0) if indicators else entry_price
                                        price_moved_against = (target_side == "LONG" and current_price < entry_price * 0.995) or (target_side == "SHORT" and current_price > entry_price * 1.005)
                                        k_3m_confirmed_bad = (target_side == "LONG" and k_3m < 30 and k_3m < d_3m) or (target_side == "SHORT" and k_3m > 70 and k_3m > d_3m)
                                        k_3m_flipped = (target_side == "LONG" and k_3m_prev >= 50 and k_3m < 50) or (target_side == "SHORT" and k_3m_prev <= 50 and k_3m > 50)
                                        if position.gain > config.NEW_POSITION_MAX_LOSS_THRESHOLD:
                                            if not (price_moved_against and k_3m_confirmed_bad and k_3m_flipped):
                                                logger.debug(f"[NEW_POSITION_PROTECTION] {position_key}: Blocking EXIT_ON_ALL reduction - position is new ({position_age_seconds:.1f}s old), gain {position.gain:.2f}% > threshold {config.NEW_POSITION_MAX_LOSS_THRESHOLD:.2f}%, but no clear confirmation (price_moved={price_moved_against}, k_3m_confirmed={k_3m_confirmed_bad}, k_3m_flipped={k_3m_flipped}, k_3m={k_3m:.1f}, d_3m={d_3m:.1f})")
                                                continue
                                            else:
                                                logger.warning(f"[NEW_POSITION_OVERRIDE] {position_key}: Allowing EXIT_ON_ALL reduction on new position ({position_age_seconds:.1f}s old) - clear confirmation: price_moved={price_moved_against}, k_3m_confirmed={k_3m_confirmed_bad}, k_3m_flipped={k_3m_flipped}")
                                    conviction = float(indicators.get('zconviction_long' if target_side == "LONG" else 'zconviction_short', signal_data.get("conviction", actual_data.get("conviction", 75.0))))
                                    reason_code = f"[SIGNAL_MESS]:EXIT_ON_ALL_{signal_category}_{event_type}_REDUCE"
                                    logger.warning(f"[🚀 EXIT_ON_ALL] {position_key}: {signal_category} signal -> REDUCE (conviction={conviction:.1f})")
                                    try:
                                        result = await queue_trade_action(self.order_queue, self, position_key, "REDUCE", reason_code, conviction)
                                        if result and not result.startswith("QUEUED") and not result.startswith("SUCCESS") and not ("-2021" in str(result) or "-2022" in str(result)):
                                            await self.clear_all_cooldowns_for_position(position_key, "SELL" if target_side == "LONG" else "BUY")
                                    except Exception as e:
                                        if "-2021" not in str(e) and "-2022" not in str(e): logger.error(f"[EXIT_ON_ALL] Error queueing REDUCE for {position_key}: {e}")
                            except Exception as e:
                                if "-2021" not in str(e) and "-2022" not in str(e): logger.debug(f"[EXIT_ON_ALL] Skipping {account_key}:{symbol}:{target_side} - {e}")
                entry_routed_to = []
                exit_routed_to = []
                entry_not_allowed = []
                exit_not_allowed = []
                is_stoch_signal_from_quick = source == "ez_positions_quick" and ('wt_crossover' in event_type or 'wt_crossunder' in event_type or 'stoch_crossover' in event_type or 'stoch_crossunder' in event_type)
                is_priority_signal = signal_category in ["BULLISH", "BEARISH"] or any(ranking_signal in event_type for ranking_signal in RANKING_SIGNALS) or 'crossover' in event_type or 'crossunder' in event_type or 'winners_up' in event_type or 'losers_drop' in event_type or ('losers' in event_type and 'drop_rank' in event_type) or ('winners' in event_type and 'up_rank' in event_type) or 'winners_all_green' in event_type or 'losers_all_red' in event_type or 'WT Strong Alert' in event_type or 'wt_signal' in event_type or is_stoch_signal_from_quick
                if entry_side and entry_accounts:
                    for account_key in entry_accounts:
                        if account_key not in loaded_accounts:
                            entry_not_allowed.append(f"{account_key}(not_loaded)")
                            continue
                        if not self.allows_side(account_key, entry_side):
                            entry_not_allowed.append(f"{account_key}(side_not_allowed)")
                            continue
                        if not self.is_symbol_allowed(account_key, symbol):
                            entry_not_allowed.append(f"{account_key}(not_allowed)")
                            continue
                        if getattr(self.config, 'LEADERBOARD_FILTER', True) and not _check_leaderboard_allowed(self, symbol, entry_side, account_key):
                            entry_not_allowed.append(f"{account_key}(not_in_leaderboard)")
                            continue
                        entry_routed_to.append(account_key)
                        if any(ranking_signal in event_type for ranking_signal in RANKING_SIGNALS):
                            existing_positions = []
                            master_symbols = self._master_symbols_cache
                            allowed_symbols = self.symbols_men if account_key == 'men' else self.symbols_fin if account_key == 'fin' else self.symbols_ang_long.union(self.symbols_ang_short) if account_key == 'ang' else self.symbols_flz if account_key == 'flz' else self.symbols_inf_long.union(self.symbols_inf_short) if account_key == 'inf' else set()
                            for position_key, position in self.get_positions_by_account(account_key).items():
                                if position and position.symbol == symbol:
                                    pos_symbol = position.symbol.strip().upper()
                                    if (not master_symbols or pos_symbol in master_symbols) and pos_symbol in allowed_symbols:
                                        if self.is_symbol_allowed(account_key, position.symbol, position_key):
                                            existing_positions.append(position_key)
                            if existing_positions:
                                validated_positions = []
                                for position_key in existing_positions:
                                    position = await self.get_position(position_key)
                                    if not position: continue
                                    pos_amt = abs(safe_fetch_float(getattr(position, 'positionAmt', 0.0), 0.0))
                                    pos_gain = safe_fetch_float(getattr(position, 'gain', 0.0), 0.0)
                                    try:
                                        ak, sym, pos_side = parse_position_key(position_key)
                                        current_price_val = signal_price if signal_price and signal_price > 0 else (position.mark_price if hasattr(position, 'mark_price') and position.mark_price else 0.0)
                                        if current_price_val <= 0: current_price_val = await quick_price(sym)
                                        pos_min_qty_val = getattr(position, 'min_qty', 0) # Default to 0 if min_qty not available
                                        if pos_amt > config.START_POSITION_SIZE/current_price and pos_gain < 0.5 * config.MIN_GAIN:
                                            logger.warning(f"[SIGNAL_BLOCK] {position_key}: BLOCKING monitor_entries - positionAmt={pos_amt:.6f} > pos_min_qty={pos_min_qty_val:.6f} AND gain={pos_gain:.3f}% < 0.5×MIN_GAIN={0.5*config.MIN_GAIN:.2f}% | origin=QUICK")
                                            continue
                                        validated_positions.append(position_key)
                                    except Exception as val_err:
                                        logger.debug(f"[SIGNAL_VALIDATION] {position_key}: Validation error, allowing: {val_err}")
                                        validated_positions.append(position_key)
                                allowed_existing = filter_monitor_keys(self, account_key, validated_positions)
                                if allowed_existing:
                                    await monitor_entries(order_queue=self.order_queue, trade_manager=self, account_key=account_key, position_keys=allowed_existing, event_type=event_type, signal_data=signal_data, is_priority_add=False, force=True)
                            else:
                                logger.debug(f" 📊 No existing positions for {symbol}, will create new if needed")
                        else:
                            if not entry_side or entry_side.upper() not in ("LONG", "SHORT"):
                                logger.error(f"[_handle_signal_message1] ⚠️ SKIPPING - invalid entry_side: {entry_side} for symbol {symbol}")
                                continue
                            try:
                                position_key = construct_position_key(account_key, symbol, entry_side)
                                if not position_key:
                                    logger.error(f"[_handle_signal_message] ⚠️ SKIPPING - construct_position_key returned None: account={account_key}, symbol={symbol}, entry_side={entry_side}")
                                    continue
                                ak, sym, side = parse_position_key(position_key)
                                position_key = construct_position_key(ak or account_key, sym, side)
                                if not position_key: 
                                    logger.error(f"[_handle_signal_message2] ⚠️ SKIPPING - construct_position_key returned None: account={ak}, symbol={sym}, entry_side={side}")
                                    continue
                            except Exception:
                                position_key = construct_position_key(account_key, symbol, entry_side)
                                if not position_key: 
                                    logger.error(f"[_handle_signal_message3] ⚠️ SKIPPING - construct_position_key returned None: account={account_key}, symbol={symbol}, entry_side={entry_side}")
                                    continue
                            position = await self.get_position(position_key)
                            if position:
                                pos_amt = abs(safe_fetch_float(getattr(position, 'positionAmt', 0.0), 0.0))
                                pos_gain = safe_fetch_float(getattr(position, 'gain', 0.0), 0.0)
                                try:
                                    ak, sym, pos_side = parse_position_key(position_key)
                                    current_price_val = signal_price if signal_price and signal_price > 0 else (position.mark_price if hasattr(position, 'mark_price') and position.mark_price else 0.0)
                                    if current_price_val <= 0: current_price_val = await quick_price(sym)
                                    pos_min_qty_val = getattr(position, 'min_qty', 0) # Default to 0 if min_qty not available
                                    if pos_amt > config.START_POSITION_SIZE/current_price and pos_gain < 0.5 * config.MIN_GAIN:
                                        logger.warning(f"[SIGNAL_BLOCK] {position_key}: BLOCKING monitor_entries - positionAmt={pos_amt:.6f} > pos_min_qty={pos_min_qty_val:.6f} AND gain={pos_gain:.3f}% < 0.5×MIN_GAIN={0.5*config.MIN_GAIN:.2f}% | origin=QUICK")
                                    else:
                                        allowed_single = filter_monitor_keys(self, account_key, position_key)
                                        if allowed_single:
                                            await monitor_entries(order_queue=self.order_queue, trade_manager=self, account_key=account_key, position_keys=allowed_single, event_type=event_type, signal_data=signal_data, is_priority_add=False, force=True)
                                except Exception as val_err:
                                    logger.debug(f"[SIGNAL_VALIDATION] {position_key}: Validation error, allowing: {val_err}")
                                    allowed_single = filter_monitor_keys(self, account_key, position_key)
                                    if allowed_single:
                                        await monitor_entries(order_queue=self.order_queue, trade_manager=self, account_key=account_key, position_keys=allowed_single, event_type=event_type, signal_data=signal_data, is_priority_add=False, force=True)
                            else:
                                allowed_single = filter_monitor_keys(self, account_key, position_key)
                                if allowed_single:
                                    await monitor_entries(order_queue=self.order_queue, trade_manager=self, account_key=account_key, position_keys=allowed_single, event_type=event_type, signal_data=signal_data, is_priority_add=False, force=True)
                if exit_side and exit_accounts:
                    logger.debug(f"🔍 Checking EXIT {exit_side} routing for {symbol}...")
                    for account_key in exit_accounts:
                        if account_key not in loaded_accounts:
                            exit_not_allowed.append(f"{account_key}(not_loaded)")
                            continue
                        if not self.is_symbol_allowed(account_key, symbol):
                            exit_not_allowed.append(f"{account_key}(not_allowed)")
                            continue
                        exit_routed_to.append(account_key)
                        if any(ranking_signal in event_type for ranking_signal in RANKING_SIGNALS):
                            await self.refresh_from_files_once([account_key])
                            existing_positions = []
                            master_symbols = self._master_symbols_cache
                            allowed_symbols = self.symbols_men if account_key == 'men' else self.symbols_fin if account_key == 'fin' else self.symbols_ang_long.union(self.symbols_ang_short) if account_key == 'ang' else self.symbols_flz if account_key == 'flz' else self.symbols_inf_long.union(self.symbols_inf_short) if account_key == 'inf' else set()
                            for position_key, position in self.get_positions_by_account(account_key).items():
                                if position and position.symbol == symbol:
                                    pos_amt = abs(safe_float(getattr(position, 'positionAmt', 0.0), 0.0))
                                    if pos_amt < 1e-8: continue
                                    pos_symbol = position.symbol.strip().upper()
                                    if (not master_symbols or pos_symbol in master_symbols) and pos_symbol in allowed_symbols:
                                        if self.is_symbol_allowed(account_key, position.symbol, position_key):
                                            existing_positions.append(position_key)
                            if existing_positions:
                                allowed_existing = filter_monitor_keys(self, account_key, existing_positions)
                                if allowed_existing:
                                    await monitor_entries(order_queue=self.order_queue, trade_manager=self, account_key=account_key, position_keys=allowed_existing, event_type=event_type, signal_data=signal_data, is_priority_add=False, force=True)
                            else:
                                logger.debug(f" ⚠️ {account_key}: No existing {exit_side} positions for {symbol} to exit")
                        else:
                            if not exit_side or exit_side.upper() not in ("LONG", "SHORT"):
                                logger.error(f"[_handle_signal_message] ⚠️ SKIPPING - invalid exit_side: {exit_side} for symbol {symbol}")
                                continue
                            try:
                                position_key = construct_position_key(account_key, symbol, exit_side)
                                if not position_key:
                                    logger.error(f"[_handle_signal_message] ⚠️ SKIPPING - construct_position_key returned None: account={account_key}, symbol={symbol}, exit_side={exit_side}")
                                    continue
                                ak, sym, side = parse_position_key(position_key)
                                position_key = construct_position_key(ak or account_key, sym, side)
                                if not position_key:
                                    logger.error(f"[_handle_signal_message] ⚠️ SKIPPING - construct_position_key returned None: account={account_key}, symbol={sym}, exit_side={side}")
                                    continue
                                if not position_key: continue
                            except Exception:
                                position_key = construct_position_key(account_key, symbol, exit_side)
                                if not position_key:
                                    logger.error(f"[_handle_signal_message] ⚠️ SKIPPING - construct_position_key returned None: account={account_key}, symbol={symbol}, exit_side={exit_side}")
                                    continue
                            reloaded = await self._reload_single_position_fast(position_key, account_key)
                            if reloaded:
                                position = reloaded
                            else:
                                position = await self.get_position(position_key)
                            if not position or abs(float(getattr(position, 'positionAmt', 0.0) or 0.0)) < 1e-8:
                                continue
                            allowed_single = filter_monitor_keys(self, account_key, position_key)
                            if allowed_single:
                                if signal_category in ["BEARISH", "BULLISH"] or ('wt_signal' in event_type and action == "SELL"):
                                    current_price = signal_price
                                    if current_price:
                                        base_amt = abs(float(getattr(position, 'positionAmt', 0.0) or 0.0))
                                        if base_amt > 1e-8:
                                            now_utc = datetime.now(timezone.utc)
                                            is_long = position.position_side == 'LONG'
                                            indicators = await ii(self, symbol)
                                            i = indicators
                                            conviction = float(i.get('zconviction_long' if is_long else 'zconviction_short', signal_data.get("conviction", actual_data.get("conviction", 75.0))))
                                            has_recent_crossover = (is_long and (i.get('wt_cross_3m') == "BULL" or i.get('dc_basis_crossover_3m', False))) or (not is_long and (i.get('wt_cross_3m') == "BEAR" or i.get('dc_basis_crossunder_3m', False))) if i else False
                                            opened_at_dt = safe_datetime(getattr(position, 'opened_at', None)) if position.opened_at else None
                                            recently_opened = opened_at_dt and (now_utc - opened_at_dt).total_seconds() < config.AUGMENTATION_COOLDOWN_SECONDS if opened_at_dt else False
                                            recently_augmented = position.last_augmentation_time and (now_utc - position.last_augmentation_time).total_seconds() < config.AUGMENTATION_COOLDOWN_SECONDS if position.last_augmentation_time else False
                                            if (recently_opened or recently_augmented) and has_recent_crossover:
                                                logger.warning(f"[🚫 REDUCE_NOT_ALLOWED] {position_key}: not_allowed REDUCE - position recently {'opened' if recently_opened else 'augmented'} with crossover signal (opened={recently_opened}, augmented={recently_augmented}, crossover={has_recent_crossover})")
                                                continue
                                            opened_at_dt = safe_datetime(getattr(position, 'opened_at', None)) if hasattr(position, 'opened_at') and position.opened_at else None
                                            position_age_seconds = (now_utc - opened_at_dt).total_seconds() if opened_at_dt else float('inf')
                                            is_new_position = position_age_seconds < 300.0
                                            position.gain = safe_fetch_float(getattr(position, 'gain', 0.0), 0.0)
                                            if is_new_position:
                                                k_3m = safe_fetch_float(i.get('stoch_k_3m', 50), 50.0) if i else 50.0
                                                d_3m = safe_fetch_float(i.get('stoch_d_3m', 50), 50.0) if i else 50.0
                                                k_3m_prev = safe_fetch_float(i.get('k_3m_prev', 50), 50.0) if i else 50.0
                                                entry_price = safe_fetch_float(getattr(position, 'entry_price', 0.0), 0.0)
                                                price_moved_against = (is_long and current_price < entry_price * 0.995) or (not is_long and current_price > entry_price * 1.005)
                                                k_3m_confirmed_bad = (is_long and k_3m < 30 and k_3m < d_3m) or (not is_long and k_3m > 70 and k_3m > d_3m)
                                                k_3m_flipped = (is_long and k_3m_prev >= 50 and k_3m < 50) or (not is_long and k_3m_prev <= 50 and k_3m > 50)
                                                if position.gain > config.NEW_POSITION_MAX_LOSS_THRESHOLD:
                                                    if not (price_moved_against and k_3m_confirmed_bad and k_3m_flipped):
                                                        logger.warning(f"[NEW_POSITION_PROTECTION] {position_key}: Blocking IMMEDIATE_REDUCE - position is new ({position_age_seconds:.1f}s old), gain {position.gain:.2f}% > threshold {config.NEW_POSITION_MAX_LOSS_THRESHOLD:.2f}%, but no clear confirmation (price_moved={price_moved_against}, k_3m_confirmed={k_3m_confirmed_bad}, k_3m_flipped={k_3m_flipped}, k_3m={k_3m:.1f}, d_3m={d_3m:.1f})")
                                                        continue
                                                    else:
                                                        logger.warning(f"[NEW_POSITION_OVERRIDE] {position_key}: Allowing IMMEDIATE_REDUCE on new position ({position_age_seconds:.1f}s old) - clear confirmation: price_moved={price_moved_against}, k_3m_confirmed={k_3m_confirmed_bad}, k_3m_flipped={k_3m_flipped}")
                                            red_seconds = (now_utc - position.last_reduction_time).total_seconds() if position.last_reduction_time else float('inf')
                                            if red_seconds < config.REDUCTION_COOLDOWN_SECONDS:
                                                logger.error(f"[🚨 IMMEDIATE_REDUCE_NOT_ALLOWED] {position_key}: REDUCE COOLDOWN ACTIVE - last reduction was {red_seconds:.0f}s ago (required={config.REDUCTION_COOLDOWN_SECONDS}s) - NO EXCEPTIONS")
                                                continue
                                            # STRICT_NO_LOSS: NEVER reduce at a loss. Take a hedge instead.
                                            # SRS bypass (2026-04-14): STRUCTURAL_RANGE_SHIFT is a controlled-loss exit.
                                            _noloss_min = getattr(config, 'NOLOSS_MIN_PROFIT_PCT', 0.5)
                                            _imm_srs = 'STRUCTURAL_RANGE_SHIFT' in str(event_type or '').upper() or 'STRUCTURAL_RANGE_SHIFT' in str(signal_category or '').upper()
                                            if is_strict_no_loss_account(config, account_key) and position.gain < _noloss_min and not _imm_srs:
                                                logger.warning(f"[IMMEDIATE_REDUCE_BLOCKED_NOLOSS] {position_key}: gain={position.gain:.2f}% < {_noloss_min}%. STRICT_NO_LOSS — NEVER close at a loss. Hedging instead.")
                                                continue
                                            reason_code = f"[HANDLE_SIGNAL]:{signal_category}_{event_type}_IMMEDIATE_REDUCE" if signal_category != "UNKNOWN" else f"{event_type}_IMMEDIATE_REDUCE"
                                            logger.warning(f"[🚀 IMMEDIATE_REDUCE] {position_key}: {signal_category} signal -> REDUCE (conviction={conviction:.1f})")
                                            account_key, symbol, position_side = parse_position_key(position_key)
                                            side = "SELL" if position_side == "LONG" else "BUY"
                                            result = await queue_trade_action(self.order_queue, self, position_key, "REDUCE", reason_code, conviction)
                                            if result and not result.startswith("QUEUED") and not result.startswith("SUCCESS"):
                                                await self.clear_all_cooldowns_for_position(position_key, side)
                                                logger.info(f"[IMMEDIATE_REDUCE] {position_key}: Cleared cooldowns after queue failure (result={result})")
                                await monitor_entries(order_queue=self.order_queue, trade_manager=self, account_key=account_key, position_keys=allowed_single, event_type=event_type, signal_data=signal_data, is_priority_add=False, force=True)
                if event_type == "QUICK_TRIGGER_1M":
                    event_type="QUICK_TRIGGER"
                    await monitor_entries(order_queue=self.order_queue, trade_manager=self, account_key=account_key, position_keys=allowed_existing, event_type=event_type, signal_data=signal_data, is_priority_add=False, force=True)
                if entry_routed_to or exit_routed_to or entry_not_allowed or exit_not_allowed:
                    summary_parts = []
                    if entry_routed_to:
                        summary_parts.append(f"ENTRY→{entry_routed_to} -")
                    if exit_routed_to:
                        summary_parts.append(f"EXIT→{exit_routed_to} -")
                    if entry_not_allowed and account_key in loaded_accounts:
                        summary_parts.append(f"ENTRY_NOT_ALLOWED→{entry_not_allowed} -")
                    if exit_not_allowed:
                        summary_parts.append(f"EXIT_NOT_ALLOWED→{exit_not_allowed} -")
                else:
                    logger.warning(f"⚠️ NO ROUTING: {symbol} {event_type} - no accounts matched criteria")
            except asyncio.TimeoutError:
                logger.warning("Redis pub/sub timeout - reconnecting...")
            except json.JSONDecodeError:
                logger.error(f"Failed to parse JSON from Redis signal: {signal_data.get('data') }")
            except Exception as e:
                logger.error(f"Error processing Redis signal message: {e}", exc_info=True)

        except Exception as e:
            logger.critical(f"CRITICAL ERROR in Redis signals listener: {e}", exc_info=True)

    async def redis_listener_signals(self):
        """Subscribes to the trading signals channel using the UnifiedRedisManager."""
        try:
            if not self.redis_manager:
                logger.warning("⚠️ Redis manager not available - skipping signals listener")
                return
            channel_name = REDIS_CHANNELS.get("signals_data", "signals_data")
            logger.info(f"📡 [SIGNAL_SUB] Attempting to subscribe to Redis channel '{channel_name}' for real-time trading signals...")
            await self.redis_manager.subscribe( channel=channel_name, callback=self._handle_signal_message, data_type="signals" )
            logger.info(f" [SIGNAL_SUB] Successfully subscribed to Redis channel '{channel_name}' - ready to receive signals from ez_indicators")
        except Exception as e:
            logger.error(f"❌ [SIGNAL_SUB] Redis signals listener setup failed: {e} - continuing without Redis signals", exc_info=True)

    async def _handle_latest_market_data_broadcast(self, payload: Any) -> None:
        try:
            if isinstance(payload, str):
                indicators_data = json.loads(payload)
            elif isinstance(payload, dict):
                indicators_data = payload
            else:
                return
            if isinstance(indicators_data, dict) and indicators_data:
                self.indicators_snapshot.clear()
                for symbol, indicators in indicators_data.items():
                    if isinstance(indicators, dict):
                        self.indicators_snapshot[symbol] = indicators
                self.indicators_cache_timestamps.clear()
                self.indicators_cache_timestamps.update({symbol: time.time() for symbol in indicators_data.keys()})
                logger.debug(f"[latest_market_data] Updated indicators cache with {len(indicators_data)} symbols")
        except Exception as e:
            logger.debug(f"[latest_market_data] Failed to handle broadcast: {e}")

    def find_position_by_symbol(self, symbol: str):
        matching_positions = []
        managed_accounts = set(self.accounts.keys())
        for account_key, sub_dict in self.positions_by_account.items():
            if account_key not in managed_accounts or account_key not in config.ACCOUNT_KEYS:
                continue
            for position_key, position_obj in sub_dict.items():
                if position_obj and position_obj.symbol == symbol:
                    matching_positions.append(position_obj)
        if not matching_positions:
            return None
        return max(matching_positions, key=lambda pos: pos.last_updated)

    async def _refresh_price_caches_if_stale(self):
        now_ts = time.time()
        if now_ts - self.price_caches_last_loaded < self._price_cache_refresh_interval:
            return
        try:
            _pc2 = await read_json_file(self.config.PRICE_CACHE_FILE_2)
            if isinstance(_pc2, dict):
                self.price_cache_2.clear()
                self.price_cache_2.update(_pc2)
            _pc3 = await read_json_file(self.config.PRICE_CACHE_FILE_3)
            if isinstance(_pc3, dict):
                self.price_cache_3.clear()
                self.price_cache_3.update(_pc3)
        except Exception as e:
            logger.debug(f"price cache refresh failed: {e}")
        self.price_caches_last_loaded = now_ts

    async def save_price_cache(self):
        while True:
            try:
                async with self.markprice_lock:
                    price_cache_copy = self.price_cache.copy()
                # price_svc middleman removed — self.price_cache is shared directly with service via getattr
                filepath = self.config.PRICE_CACHE_FILE
                logger.debug(f"💾 Saving price cache with {len(price_cache_copy)} symbols to {filepath}")
                await atomic_write_json(filepath, price_cache_copy)
                logger.debug(f" Successfully saved price cache ({len(price_cache_copy)} symbols)")
                backup_folder = os.path.join(os.path.dirname(filepath), "backup_price_caches")
                os.makedirs(backup_folder, exist_ok=True)
                now_str = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%S').replace(":", "-")
                backup_filename = f"price_cache_{now_str}.json"
                backup_path = os.path.join(backup_folder, backup_filename)
                await atomic_write_json(backup_path, price_cache_copy)
                logger.debug(f"💾 Created backup: {backup_filename}")
                await asyncio.sleep(21)
            except Exception as e:
                logger.error(f"Error writing price cache: {e}")
                await asyncio.sleep(10)

    async def periodic_price_cache_loader(self):
        """Periodically reloads the price cache files from disk."""
        while True:
            try:
                _pc1 = await read_json_file(self.config.PRICE_CACHE_FILE)
                if isinstance(_pc1, dict):
                    self.price_cache.clear()
                    self.price_cache.update(_pc1)
                _pc3_periodic = await read_json_file(self.config.PRICE_CACHE_FILE_3)
                if isinstance(_pc3_periodic, dict):
                    self.price_cache_3.clear()
                    self.price_cache_3.update(_pc3_periodic)
                logger.debug("Refreshed price_cache and price_cache_3 from disk.")
            except Exception as e:
                logger.error(f"Error in periodic_price_cache_loader: {e}")
            await asyncio.sleep(15) 

    async def get_current_price(self, symbol: Optional[str] = None) -> Tuple[Optional[float], Optional[datetime]]:
        if not symbol: return None, None
        clean_symbol = symbol
        price, timestamp = None, None
        now_utc = datetime.now(timezone.utc)
        try_positions = []
        for account_key in config.ACCOUNT_KEYS:
            positions_dict = self.positions_by_account.get(account_key, {})
            try_positions.extend([p for p in positions_dict.values() if p and p.symbol == clean_symbol])
        try_positions.extend([p for p in self.positions.values() if p and p.symbol == clean_symbol])
        for position in try_positions:
            price_val = safe_fetch_float(getattr(position, "mark_price", 0.0), 0.0)
            if price_val <= 0:
                continue
            ts = getattr(position, "mark_price_last_updated", None) or getattr(position, "mark_price_updated_at", None) or getattr(position, "last_updated", None)
            if isinstance(ts, str):
                try:
                    ts = isoparse(ts)
                except Exception:
                    ts = None
            if isinstance(ts, datetime) and ts.tzinfo is None:
                ts = ts.replace(tzinfo=timezone.utc)
            if ts and (now_utc - ts).total_seconds() < 2:
                return price_val, ts
        try:
            read_client = None
            if self.redis_manager and self.redis_manager._initialized:
                read_client = self.redis_manager.connections.get("local") or self.redis_manager.connections.get("gateway") or self.redis_manager.connections.get("server")
            if read_client:
                redis_key = f"mark_price:{clean_symbol}"
                data = await read_client.get(redis_key)
                if data:
                    try:
                        if isinstance(data, (bytes, bytearray)):
                            data = data.decode()
                        p_data = json.loads(data) if isinstance(data, str) and data.startswith("{") else {"price": data}
                        price = float(p_data["price"])
                        ts_raw = p_data.get("timestamp") or p_data.get("time")
                        if isinstance(ts_raw, (int, float)):
                            divisor = 1000.0 if ts_raw > 1e12 else 1.0
                            timestamp = datetime.fromtimestamp(ts_raw / divisor, tz=timezone.utc)
                        elif isinstance(ts_raw, str):
                            try:
                                timestamp = safe_datetime(ts_raw)
                            except Exception:
                                timestamp = None
                        else:
                            timestamp = None
                        if isinstance(timestamp, datetime) and timestamp.tzinfo is None:
                            timestamp = timestamp.replace(tzinfo=timezone.utc)
                        now_utc = datetime.now(timezone.utc)
                        age = (now_utc - timestamp).total_seconds() if timestamp else 999
                        if price > 0 and age < 12.0:
                            return price, timestamp
                        if price > 0:
                            price, timestamp = price, timestamp
                    except (json.JSONDecodeError, KeyError, ValueError):
                        pass
        except Exception as e:
            logger.debug(f"Redis direct fetch failed for {clean_symbol}: {e}")
        if price and timestamp and (datetime.now(timezone.utc) - timestamp).total_seconds() < 12.0:
            return price, timestamp
        await self._refresh_price_caches_if_stale()
        cache_candidates = []
        for cache_name, cache in (("price_cache", self.price_cache), ("price_cache_2", self.price_cache_2), ("price_cache_3", self.price_cache_3)):
            try:
                entry = cache.get(clean_symbol) if isinstance(cache, dict) else None
                if not entry:
                    continue
                if isinstance(entry, dict):
                    price_val = safe_fetch_float(entry.get("price"), 0.0)
                    ts = entry.get("timestamp")
                else:
                    price_val = safe_fetch_float(entry, 0.0)
                    ts = None
                if isinstance(ts, (int, float)):
                    divisor = 1000.0 if ts > 1e12 else 1.0
                    ts = datetime.fromtimestamp(ts / divisor, tz=timezone.utc)
                if isinstance(ts, str):
                    try:
                        ts = isoparse(ts)
                    except Exception:
                        ts = None
                if isinstance(ts, datetime) and ts.tzinfo is None:
                    ts = ts.replace(tzinfo=timezone.utc)
                if price_val > 0 and ts:
                    age = (now_utc - ts).total_seconds()
                    if age < 12.0:
                        return price_val, ts
                    if age < 90:
                        cache_candidates.append((age, price_val, ts, cache_name))
            except Exception as e:
                logger.debug(f"{cache_name} lookup failed for {clean_symbol}: {e}")
        position_candidates = []
        for position in try_positions:
            price_val = safe_fetch_float(getattr(position, "mark_price", 0.0), 0.0)
            if price_val > 0:
                fallback_ts = getattr(position, "mark_price_last_updated", None) or getattr(position, "last_updated", None)
                if isinstance(fallback_ts, str):
                    try:
                        fallback_ts = isoparse(fallback_ts)
                    except Exception:
                        fallback_ts = None
                if isinstance(fallback_ts, datetime) and fallback_ts.tzinfo is None:
                    fallback_ts = fallback_ts.replace(tzinfo=timezone.utc)
                if not isinstance(fallback_ts, datetime):
                    fallback_ts = datetime.now(timezone.utc)
                age = (now_utc - fallback_ts).total_seconds()
                if age < 12.0:
                    return price_val, fallback_ts
                position_candidates.append((age, price_val, fallback_ts))
        all_candidates = []
        if price and timestamp:
            all_candidates.append(((now_utc - timestamp).total_seconds(), price, timestamp, "Redis"))
        all_candidates.extend([(age, price, ts, src) for age, price, ts, src in cache_candidates])
        all_candidates.extend([(age, price, ts) for age, price, ts in position_candidates])
        if all_candidates:
            all_candidates.sort(key=lambda x: x[0])
            best_age, price_final, best_ts_final = all_candidates[0][:3]
            logger.debug(f"[{clean_symbol}] Using most recent price: {price_final} (age={best_age:.1f}s)")
            return price_final, best_ts_final
        logger.debug(f"[{clean_symbol}] No price available from positions, redis, or caches. Trying robust fallback...")
        return await get_current_price(clean_symbol)

    def is_valid_stoch_event(self, latest_data: dict, max_valid_minutes: int = 2) -> bool:
        now = datetime.now(timezone.utc)
        if not latest_data:
            return False
        event_timestamp_str = latest_data.get("timestamp")
        if not event_timestamp_str:
            return False
        normalized_ts = _normalize_timestamp_to_z(event_timestamp_str) if isinstance(event_timestamp_str, str) else event_timestamp_str
        event_timestamp = safe_datetime(normalized_ts, normalized_ts)
        if event_timestamp.tzinfo is None:
            event_timestamp = event_timestamp.replace(tzinfo=timezone.utc)
        time_difference = now - event_timestamp
        return time_difference <= timedelta(minutes=max_valid_minutes)

    async def load_leaderboards(self):

        def normalize_symbol(s):
            sym = str(s).strip().upper()
            if sym.endswith("USDT"):
                usdc_sym = sym[:-4] + "USDC"
                if hasattr(self, 'available_usdc_pairs') and usdc_sym in self.available_usdc_pairs:
                    return usdc_sym
            return sym

        async def _load_file(filepath):
            if not filepath: return {}
            path = Path(filepath)
            if not path.exists():
                return {}
            try:
                async with aiofiles.open(path, "rb") as f:
                    content = await f.read()
                    if not content: return {}
                    data = orjson.loads(content)
                result = {}
                items = data if isinstance(data, list) else []
                if isinstance(data, dict): items = data.values() # Handle dict format if passed
                for item in items:
                    if not isinstance(item, dict) or "symbol" not in item: continue
                    raw_sym = item["symbol"]
                    norm_sym = normalize_symbol(raw_sym)
                    item["symbol"] = norm_sym
                    result[norm_sym] = item
                return result
            except Exception as e:
                logger.error(f"Error loading leaderboard {path}: {e}")
                return {}
        w15_path = config.WINNERS_15M_FILE
        if not os.path.exists(w15_path) and os.path.exists(config.DATA_DIR / "winners_30r"):
            w15_path = config.DATA_DIR / "winners_30r"
        l15_path = config.LOSERS_15M_FILE
        if not os.path.exists(l15_path) and os.path.exists(config.DATA_DIR / "losers_30r"):
            l15_path = config.DATA_DIR / "losers_30r"
        w20_task = _load_file(config.WINNERS_20_FILE)
        l20_task = _load_file(config.LOSERS_20_FILE)
        w15_task = _load_file(w15_path)
        l15_task = _load_file(l15_path)
        res_w20, res_l20, res_w15, res_l15 = await asyncio.gather(w20_task, l20_task, w15_task, l15_task)
        self.winners_20: Dict[str, Any] = res_w20
        self.losers_20: Dict[str, Any] = res_l20
        self.winners_15m: Dict[str, Any] = res_w15
        self.losers_15m: Dict[str, Any] = res_l15
        logger.info(f"[loa d_leaderboards] Loaded: W20={len(self.winners_20)}, L20={len(self.losers_20)}, W15={len(self.winners_15m)}, L15={len(self.losers_15m)}")
        loaded_accounts = set(self.accounts.keys())

        async def forward_to_monitor(account_key, position_key, event_type, signal_data, is_priority=False):
            if account_key not in loaded_accounts:
                return
            ak, pos_symbol, side = parse_position_key(position_key)
            if account_key == ak:
                try:
                    has_open = False
                    pos_obj = self._get_position_obj(position_key, ak)
                    if pos_obj and getattr(pos_obj, 'positionAmt', 0) and abs(float(pos_obj.positionAmt)) > 0:
                        has_open = True
                    if (position_key not in getattr(self, 'positions_to_gracefully_exit', set())) and (not has_open):
                        if not self.is_symbol_allowed(account_key, pos_symbol, position_key):
                            return
                except Exception:
                    pass
                allowed_single = filter_monitor_keys(self, account_key, position_key)
                if not allowed_single: return
                await monitor_entries( order_queue=self.order_queue, trade_manager=self, account_key=account_key, position_keys=allowed_single, event_type=event_type, signal_data=signal_data, is_priority_add=is_priority )
        for symbol, item in self.winners_20.items():
            event_type = item.get("event_type", "leaderboard_winners_20")
            for account in ("ang", "inf", "flz", "men", "fin"):
                position_key = construct_position_key(account, symbol, "LONG")
                if self.is_symbol_allowed(account, symbol, position_key):
                    await forward_to_monitor(account, position_key, event_type, item, is_priority=True)
        for symbol, item in self.losers_20.items():
            event_type = item.get("event_type", "leaderboard_losers_20")
            for account in ("ang", "inf", "flz", "men", "fin"):
                position_key = construct_position_key(account, symbol, "SHORT")
                if self.is_symbol_allowed(account, symbol, position_key):
                    await forward_to_monitor(account, position_key, event_type, item, is_priority=True)
        for symbol, item in self.winners_15m.items():
            event_type = item.get("event_type", "leaderboard_winners_15m")
            for account in ("ang", "inf", "flz", "men", "fin"):
                position_key = construct_position_key(account, symbol, "LONG")
                if self.is_symbol_allowed(account, symbol, position_key):
                    await forward_to_monitor(account, position_key, event_type, item, is_priority=True)
        for symbol, item in self.losers_15m.items():
            event_type = item.get("event_type", "leaderboard_losers_15m")
            for account in ("ang", "inf", "flz", "men", "fin"):
                position_key = construct_position_key(account, symbol, "SHORT")
                if self.is_symbol_allowed(account, symbol, position_key):
                    await forward_to_monitor(account, position_key, event_type, item, is_priority=True)

    async def save_graceful_exit_list(self):
        for account_key in self.accounts.keys():
            if account_key in ['ang','inf','men', 'flz', 'fin']: # Only these accounts use this feature
                filepath = self.config.GRACEFUL_EXIT_FILE_TEMPLATE.with_name( self.config.GRACEFUL_EXIT_FILE_TEMPLATE.name.format(account_key=account_key) )
                account_specific_keys = {k for k in self.positions_to_gracefully_exit if isinstance(k, str) and k.startswith(f"{account_key}:")}
                try:
                    await atomic_write_json(filepath, {"keys": list(account_specific_keys)})
                    logger.debug(f"[GracefulExit] Saved {len(account_specific_keys)} keys for {account_key} to {filepath.name}")
                except Exception as e:
                    logger.error(f"[GracefulExit] Failed to save graceful exit list for {account_key}: {e}")

    async def load_graceful_exit_list(self):
        self.positions_to_gracefully_exit.clear()
        normalized_keys, invalid_keys = set(), set()

        def normalize_key(raw_key):
            if not isinstance(raw_key, str): return None
            key = raw_key.strip()
            if not key: return None
            parts = [p for p in key.split(":") if p]
            account = parts[0].strip() if parts else ""
            symbol = ""
            side = None
            if len(parts) >= 3:
                side_token = parts[-1].strip().upper()
                symbol = ":".join(parts[1:-1]).strip().upper()
            elif len(parts) == 2:
                side_token = parts[1].strip().upper()
                if side_token.endswith("_LONG"):
                    symbol = side_token[:-5].strip().upper()
                    side_token = "LONG"
                elif side_token.endswith("_SHORT"):
                    symbol = side_token[:-6].strip().upper()
                    side_token = "SHORT"
                else:
                    return None
            else:
                return None
            if "SHORT" in side_token:
                side = "SHORT"
            elif "LONG" in side_token:
                side = "LONG"
            if not account or not symbol or side not in ("LONG","SHORT"):
                return None
            if not account or not symbol or not side: 
                logger.error(f"[load_graceful_exit] ⚠️ SKIPPING - construct_position_key returned None: account={account}, symbol={symbol}, pos_side={side}")
                return None
            return construct_position_key(account, symbol, side)
        for account_key in self.accounts.keys():
            if account_key in ['ang', 'inf', 'men', 'flz','fin']:
                filepath = self.config.GRACEFUL_EXIT_FILE_TEMPLATE.with_name(self.config.GRACEFUL_EXIT_FILE_TEMPLATE.name.format(account_key=account_key))
                data = await read_json_file(filepath)
                raw_keys = data.get("keys")
                if isinstance(raw_keys, list):
                    for raw_key in raw_keys:
                        normalized = normalize_key(raw_key)
                        if normalized:
                            normalized_keys.add(normalized)
                        else:
                            invalid_keys.add(str(raw_key))
        if normalized_keys:
            self.positions_to_gracefully_exit.update(normalized_keys)
            logger.info(f"[GracefulExit] Loaded {len(normalized_keys)} exit flags across accounts (invalid={len(invalid_keys)})")

