            if _sg_val >= _sg_start:
                _sg_gain = safe_fetch_float(getattr(_sg_pos, 'gain', 0), 0.0) if _sg_pos else 0
                _sg_min_gain = safe_fetch_float(getattr(config, 'MIN_GAIN', 1.2), 1.2)
