        if not is_long and dc_low_1h > 0 and current_price < dc_low_1h * 0.999 and wt1_15m < wt2_15m:
            logger.warning(f"[REENTRY_B11] {position_key}: DC_BREAK_SHORT dc1h={dc_low_1h:.4f}")
