def _breakout_tf_size_mult(reason: str) -> tuple:
    """Parse TF marker from an entry reason and return (multiplier, tf_label) per BREAKOUT_TF_SIZE_MULT_* config.
    Returns (1.0, '') if disabled or no TF marker found. Matches tokens _3M_ / _15M_ / _1H_ / _4H_ / _D_
    (with word boundaries so '3m' inside another token doesn't double-match). Higher TF wins when multiple present."""
    if not bool(getattr(config, 'BREAKOUT_TF_SIZE_ENABLED', True)):
        return 1.0, ''
    if not reason:
        return 1.0, ''
    _r = reason.upper()
    # Check highest TF first so the largest multiplier wins when multiple markers appear in the reason.
    _tf_checks = [
        ('_D_', float(getattr(config, 'BREAKOUT_TF_SIZE_MULT_D', 4.0)), 'D'),
        ('_4H_', float(getattr(config, 'BREAKOUT_TF_SIZE_MULT_4H', 3.0)), '4H'),
        ('_1H_', float(getattr(config, 'BREAKOUT_TF_SIZE_MULT_1H', 2.0)), '1H'),
        ('_15M_', float(getattr(config, 'BREAKOUT_TF_SIZE_MULT_15M', 1.0)), '15M'),
        ('_3M_', float(getattr(config, 'BREAKOUT_TF_SIZE_MULT_3M', 0.5)), '3M'),
    ]
    for _marker, _mult, _lbl in _tf_checks:
        if _marker in _r:
            _cap = float(getattr(config, 'BREAKOUT_TF_SIZE_CAP_MULT', 5.0))
            return min(_mult, _cap), _lbl
    return 1.0, ''


async def queue_trade_action(order_queue: OrderQueue, trade_manager: "MultiAccountTradeManager", position_key: Optional[str] = None, action: str = "", reason: str = "", conviction: float = 0.5, override_qty: Optional[float] = None, account_key: Optional[str] = None) -> str:
    logger.info(f"[queue_trade_action] 🚨 Queueing: {position_key} ")
    now = datetime.now(timezone.utc)
    conviction = safe_fetch_float(conviction, 0.5)
    reason_str = str(reason or "")
    try:
        account_key, symbol, position_side = parse_position_key(position_key)
        if account_key not in trade_manager.accounts:
            logger.warning(f"[queue_trade_action] SKIPPING: {position_key} account mismatch")
            return f"SKIPPED_ACCOUNT_MISMATCH_{account_key}"
        is_long = position_side == 'LONG'
        if action in ['AUGMENT', 'OPEN', 'QUICK_OPEN', 'QUICK_AUGMENT', 'REENTRY', 'HEDGE_OPEN', 'REVERSE_AUGMENT']:
            side = 'BUY' if is_long else 'SELL'
        elif action in ['REDUCE', 'QUICK_CLOSE', 'CLOSE', 'SELL', 'PROFIT_TAKE', 'HEDGE_CLOSE', 'REVERSE_REDUCE']:
            side = 'SELL' if is_long else 'BUY'
        elif action == 'REVERSE':
             side = 'SELL' if is_long else 'BUY' # Initial action is close
        else:
            logger.critical(f"[UNMAPPED_ACTION_BLOCK] {position_key}: action='{action}' is NOT in any known action list — BLOCKING to prevent wrong-direction order. Fix the caller!")
            return f"BLOCKED_UNMAPPED_ACTION_{action}"
        side, is_valid_side = trade_manager.validate_order_side(side, position_side, action, position_key)
        if not override_qty: # Skip checks if manual override
            if action in ('OPEN', 'AUGMENT', 'REENTRY') and getattr(trade_manager, 'redis_manager', None):
                open_block = await trade_manager.redis_manager.get(f"open_blocked:{position_key}")
                if open_block:
                    logger.warning(f"[{position_key}] {action} blocked: consecutive unverified OPEN failures. Key=open_blocked:{position_key}")
                    return f"SKIPPED_OPEN_BLOCKED_{action}"
            if await trade_manager.is_duplicate_order(position_key, 0.0, side, unique_id="queue_check"):
                 logger.debug(f"[{position_key}] SKIPPED: Duplicate/Rapid-fire order detected")
                 return f"SKIPPED_DUPLICATE_{action}"
            if hasattr(trade_manager, 'orders_in_limbo'):
                if position_key in trade_manager.orders_in_limbo and side in trade_manager.orders_in_limbo[position_key]:
                    limbo_ts = trade_manager.orders_in_limbo[position_key][side]
                    if time.time() - limbo_ts < 5.0: # 5s hard lock
                        return f"SKIPPED_IN_LIMBO_{action}"
        final_order_qty = 0.0
        current_price = 0.0
        position = await trade_manager.get_position(position_key)
        current_price = await price(symbol, position)
        if not current_price or current_price <= 0:
            current_price = safe_fetch_float(getattr(position, 'mark_price', 0.0), 0.0)
        positionAmt = abs(safe_fetch_float(getattr(position, "positionAmt", 0.0), 0.0)) if position else 0.0 
        if action in ('AUGMENT', 'QUICK_AUGMENT') and position and current_price > 0:
            _pos_gain = safe_fetch_float(getattr(position, 'gain', 0.0), 0.0)
            _pos_notional = abs(safe_fetch_float(getattr(position, 'positionAmt', 0.0), 0.0)) * current_price
            _dd_bypass = 'DD_BOUNCE_AUG' in (reason or '').upper()
            if _pos_notional > 0 and _pos_gain < config.MIN_GAIN and not _dd_bypass:
                logger.warning(f"[AUGMENT_GATE_QUEUE] {position_key}: Blocked {action} at gain={_pos_gain:.3f}% < {config.MIN_GAIN:.3f}% before queuing. reason={reason} — NO BYPASS")
                return f"BLOCKED_AUGMENT_QUEUE_LOW_GAIN_{_pos_gain:.3f}%"
        pos_min_qty = max(config.MIN_POSITION_SIZE / current_price, 1.2 * trade_manager.min_qty.get(symbol, 0.0001))
        qty = pos_min_qty
        if override_qty:
            final_order_qty = override_qty
        elif position and current_price > 0:
            try:
                preliminary_qty = 0.0
                if action == 'OPEN':
                    preliminary_qty = max(trade_manager.config.START_POSITION_SIZE / current_price, 1.2 * trade_manager.min_qty.get(symbol, 0.001))
                    if 'HEDGE' in reason.upper():
                        exchange_min = 5.5 / current_price
                        qty = max(qty, exchange_min)
                    else:
                        qty = max(qty, config.START_POSITION_SIZE / current_price, pos_min_qty)
                elif action == 'AUGMENT':
                    preliminary_qty = max(2 * trade_manager.config.START_POSITION_SIZE / current_price, 0.6 * position.positionAmt)
                elif action in ['REENTRY', 'QUICK_OPEN', 'REENTRY', 'AUGMENT', 'REVERSE', 'HEDGE_OPEN']:
                    preliminary_qty = max(2 * trade_manager.config.START_POSITION_SIZE / current_price, 0.6 * position.positionAmt)
                if preliminary_qty > 0:
                    # 2026-04-16: breakout TF-size multiplier. Hedges opt out (hedge sizing owned by HedgeEngine).
                    if 'HEDGE' not in (reason or '').upper() and action not in ('HEDGE_OPEN',):
                        _tf_mult, _tf_lbl = _breakout_tf_size_mult(reason)
                        if _tf_mult != 1.0:
                            _orig_q = preliminary_qty
                            preliminary_qty = preliminary_qty * _tf_mult
                            logger.info(f"[BREAKOUT_TF_SIZE] {position_key} {action}: TF={_tf_lbl} mult={_tf_mult:.2f} qty {_orig_q:.6f}→{preliminary_qty:.6f} (reason={reason[:60]})")
                    final_order_qty = await calculate_final_order_quantity( position_key, account_key, symbol, position, action, trade_manager, conviction, preliminary_qty, reason, None )
            except Exception as e:
                logger.warning(f"[{position_key}] Preliminary qty calc failed ({e}), using default for handler.")
                final_order_qty = config.START_POSITION_SIZE/current_price
        elif 'REDUCE' in action or action in ['REDUCE', 'QUICK_CLOSE', 'CLOSE', 'PROFIT_TAKE', 'HEDGE_CLOSE', 'REVERSE_REDUCE']:
            final_order_qty = positionAmt - pos_min_qty
        elif 'CLOSE' in action :
            final_order_qty = positionAmt 
        unique_id = generate_unique_id(position_key, side, reason)
        is_full_close = action in ['CLOSE', 'QUICK_CLOSE', 'FULL_CLOSE']
        order = { "account_key": account_key, "position_key": position_key, "symbol": symbol, "side": side, "quantity": final_order_qty, "current_price": current_price, "position_side": position_side, "unique_id": unique_id, "is_full_close": is_full_close, "action": action, "reason": reason_str, "override_qty": override_qty, "conviction": conviction }
        added = False
        queue_fail_reason = ""
        for i in range(3):
            success, msg = await order_queue.add_order(order)
            if success:
                added = True
                break
            else:
                queue_fail_reason = msg
                await asyncio.sleep(0.1)
        if not added and action in ['CLOSE', 'REDUCE', 'QUICK_CLOSE', 'STOP_MAJOR_LOSS_REDUCE']:
            logger.warning(f"[{position_key}] 🚨 QUEUE FULL/FAILED ({queue_fail_reason}) for {action}. Bypassing queue to execute immediately.")
            asyncio.create_task(trade_manager.execute_trade_action(**order))
            return f"QUEUED_BYPASS_{action}"
        if added:
            if not hasattr(trade_manager, 'orders_in_limbo'): trade_manager.orders_in_limbo = {}
            if position_key not in trade_manager.orders_in_limbo: trade_manager.orders_in_limbo[position_key] = {}
            trade_manager.orders_in_limbo[position_key][side] = time.time()
            asyncio.create_task(trade_manager._expire_limbo_order(position_key, side, 8.0))
            return f"QUEUED_{action}_{position_side}"
        else:
            logger.error(f"[{position_key}] ❌ Failed to queue {action}: {queue_fail_reason}")
            return f"FAILED_QUEUE_{queue_fail_reason}"
    except Exception as e:
        logger.error(f"[{position_key}] Exception in queue_trade_action: {e}", exc_info=True)
        return f"ERROR_QUEUE_EXCEPTION"

async def cleanup_positions(trade_manager: MultiAccountTradeManager, order_queue: OrderQueue, force: bool = False):
    """Trigger local position cleanup and reload."""
    await trade_manager.cleanup_positions_local(force=force)

async def cleanup_stale_locks(trade_manager: MultiAccountTradeManager):
    while True:
        await asyncio.sleep(20) # Check every 30 seconds
        now_ts = time.time()
        STALE_PENDING_SECONDS = 70 # A lock stuck in "pending" for 2 minutes is stale.
        STALE_COMPLETE_SECONDS = 45 # A "completed" lock is kept for 45s to ensure state updates propagate.
        stale_keys_to_release = []
        for key, lock_data in list(trade_manager.active_order_locks.items()):
            status = lock_data.get("status", "unknown")
            timestamp = lock_data.get("timestamp", 0)
            if status == "pending" and (now_ts - timestamp) > STALE_PENDING_SECONDS:
                stale_keys_to_release.append(key)
            elif status in ["complete", "error"] and (now_ts - timestamp) > STALE_COMPLETE_SECONDS:
                stale_keys_to_release.append(key)
        if stale_keys_to_release:
            for key in stale_keys_to_release:
                trade_manager.active_order_locks.pop(key, None)

@timed_function("process_symbols_periodically")
async def process_symbols_periodically(order_queue: OrderQueue, trade_manager: MultiAccountTradeManager, account_key: str):
    managed_accounts = set(trade_manager.accounts.keys()) if hasattr(trade_manager, 'accounts') else set()
    if account_key not in managed_accounts:
        logger.warning(f"[process _symbols_periodically] SKIPPING: account '{account_key}' not in managed accounts - loop will not start")
        return 
    logger.info(f"🔄 [MONITORIN G_LOOP] Started periodic symbol processing for {account_key}")
    while True:
        try:
            await process_all_symbols_for_account(order_queue, trade_manager, account_key, force=False)
        except Exception as e:
            logger.error(f"[{account_key}] process_all_symbols_for_account CRASHED: {e}", exc_info=True)
        await asyncio.sleep(config.SLEEP_TIME_PROC_ACCT)
_last_reshuffle_time = {}

def should_reshuffle(account_key: str, interval_minutes: int = 3) -> bool:
    now = datetime.now(timezone.utc)
    last_time = _last_reshuffle_time.get(account_key)
    if not last_time or (minutes_since(last_time, now) > interval_minutes):
        _last_reshuffle_time[account_key] = now
        return True
    return False

_valid_symbols_cache = {"symbols": set(), "ts": 0.0}
def get_tradeable_position_keys_for(trade_manager,account_key: str) -> list:
    import time as _t
    if _t.time() - _valid_symbols_cache["ts"] > 300:
        try:
            _valid_symbols_cache["symbols"] = set(json.load(open(Path(config.BASE_PATH) / "symbols.json")))
            _valid_symbols_cache["ts"] = _t.time()
        except Exception:
            pass
    _valid = _valid_symbols_cache["symbols"]
    keys = set()
    if account_key == 'ang':
        for s in trade_manager.symbols_ang_long: keys.add(f"ang:{s}_LONG")
        for s in trade_manager.symbols_ang_short: keys.add(f"ang:{s}_SHORT")
    elif account_key == 'inf':
        for s in trade_manager.symbols_inf_long: keys.add(f"inf:{s}_LONG")
        for s in trade_manager.symbols_inf_short: keys.add(f"inf:{s}_SHORT")
    elif account_key == 'flz':
        for s in trade_manager.symbols_flz:
            keys.add(f"flz:{s}_LONG"); keys.add(f"flz:{s}_SHORT")
    elif account_key == 'men':
        for s in trade_manager.symbols_men:
            keys.add(f"men:{s}_LONG"); keys.add(f"men:{s}_SHORT")
    elif account_key == 'fin':
        for s in trade_manager.symbols_fin:
            keys.add(f"fin:{s}_LONG"); keys.add(f"fin:{s}_SHORT")
    if account_key in trade_manager.positions_by_account:
        for k, pos in trade_manager.positions_by_account[account_key].items():
            if pos and abs(safe_fetch_float(getattr(pos, 'positionAmt', 0.0), 0.0)) > 0:
                sym = getattr(pos, 'symbol', '')
                if _valid and sym and sym not in _valid:
                    logger.warning(f"[SYMBOL_GUARD] {k}: {sym} not in symbols.json — SKIPPING (orphaned position from scanner/outlier)")
                    continue
                keys.add(k)
    return list(keys)

@timed_function("process_all_symbols_for_account")
async def process_all_symbols_for_account(order_queue: OrderQueue, trade_manager: MultiAccountTradeManager, account_key: str, force: bool = False):
    if account_key not in trade_manager.accounts: 
        return
    acct_pos = trade_manager.positions_by_account.get(account_key, {})
    current_open_keys = { k for k, p in acct_pos.items() if abs(safe_fetch_float(getattr(p, 'positionAmt', 0.0), 0.0)) > 0.0001 }
    all_tradeable_keys = await trade_manager.load_tradeable() 
    watchlist_keys = {k for k in all_tradeable_keys if k.startswith(f"{account_key}:")}
    total_keys_to_monitor = current_open_keys | watchlist_keys
    now_ts = time.time()

    def staleness_for(k): 
        return now_ts - trade_manager.last_monitored_positions.get(k, 0.0)
    starved_priority = [] # Open positions (Bleeding risk - check fast)
    starved_standard = [] # Watchlist items (Entry hunting - check slow) 
    for k in total_keys_to_monitor:
        is_open = k in current_open_keys
        threshold = 20.0 if is_open else 150.0
        if staleness_for(k) > threshold:
            if is_open:
                starved_priority.append(k)
            else:
                starved_standard.append(k)
    qd = trade_manager.account_position_queues.get(account_key)
    queue_length = len(qd['queue']) if qd else 0
    is_busy = queue_length > 150
    batch_limit = 60 if is_busy else 400
    random.shuffle(starved_standard)
    batch = (starved_priority + starved_standard)[:batch_limit]
    if batch:
        for k in batch: 
            trade_manager.last_monitored_positions[k] = now_ts
        open_count = len([k for k in batch if k in current_open_keys])
        logger.info(f"[{account_key}] MONITOR_QUEUE: Total={len(batch)} (OPEN/PRIORITY={open_count}, WATCHLIST={len(batch)-open_count}) | Q={queue_length}")
        await monitor_entries(order_queue, trade_manager, account_key, batch, force=True)

@timed_function("continuous_queue_processor")
async def continuous_queue_processor(order_queue: OrderQueue, trade_manager: MultiAccountTradeManager, account_key: str):
    """ Legacy loop kept for heartbeat purposes. Main processing is now done directly via process_all_symbols_for_account. """
    managed_accounts = set(trade_manager.accounts.keys()) if hasattr(trade_manager, 'accounts') else set()
    if account_key not in managed_accounts:
        return
    while True:
        try:
            await asyncio.sleep(5.0)
            now = time.time()
            stuck_keys = []
        except Exception as e:
            logger.error(f"[{account_key}] conti nuous_queue_processor error: {e}")
            await asyncio.sleep(5.0)

async def periodic_lock_cleanup(trade_manager):
    """Run every 30 seconds to clean up stale locks"""
    while True:
        try:
            await trade_manager.cleanup_stale_execution_locks()
        except Exception as e:
            logger.error(f"[PERIODIC_LOCK_CLEANUP] Error: {e}")
        await asyncio.sleep(30)

def generate_unique_id(position_key, side, reason=""):
    unique_id = uuid.uuid4().hex[:8] # short random
    return f"{position_key}:{side}:{reason}:{unique_id}"

async def periodic_queue_reset(trade_manager, interval_minutes=5):
    while True:
        trade_manager.reset_all_queues()
        logger.debug("[reset_all_queues] Queues refreshed for all accounts.")
        await asyncio.sleep(interval_minutes * 60)

async def periodic_tasks(order_queue: OrderQueue, trade_manager: MultiAccountTradeManager):
    if not hasattr(trade_manager, '_last_priority_monitor'):
        trade_manager._last_priority_monitor = {}
    if not hasattr(trade_manager, '_last_regular_monitor'):
        trade_manager._last_regular_monitor = {}
    _oversize_cooldown = {}
    while True:
        await asyncio.sleep(config.SLEEP_TIME_PER_TASKS)
        # ═══ EMERGENCY POSITION SIZE GUARD — catches Finandy TP ladder bug ═══
        # Finandy TP orders bypass our guards. This catches ANY position that exceeds MAX_POSITION_SIZE
        # and force-closes the excess immediately. Runs every cycle.
        managed_accounts = set(trade_manager.accounts.keys())
        for _ak, _pdict in trade_manager.positions_by_account.items():
            if _ak not in managed_accounts: continue
            _max_usd = get_max_position_size(account_key=_ak)
            for _pk, _pos in _pdict.items():
                if not _pos: continue
                _amt = abs(safe_fetch_float(getattr(_pos, 'positionAmt', 0), 0))
                if _amt == 0: continue
                _mp = safe_fetch_float(getattr(_pos, 'mark_price', 0), 0)
                if _mp <= 0: continue
                _notional = _amt * _mp
                if _notional > _max_usd * 1.5:
                    _cd_key = f"oversize:{_pk}"
                    if time.time() - _oversize_cooldown.get(_cd_key, 0) < 30: continue
                    _oversize_cooldown[_cd_key] = time.time()
                    _excess_usd = _notional - _max_usd
                    _excess_qty = _excess_usd / _mp
                    _, _sym, _ps = parse_position_key(_pk)
                    _is_long = _ps == 'LONG'
                    _close_side = 'SELL' if _is_long else 'BUY'
                    logger.critical(f"🚨🚨🚨 [EMERGENCY_OVERSIZE] {_pk}: notional=${_notional:.2f} > max=${_max_usd:.2f} (150%). FORCE REDUCING excess ${_excess_usd:.2f} ({_excess_qty:.4f} qty)")
                    try:
                        await trade_manager.execute_now(_pk, _ak, _sym, _amt, _close_side, _ps, _excess_qty, _mp, f"EMERGENCY_OVERSIZE_{int(time.time())}", f"FORCE_REDUCE_OVERSIZE_{_notional:.0f}>${_max_usd:.0f}", False, 'REDUCE', is_hedge=False)
                    except Exception as _oe:
                        logger.error(f"[EMERGENCY_OVERSIZE] Failed to reduce {_pk}: {_oe}")
        open_position_keys = []
        high_gain_positions = []
        for account_key, positions_dict in trade_manager.positions_by_account.items():
            if account_key not in managed_accounts or account_key not in config.ACCOUNT_KEYS:
                continue
            for position_key, position in positions_dict.items():
                if position and position.positionAmt > 0:
                    mark_price_val = safe_fetch_float(position.mark_price, 0.0)
                    if (position.positionAmt * mark_price_val) > config.MIN_POSITION_SIZE:
                        if trade_manager.is_symbol_allowed(account_key, position.symbol, position_key):
                            if position_key not in open_position_keys:
                                open_position_keys.append(position_key)
                            gain = safe_fetch_float(position.gain, 0.0)
                            high_gain_on_price = gain > config.MIN_GAIN
                            high_gain_on_realized = position.realized_pnl > config.MIN_GAIN and gain > 0
                            
                            # MANDATORY AUGMENTATION BYPASS
                            # If gain is > 3.0%, we MUST evaluate for augmentation, ignoring static filters
                            is_huge_gain = gain > 3.0 or position.realized_pnl > 3.0
                            
                            if high_gain_on_price or high_gain_on_realized:
                                min_since_last_aug = (datetime.now(timezone.utc) - position.last_augmentation_time).total_seconds() / 60 if position.last_augmentation_time else 999
                                if min_since_last_aug > 5:
                                    trigger_reason = "gain>MIN_GAIN" if high_gain_on_price else "realized_pnl>MIN_GAIN"
                                    high_gain_positions.append(position_key)
                                    logger.info(f"[BIG_GAIN_ALERT] {position_key}: gain={position.gain:.2f}% reason={trigger_reason} but not augmented in {min_since_last_aug:.1f}min - forcing evaluation")
        if high_gain_positions:
            logger.warning(f"[FORCE_AUGMENT_DIRECT] Processing {len(high_gain_positions)} high-gain positions with DIRECT augmentation")
            for position_key in high_gain_positions:
                try:
                    account_key, symbol, position_side = parse_position_key(position_key)
                    position = trade_manager.positions_by_account.get(account_key, {}).get(position_key) or trade_manager.positions.get(position_key)
                    logger.warning(f"[FORCE_AUGMENT_DIRECT] {position_key}: gain={position.gain:.2f}% - DIRECT augmentation with fresh data")
                    normalized_symbol = symbol.strip().upper()
                    side = position_side
                    
                    # HUGE GAIN BYPASS: Skip leaderboard check if gain is substantial
                    bypass_filter = position.gain > 3.0 or position.realized_pnl > 3.0
                    
                    if not bypass_filter and not _check_leaderboard_allowed(trade_manager, normalized_symbol, side, account_key, position_key):
                        logger.debug(f"[{account_key}] process_all_symbols_for_account FILTERED: {side} symbol {normalized_symbol} not in leaderboard lists (FORBIDDEN)")
                        continue
                    await direct_high_gain_augmentation(position_key, order_queue, trade_manager)
                    logger.warning(f"[FORCE_AUGMENT_DIRECT] {position_key}: Completed direct augmentation")
                except Exception as e:
                    logger.error(f"[FORCE_AUGMENT_DIRECT] Error processing {position_key}: {e}", exc_info=True)
        if open_position_keys:
            logger.debug(f"[RISK_LOOP] Found {len(open_position_keys)} open positions to re-evaluate: {open_position_keys[:5]}...")
            grouped_keys = defaultdict(list)
            for key in open_position_keys:
                try:
                    account_key, _, _ = parse_position_key(key)
                    grouped_keys[account_key].append(key)
                except ValueError:
                    continue # Skip any malformed keys
            for account_key, keys_list in grouped_keys.items():
                logger.debug(f"[PROCESS_SYMBOLS] (periodic_tasks) Calling monitor_entries for {account_key} with {len(keys_list)} positions")
                allowed_batch = filter_monitor_keys(trade_manager, account_key, keys_list)
                if allowed_batch:
                    await monitor_entries(order_queue, trade_manager, account_key=account_key, position_keys=allowed_batch, event_type=None, is_priority_add=False, force=False)
        for account_key in managed_accounts:
            if account_key not in trade_manager.positions_by_account or not trade_manager.positions_by_account.get(account_key):
                await monitor_entries(order_queue, trade_manager, account_key=account_key, position_keys=None, event_type="periodic_tasks_no_positions", is_priority_add=False, force=False)

# ═══════════════════════════════════════════════════════════════════
# PERFORMANCE TRACKING + OUTLIER DETECTION + CAPITAL ALLOCATION
# Inline loops — write reports to data/reports/
# ═══════════════════════════════════════════════════════════════════

async def performance_report_loop(trade_manager: MultiAccountTradeManager):
    """Every 5 min: compute per-symbol rolling stats, write data/reports/performance_report.txt + .json."""
    await asyncio.sleep(30.0)
    report_dir = Path(config.BASE_PATH) / 'data' / 'reports'
    report_dir.mkdir(parents=True, exist_ok=True)
    while True:
        try:
            if not config.SYMBOL_PERF_ENABLED:
                await asyncio.sleep(300)
                continue
            from utils import _ensure_cache, refresh_cache
            stats = refresh_cache()
            if not stats:
                await asyncio.sleep(300)
                continue
            tiers = {'A': [], 'B': [], 'C': []}
            for sym, s in sorted(stats.items(), key=lambda x: x[1].get('total_pnl_pct', 0), reverse=True):
                tiers[s.get('tier', 'B')].append(s)
            now_str = datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M UTC')
            lines = [f"PERFORMANCE REPORT — {now_str}", f"{'=' * 80}", f"Total: {len(stats)} symbols | A={len(tiers['A'])} B={len(tiers['B'])} C={len(tiers['C'])}", f"Window: {config.SYMBOL_PERF_WINDOW_DAYS} days | Min trades: {config.SYMBOL_PERF_MIN_TRADES}", ""]
            open_symbols = set()
            for acct, pdict in trade_manager.positions_by_account.items():
                for pk, pos in pdict.items():
                    if pos and abs(getattr(pos, 'positionAmt', 0)) > 0:
                        sym = pk.split(':')[-1].rsplit('_', 1)[0] if ':' in pk else pk.rsplit('_', 1)[0]
                        open_symbols.add(sym)
            for tier_name in ('A', 'B', 'C'):
                items = tiers[tier_name]
                lines.append(f"--- TIER {tier_name} ({len(items)} symbols) ---")
                for s in items:
                    marker = " ** OPEN **" if s['symbol'] in open_symbols else ""
                    lines.append(f"  {s['symbol']:>15s}  WR={s['win_rate']:.0%}  avg={s['avg_gain_pct']:+.2f}%  total={s['total_pnl_pct']:+.1f}%  trades={s['trade_count']:3d}  mult={s['order_multiplier']:.2f}{marker}")
                lines.append("")
            total_pnl = sum(s['total_pnl_pct'] for s in stats.values())
            avg_wr = sum(s['win_rate'] for s in stats.values()) / max(1, len(stats))
            lines.extend(["SUMMARY:", f"  Total PnL (all symbols): {total_pnl:+.1f}%", f"  Avg win rate: {avg_wr:.0%}", f"  A-tier avg mult: {sum(s['order_multiplier'] for s in tiers['A']) / max(1, len(tiers['A'])):.2f}", f"  C-tier avg mult: {sum(s['order_multiplier'] for s in tiers['C']) / max(1, len(tiers['C'])):.2f}", ""])
            with open(report_dir / 'performance_report.txt', 'w') as f:
                f.write('\n'.join(lines))
            import json as _json
            with open(report_dir / 'performance_report.json', 'w') as f:
                _json.dump({'generated_at': now_str, 'stats': stats, 'tiers': {k: [s['symbol'] for s in v] for k, v in tiers.items()}, 'total_pnl_pct': round(total_pnl, 2), 'avg_win_rate': round(avg_wr, 4)}, f, indent=1)
            logger.info(f"[PERF_REPORT] Written: {len(stats)} symbols (A={len(tiers['A'])} B={len(tiers['B'])} C={len(tiers['C'])}) total_pnl={total_pnl:+.1f}%")
        except Exception as e:
            logger.error(f"[PERF_REPORT] Error: {e}", exc_info=True)
        await asyncio.sleep(config.SYMBOL_PERF_REFRESH_SECONDS)

_spike_fade_prices = {}  # {symbol: deque([(ts, price), ...], maxlen=20)} — rolling 60min window
_spike_fade_cooldowns = {}
_spike_fade_count = 0
_spike_fade_results = []  # list of (ts, symbol, pnl_pct) for completed trades
_spike_fade_auto_killed = False
_sf_exhaust_watch = {}  # {pk: True} — positions in exhaustion watch mode

async def _spike_fade_1m_exit_monitor(trade_manager):
    """BC_162 EXIT: high gain + high K → 3m candle structure (already in indicator snapshot) + mark price as live bar.
    When current price fails to break prev 3m high (pump) or prev 3m low (dump) → EXIT.
    Uses EXISTING data from ez_market_data pipeline — no synthetic candles, no extra CPU."""
    global _sf_exhaust_watch
    await asyncio.sleep(45.0)
    logger.info("[SF_1M_EXIT] Started — 3m structure exhaustion exit for spike fade (uses existing indicator data)")
    while True:
        try:
            snap = trade_manager.service.indicators_snapshot if trade_manager.service else {}
            price_cache = getattr(trade_manager.service, 'price_cache', {}) if trade_manager.service else {}
            for pk, pos in list(trade_manager.positions.items()):
                if 'SPIKE_FADE' not in str(getattr(pos, 'augment_reason', '') or getattr(pos, 'last_signal', '') or ''):
                    continue
                amt = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0), 0))
                if amt == 0:
                    _sf_exhaust_watch.pop(pk, None); continue
                gain = safe_fetch_float(getattr(pos, 'gain', 0), 0)
                symbol = pk.split(':')[-1].replace('_LONG', '').replace('_SHORT', '')
                is_long = pk.endswith('_LONG')
                i = snap.get(symbol, {})
                k_3m = safe_fetch_float(i.get('stoch_k_3m', 50), 50)
                if gain > 0.3 and ((is_long and k_3m > 75) or (not is_long and k_3m < 25)):
                    if pk not in _sf_exhaust_watch:
                        _sf_exhaust_watch[pk] = True
                        logger.info(f"[SF_1M_EXIT] {pk}: WATCHING — gain={gain:.2f}% k3m={k_3m:.0f}")
                if pk not in _sf_exhaust_watch:
                    continue
                px_data = price_cache.get(symbol, {})
                current_price = float(px_data.get('price', 0) or 0) if isinstance(px_data, dict) else 0
                if current_price <= 0:
                    continue
                high_3m = safe_fetch_float(i.get('high_3m', 0), 0)
                low_3m = safe_fetch_float(i.get('low_3m', 0), 0)
                high_3m_prev = safe_fetch_float(i.get('high_3m_prev', 0), 0)
                low_3m_prev = safe_fetch_float(i.get('low_3m_prev', 0), 0)
                if is_long and high_3m_prev > 0 and high_3m > 0 and gain > 0:
                    lower_high = high_3m < high_3m_prev
                    failed_break = current_price < high_3m_prev
                    if lower_high and failed_break:
                        reason = f"SF_EXHAUST_LONG_LH(h3={high_3m:.6f}<prev={high_3m_prev:.6f}_px={current_price:.6f})_g={gain:.2f}%_k={k_3m:.0f}"
                        logger.critical(f"[SF_1M_EXIT] {pk}: {reason} → CLOSE")
                        await queue_trade_action(trade_manager.order_queue, trade_manager, pk, "QUICK_CLOSE", reason, 0.95)
                        _sf_exhaust_watch.pop(pk, None)
                elif not is_long and low_3m_prev > 0 and low_3m > 0 and gain > 0:
                    higher_low = low_3m > low_3m_prev
                    failed_break = current_price > low_3m_prev
                    if higher_low and failed_break:
                        reason = f"SF_EXHAUST_SHORT_HL(l3={low_3m:.6f}>prev={low_3m_prev:.6f}_px={current_price:.6f})_g={gain:.2f}%_k={k_3m:.0f}"
                        logger.critical(f"[SF_1M_EXIT] {pk}: {reason} → CLOSE")
                        await queue_trade_action(trade_manager.order_queue, trade_manager, pk, "QUICK_CLOSE", reason, 0.95)
                        _sf_exhaust_watch.pop(pk, None)
        except asyncio.CancelledError:
            break
        except Exception as exc:
            logger.error(f"[SF_1M_EXIT] Error: {exc}", exc_info=True)
        await asyncio.sleep(10.0)
async def _spike_fade_result_tracker(trade_manager):
    """Monitor SPIKE_FADE positions — when they close, record win/loss. Auto-kill if 3/5 lose."""
    global _spike_fade_results, _spike_fade_auto_killed
    await asyncio.sleep(60.0)
    _known_fade_positions = {}  # {pk: entry_price}
    logger.info("[SPIKE_FADE_TRACKER] Started — monitoring spike fade trade outcomes")
    while True:
        try:
            for pk, pos in list(trade_manager.positions.items()):
                if 'SPIKE_FADE' not in str(getattr(pos, 'augment_reason', '') or getattr(pos, 'last_signal', '')):
                    continue
                amt = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0), 0))
                entry = safe_fetch_float(getattr(pos, 'entry_price', 0), 0)
                if amt > 0 and entry > 0:
                    if pk not in _known_fade_positions:
                        _known_fade_positions[pk] = entry
                        logger.info(f"[SPIKE_FADE_TRACKER] Tracking new position: {pk} entry={entry:.6f}")
            closed = []
            for pk, entry_px in list(_known_fade_positions.items()):
                pos = trade_manager.positions.get(pk)
                amt = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0), 0)) if pos else 0
                if amt == 0:
                    mark = safe_fetch_float(getattr(pos, 'mark_price', 0), 0) if pos else 0
                    if mark <= 0:
                        continue
                    is_long = pk.endswith('_LONG')
                    pnl_pct = ((mark - entry_px) / entry_px * 100) if is_long else ((entry_px - mark) / entry_px * 100)
                    _spike_fade_results.append((time.time(), pk, pnl_pct))
                    closed.append(pk)
                    win = "WIN" if pnl_pct > 0 else "LOSS"
                    logger.critical(f"[SPIKE_FADE_TRACKER] {win}: {pk} pnl={pnl_pct:+.2f}% (entry={entry_px:.6f} exit~={mark:.6f})")
            for pk in closed:
                _known_fade_positions.pop(pk, None)
            recent = _spike_fade_results[-5:] if len(_spike_fade_results) >= 5 else _spike_fade_results
            if len(recent) >= 5:
                losses = sum(1 for _, _, pnl in recent if pnl < 0)
                if losses >= 3 and not _spike_fade_auto_killed:
                    _spike_fade_auto_killed = True
                    config.CRYPTO_SPIKE_FADE_ENABLED = False
                    total_pnl = sum(pnl for _, _, pnl in _spike_fade_results)
                    logger.critical(f"🛑 [SPIKE_FADE_AUTO_KILL] DISABLED — {losses}/5 recent trades lost. Total results: {len(_spike_fade_results)} trades, net={total_pnl:+.2f}%. Recent: {[(pk.split(':')[-1], f'{pnl:+.1f}%') for _, pk, pnl in recent]}")
        except asyncio.CancelledError:
            break
        except Exception as exc:
            logger.error(f"[SPIKE_FADE_TRACKER] Error: {exc}")
        await asyncio.sleep(30.0)

async def crypto_fh_momentum_loop(trade_manager: MultiAccountTradeManager):
    """MT3: Crypto First-Hour Momentum — US market open drives crypto direction.
    At 14:00-14:30 UTC (10:00-10:30 AM ET), check crypto move from 13:30 UTC.
    If move > 0.5%, enter WITH direction. DC retest scoring for confirmation.
    Validated on stocks: Sharpe 1.54, 25/25 configs profitable."""
    await asyncio.sleep(60.0)
    logger.info("[CRYPTO_FH_MOM] Started — evaluates 14:00-14:30 UTC daily (US market manipulation window)")
    _ran_today = ""
    while True:
        try:
            if not getattr(config, 'CRYPTO_FH_MOMENTUM_ENABLED', False):
                await asyncio.sleep(60); continue
            now_utc = datetime.now(timezone.utc)
            tod_min = now_utc.hour * 60 + now_utc.minute
            if tod_min < 840 or tod_min > 870:
                await asyncio.sleep(30); continue
            today_key = now_utc.strftime('%Y%m%d')
            if _ran_today == today_key:
                await asyncio.sleep(60); continue
            _ran_today = today_key
            min_move = getattr(config, 'CRYPTO_FH_MOMENTUM_MIN_MOVE_PCT', 0.5)
            size_mult = getattr(config, 'CRYPTO_FH_MOMENTUM_POSITION_SIZE_MULT', 1.0)
            max_pos = getattr(config, 'CRYPTO_FH_MOMENTUM_MAX_POSITIONS', 4)
            dc_confirm = getattr(config, 'CRYPTO_FH_MOMENTUM_DC_CONFIRM', True)
            dc_max_long = getattr(config, 'CRYPTO_FH_MOMENTUM_DC_MAX_LONG', 0.5)
            snap = trade_manager.service.indicators_snapshot if trade_manager.service else {}
            price_cache = getattr(trade_manager.service, 'price_cache', {}) if trade_manager.service else {}
            entered = 0
            for symbol in list(trade_manager.min_qty.keys()):
                if entered >= max_pos:
                    break
                ind = snap.get(symbol, {})
                if not ind:
                    continue
                px_data = price_cache.get(symbol, {})
                current_price = float(px_data.get('price', 0) or 0) if isinstance(px_data, dict) else 0
                if current_price <= 0:
                    current_price = float(ind.get('mark_price', 0) or ind.get('current_price', 0) or 0)
                if current_price <= 0:
                    continue
                open_d = float(ind.get('open_D', 0) or 0)
                if open_d <= 0:
                    open_1h = float(ind.get('open_1h', 0) or 0)
                    if open_1h > 0:
                        open_d = open_1h
                    else:
                        continue
                move_pct = (current_price - open_d) / open_d * 100.0
                if abs(move_pct) < min_move:
                    continue
                dc_pos = float(ind.get('dc_position_D', ind.get('dc_position_4h', 0.5)) or 0.5)
                if dc_confirm:
                    if move_pct > 0 and dc_pos > dc_max_long:
                        continue
                    if move_pct < 0 and dc_pos < (1.0 - dc_max_long):
                        continue
                dc_hi = float(ind.get('dc_high_4h', 0) or 0)
                dc_hi_ant = float(ind.get('dc_high_4h_ant', ind.get('dc_high_4h_prev', 0)) or 0)
                dc_lo = float(ind.get('dc_low_4h', 0) or 0)
                dc_lo_ant = float(ind.get('dc_low_4h_ant', ind.get('dc_low_4h_prev', 0)) or 0)
                retest_bonus = 0
                if move_pct > 0 and dc_hi > 0 and dc_hi_ant > 0 and dc_hi > dc_hi_ant:
                    dist = (current_price - dc_hi_ant) / dc_hi_ant * 100
                    if 0 < dist < 1.5:
                        retest_bonus = 1
                elif move_pct < 0 and dc_lo > 0 and dc_lo_ant > 0 and dc_lo < dc_lo_ant:
                    dist = (dc_lo_ant - current_price) / dc_lo_ant * 100
                    if 0 < dist < 1.5:
                        retest_bonus = 1
                qty_usd = config.START_POSITION_SIZE * size_mult * (1.5 if retest_bonus else 1.0)
                for account_key in trade_manager.active_accounts:
                    positions = trade_manager.get_positions_for_account(account_key)
                    if move_pct > 0:
                        pk = f"{symbol}_LONG"
                        if pk in positions and abs(float(getattr(positions[pk], 'positionAmt', 0))) > 0:
                            continue
                        side = "BUY"
                        reason = f"FH_MOM_CRYPTO_L move={move_pct:+.2f}%_dc={dc_pos:.2f}_rt={retest_bonus}"
                    else:
                        pk = f"{symbol}_SHORT"
                        if pk in positions and abs(float(getattr(positions[pk], 'positionAmt', 0))) > 0:
                            continue
                        side = "SELL"
                        reason = f"FH_MOM_CRYPTO_S move={move_pct:+.2f}%_dc={dc_pos:.2f}_rt={retest_bonus}"
                    try:
                        success = await trade_manager.execute_now(account_key=account_key, symbol=symbol, side=side, quantity_usd=qty_usd, reason=reason, is_hedge=False)
                        if success:
                            entered += 1
                            logger.info(f"[CRYPTO_FH_MOM] {reason} {symbol} @ {current_price:.4f} qty_usd=${qty_usd:.0f}")
                    except Exception as e:
                        logger.debug(f"[CRYPTO_FH_MOM] Execute failed {symbol}: {e}")
            logger.info(f"[CRYPTO_FH_MOM] Scan complete: {entered} entries (move>{min_move}%, {len(list(trade_manager.min_qty.keys()))} symbols scanned)")
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"[CRYPTO_FH_MOM] Error: {e}", exc_info=True)
        await asyncio.sleep(30.0)


async def crypto_spike_fade_loop(trade_manager: MultiAccountTradeManager):
    """BC_162: Crypto contrarian spike fade — SHORT P&D pumps, LONG panic dumps.
    Crypto has far more pump-and-dump on low-cap tickers than stocks.
    Backtest basis: stock version +480%, 67% WR, 4.69 W/L on 24 symbols.
    Entry: >3% move in ~30min + K exhausted + 2/3 WT confirms fade.
    STRICT_NO_LOSS on spike fade positions: augment both sides, NEVER sell at loss.
    Exit: standard WT 2/3 exit (same as all other positions)."""
    global _spike_fade_prices, _spike_fade_cooldowns, _spike_fade_count
    await asyncio.sleep(30.0)
    from collections import deque
    logger.info("[CRYPTO_SPIKE_FADE] Started — scanning every 30s for P&D spikes across all symbols")
    while True:
        try:
            if not getattr(config, 'CRYPTO_SPIKE_FADE_ENABLED', True):
                await asyncio.sleep(60); continue
            thresh = getattr(config, 'CRYPTO_SPIKE_FADE_THRESHOLD_PCT', 3.0)
            k_exh = getattr(config, 'CRYPTO_SPIKE_FADE_K_EXHAUSTION', 75.0)
            pos_size = config.START_POSITION_SIZE
            max_pos = getattr(config, 'CRYPTO_SPIKE_FADE_MAX_POSITIONS', 6)
            cd_seconds = getattr(config, 'CRYPTO_SPIKE_FADE_COOLDOWN_SEC', 900.0)
            now = time.time()
            snap = trade_manager.service.indicators_snapshot if trade_manager.service else {}
            price_cache = getattr(trade_manager.service, 'price_cache', {}) if trade_manager.service else {}
            symbols_scanned = 0; spikes_found = 0
            for symbol in list(trade_manager.min_qty.keys()):
                px_data = price_cache.get(symbol, {})
                current_price = float(px_data.get('price', 0) or 0) if isinstance(px_data, dict) else 0
                if current_price <= 0:
                    mark = snap.get(symbol, {})
                    current_price = float(mark.get('mark_price', 0) or mark.get('current_price', 0) or 0)
                if current_price <= 0:
                    continue
                symbols_scanned += 1
                if symbol not in _spike_fade_prices:
                    _spike_fade_prices[symbol] = deque(maxlen=20)
                _spike_fade_prices[symbol].append((now, current_price))
                buf = _spike_fade_prices[symbol]
                if len(buf) < 3:
                    continue
                target_age = 1800.0
                oldest_price = None
                for ts, px in buf:
                    if now - ts >= target_age * 0.5:
                        oldest_price = px; break
                if not oldest_price:
                    oldest_price = buf[0][1]
                    age = now - buf[0][0]
                    if age < 300:
                        continue
                ret_pct = (current_price - oldest_price) / oldest_price * 100
                if abs(ret_pct) < thresh:
                    continue
                spikes_found += 1
                if now - _spike_fade_cooldowns.get(symbol, 0) < cd_seconds:
                    continue
                i = snap.get(symbol, {})
                high_3m = safe_fetch_float(i.get('high_3m', 0), 0)
                low_3m = safe_fetch_float(i.get('low_3m', 0), 0)
                high_3m_prev = safe_fetch_float(i.get('high_3m_prev', 0), 0)
                low_3m_prev = safe_fetch_float(i.get('low_3m_prev', 0), 0)
                pump_fading = high_3m > 0 and high_3m_prev > 0 and high_3m < high_3m_prev and low_3m > 0 and low_3m_prev > 0 and low_3m < low_3m_prev
                price_below_prev_high = current_price < high_3m_prev if high_3m_prev > 0 else False
                dump_reversing = low_3m > 0 and low_3m_prev > 0 and low_3m > low_3m_prev and high_3m > 0 and high_3m_prev > 0 and high_3m > high_3m_prev
                price_above_prev_low = current_price > low_3m_prev if low_3m_prev > 0 else False
                for account_key in list(trade_manager.accounts.keys()):
                    active_fades = sum(1 for pk in trade_manager.positions if pk.startswith(f"{account_key}:") and 'SPIKE_FADE' in str(getattr(trade_manager.positions[pk], 'augment_reason', '') or getattr(trade_manager.positions[pk], 'last_signal', '')))
                    if active_fades >= max_pos:
                        continue
                    if ret_pct > thresh and (pump_fading or price_below_prev_high):
                        pk = f"{account_key}:{symbol}_SHORT"
                        pos = trade_manager.positions.get(pk)
                        pos_amt = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0), 0)) if pos else 0
                        if pos_amt > 0 and pos_amt * current_price >= pos_size * 2:
                            continue
                        qty = max(pos_size / current_price, trade_manager.min_qty.get(symbol, 0.001) * 1.2)
                        action = "AUGMENT" if pos_amt > 0 else "OPEN"
                        _sig = "3m_LH_LL" if pump_fading else "px<prevHi"
                        reason = f"CRYPTO_SPIKE_FADE_SHORT_ret={ret_pct:+.1f}%_{_sig}_age={now - buf[0][0]:.0f}s"
                        logger.warning(f"[CRYPTO_SPIKE_FADE] {account_key}:{symbol}: {reason} → {action} SHORT qty={qty:.4f}")
                        await queue_trade_action(trade_manager.order_queue, trade_manager, pk, action, reason, 85.0, override_qty=qty)
                        _spike_fade_cooldowns[symbol] = now; _spike_fade_count += 1
                    elif ret_pct < -thresh and (dump_reversing or price_above_prev_low):
                        pk = f"{account_key}:{symbol}_LONG"
                        pos = trade_manager.positions.get(pk)
                        pos_amt = abs(safe_fetch_float(getattr(pos, 'positionAmt', 0), 0)) if pos else 0
                        if pos_amt > 0 and pos_amt * current_price >= pos_size * 2:
                            continue
                        qty = max(pos_size / current_price, trade_manager.min_qty.get(symbol, 0.001) * 1.2)
                        action = "AUGMENT" if pos_amt > 0 else "OPEN"
                        _sig = "3m_HL_HH" if dump_reversing else "px>prevLo"
                        reason = f"CRYPTO_SPIKE_FADE_LONG_ret={ret_pct:+.1f}%_{_sig}_age={now - buf[0][0]:.0f}s"
                        logger.warning(f"[CRYPTO_SPIKE_FADE] {account_key}:{symbol}: {reason} → {action} LONG qty={qty:.4f}")
                        await queue_trade_action(trade_manager.order_queue, trade_manager, pk, action, reason, 85.0, override_qty=qty)
                        _spike_fade_cooldowns[symbol] = now; _spike_fade_count += 1
            if _spike_fade_count % 50 == 0 or spikes_found > 0:
                logger.info(f"[CRYPTO_SPIKE_FADE] Scanned {symbols_scanned} symbols, {spikes_found} spikes >{thresh}%, total_trades={_spike_fade_count}")
        except asyncio.CancelledError:
            break
        except Exception as exc:
            logger.error(f"[CRYPTO_SPIKE_FADE] Error: {exc}", exc_info=True)
        await asyncio.sleep(30.0)

async def outlier_scan_loop(trade_manager: MultiAccountTradeManager):
    """Every 60s: scan all open positions for stuck/runaway/stale anomalies, write data/reports/outlier_report.txt + .json."""
    await asyncio.sleep(45.0)
    report_dir = Path(config.BASE_PATH) / 'data' / 'reports'
    report_dir.mkdir(parents=True, exist_ok=True)
    alerts_file = Path(config.BASE_PATH) / 'data' / 'outlier_alerts.json'
    while True:
        try:
            if not config.OUTLIER_DETECTOR_ENABLED:
                await asyncio.sleep(60)
                continue
            now = datetime.now(timezone.utc)
            all_alerts = []
            total_positions = 0
            for account_key, positions_dict in trade_manager.positions_by_account.items():
                if account_key not in config.ACCOUNT_KEYS:
                    continue
                for pk, pos in positions_dict.items():
                    if not pos or abs(getattr(pos, 'positionAmt', 0)) == 0:
                        continue
                    total_positions += 1
                    entry_price = safe_fetch_float(getattr(pos, 'entry_price', 0) or getattr(pos, 'entryPrice', 0), 0.0)
                    mark_price = safe_fetch_float(getattr(pos, 'mark_price', 0) or getattr(pos, 'markPrice', 0), 0.0)
                    if entry_price <= 0 or mark_price <= 0:
                        continue
                    sym = pk.split(':')[-1].rsplit('_', 1)[0] if ':' in pk else pk.rsplit('_', 1)[0]
                    is_long = pk.endswith('_LONG')
                    indicators = trade_manager.indicators_cache.get(sym, {}) if hasattr(trade_manager, 'indicators_cache') else {}
                    atr = safe_fetch_float(indicators.get('atr_15m') or indicators.get('atr_1h', 0), 0.0)
                    if atr <= 0:
                        dc_h = safe_fetch_float(indicators.get('dc_high_15m', 0), 0.0)
                        dc_l = safe_fetch_float(indicators.get('dc_low_15m', 0), 0.0)
                        if dc_h > 0 and dc_l > 0:
                            atr = (dc_h - dc_l) * 0.5
                    atr_pct = (atr / mark_price * 100) if atr > 0 and mark_price > 0 else 0
                    # STUCK: no significant movement for >N hours
                    if atr_pct > 0:
                        price_move_pct = abs(mark_price - entry_price) / entry_price * 100
                        last_aug_time = getattr(pos, 'last_augmentation_time', None)
                        opened_at = last_aug_time or getattr(pos, 'updateTime', None) or getattr(pos, 'opened_at', None)
                        age_hours = 0
                        if opened_at:
                            try:
                                if isinstance(opened_at, datetime):
                                    age_hours = (now - opened_at).total_seconds() / 3600
                                elif isinstance(opened_at, (int, float)):
                                    ts_val = opened_at / 1000 if opened_at > 1e12 else opened_at
                                    age_hours = (now - datetime.fromtimestamp(ts_val, tz=timezone.utc)).total_seconds() / 3600
                                else:
                                    age_hours = (now - datetime.fromisoformat(str(opened_at).replace('Z', '+00:00'))).total_seconds() / 3600
                            except Exception:
                                pass
                        if age_hours >= config.OUTLIER_STUCK_HOURS and price_move_pct < atr_pct * config.OUTLIER_STUCK_ATR_FACTOR:
                            all_alerts.append({'position_key': pk, 'symbol': sym, 'type': 'STUCK', 'severity': 'WARNING', 'entry': entry_price, 'mark': mark_price, 'move_pct': round(price_move_pct, 3), 'atr_pct': round(atr_pct, 3), 'age_h': round(age_hours, 1)})
                    # RUNAWAY_LOSS: unrealized loss > N x ATR
                    if atr_pct > 0:
                        loss_pct = ((entry_price - mark_price) / entry_price * 100) if is_long else ((mark_price - entry_price) / entry_price * 100)
                        if loss_pct > 0 and loss_pct > atr_pct * config.OUTLIER_RUNAWAY_ATR_FACTOR:
                            amt = abs(getattr(pos, 'positionAmt', 0))
                            loss_usd = loss_pct / 100 * amt * mark_price
                            severity = 'CRITICAL' if loss_pct > atr_pct * 3.0 else 'WARNING'
                            all_alerts.append({'position_key': pk, 'symbol': sym, 'type': 'RUNAWAY_LOSS', 'severity': severity, 'loss_pct': round(loss_pct, 3), 'atr_pct': round(atr_pct, 3), 'loss_x_atr': round(loss_pct / atr_pct, 1), 'est_loss_usd': round(loss_usd, 2)})
                    # STALE_ACTIVITY: no action for >N hours
                    last_activity = getattr(pos, 'last_augmentation_time', None) or getattr(pos, 'last_reduction_time', None)
                    if last_activity:
                        try:
                            if isinstance(last_activity, datetime):
                                idle_hours = (now - last_activity).total_seconds() / 3600
                            else:
                                idle_hours = (now - datetime.fromisoformat(str(last_activity).replace('Z', '+00:00'))).total_seconds() / 3600
                        except Exception:
                            idle_hours = 0
                        if idle_hours >= config.OUTLIER_STALE_HOURS:
                            all_alerts.append({'position_key': pk, 'symbol': sym, 'type': 'STALE_ACTIVITY', 'severity': 'WARNING', 'idle_h': round(idle_hours, 1)})
            # Write outlier_alerts.json for ez_symbol_performance to read
            import json as _json
            alert_data = {'active': all_alerts, 'last_scan': now.isoformat(), 'summary': {'stuck': sum(1 for a in all_alerts if a['type'] == 'STUCK'), 'runaway_loss': sum(1 for a in all_alerts if a['type'] == 'RUNAWAY_LOSS'), 'stale_activity': sum(1 for a in all_alerts if a['type'] == 'STALE_ACTIVITY'), 'total': len(all_alerts), 'critical': sum(1 for a in all_alerts if a['severity'] == 'CRITICAL'), 'positions_scanned': total_positions}}
            try:
                with open(alerts_file, 'w') as f:
                    _json.dump(alert_data, f, indent=1)
            except Exception:
                pass
            # Write text report
            now_str = now.strftime('%Y-%m-%d %H:%M UTC')
            lines = [f"OUTLIER REPORT — {now_str}", f"{'=' * 80}", f"Scanned: {total_positions} open positions | Alerts: {len(all_alerts)}", ""]
            for atype in ('RUNAWAY_LOSS', 'STUCK', 'STALE_ACTIVITY'):
                typed = [a for a in all_alerts if a['type'] == atype]
                if typed:
                    lines.append(f"--- {atype} ({len(typed)}) ---")
                    for a in typed:
                        sev = 'CRIT' if a['severity'] == 'CRITICAL' else 'WARN'
                        detail_parts = [f"{k}={v}" for k, v in a.items() if k not in ('position_key', 'symbol', 'type', 'severity')]
                        lines.append(f"  [{sev}] {a['position_key']:>35s}  {' '.join(detail_parts)}")
                    lines.append("")
            if not all_alerts:
                lines.append("  No outliers detected.")
            try:
                with open(report_dir / 'outlier_report.txt', 'w') as f:
                    f.write('\n'.join(lines))
                with open(report_dir / 'outlier_report.json', 'w') as f:
                    _json.dump(alert_data, f, indent=1)
            except Exception:
                pass
            if all_alerts:
                critical = sum(1 for a in all_alerts if a['severity'] == 'CRITICAL')
                logger.info(f"[OUTLIER_SCAN] {len(all_alerts)} alerts ({critical} critical) across {total_positions} positions")
        except Exception as e:
            logger.error(f"[OUTLIER_SCAN] Error: {e}", exc_info=True)
        await asyncio.sleep(config.OUTLIER_SCAN_INTERVAL)

async def capital_reallocation_loop(trade_manager: MultiAccountTradeManager):
    """Every 5 min: analyze capital distribution across positions, write data/reports/capital_report.txt.
    Identifies mediocre positions (B/C tier, small gain, no momentum) vs winners (A tier, running) and reports reallocation suggestions."""
    await asyncio.sleep(60.0)
    report_dir = Path(config.BASE_PATH) / 'data' / 'reports'
    report_dir.mkdir(parents=True, exist_ok=True)
    while True:
        try:
            if not config.SYMBOL_PERF_ENABLED:
                await asyncio.sleep(300)
                continue
            from utils import get_performance_multiplier, get_symbol_tier
            now = datetime.now(timezone.utc)
            now_str = now.strftime('%Y-%m-%d %H:%M UTC')
            positions_data = []
            total_capital = 0.0
            for account_key, positions_dict in trade_manager.positions_by_account.items():
                if account_key not in config.ACCOUNT_KEYS:
                    continue
                for pk, pos in positions_dict.items():
                    if not pos:
                        continue
                    amt = abs(getattr(pos, 'positionAmt', 0))
                    if amt == 0:
                        continue
                    mark = safe_fetch_float(getattr(pos, 'mark_price', 0) or getattr(pos, 'markPrice', 0), 0.0)
                    if mark <= 0:
                        continue
                    value_usd = amt * mark
                    gain = safe_fetch_float(getattr(pos, 'gain', 0), 0.0)
                    sym = pk.split(':')[-1].rsplit('_', 1)[0] if ':' in pk else pk.rsplit('_', 1)[0]
                    tier = get_symbol_tier(sym, 'B')
                    perf_mult = get_performance_multiplier(sym, 1.0)
                    total_capital += value_usd
                    positions_data.append({'pk': pk, 'symbol': sym, 'account': account_key, 'value_usd': round(value_usd, 2), 'gain_pct': round(gain, 3), 'tier': tier, 'perf_mult': round(perf_mult, 2), 'amt': amt, 'mark': mark})
            if not positions_data:
                await asyncio.sleep(300)
                continue
            positions_data.sort(key=lambda p: p['value_usd'], reverse=True)
            tier_capital = {'A': 0.0, 'B': 0.0, 'C': 0.0}
            tier_count = {'A': 0, 'B': 0, 'C': 0}
            winners = []
            losers = []
            mediocre = []
            for p in positions_data:
                tier_capital[p['tier']] += p['value_usd']
                tier_count[p['tier']] += 1
                if p['tier'] == 'A' and p['gain_pct'] > 0.1:
                    winners.append(p)
                elif p['tier'] == 'C' or (p['tier'] == 'B' and p['gain_pct'] < -0.5):
                    losers.append(p)
                elif abs(p['gain_pct']) < 0.3 and p['perf_mult'] <= 1.0:
                    mediocre.append(p)
            winners.sort(key=lambda p: p['gain_pct'], reverse=True)
            losers.sort(key=lambda p: p['gain_pct'])
            mediocre.sort(key=lambda p: p['value_usd'], reverse=True)
            lines = [f"CAPITAL ALLOCATION REPORT — {now_str}", f"{'=' * 80}", f"Total capital deployed: ${total_capital:,.2f} across {len(positions_data)} positions", ""]
            lines.append("TIER DISTRIBUTION:")
            for t in ('A', 'B', 'C'):
                pct = tier_capital[t] / total_capital * 100 if total_capital > 0 else 0
                lines.append(f"  Tier {t}: ${tier_capital[t]:>10,.2f} ({pct:5.1f}%) — {tier_count[t]} positions")
            lines.append("")
            ideal_a = 50
            actual_a = tier_capital['A'] / total_capital * 100 if total_capital > 0 else 0
            if actual_a < ideal_a - 10:
                lines.append(f"  ** A-tier UNDERWEIGHT: {actual_a:.0f}% vs target {ideal_a}% — consider augmenting winners **")
            actual_c = tier_capital['C'] / total_capital * 100 if total_capital > 0 else 0
            if actual_c > 20:
                lines.append(f"  ** C-tier OVERWEIGHT: {actual_c:.0f}% vs target <20% — reduce poor performers **")
            lines.append("")
            lines.append(f"WINNERS — augment these (A-tier, in gain) [{len(winners)}]:")
            for p in winners[:15]:
                lines.append(f"  {p['pk']:>35s}  ${p['value_usd']:>8,.2f}  gain={p['gain_pct']:+.2f}%  mult={p['perf_mult']:.2f}")
            if not winners:
                lines.append("  (none)")
            lines.append("")
            lines.append(f"LOSERS — reduce allocation (C-tier or losing) [{len(losers)}]:")
            for p in losers[:15]:
                lines.append(f"  {p['pk']:>35s}  ${p['value_usd']:>8,.2f}  gain={p['gain_pct']:+.2f}%  tier={p['tier']}  mult={p['perf_mult']:.2f}")
            if not losers:
                lines.append("  (none)")
            lines.append("")
            lines.append(f"MEDIOCRE — capital sitting idle [{len(mediocre)}]:")
            for p in mediocre[:15]:
                lines.append(f"  {p['pk']:>35s}  ${p['value_usd']:>8,.2f}  gain={p['gain_pct']:+.2f}%  tier={p['tier']}")
            if not mediocre:
                lines.append("  (none)")
            lines.append("")
            try:
                with open(report_dir / 'capital_report.txt', 'w') as f:
                    f.write('\n'.join(lines))
                import json as _json
                with open(report_dir / 'capital_report.json', 'w') as f:
                    _json.dump({'generated_at': now_str, 'total_capital_usd': round(total_capital, 2), 'tier_capital': {k: round(v, 2) for k, v in tier_capital.items()}, 'tier_count': tier_count, 'winners': [p['pk'] for p in winners[:20]], 'losers': [p['pk'] for p in losers[:20]], 'mediocre': [p['pk'] for p in mediocre[:20]], 'positions': positions_data}, f, indent=1)
            except Exception:
                pass
            logger.info(f"[CAPITAL_REPORT] ${total_capital:,.0f} deployed | A=${tier_capital['A']:,.0f}({tier_count['A']}) B=${tier_capital['B']:,.0f}({tier_count['B']}) C=${tier_capital['C']:,.0f}({tier_count['C']}) | {len(winners)}W {len(losers)}L {len(mediocre)}M")
        except Exception as e:
            logger.error(f"[CAPITAL_REPORT] Error: {e}", exc_info=True)
        await asyncio.sleep(config.SYMBOL_PERF_REFRESH_SECONDS)

async def monitor_hedges_continuously(trade_manager: MultiAccountTradeManager):
    await asyncio.sleep(15.0)
    while True:
        try:
            await asyncio.sleep(5.0)
            if not hasattr(trade_manager, 'hedge_engine') or not trade_manager.hedge_engine:
                continue
            accounts_to_process = list(trade_manager.accounts.keys())
            for account_key in accounts_to_process:
                if hasattr(trade_manager, '_allowed_accounts') and account_key not in trade_manager._allowed_accounts:
                    continue
                try:
                    actions = await trade_manager.hedge_engine.monitor_and_manage_hedges(account_key)
                    if actions:
                        for action in actions:
                            logger.info(f"[HedgeMonitor] {account_key}: Executed {action.get('action')} on {action.get('key')}")
                except Exception as account_err:
                    logger.error(f"[HedgeMonitor] Error processing account {account_key}: {account_err}")
                    continue
        except asyncio.CancelledError:
            break
        except Exception as e:
            logger.error(f"[HedgeMonitor] Global loop error: {e}", exc_info=True)
            await asyncio.sleep(5.0)

async def symbol_monitoring_watchdog(trade_manager: MultiAccountTradeManager, account_keys: List[str]):
    """Guarantees ALL tradeable position_keys are monitored. Open positions = priority. No symbol ever skipped. No API calls — memory only."""
    await asyncio.sleep(10)
    if not hasattr(trade_manager, 'last_symbol_monitored'):
        trade_manager.last_symbol_monitored = {}
    if not hasattr(trade_manager, 'last_monitored_positions'):
        trade_manager.last_monitored_positions = {}
    allowed_accounts = getattr(trade_manager, '_allowed_accounts', frozenset(account_keys))
    account_keys = [ak for ak in account_keys if ak in allowed_accounts]
    if not account_keys: return
    while True:
        try:
            now_ts = time.time(); now_dt = datetime.now(timezone.utc)
            all_symbols = set()
            account_symbol_map = {'ang': getattr(trade_manager, 'symbols_ang_long', set()) | getattr(trade_manager, 'symbols_ang_short', set()), 'inf': getattr(trade_manager, 'symbols_inf_long', set()) | getattr(trade_manager, 'symbols_inf_short', set()), 'men': getattr(trade_manager, 'symbols_men', set()), 'flz': getattr(trade_manager, 'symbols_flz', set()), 'fin': getattr(trade_manager, 'symbols_fin', set())}
            for account_key in account_keys:
                if account_key not in allowed_accounts: continue
                sym_set = account_symbol_map.get(account_key, set())
                for symbol in sym_set:
                    if trade_manager.is_symbol_allowed(account_key, symbol):
                        if getattr(trade_manager.config, 'LEADERBOARD_FILTER', True) and not _check_leaderboard_allowed(trade_manager, symbol, "LONG", account_key) and not _check_leaderboard_allowed(trade_manager, symbol, "SHORT", account_key):
                            continue
                        all_symbols.add(symbol)
            tradeable_position_keys_stale = []
            last_monitored = getattr(trade_manager, 'last_monitored_positions', {})
            for account_key in account_keys:
                for position_key, position in trade_manager.get_positions_by_account(account_key).items():
                    if not position: continue
                    try:
                        ak, symbol, position_side = parse_position_key(position_key)
                        if ak != account_key: continue
                        if not trade_manager.is_symbol_allowed(account_key, symbol, position_key): continue
                        if not trade_manager.allows_side(account_key, position_side, symbol): continue
                        # Leaderboard filter removed for monitoring
                        positionAmt = getattr(position, 'positionAmt', 0.0) or 0.0
                        _wdog_price = safe_fetch_float(getattr(position, 'mark_price', 0), 0) or safe_fetch_float(getattr(position, 'entry_price', 0), 0)
                        _wdog_min_qty = max(trade_manager.config.MIN_POSITION_SIZE / _wdog_price, trade_manager.min_qty.get(symbol, 0.001)) if _wdog_price > 0 else 0.001
                        if abs(float(positionAmt)) < _wdog_min_qty: continue
                        last_ts = last_monitored.get(position_key, 0.0)
                        age = now_ts - (last_ts if isinstance(last_ts, (int, float)) else 0.0)
                        if age > 60.0:
                            tradeable_position_keys_stale.append((position_key, account_key, symbol, position_side, age))
                    except Exception: pass
            if tradeable_position_keys_stale:
                tradeable_position_keys_stale.sort(key=lambda x: -x[4])
                for position_key, account_key, symbol, position_side, age in tradeable_position_keys_stale[:20]:
                    try:
                        blocker_found = False
                        i = await ii(trade_manager, symbol)
                        if not i :
                            blocker_found = True
                            if hasattr(trade_manager, 'refresh_indicator_for_symbol'):
                                asyncio.create_task(trade_manager.refresh_indicator_for_symbol(symbol))
                        indicator_age = None
                        if indicator_age is not None and indicator_age > 15.0:
                            blocker_found = True
                            if hasattr(trade_manager, 'refresh_indicator_for_symbol'):
                                asyncio.create_task(trade_manager.refresh_indicator_for_symbol(symbol))
                        position = await trade_manager.get_position(position_key)
                        if position:
                            positionAmt = getattr(position, 'positionAmt', 0.0) or 0.0
                            _wdog_price = safe_fetch_float(getattr(position, 'mark_price', 0), 0) or safe_fetch_float(getattr(position, 'entry_price', 0), 0)
                            _wdog_min_qty = max(trade_manager.config.MIN_POSITION_SIZE / _wdog_price, trade_manager.min_qty.get(symbol, 0.001)) if _wdog_price > 0 else 0.001
                            if abs(float(positionAmt)) >= _wdog_min_qty:
                                pos_last = getattr(position, 'mark_price_last_updated', None) or getattr(position, 'last_updated', None) 
                                if isinstance(pos_last, datetime):
                                    pos_last_fixed = pos_last.replace(tzinfo=timezone.utc) if pos_last.tzinfo is None else pos_last
                                    pos_age = (now_dt - pos_last_fixed).total_seconds()
                                    if pos_age > 3600.0:
                                        if pos_age > 12000:
                                            logger.warning(f"[SYMBOL_WATCHDOG] 🔥 {position_key} POSITION_DATA_STALE age={pos_age:.1f}s - threshold increased to 1h")
                                        pass  # No API call — use memory data only
                                        position = await trade_manager.get_position(position_key)
                        if not blocker_found:
                            if getattr(trade_manager.config, 'LEADERBOARD_FILTER', True) and not _check_leaderboard_allowed(trade_manager, symbol, position_side, account_key, position_key):
                                logger.debug(f"[SYMBOL_WATCHDOG] Skipping alert for {position_key}: filtered by LEADERBOARD_FILTER")
                            else:
                                logger.debug(f"[SYMBOL_WATCHDOG] 🔥 {position_key} NOT_MONITORED age={age:.1f}s - NO_BLOCKER_FOUND - forcing override check")
                                asyncio.create_task(override_check_uptrend_positions(trade_manager, account_key))
                    except Exception as pos_err:
                        logger.error(f"[SYMBOL_WATCHDOG] Error checking {position_key}: {pos_err}")
            symbols_stale = []
            for symbol in all_symbols:
                try:
                    last_monitored = trade_manager.last_symbol_monitored.get(symbol, 0.0)
                    age = now_ts - last_monitored if last_monitored > 0 else 999.0
                    if age > 90.0:
                        symbols_stale.append((symbol, age))
                except Exception: pass
            if symbols_stale:
                symbols_stale.sort(key=lambda x: -x[1])
                for symbol, age in symbols_stale[:10]:
                    try:
                        blocker_found = False
                        i = await ii(trade_manager, symbol)
                        if not i :
                            blocker_found = True
                            logger.critical(f"[SYMBOL_WATCHDOG] 🔥 {symbol} STALE_INDICATORS age={age:.1f}s - reloading indicators")
                            if hasattr(trade_manager, 'refresh_indicator_for_symbol'):
                                asyncio.create_task(trade_manager.refresh_indicator_for_symbol(symbol))
                        indicator_ts = getattr(trade_manager, 'indicators_timestamp', None)
                        if isinstance(indicator_ts, datetime):
                            indicator_ts_fixed = indicator_ts.replace(tzinfo=timezone.utc) if indicator_ts.tzinfo is None else indicator_ts
                            indicator_age = (now_dt - indicator_ts_fixed).total_seconds()
                            if indicator_age > 180.0:
                                blocker_found = True
                                logger.critical(f"[SYMBOL_WATCHDOG] 🔥 {symbol} INDICATOR_SNAPSHOT_STALE age={indicator_age:.1f}s - forcing refresh")
                                if hasattr(trade_manager, 'ensure_indicator_snapshot_ready'):
                                    asyncio.create_task(trade_manager.ensure_indicator_snapshot_ready({'trade_manager': trade_manager, 'symbol': symbol, 'logger': logger}))
                        positions_stale = []
                        for account_key in account_keys:
                            if account_key not in allowed_accounts: continue
                            account_positions = trade_manager.get_positions_by_account(account_key)
                            for position_key, position in account_positions.items():
                                if position and getattr(position, 'symbol', None) == symbol:
                                    positionAmt = getattr(position, 'positionAmt', 0.0) or 0.0
                                    _wdog_price = safe_fetch_float(getattr(position, 'mark_price', 0), 0) or safe_fetch_float(getattr(position, 'entry_price', 0), 0)
                            _wdog_min_qty = max(trade_manager.config.MIN_POSITION_SIZE / _wdog_price, trade_manager.min_qty.get(symbol, 0.001)) if _wdog_price > 0 else 0.001
                            if abs(float(positionAmt)) >= _wdog_min_qty:
                                        pos_last = getattr(position, 'last_updated', None) or getattr(position, 'mark_price_last_updated', None)
                                        if isinstance(pos_last, datetime):
                                            pos_last_fixed = pos_last.replace(tzinfo=timezone.utc) if pos_last.tzinfo is None else pos_last
                                            pos_age = (now_dt - pos_last_fixed).total_seconds()
                                            if pos_age > 60.0:
                                                positions_stale.append((position_key, account_key, pos_age))
                        if positions_stale:
                            blocker_found = True
                            stale_keys = ', '.join([f"{position_key}@{acc_key}({age:.1f}s)" for position_key, acc_key, age in positions_stale[:5]])
                            logger.critical(f"[SYMBOL_WATCHDOG] 🔥 {symbol} POSITIONS_STALE {len(positions_stale)} open positions age>60s: {stale_keys} - reloading from Redis/JSON")
                            account_keys_to_reload = set()
                            for position_key, acc_key, pos_age in positions_stale[:5]:
                                if acc_key in allowed_accounts: account_keys_to_reload.add(acc_key)

                            async def reload_account_positions(acc_key: str):
                                if hasattr(trade_manager, '_load_positions_from_redis'):
                                    try:
                                        bucket = await trade_manager._load_positions_from_redis(acc_key)
                                        if bucket:
                                            if acc_key not in trade_manager.positions_by_account:
                                                trade_manager.positions_by_account[acc_key] = {}
                                            existing_count = len(trade_manager.positions_by_account[acc_key])
                                            trade_manager.positions_by_account[acc_key].update(bucket)
                                            trade_manager.positions.update(bucket)
                                            if len(trade_manager.positions_by_account[acc_key]) < existing_count:
                                                logger.critical(f"[SYMBOL_WATCHDOG] {acc_key} - POSITION COUNT DECREASED from {existing_count} to {len(trade_manager.positions_by_account[acc_key])} - THIS SHOULD NEVER HAPPEN!")
                                            logger.info(f"[SYMBOL_WATCHDOG] Reloaded {len(bucket)} positions for {acc_key} from Redis")
                                            return
                                    except Exception as reload_exc:
                                        logger.debug(f"[SYMBOL_WATCHDOG] Redis reload failed for {acc_key}, trying files: {reload_exc}")
                                if hasattr(trade_manager, '_load_positions_quick_from_files'):
                                    try:
                                        bucket = await trade_manager._load_positions_quick_from_files(acc_key)
                                        if bucket:
                                            if acc_key not in trade_manager.positions_by_account:
                                                trade_manager.positions_by_account[acc_key] = {}
                                            existing_count = len(trade_manager.positions_by_account[acc_key])
                                            trade_manager.positions_by_account[acc_key].update(bucket)
                                            trade_manager.positions.update(bucket)
                                            if len(trade_manager.positions_by_account[acc_key]) < existing_count:
                                                logger.critical(f"[SYMBOL_WATCHDOG] {acc_key} - POSITION COUNT DECREASED from {existing_count} to {len(trade_manager.positions_by_account[acc_key])} - THIS SHOULD NEVER HAPPEN!")
                                            logger.info(f"[SYMBOL_WATCHDOG] Reloaded {len(bucket)} positions for {acc_key} from files")
                                    except Exception as file_exc:
                                        logger.debug(f"[SYMBOL_WATCHDOG] File reload failed for {acc_key}: {file_exc}")
                            reload_tasks = [reload_account_positions(acc_key) for acc_key in account_keys_to_reload]
                            if reload_tasks:
                                try:
                                    await asyncio.gather(*reload_tasks, return_exceptions=True)
                                except Exception as gather_exc:
                                    logger.debug(f"[SYMBOL_WATCHDOG] Error during position reload: {gather_exc}")
                            if hasattr(trade_manager, 'get_mark_price'):
                                asyncio.create_task(trade_manager.get_mark_price(symbol, allow_fallback=True, max_staleness=2.0))
                        if not blocker_found:
                            logger.debug(f"[SYMBOL_WATCHDOG] 🔥 {symbol} NOT_MONITORED age={age:.1f}s - NO_BLOCKER_FOUND - forcing override check")
                            for account_key in account_keys:
                                if account_key not in allowed_accounts: continue
                                if trade_manager.is_symbol_allowed(account_key, symbol):
                                    asyncio.create_task(override_check_uptrend_positions(trade_manager, account_key))
                        trade_manager.last_symbol_monitored[symbol] = now_ts
                    except Exception as sym_err:
                        logger.error(f"[SYMBOL_WATCHDOG] Error checking {symbol}: {sym_err}")
                reentry_data_dict = trade_manager.service.reentry_data if trade_manager.service else getattr(trade_manager, 'reentry_data', {})
                if reentry_data_dict and isinstance(reentry_data_dict, dict):
                    filtered_keys = _filter_position_keys(trade_manager, list(reentry_data_dict.keys()))
                    if filtered_keys:
                        filtered_reentry_data = {position_key: reentry_data_dict[position_key] for position_key in filtered_keys if position_key in reentry_data_dict}
                        original_reentry_data = trade_manager.reentry_data
                        try:
                            trade_manager.reentry_data = filtered_reentry_data
                            await evaluate_reentry_2(trade_manager)
                        finally:
                            trade_manager.reentry_data = original_reentry_data
            await asyncio.sleep(10)
        except asyncio.CancelledError:
            break
        except Exception as exc:
            logger.error(f"[SYMBOL_WATCHDOG] Watchdog error: {exc}", exc_info=True)
            await asyncio.sleep(15)


_reentry_monitor_fired = {}

async def _price_level_reentry_monitor(trade_manager: MultiAccountTradeManager) -> None:
    """Polls all reentry data sources (long/short_reentry.json, long/short_ladder.json,
    reduced_positions.json) every REENTRY_LIVE_MONITOR_INTERVAL_S seconds and fires a
    guaranteed partial REENTRY via execute_now when price crosses any uncrossed level.
    No stoch gate — partial is always guaranteed. Zero-amount entries fall back to
    START_POSITION_SIZE. Deduplicates via _reentry_monitor_fired cache."""
    cfg = getattr(trade_manager, 'config', config)
    if not getattr(cfg, 'REENTRY_LIVE_MONITOR_ENABLED', True):
        return
    base_path = Path(getattr(cfg, 'BASE_PATH', '/Users/niels/Documents/binance'))
    partial_pct = float(getattr(cfg, 'REENTRY_LIVE_MONITOR_PARTIAL_PCT', 0.5))
    min_qty_usd = float(getattr(cfg, 'START_POSITION_SIZE', 55.0))
    account_keys = set(getattr(cfg, 'ACCOUNT_KEYS', []))
    now_ts = time.time()
    for account_key in account_keys:
        acc_dir = base_path / account_key
        if not acc_dir.exists():
            continue
        # Collect all price levels from all sources
        levels_to_check: list[tuple[str, float, float, str]] = []
        for side in ('long', 'short'):
            is_long = (side == 'long')
            # --- reentry JSON ---
            reentry_file = acc_dir / f'{side}_reentry.json'
            if reentry_file.exists():
                try:
                    async with aiofiles.open(reentry_file, 'r') as f:
                        rdata = json.loads(await f.read())
                    for pk, rd in rdata.items() if isinstance(rdata, dict) else []:
                        lvl = float(rd.get('reentry_level', 0) or 0)
                        amt = float(rd.get('reentry_amount', 0) or 0)
                        if lvl > 0:
                            fire_amt = amt if amt > 0 else min_qty_usd
                            fire_qty_usd = fire_amt * partial_pct
                            levels_to_check.append((pk, lvl, fire_qty_usd, f'FILE_{side.upper()}_REENTRY'))
                except Exception as _e:
                    logger.debug(f"[REENTRY_MONITOR] {account_key}/{side}_reentry.json read error: {_e}")
            # --- ladder JSON ---
            ladder_file = acc_dir / f'{side}_ladder.json'
            if ladder_file.exists():
                try:
                    async with aiofiles.open(ladder_file, 'r') as f:
                        ldata = json.loads(await f.read())
                    for pk, plan in ldata.items() if isinstance(ldata, dict) else []:
                        levels = plan.get('levels', []) if isinstance(plan, dict) else []
                        for entry in levels:
                            if entry.get('crossed', False):
                                continue
                            lvl = float(entry.get('level', 0) or 0)
                            qty = float(entry.get('quantity', 0) or 0)
                            if lvl > 0:
                                fire_qty = max(qty, min_qty_usd / max(lvl, 1e-9)) * partial_pct
                                levels_to_check.append((pk, lvl, fire_qty * lvl, f'LADDER_{side.upper()}'))
                except Exception as _e:
                    logger.debug(f"[REENTRY_MONITOR] {account_key}/{side}_ladder.json read error: {_e}")
        # --- evaluate each level ---
        for position_key, level_price, fire_usd, source in levels_to_check:
            try:
                _parts = position_key.split(':')
                if len(_parts) < 2:
                    continue
                _acc = _parts[0]
                _sym_side = _parts[1]
                _is_long = _sym_side.endswith('_LONG')
                _sym = _sym_side.rsplit('_', 1)[0]
                _cur_price = 0.0
                _pos = trade_manager.positions.get(position_key) if hasattr(trade_manager, 'positions') else None
                if _pos:
                    _cur_price = float(getattr(_pos, 'mark_price', 0) or 0)
                if _cur_price <= 0:
                    try:
                        _cur_price, _ = await get_current_price(_sym)
                    except Exception:
                        continue
                if _cur_price <= 0:
                    continue
                _crossed = (_is_long and _cur_price >= level_price) or (not _is_long and _cur_price <= level_price)
                if not _crossed:
                    continue
                # Dedup: don't re-fire the same level within 15min
                _cache_key = f"{position_key}:{level_price:.8f}"
                _last_fired = _reentry_monitor_fired.get(_cache_key, 0)
                if now_ts - _last_fired < 900:
                    continue
                # Position size guard — don't add if already at full size
                if _pos and hasattr(_pos, 'max_quantity') and hasattr(_pos, 'positionAmt'):
                    _amt = abs(float(getattr(_pos, 'positionAmt', 0) or 0))
                    _max_q = float(getattr(_pos, 'max_quantity', 0) or 0)
                    if _max_q > 0 and _amt >= _max_q:
                        continue
                fire_qty = max(fire_usd / max(_cur_price, 1e-9), min_qty_usd / max(_cur_price, 1e-9) * partial_pct)
                _reentry_monitor_fired[_cache_key] = now_ts
                _uid = f"LEVEL_REENTRY_{int(now_ts)}"
                logger.warning(f"[REENTRY_MONITOR] {position_key}: {source} level={level_price:.6f} cur={_cur_price:.6f} → partial qty={fire_qty:.4f} (${fire_usd:.1f})")
                await execute_now(trade_manager.order_queue, trade_manager, position_key, _acc, _sym, 0.0, 'BUY' if _is_long else 'SELL', 'LONG' if _is_long else 'SHORT', fire_qty, _cur_price, _uid, f"{source}_LEVEL={level_price:.6f}", False, "AUGMENT")
            except Exception as _e:
                logger.debug(f"[REENTRY_MONITOR] {position_key} error: {_e}")
    # Purge old cache entries > 2h
    cutoff = now_ts - 7200
    for k in [k for k, v in list(_reentry_monitor_fired.items()) if v < cutoff]:
        _reentry_monitor_fired.pop(k, None)

async def _price_level_reentry_monitor_loop(trade_manager: MultiAccountTradeManager) -> None:
    """Wrapper loop — runs _price_level_reentry_monitor every REENTRY_LIVE_MONITOR_INTERVAL_S seconds."""
    cfg = getattr(trade_manager, 'config', config)
    interval = int(getattr(cfg, 'REENTRY_LIVE_MONITOR_INTERVAL_S', 30))
    logger.info(f"[REENTRY_MONITOR_LOOP] started — interval={interval}s")
    while True:
        try:
            await _price_level_reentry_monitor(trade_manager)
        except Exception as _e:
            logger.error(f"[REENTRY_MONITOR_LOOP] error: {_e}", exc_info=True)
        await asyncio.sleep(interval)

@timed_function("periodic_evaluate_reentry_loop")
async def periodic_evaluate_reentry_loop(trade_manager: MultiAccountTradeManager):
    try:
        logger.debug("[periodic_evaluate_reentry_loop] STARTING independent reentry evaluation loop")
        config = getattr(trade_manager, 'config', None)
        allowed_accounts = set(getattr(config, 'ACCOUNT_KEYS', [])) if config else set()
        allowed_accounts = {acc for acc in allowed_accounts if acc not in ['fin', 'men']}
        while True:
            try:
                # service.reentry_data is the live dict — same process, same object
                reentry_data_dict = trade_manager.service.reentry_data if trade_manager.service else trade_manager.reentry_data
                if not isinstance(reentry_data_dict, dict):
                    reentry_data_dict = {}
                    return
                all_keys = list(reentry_data_dict.keys())
                filtered_keys = _filter_position_keys(trade_manager, all_keys)
                filtered_reentry_data = {position_key: reentry_data_dict[position_key] for position_key in filtered_keys if position_key in reentry_data_dict}
                original_reentry_data = trade_manager.reentry_data
                try:
                    trade_manager.reentry_data = filtered_reentry_data
                    reentry_count = len(filtered_reentry_data)
                    if (config and getattr(config, 'VERBOSE', False)) or reentry_count > 0:
                        logger.debug(f"[periodic_evaluate_reentry_loop] Processing {reentry_count} positions with reentry_data (filtered from {len(reentry_data_dict)} total, {len(all_keys)} keys, {len(filtered_keys)} passed filter): {list(filtered_reentry_data.keys())}")
                    await evaluate_reentry_2(trade_manager)
                finally:
                    trade_manager.reentry_data = original_reentry_data
            except Exception as e:
                logger.error(f"[evaluate_reentry_loop] Error: {e}", exc_info=True)
            await asyncio.sleep(10)
    except Exception as e:
        logger.critical(f"[PERIODIC_EVALUATE_REENTRY_LOOP] CRITICAL ERROR - Function crashed: {e}", exc_info=True)
        raise

